/**
 * Number input parsing utilities for handling fractions, mixed numbers, math expressions, and units
 * Extracted from CoordinateUtil for better code organization
 */
export class NumberInputUtil {
  /**
   * Parse text input to number supporting fractions, mixed numbers, math expressions, and units
   * @param text Input text to parse
   * @param defaultUnit Default unit ('in' or 'mm')
   * @param allowNegative Whether negative numbers are allowed
   * @param allowPositive Whether positive numbers are allowed
   * @param allowFractions Whether fractions are allowed
   * @param precision Number of decimal places for result
   * @param min Minimum allowed value
   * @param max Maximum allowed value
   * @returns Object with parsed value and validity flag
   */
  static parseNumberInput(
    text: string,
    defaultUnit: 'in' | 'mm' = 'in',
    allowNegative = true,
    allowPositive = true,
    allowFractions = true,
    precision = 3,
    min?: number,
    max?: number
  ): { value: number; isValid: boolean } {
    if (!text || text.trim() === '') {
      return { value: 0, isValid: true };
    }

    const trimmedText = text.trim().toLowerCase();
    
    // Extract unit if present
    let unitMultiplier = 1;
    let numberPart = trimmedText;
    
    if (trimmedText.endsWith('mm')) {
      numberPart = trimmedText.slice(0, -2).trim();
      unitMultiplier = defaultUnit === 'in' ? 1 / 25.4 : 1; // Convert mm to inches if default is inches
    } else if (trimmedText.endsWith('in') || trimmedText.endsWith('"')) {
      numberPart = trimmedText.replace(/in$|"$/, '').trim();
      unitMultiplier = defaultUnit === 'mm' ? 25.4 : 1; // Convert inches to mm if default is mm
    }

    // Handle math expressions (e.g., "10 + 4 1/2", "14 + 2", "10 - 1.5")
    // Exclude simple negative numbers, negative fractions, and negative mixed numbers
    if (/[+-]/.test(numberPart) && 
        !numberPart.match(/^-?\d+(\.\d+)?$/) && 
        !numberPart.match(/^-?\d+\/\d+$/) && 
        !numberPart.match(/^-?\d+\s+\d+\/\d+$/)) {
      const result = NumberInputUtil.parseSimpleMath(numberPart, unitMultiplier, allowFractions, precision);
      if (!result.isValid) return result;
      return NumberInputUtil.validateConstraints(result.value, allowNegative, allowPositive, min, max, precision);
    }

    // Handle mixed numbers with space (e.g., "14 1/2")
    if (allowFractions && /^-?\d+\s+\d+\/\d+$/.test(numberPart)) {
      const result = NumberInputUtil.parseMixedNumber(numberPart, unitMultiplier, precision);
      if (!result.isValid) return result;
      return NumberInputUtil.validateConstraints(result.value, allowNegative, allowPositive, min, max, precision);
    }

    // Check for malformed mixed numbers (numbers with space but no fraction)
    if (/^-?\d+\s+\d+$/.test(numberPart)) {
      return { value: 0, isValid: false };
    }

    // Handle fractions
    if (allowFractions && numberPart.includes('/') && !numberPart.includes(' ')) {
      const result = NumberInputUtil.parseFraction(numberPart, unitMultiplier, precision);
      if (!result.isValid) return result;
      return NumberInputUtil.validateConstraints(result.value, allowNegative, allowPositive, min, max, precision);
    }

    // Handle decimal numbers
    const parsed = parseFloat(numberPart);
    if (isNaN(parsed)) {
      return { value: 0, isValid: false };
    }

    const result = parsed * unitMultiplier;
    return NumberInputUtil.validateConstraints(result, allowNegative, allowPositive, min, max, precision);
  }

  /**
   * Parse fraction text (e.g., "3/4", "-1/8")
   */
  private static parseFraction(text: string, unitMultiplier: number, precision: number): { value: number; isValid: boolean } {
    const parts = text.split('/');
    if (parts.length !== 2) {
      return { value: 0, isValid: false };
    }

    const numerator = parseFloat(parts[0].trim());
    const denominator = parseFloat(parts[1].trim());

    if (isNaN(numerator) || isNaN(denominator) || denominator === 0) {
      return { value: 0, isValid: false };
    }

    const result = (numerator / denominator) * unitMultiplier;
    return { value: parseFloat(result.toFixed(precision)), isValid: true };
  }

  /**
   * Parse mixed number text (e.g., "14 1/2", "-2 3/8")
   */
  private static parseMixedNumber(text: string, unitMultiplier: number, precision: number): { value: number; isValid: boolean } {
    const match = text.match(/^(-?\d+)\s+(\d+)\/(\d+)$/);
    if (!match) {
      return { value: 0, isValid: false };
    }

    const wholeNumber = parseFloat(match[1]);
    const numerator = parseFloat(match[2]);
    const denominator = parseFloat(match[3]);

    if (isNaN(wholeNumber) || isNaN(numerator) || isNaN(denominator) || denominator === 0) {
      return { value: 0, isValid: false };
    }

    const fraction = numerator / denominator;
    // For mixed numbers, the fraction is always added to the whole number
    // The sign of the whole number determines the overall sign
    const result = (Math.abs(wholeNumber) + fraction) * (wholeNumber >= 0 ? 1 : -1) * unitMultiplier;
    
    return { value: parseFloat(result.toFixed(precision)), isValid: true };
  }

  /**
   * Parse simple math expressions (e.g., "10 + 4 1/2", "14 + 2", "10 - 1.5")
   */
  private static parseSimpleMath(text: string, unitMultiplier: number, allowFractions: boolean, precision: number): { value: number; isValid: boolean } {
    // Split on + or - operators, but preserve the operator
    const parts: string[] = [];
    const operators: string[] = [];
    
    let currentPart = '';
    let i = 0;
    
    while (i < text.length) {
      const char = text[i];
      
      if ((char === '+' || char === '-') && i > 0) {
        // Found an operator (not a negative sign at the start)
        parts.push(currentPart.trim());
        operators.push(char);
        currentPart = '';
      } else {
        currentPart += char;
      }
      i++;
    }
    
    // Add the last part
    if (currentPart.trim()) {
      parts.push(currentPart.trim());
    }

    if (parts.length < 2 || operators.length !== parts.length - 1) {
      return { value: 0, isValid: false };
    }

    // Parse the first value
    let result = NumberInputUtil.parseNumberPart(parts[0], allowFractions, precision);
    if (!result.isValid) return result;
    
    let accumulator = result.value;

    // Process each subsequent part with its operator
    for (let j = 1; j < parts.length; j++) {
      const operator = operators[j - 1];
      const partResult = NumberInputUtil.parseNumberPart(parts[j], allowFractions, precision);
      
      if (!partResult.isValid) return partResult;
      
      if (operator === '+') {
        accumulator += partResult.value;
      } else if (operator === '-') {
        accumulator -= partResult.value;
      }
    }

    const finalResult = accumulator * unitMultiplier;
    return { value: parseFloat(finalResult.toFixed(precision)), isValid: true };
  }

  /**
   * Parse a single number part (decimal, fraction, or mixed number)
   */
  private static parseNumberPart(text: string, allowFractions: boolean, precision: number): { value: number; isValid: boolean } {
    const trimmed = text.trim();
    
    // Handle mixed numbers with space (e.g., "4 1/2")
    if (allowFractions && /^-?\d+\s+\d+\/\d+$/.test(trimmed)) {
      return NumberInputUtil.parseMixedNumber(trimmed, 1, precision);
    }

    // Handle fractions
    if (allowFractions && trimmed.includes('/') && !trimmed.includes(' ')) {
      return NumberInputUtil.parseFraction(trimmed, 1, precision);
    }

    // Handle decimal numbers
    const parsed = parseFloat(trimmed);
    if (isNaN(parsed)) {
      return { value: 0, isValid: false };
    }

    return { value: parseFloat(parsed.toFixed(precision)), isValid: true };
  }

  /**
   * Validate constraints on a parsed number
   */
  private static validateConstraints(
    value: number,
    allowNegative: boolean,
    allowPositive: boolean,
    min?: number,
    max?: number,
    precision?: number
  ): { value: number; isValid: boolean } {
    // Validate constraints
    if (!allowNegative && value < 0) {
      return { value: 0, isValid: false };
    }
    if (!allowPositive && value > 0) {
      return { value: 0, isValid: false };
    }
    if (min !== undefined && value < min) {
      return { value: min, isValid: false };
    }
    if (max !== undefined && value > max) {
      return { value: max, isValid: false };
    }

    const finalValue = precision !== undefined ? parseFloat(value.toFixed(precision)) : value;
    return { value: finalValue, isValid: true };
  }
}
