import { CNCPoint } from '../data/CNCPoint';
import { CoordinateType } from '../data/Common/CoordinateType';
import { MachineData } from '../data/MachineData';
import { CoordinateUtil } from './CoordinateUtil';
import { LogCategory, Logger } from './Logger';

/**
 * Result from getSoftLimits utility
 */
export interface SoftLimitsResult {
    min: CNCPoint;
    max: CNCPoint;
    fromAPI: boolean;
}

/**
 * Utility for retrieving soft limits either from MachineData or from the machine API
 * Handles coordinate conversion between MachineHome (API) and MachineZero (storage)
 * 
 * IMPORTANT: Call initialize() at application startup to cache API limits
 */
export class SoftLimitsUtil {
    private static _cachedLimits: SoftLimitsResult | null = null;
    private static _initialized: boolean = false;

    /**
     * Initialize and cache soft limits from API (call once at startup)
     * This makes all subsequent calls synchronous
     */
    public static async initialize(): Promise<void> {
        if (this._initialized) {
            return;
        }

        try {
            // Dynamically import Machine to avoid circular dependencies
            const { Machine } = await import('../machine/Machine');
            const machineInterface = Machine.getInstance();

            // Try to get travel limits from the API
            const travelLimits = await machineInterface.setup.GetTravelLimits();

            if (travelLimits) {
                // API returned travel limits in MachineHome coordinates
                // Convert to MachineZero for consistency with stored soft limits
                const minInMachineZero = CoordinateUtil.toMachineZero(travelLimits.min);
                const maxInMachineZero = CoordinateUtil.toMachineZero(travelLimits.max);

                this._cachedLimits = {
                    min: minInMachineZero,
                    max: maxInMachineZero,
                    fromAPI: true
                };

                Logger.Instance.log(
                    LogCategory.System,
                    `Cached travel limits from API: Min(${minInMachineZero.x}, ${minInMachineZero.y}, ${minInMachineZero.z}) Max(${maxInMachineZero.x}, ${maxInMachineZero.y}, ${maxInMachineZero.z})`
                );
            } else {
                Logger.Instance.log(
                    LogCategory.System,
                    'API returned no travel limits, will use MachineData soft limits'
                );
            }
        } catch (error) {
            Logger.Instance.log(
                LogCategory.System,
                'Could not retrieve travel limits from API, will use MachineData soft limits'
            );
        }

        this._initialized = true;
    }

    /**
     * Get soft limits synchronously (uses cached API limits or falls back to MachineData)
     * Returns limits in MachineZero coordinates (for use in UI and collision detection)
     * 
     * @returns SoftLimitsResult with min/max CNCPoints in MachineZero coordinates and flag indicating source
     */
    public static getSoftLimits(): SoftLimitsResult {
        // If we have cached API limits, return them
        if (this._cachedLimits) {
            return this._cachedLimits;
        }

        // Fall back to MachineData soft limits (already in MachineZero coordinates)
        const machineData = MachineData.Instance;

        const min = new CNCPoint(
            machineData.xLowerSoftLimitFromMachineZero,
            machineData.yLowerSoftLimitFromMachineZero,
            machineData.zLowerSoftLimitFromMachineZero,
            CoordinateType.MachineZero
        );

        const max = new CNCPoint(
            machineData.xUpperSoftLimitFromMachineZero,
            machineData.yUpperSoftLimitFromMachineZero,
            machineData.zUpperSoftLimitFromMachineZero,
            CoordinateType.MachineZero
        );

        return {
            min,
            max,
            fromAPI: false
        };
    }

    /**
     * Check if soft limits are currently being sourced from the API
     * Used by UI to determine if soft limit fields should be read-only
     * 
     * @returns true if limits come from API, false if from MachineData
     */
    public static areLimitsFromAPI(): boolean {
        return this._cachedLimits !== null;
    }
}
