import {
    Box,
    CircularProgress,
    Paper,
    Typography
} from '@mui/material';
import { ConfigurationData } from '../data/ConfigurationData';
import { MachineStateData } from '../data/MachineStateData';
import { ObserveState } from '../utils/statemanager/ObserveState';

/**
 * ConnectionOverlay displays over the UI when machine connection is lost
 * Uses ObserveState to reactively show/hide based on MachineStateData.isConnected
 */
export function ConnectionOverlay() {
    return (
        <ObserveState
            key="connection-overlay-observer"
            listenTo={MachineStateData.Instance}
            properties={['isConnected']}
            control={() => {
                const machineState = MachineStateData.Instance;
                const config = ConfigurationData.Instance;

                // Don't show overlay if connected
                if (machineState.isConnected) {
                    return null;
                }

                // Show overlay when disconnected
                return (
                    <Box
                        sx={{
                            position: 'fixed',
                            top: 0,
                            left: 0,
                            right: 0,
                            bottom: 0,
                            display: 'flex',
                            flexDirection: 'column',
                            alignItems: 'center',
                            justifyContent: 'center',
                            backgroundColor: config.darkOverlay,
                            zIndex: 9999, // Above everything else
                            padding: 3
                        }}
                    >
                        <Paper
                            elevation={8}
                            sx={{
                                padding: 6,
                                borderRadius: 4,
                                textAlign: 'center',
                                maxWidth: 500,
                                width: '100%',
                                backgroundColor: config.darkBackgroundColor,
                                color: config.lightTextColor,
                                border: `2px solid ${config.errorColor}`
                            }}
                        >
                            {/* Warning Icon/Title */}
                            <Typography
                                variant="h3"
                                component="h1"
                                gutterBottom
                                sx={{
                                    color: config.errorColor,
                                    fontWeight: 'bold',
                                    marginBottom: 3
                                }}
                            >
                                Connection Lost
                            </Typography>

                            {/* Loading Spinner */}
                            <CircularProgress
                                size={60}
                                sx={{
                                    color: config.errorColor,
                                    marginBottom: 3
                                }}
                            />

                            {/* Connection Status */}
                            <Typography
                                variant="h6"
                                sx={{
                                    color: config.lightTextColor,
                                    marginBottom: 1
                                }}
                            >
                                Waiting for Connection...
                            </Typography>

                            <Typography
                                variant="body2"
                                sx={{
                                    color: config.mutedTextColor,
                                    marginBottom: 2
                                }}
                            >
                                The connection to the CNC machine has been lost.
                                <br />
                                Attempting to reconnect...
                            </Typography>

                            {/* Info Box */}
                            <Box
                                sx={{
                                    backgroundColor: 'rgba(255, 255, 255, 0.1)',
                                    borderRadius: 2,
                                    padding: 2,
                                    marginTop: 3
                                }}
                            >
                                <Typography
                                    variant="caption"
                                    sx={{
                                        color: config.mutedTextColor,
                                        fontStyle: 'italic'
                                    }}
                                >
                                    Please check:
                                    <br />
                                    • Network connection to CNC machine
                                    <br />
                                    • CNC control software is running
                                    <br />
                                    • SignalR server is active
                                </Typography>
                            </Box>
                        </Paper>
                    </Box>
                );
            }}
        />
    );
}
