import { Box } from '@react-three/drei';
import { CNCPoint } from '../../../data/CNCPoint';
import { SimulatorView } from '../../../data/Common/SimulatorView';
import { ViewStyle } from '../../../data/Common/ViewStyle';
import { ConfigurationData } from '../../../data/ConfigurationData';
import { MachineData } from '../../../data/MachineData';
import { MachineStateData } from '../../../data/MachineStateData';
import { CoordinateUtil } from '../../../utils/CoordinateUtil';
import { ObserveMultiProperties } from '../../../utils/statemanager/ObserveMultiProperties';
import { ATCPositionedTool } from './ATCPositionedTool';
import { ATCToolClamp } from './ATCToolClamp';
import { ISO30ToolHolder } from './ISO30ToolHolder';

export interface ATCProps {
  simulatorView: SimulatorView;
}

export function ATC({ simulatorView }: ATCProps) {
  const machineData = MachineData.Instance;
  const machineState = MachineStateData.Instance;
  const config = ConfigurationData.Instance;

  // Don't render if ATC is disabled
  if (!machineData.hasATC) {
    return null;
  }

  return (
    <ObserveMultiProperties
      listenTo={[
        { object: machineState, properties: ['currentToolNumber'] },
        { object: machineData, properties: ['hasATC', 'atcNumberOfTools', 'atcLocation', 'atcStructure', 'atcToolClamps', 'baseHeight', 'bedHeight', 'bedOffsetX', 'bedOffsetY'] },
        { object: config, properties: ['atcBarColor', 'atcToolClampColor', 'atcPostColor', 'atcTransparency'] },
        { object: simulatorView, properties: ['atc'] }
      ]}
      control={() => {
        // Return null if ATC is hidden
        if (simulatorView.atc === ViewStyle.Hide) {
          return null;
        }

        const atcLocation = machineData.atcLocation;
        const atcStructure = machineData.atcStructure;
        const toolClamps = machineData.atcToolClamps;
        const currentToolNumber = machineState.currentToolNumber;

        // Calculate ATC position based on machine configuration
        // ATC location is an offset from machine base top corner

        // Get the machine base top corner position in MachineZero coordinates
        const baseTopCorner = CoordinateUtil.getMachineBaseTopCornerPosition();

        // Add the ATC offset to the base top corner position
        const atcPositionInMachineZero = CNCPoint.addOffset(baseTopCorner, atcLocation.offset);

        // Convert to Simulator coordinates for rendering
        const barSimulatorPos = CoordinateUtil.toSimulator(atcPositionInMachineZero);
        const barX = barSimulatorPos.x;
        const barY = barSimulatorPos.y;
        const barZ = barSimulatorPos.z;

        // Calculate the top of the base in simulator coordinates
        const baseTopZ = machineData.baseHeight;

        // Get structure dimensions
        const postWidth = atcStructure.postWidth;
        const postLength = atcStructure.postLength;
        const barHeight = atcStructure.barHeight;
        const barWidth = atcStructure.barWidth;
        const barLength = atcStructure.barLength;

        // Bar positioning - adjust so that front-left corner is at ATC location
        // Bar center should be offset by half the bar dimensions
        const barCenterX = barX + barLength / 2;
        const barCenterY = barY + barWidth / 2;
        const barCenterZ = barZ + barHeight / 2;

        // Calculate post positions (posts extend from bar down to base)
        // Posts are positioned at the ends of the bar, accounting for bar positioning
        const post1X = barX + atcStructure.postOffsetFromRails; // Left post
        const post2X = barX + barLength - atcStructure.postOffsetFromRails; // Right post
        const postY = barY + barWidth / 2; // Center of bar width

        // Posts extend from bottom of bar down to top of base
        // Posts should be positioned under the bar, extending downward to base
        const postHeight = Math.abs(barZ - baseTopZ); // Absolute height of posts
        const postZ = baseTopZ + postHeight / 2; // Position posts from base top up to bottom of bar

        // Tool clamp dimensions (boxes with rounded front)
        const toolClampWidth = barWidth * 0.8; // Slightly narrower than bar
        const toolClampHeight = 0.6; // Fixed height of 0.6 inches
        const toolClampDepth = 2; // Standard tool clamp depth

        // Determine material properties based on ViewStyle
        const isTransparent = simulatorView.atc === ViewStyle.SemiTransparent;
        const isWireframe = simulatorView.atc === ViewStyle.Wireframe;
        const opacity = isTransparent ? (config.atcTransparency || 0.9) : 1.0;

        // Create unique key for React re-rendering when material properties change
        const renderKey = `atc-${ViewStyle[simulatorView.atc]}-${opacity}-${Date.now()}`;

        return (
          <group key={renderKey}>
            {/* Post 1 (left support) */}
            <Box
              position={[post1X, postY, postZ]}
              args={[postWidth, postLength, postHeight]}
            >
              <meshPhongMaterial
                color={config.atcPostColor}
                transparent={isTransparent}
                opacity={opacity}
                wireframe={isWireframe}
              />
            </Box>

            {/* Post 2 (right support) */}
            <Box
              position={[post2X, postY, postZ]}
              args={[postWidth, postLength, postHeight]}
            >
              <meshPhongMaterial
                color={config.atcPostColor}
                transparent={isTransparent}
                opacity={opacity}
                wireframe={isWireframe}
              />
            </Box>

            {/* Horizontal Bar (positioned so front-left corner is at ATC location) */}
            <Box
              position={[barCenterX, barCenterY, barCenterZ]}
              args={[barLength, barWidth, barHeight]}
            >
              <meshPhongMaterial
                color={config.atcBarColor}
                transparent={isTransparent}
                opacity={opacity}
                wireframe={isWireframe}
              />
            </Box>

            {/* Tool Clamps (positioned along the bar) */}
            {toolClamps.map((clamp, index) => {
              // Calculate clamp position: base top corner + ATC offset + clamp offset
              const baseTopCorner = CoordinateUtil.getMachineBaseTopCornerPosition();
              const atcPositionInMachineZero = CNCPoint.addOffset(baseTopCorner, atcLocation.offset);
              const clampPositionInMachineZero = CNCPoint.addOffset(atcPositionInMachineZero, clamp.offset);
              const clampBasePos = CoordinateUtil.toSimulator(clampPositionInMachineZero);

              // Calculate Z adjustment for clamp height
              const clampZAdjustment = barHeight / 2 + toolClampHeight / 2;
              const clampX = clampBasePos.x;
              const clampY = clampBasePos.y;
              const clampZ = clampBasePos.z + clampZAdjustment;

              // Tool clamp arm dimensions for ISO30 holder
              const armHeight = toolClampHeight * 0.8; // Height of the arms
              const armDepth = toolClampDepth * 0.6; // Depth of the arms

              return (
                <group key={`tool-clamp-${clamp.clampNumber}`}>
                  {/* Tool Clamp Component */}
                  <ATCToolClamp
                    clamp={clamp}
                    position={[clampX, clampY, clampZ]}
                    toolClampWidth={toolClampWidth}
                    toolClampHeight={toolClampHeight}
                    toolClampDepth={toolClampDepth}
                    simulatorView={simulatorView}
                  />

                  {/* ISO30 Tool Holder - only show if this position doesn't match current tool */}
                  {clamp.clampNumber !== currentToolNumber && (
                    <ISO30ToolHolder
                      position={[clampX, clampY, clampZ]}
                      toolClampHeight={toolClampHeight}
                      armHeight={armHeight}
                      armDepth={armDepth}
                    />
                  )}

                  {/* Tool - render tool at this clamp position if it's not the current tool */}
                  {clamp.clampNumber !== currentToolNumber && (
                    <ATCPositionedTool
                      clamp={clamp}
                      simulatorView={simulatorView}
                      machineData={machineData}
                      toolClampHeight={toolClampHeight}
                    />
                  )}
                </group>
              );
            })}
          </group>
        );
      }}
    />
  );
}
