import React from 'react';
import { Box, Cylinder } from '@react-three/drei';
import { ConfigurationData } from '../../../data/ConfigurationData';
import { ATCToolClamp as ATCToolClampData } from '../../../data/MachineData';
import { SimulatorView } from '../../../data/Common/SimulatorView';
import { ViewStyle } from '../../../data/Common/ViewStyle';
import { ObserveState } from '../../../utils/statemanager/ObserveState';

interface ATCToolClampProps {
  clamp: ATCToolClampData;
  position: [number, number, number];
  toolClampWidth: number;
  toolClampHeight: number;
  toolClampDepth: number;
  simulatorView: SimulatorView;
}

export function ATCToolClamp({ clamp, position, toolClampWidth, toolClampHeight, toolClampDepth, simulatorView }: ATCToolClampProps) {
  const config = ConfigurationData.Instance;
  
  return (
    <ObserveState
      listenTo={config}
      properties={['atcToolClampColor', 'atcTransparency']}
      control={() => {
        const [clampX, clampY, clampZ] = position;

        // Tool clamp arm dimensions
        const armWidth = toolClampWidth * 0.25; // Width of each arm
        const armHeight = toolClampHeight * 0.8; // Height of the arms
        const armDepth = toolClampDepth * 0.6; // Depth of the arms
        const armSeparation = toolClampWidth * 0.4; // Distance between arms
        const baseThickness = toolClampHeight * 0.3; // Thickness of mounting base

        // Determine material properties based on ViewStyle
        const isTransparent = simulatorView.atc === ViewStyle.SemiTransparent;
        const isWireframe = simulatorView.atc === ViewStyle.Wireframe;
        const opacity = isTransparent ? (config.atcTransparency || 0.9) : 1.0;

        // Create unique key for React re-rendering when material properties change
        const renderKey = `atc-tool-clamp-${ViewStyle[simulatorView.atc]}-${opacity}-${Date.now()}`;

        return (
          <group key={renderKey}>
      {/* Mounting Base (back plate that attaches to bar) */}
      <Box
        position={[clampX, clampY + toolClampDepth / 2 - baseThickness / 2, clampZ]}
        args={[toolClampWidth, baseThickness, toolClampHeight]}
      >
        <meshPhongMaterial 
          color={config.atcToolClampColor}
          transparent={isTransparent}
          opacity={opacity}
          wireframe={isWireframe}
        />
      </Box>

      {/* Left Arm */}
      <Box
        position={[clampX - armSeparation / 2, clampY, clampZ + (toolClampHeight - armHeight) / 2]}
        args={[armWidth, armDepth, armHeight]}
      >
        <meshPhongMaterial 
          color={config.atcToolClampColor}
          transparent={isTransparent}
          opacity={opacity}
          wireframe={isWireframe}
        />
      </Box>

      {/* Right Arm */}
      <Box
        position={[clampX + armSeparation / 2, clampY, clampZ + (toolClampHeight - armHeight) / 2]}
        args={[armWidth, armDepth, armHeight]}
      >
        <meshPhongMaterial 
          color={config.atcToolClampColor}
          transparent={isTransparent}
          opacity={opacity}
          wireframe={isWireframe}
        />
      </Box>

      {/* Left Arm Rounded Front */}
      <Cylinder
        position={[clampX - armSeparation / 2, clampY - armDepth / 2, clampZ + (toolClampHeight - armHeight) / 2]}
        args={[armWidth / 2, armWidth / 2, armHeight, 8]}
        rotation={[Math.PI / 2, 0, 0]}
      >
        <meshPhongMaterial 
          color={config.atcToolClampColor}
          transparent={isTransparent}
          opacity={opacity}
          wireframe={isWireframe}
        />
      </Cylinder>

      {/* Right Arm Rounded Front */}
      <Cylinder
        position={[clampX + armSeparation / 2, clampY - armDepth / 2, clampZ + (toolClampHeight - armHeight) / 2]}
        args={[armWidth / 2, armWidth / 2, armHeight, 8]}
        rotation={[Math.PI / 2, 0, 0]}
      >
        <meshPhongMaterial 
          color={config.atcToolClampColor}
          transparent={isTransparent}
          opacity={opacity}
          wireframe={isWireframe}
        />
      </Cylinder>
    </group>
        );
      }}
    />
  );
}
