import { CallMade as CallIcon } from '@mui/icons-material';
import { Box, Typography } from '@mui/material';
import React from 'react';
import { StorageType } from '../../../machine/ICNCProgramStorage';
import { Machine } from '../../../machine/Machine';
import { LogCategory, Logger } from '../../../utils/Logger';
import { DataUtilities } from '../../../utils/storage/DataUtilities';
import { Flow, FlowType } from "../../Flow";
import { FlowEngine } from "../../FlowEngine";
import { FlowNumberValue, ValueSource } from "../../FlowNumberValue";
import { FlowNumberValueEditor } from "../../FlowNumberValueEditor";
import { FlowStep } from "../../FlowStep";
import { FlowStepData } from "../../FlowStepData";

/**
 * Edit UI component for CallFlowStep
 * Separate function component to use React Hooks
 */
function CallFlowStepEditUI(props: { flowName: string; inputValue: FlowNumberValue; flow: any; flowStep: any }) {
    const { flowName, inputValue, flow, flowStep } = props;
    const [flowType, setFlowType] = React.useState<FlowType | null>(null);
    const [inputLabel, setInputLabel] = React.useState<string>('');

    React.useEffect(() => {
        const loadFlowType = async () => {
            try {
                const storage = await Machine.getInstance().storage.getStorageData(flowName);
                if (storage && storage.storageType === StorageType.Flow) {
                    const flowData = JSON.parse(storage.data);
                    const targetFlow = new Flow();
                    targetFlow.fromJSON(flowData);
                    setFlowType(targetFlow.FlowType);

                    // Set appropriate label based on flow type
                    if (targetFlow.FlowType === FlowType.ToolChange) {
                        setInputLabel('Tool Number');
                    } else if (targetFlow.FlowType === FlowType.NumberInput) {
                        setInputLabel('Number Value');
                    }
                }
            } catch (error) {
                Logger.Instance.logError(LogCategory.System, 'Failed to load flow type:', error);
            }
        };
        loadFlowType();
    }, [flowName]);

    return (
        <Box sx={{ p: 2, minWidth: 400 }}>
            <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                This step calls the flow "{flowName}".
            </Typography>

            {(flowType === FlowType.ToolChange || flowType === FlowType.NumberInput) && (
                <FlowNumberValueEditor
                    numberValue={inputValue}
                    flow={flow}
                    flowStep={flowStep}
                    label={inputLabel}
                />
            )}
        </Box>
    );
}

/**
 * Generic step for calling another flow or MDI program
 * Used by the factory to create flow-specific step instances
 * Stores the flow/MDI NAME - looks up the actual program at runtime
 */
export class CallFlowStep extends FlowStep {
    get __type(): string { return 'CallFlowStep'; }
    get category(): string[] {
        const config = this.getFlowConfig();
        return ['Flows', config.categoryName || 'General', config.name];
    }

    private flowName: string = '';
    public inputValue: FlowNumberValue = new FlowNumberValue();

    constructor(flowName?: string) {
        super();
        if (flowName !== undefined) {
            this.flowName = flowName;
        }
    }

    /**
     * Set the flow name (used by factory)
     */
    public setFlowName(flowName: string): void {
        this.flowName = flowName;
    }

    /**
     * Get the flow/MDI configuration from storage by name
     */
    private getFlowConfig(): { name: string; categoryName: string; storageType: StorageType } {
        return {
            name: this.flowName || 'Unknown Flow',
            categoryName: 'General',
            storageType: StorageType.Flow
        };
    }

    get name(): string {
        const config = this.getFlowConfig();
        return `Call ${config.name}`;
    }

    get description(): string {
        const config = this.getFlowConfig();
        return `Execute the ${config.storageType === StorageType.Flow ? 'flow' : 'MDI program'}: ${config.name}`;
    }

    get icon(): React.ReactNode {
        return React.createElement(CallIcon, { sx: { color: 'primary.main' } });
    }

    async execute(data: FlowStepData, prototypeRun: boolean): Promise<string | null> {
        if (prototypeRun) {
            return 'success';
        }

        try {
            const storage = await Machine.getInstance().storage.getStorageData(this.flowName);

            if (!storage) {
                Logger.Instance.logError(LogCategory.System, `Flow/MDI not found: ${this.flowName}`);
                return 'error';
            }

            if (storage.storageType === StorageType.Flow) {
                const flowData = JSON.parse(storage.data);
                const flow = new Flow();
                flow.fromJSON(flowData);

                const flowInputData = new FlowStepData();

                // Get the numeric value from FlowNumberValue
                let numericValue: number;
                if (this.inputValue.valueSource === ValueSource.DataElement) {
                    const value = this.getValueFromData(data, this.inputValue.dataPath);
                    numericValue = Number(value) || 0;
                } else {
                    numericValue = this.inputValue.numberValue;
                }

                // Set input parameter based on flow type
                if (flow.FlowType === FlowType.ToolChange) {
                    flowInputData.setVariable('ToTool', numericValue);
                } else if (flow.FlowType === FlowType.NumberInput) {
                    flowInputData.setVariable('NumberValue', numericValue);
                }

                const result = await FlowEngine.execute(flow, flowInputData, { prototypeRun });
                return result.success ? 'success' : 'error';
            } else {
                const mdiCommands = storage.data.split('\n').filter(line => line.trim());
                await Machine.getInstance().program.RunGCode(mdiCommands, true);
                return 'success';
            }
        } catch (error) {
            Logger.Instance.logError(LogCategory.System, `Call flow ${this.flowName} failed:`, error);
            return 'error';
        }
    }

    private getValueFromData(data: FlowStepData, path: string): any {
        if (!path) return undefined;

        const allData = data.getAllData();
        const pathParts = path.split('.');

        let current = allData;
        for (const part of pathParts) {
            if (current && typeof current === 'object' && part in current) {
                current = current[part];
            } else {
                return undefined;
            }
        }

        return current;
    }

    results(): string[] {
        return ['success', 'error'];
    }

    renderResultsUI(data: FlowStepData, result: string): React.ReactNode {
        return (
            <Typography variant="caption">
                {this.flowName}: {result}
            </Typography>
        );
    }

    renderEditUI(props: { onClose: () => void; flow: any; flowStep?: any }): React.ReactNode {
        return (
            <CallFlowStepEditUI
                flowName={this.flowName}
                inputValue={this.inputValue}
                flow={props.flow}
                flowStep={this}
            />
        );
    }

    public toJSON(): any {
        const data = DataUtilities.getStorageData(this, ['icon', 'inputValue']) as any;
        data.__type = this.__type;
        data.flowName = this.flowName;
        data.inputValue = this.inputValue.toJSON();
        return data;
    }

    public fromJSON(data: any): void {
        DataUtilities.loadStorageData(this, data, ['inputValue']);
        if (data.flowName !== undefined) {
            this.flowName = data.flowName;
        }
        if (data.inputValue !== undefined) {
            this.inputValue.fromJSON(data.inputValue);
        }
    }
}
