import React from 'react';
import * as THREE from 'three';
import { CNCPoint } from '../../../data/CNCPoint';
import { SimulatorView } from '../../../data/Common/SimulatorView';
import { ConfigurationData } from '../../../data/ConfigurationData';
import { MachineData } from '../../../data/MachineData';
import { MachineStateData } from '../../../data/MachineStateData';
import { CoordinateUtil } from '../../../utils/CoordinateUtil';
import { ObserveState } from '../../../utils/statemanager/ObserveState';

export interface SoftLimitsBoxProps {
  simulatorView: SimulatorView;
  machineData: MachineData;
}

export const SoftLimitsBox: React.FC<SoftLimitsBoxProps> = ({
  simulatorView,
  machineData
}) => {
  // Get configuration colors
  const config = ConfigurationData.Instance;

  // Get soft limits box dimensions and center position using utility method (now synchronous)
  const limitsBox = CoordinateUtil.getSoftLimitsBox(MachineStateData.Instance);

  // Calculate center position (preserve the coordinate type from the box origin)
  const centerPoint = new CNCPoint(
    limitsBox.origin.x + limitsBox.width / 2,
    limitsBox.origin.y + limitsBox.length / 2,
    limitsBox.origin.z + limitsBox.height / 2,
    limitsBox.origin.coordinateType
  );
  const limitsPosition = CoordinateUtil.toSimulator(centerPoint);

  const boxGeometry = new THREE.BoxGeometry(limitsBox.width, limitsBox.length, limitsBox.height);

  return (
    <ObserveState
      listenTo={config}
      properties={['softLimitsColor']}
      control={() => (
        <group position={[limitsPosition.x, limitsPosition.y, limitsPosition.z]}>
          {/* Use edges geometry to show only the box edges without diagonal lines */}
          <lineSegments>
            <edgesGeometry args={[boxGeometry]} />
            <lineBasicMaterial
              color={config.softLimitsColor}
              transparent={true}
              opacity={0.6}
            />
          </lineSegments>
        </group>
      )}
    />
  );
};
