import React from "react";
import { Box, Typography } from '@mui/material';
import { BaseWizardStep } from "../../../Wizard/BaseWizardStep";
import { Wizard } from "../../../Wizard/Wizard";
import { WizardStep } from "../../../Wizard/WizardStep";
import { CNCViewType } from '../../../MachineViewer/CNCViewer';
import { FullSizeCNCViewer } from '../../../MachineViewer/FullSizeCNCViewer';
import { MachineStateData } from '../../../../data/MachineStateData';
import { MachineData } from '../../../../data/MachineData';
import { CoordinateUtil } from '../../../../utils/CoordinateUtil';
import { ObserveState } from '../../../../utils/statemanager/ObserveState';
import { ZAxisReferenceType } from '../common/types';
import { ZJogControls } from '../../../Common/ZJogControls';
import { createCalibrationSimulatorView } from '../common/utils';
import { Job } from '../../../../data/Job';

export class JogControlsStep extends BaseWizardStep {

  constructor(wizard: Wizard, priorStep: WizardStep | null = null) {
    super(wizard, priorStep, "Set Position", "Back");
  }

  getTitle(): string {
    return "Jog Z-Axis to Reference";
  }

  nextStep(): WizardStep | null {
    // Set the final Z position before moving to results
    this.wizard.state.finalZPosition = MachineStateData.Instance.currentMachinePoint.z;
    
    // Dynamic import to avoid circular dependencies
    const ResultsStep = require("./ResultsStep").ResultsStep;
    return new ResultsStep(this.wizard, this);
  }

  backStep(): WizardStep | null {
    // Dynamic import to avoid circular dependencies
    const InstructionsStep = require("./InstructionsStep").InstructionsStep;
    return new InstructionsStep(this.wizard, this.priorStep);
  }

  private getReferenceTitle(): string {
    switch (this.wizard.state.referenceType) {
      case ZAxisReferenceType.BED:
        return 'Machine Bed';
      case ZAxisReferenceType.SPOILBOARD:
        return 'Spoilboard';
      case ZAxisReferenceType.MATERIAL:
        return 'Material Surface';
      default:
        return 'Surface';
    }
  }

  render(): React.ReactNode {
    return this.renderWithButtons(
      <ObserveState
        listenTo={MachineStateData.Instance}
        properties={['currentMachinePoint', 'materialTopZ']}
        control={() => {
          const machineState = MachineStateData.Instance;
          const currentZ = machineState.currentMachinePoint.z;
          const distanceToSpoilboard = CoordinateUtil.distanceToSpoilboard();
          const distanceToBed = CoordinateUtil.distanceToBed();
          const distanceToMaterial = CoordinateUtil.distanceToMaterial();
          const distanceToMachineZero = Math.abs(currentZ); // Distance from current Z to machine zero (Z=0)
          const calibrationSimulatorView = createCalibrationSimulatorView();
          
          return (
            <Box sx={{ display: 'flex', height: '100%' }}>
              <Box sx={{ flex: 1, pr: 3, display: 'flex', flexDirection: 'column' }}>
                <Typography variant="body1" sx={{ mb: 3 }}>
                  With paper under the tool, use the controls below to lower the tool until it just touches the {this.getReferenceTitle().toLowerCase()}.  You should not be able to move the paper, but it should not be too tight.
                  <span style={{ color: 'red' }}> Because we are allowing you to touch the target, the safety checks have been turned off.  Be careful!</span>
                </Typography>
                
                {/* Jog Controls */}
                <ZJogControls />

                {/* Position Information */}
                <Box sx={{ p: 2 }}>
                  {/* Table-like layout for proper number alignment */}
                  <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1 }}>
                    {/* Row 1 */}
                    <Box sx={{ display: 'grid', gridTemplateColumns: '160px 80px 160px 80px', gap: 3, alignItems: 'center' }}>
                      <Typography variant="body2" sx={{ fontFamily: 'monospace' }}>
                        To Machine Zero:
                      </Typography>
                      <Typography variant="body2" sx={{ fontFamily: 'monospace', textAlign: 'right' }}>
                        {distanceToMachineZero.toFixed(3)}"
                      </Typography>
                      <Typography variant="body2" sx={{ fontFamily: 'monospace' }}>
                        To Bed:
                      </Typography>
                      <Typography variant="body2" sx={{ fontFamily: 'monospace', textAlign: 'right' }}>
                        {distanceToBed.toFixed(3)}"
                      </Typography>
                    </Box>
                    
                    {/* Row 2 */}
                    <Box sx={{ display: 'grid', gridTemplateColumns: '160px 80px 160px 80px', gap: 3, alignItems: 'center' }}>
                      <Typography variant="body2" sx={{ fontFamily: 'monospace' }}>
                        To Material:
                      </Typography>
                      <Typography variant="body2" sx={{ fontFamily: 'monospace', textAlign: 'right' }}>
                        {distanceToMaterial.toFixed(3)}"
                      </Typography>
                      <Typography variant="body2" sx={{ fontFamily: 'monospace' }}>
                        To Spoilboard:
                      </Typography>
                      <Typography variant="body2" sx={{ fontFamily: 'monospace', textAlign: 'right' }}>
                        {distanceToSpoilboard.toFixed(3)}"
                      </Typography>
                    </Box>
                  </Box>
                </Box>
              </Box>
              
              <Box sx={{ flex: 1, minHeight: 0 }}>
                <FullSizeCNCViewer
                  enableOrbit={false}
                  enableClampDragging={false}
                  enableSpindleDrag={false}
                  viewType={CNCViewType.ZAxisCalibration}
                  zAxisReferenceType={this.wizard.state.referenceType}
                  simulatorView={calibrationSimulatorView}
                  machineState={MachineStateData.Instance}
                  machineData={MachineData.Instance}
                  job={MachineStateData.Instance.currentJob || Job.createTestJob()}
                />
              </Box>
            </Box>
          );
        }}
      />
    );
  }
}
