import { CNCPoint } from '../../../data/CNCPoint';
import { CoordinateType } from '../../../data/Common/CoordinateType';
import { SimulatorView } from '../../../data/Common/SimulatorView';
import { ViewStyle } from '../../../data/Common/ViewStyle';
import { ConfigurationData } from '../../../data/ConfigurationData';
import { MachineData } from '../../../data/MachineData';
import { MachineStateData } from '../../../data/MachineStateData';
import { CoordinateUtil } from '../../../utils/CoordinateUtil';
import { ObserveMultiProperties } from '../../../utils/statemanager/ObserveMultiProperties';
import { Box } from './Box';

export interface MachineBedProps {
  simulatorView: SimulatorView;
  machineData: MachineData;
}

export function MachineBed({
  simulatorView,
  machineData
}: MachineBedProps) {
  return (
    <ObserveMultiProperties
      listenTo={[
        { object: simulatorView, properties: ['base', 'bed'] },
        { object: ConfigurationData.Instance, properties: ['baseTransparency', 'bedTransparency', 'baseColor', 'bedColor', 'railingColor'] }
      ]}
      control={() => {
        // Get configuration colors
        const config = ConfigurationData.Instance;

        // Get dimensions from machine data
        const baseWidth = machineData.baseWidth;
        const baseHeight = machineData.baseHeight;
        const baseLength = machineData.baseLength;

        const railingWidth = machineData.railingWidth;
        const railingHeight = machineData.railingHeight;
        const railingOutsideBed = machineData.railingOutsideBed;

        // Base positioning - corner at simulator origin (0,0,0), not centered
        const basePosition = CoordinateUtil.toSimulator(
          new CNCPoint(baseWidth / 2, baseLength / 2, baseHeight / 2, CoordinateType.Simulator)
        );

        // Get bed box from CoordinateUtil to ensure consistency
        const bedBox = CoordinateUtil.getBedBox(MachineStateData.Instance);

        // Bed positioning - calculate center point from box origin (which is already in MachineZero)
        // Then convert to simulator coordinates
        const bedCenterMachineZero = new CNCPoint(
          bedBox.origin.x + bedBox.width / 2,   // X: box origin + half width for center
          bedBox.origin.y + bedBox.length / 2,  // Y: box origin + half length for center
          bedBox.origin.z + bedBox.height / 2,  // Z: box origin + half height for center
          bedBox.origin.coordinateType          // Use same coordinate type as origin
        );
        const bedPosition = CoordinateUtil.toSimulator(bedCenterMachineZero);

        // Railing positions - matches C# implementation exactly
        let leftRailingPosition, rightRailingPosition, railingHeightActual;

        if (railingOutsideBed) {
          // Outside bed configuration
          leftRailingPosition = CoordinateUtil.toSimulator(
            new CNCPoint(
              -railingWidth / 2,  // Simplified: -railingWidth + railingWidth/2 = -railingWidth/2
              baseLength / 2,
              baseHeight - 2 + (railingHeight + 2) / 2,
              CoordinateType.Simulator
            )
          );
          rightRailingPosition = CoordinateUtil.toSimulator(
            new CNCPoint(
              baseWidth + railingWidth / 2,
              baseLength / 2,
              baseHeight - 2 + (railingHeight + 2) / 2,
              CoordinateType.Simulator
            )
          );
          railingHeightActual = railingHeight + 2;
        } else {
          // Inside bed configuration
          leftRailingPosition = CoordinateUtil.toSimulator(
            new CNCPoint(
              railingWidth / 2,
              baseLength / 2,
              baseHeight + railingHeight / 2,
              CoordinateType.Simulator
            )
          );
          rightRailingPosition = CoordinateUtil.toSimulator(
            new CNCPoint(
              baseWidth - railingWidth / 2,
              baseLength / 2,
              baseHeight + railingHeight / 2,
              CoordinateType.Simulator
            )
          );
          railingHeightActual = railingHeight;
        }

        // Create unique key for React re-rendering when material properties change
        const renderKey = `machinebed-${ViewStyle[simulatorView.base as keyof typeof ViewStyle]}-${ViewStyle[simulatorView.bed as keyof typeof ViewStyle]}-${ViewStyle[simulatorView.railing as keyof typeof ViewStyle]}-${Date.now()}`;

        return (
          <group key={renderKey}>
            {/* Machine Base */}
            {simulatorView.base !== ViewStyle.Hide && (
              <Box
                position={[basePosition.x, basePosition.y, basePosition.z]}
                size={[baseWidth, baseLength, baseHeight]}
                color={config.baseColor}
                viewStyle={simulatorView.base}
                opacity={simulatorView.base === ViewStyle.SemiTransparent ? config.baseTransparency : 1}
              />
            )}

            {/* Machine Bed */}
            {simulatorView.bed !== ViewStyle.Hide && (
              <Box
                position={[bedPosition.x, bedPosition.y, bedPosition.z]}
                size={[bedBox.width, bedBox.length, bedBox.height]}
                color={config.bedColor}
                viewStyle={simulatorView.bed}
                opacity={simulatorView.bed === ViewStyle.SemiTransparent ? config.bedTransparency : 1}
              />
            )}

            {/* Left Railing - Shown whenever base is visible */}
            {simulatorView.base !== ViewStyle.Hide && (
              <Box
                position={[leftRailingPosition.x, leftRailingPosition.y, leftRailingPosition.z]}
                size={[railingWidth, baseLength, railingHeightActual]}
                color={config.railingColor}
                viewStyle={simulatorView.base}
                opacity={simulatorView.base === ViewStyle.SemiTransparent ? config.baseTransparency : 1}
              />
            )}

            {/* Right Railing - Shown whenever base is visible */}
            {simulatorView.base !== ViewStyle.Hide && (
              <Box
                position={[rightRailingPosition.x, rightRailingPosition.y, rightRailingPosition.z]}
                size={[railingWidth, baseLength, railingHeightActual]}
                color={config.railingColor}
                viewStyle={simulatorView.base}
                opacity={simulatorView.base === ViewStyle.SemiTransparent ? config.baseTransparency : 1}
              />
            )}
          </group>
        );
      }}
    />
  );
}
