import React, { useState } from 'react';
import {
  Box,
  Typography,
  Card,
  CardContent,
  Link,
  Grid,
  Divider,
  IconButton,
} from '@mui/material';
import {
  Star as StarIcon,
  TrendingUp as TrendingUpIcon,
  Visibility as VisibilityIcon,
} from '@mui/icons-material';
import { UserActionData } from '../../data/UserActionData';
import { ObserveState } from '../../utils/statemanager/ObserveState';
import { UserActionRegistry, type IUserAction } from '../../utils/userActions';

interface QuickActionsProps {
  onViewChange?: (view: string) => void;
  showSeeAllLink?: boolean;
}

interface ActionLinkProps {
  action: IUserAction;
  onClick: (actionId: string) => void;
  showUsageCount?: boolean;
}

const ActionLink: React.FC<ActionLinkProps> = ({
  action,
  onClick,
  showUsageCount = false
}) => {
  const Icon = action.icon;
  const [isHovering, setIsHovering] = React.useState(false);
  const userActionData = UserActionData.Instance;
  const isFavorite = userActionData.isFavorite(action.id);
  const usageStats = showUsageCount ? userActionData.getActionUsage(action.id) : undefined;
  
  const handleFavoriteClick = (e: React.MouseEvent) => {
    e.stopPropagation();
    userActionData.toggleFavorite(action.id);
  };
  
  return (
    <Box
      onMouseEnter={() => setIsHovering(true)}
      onMouseLeave={() => setIsHovering(false)}
      sx={{
        position: 'relative',
        display: 'flex',
        alignItems: 'center',
        width: '100%',
      }}
    >
      <Link
        component="button"
        variant="body2"
        onClick={() => onClick(action.id)}
        disabled={action.enabled === false}
        sx={{
          display: 'flex',
          alignItems: 'center',
          gap: 1.5,
          py: 1,
          px: 0,
          pr: isHovering || isFavorite ? 4 : 0, // Make room for star
          textDecoration: 'none',
          color: action.enabled === false ? 'text.disabled' : 'text.primary',
          cursor: action.enabled === false ? 'not-allowed' : 'pointer',
          borderRadius: 1,
          '&:hover': {
            backgroundColor: action.enabled === false ? 'transparent' : 'action.hover',
            textDecoration: 'none',
          },
          background: 'none',
          border: 'none',
          textAlign: 'left',
          width: '100%',
          transition: 'background-color 0.2s, padding-right 0.2s',
        }}
      >
        <Icon sx={{ 
          fontSize: 18, 
          color: action.enabled === false ? 'text.disabled' : 'primary.main' 
        }} />
        <Box sx={{ flex: 1 }}>
          <Typography variant="body2" sx={{ 
            color: 'inherit',
            fontWeight: 500,
          }}>
            {action.name}
            {usageStats && (
              <Typography component="span" variant="body2" sx={{ 
                color: 'text.secondary',
                fontWeight: 400,
                ml: 0.5
              }}>
                ({usageStats.count})
              </Typography>
            )}
          </Typography>
        </Box>
      </Link>
      
      {/* Star icon - shows on hover or if favorited */}
      {(isHovering || isFavorite) && (
        <IconButton
          size="small"
          onClick={handleFavoriteClick}
          sx={{
            position: 'absolute',
            right: 0,
            top: '50%',
            transform: 'translateY(-50%)',
            padding: 0.5,
            transition: 'all 0.2s',
            '&:hover': {
              backgroundColor: 'action.hover',
              transform: 'translateY(-50%) scale(1.1)',
            },
          }}
        >
          {isFavorite ? (
            <StarIcon sx={{ 
              fontSize: 16, 
              color: 'warning.main' // Gold color for favorites
            }} />
          ) : (
            <StarIcon sx={{ 
              fontSize: 16, 
              color: 'text.secondary',
              '&:hover': { color: 'warning.main' }
            }} />
          )}
        </IconButton>
      )}
    </Box>
  );
};

const SpecialActionSection: React.FC<{
  title: string;
  icon: React.ComponentType<any>;
  actions: IUserAction[];
  onActionClick: (actionId: string) => void;
  showUsageCount?: boolean;
  emptyMessage: string;
}> = ({ title, icon: Icon, actions, onActionClick, showUsageCount = false, emptyMessage }) => (
  <Card 
    variant="outlined" 
    sx={{ 
      mb: 0.5, 
      height: 'fit-content',
      transition: 'box-shadow 0.2s, border-color 0.2s',
      border: '2px solid',
      borderColor: actions.length > 0 ? 'primary.main' : 'divider',
      background: actions.length > 0 ? 'linear-gradient(145deg, rgba(25, 118, 210, 0.03), rgba(25, 118, 210, 0.01))' : 'background.paper',
      '&:hover': { 
        boxShadow: actions.length > 0 ? 4 : 2,
        borderColor: actions.length > 0 ? 'primary.dark' : 'primary.light'
      }
    }}
  >
    <CardContent sx={{ p: 2.5, '&:last-child': { pb: 2.5 } }}>
      <Box sx={{ display: 'flex', alignItems: 'center', mb: 1.5 }}>
        <Icon sx={{ 
          mr: 1.5, 
          color: actions.length > 0 ? 'primary.main' : 'text.secondary',
          fontSize: 24 
        }} />
        <Typography variant="h6" sx={{ 
          fontWeight: 600, 
          fontSize: '17px',
          color: actions.length > 0 ? 'primary.main' : 'text.secondary'
        }}>
          {title}
        </Typography>
      </Box>
      <Divider sx={{ mb: 1.5, borderColor: actions.length > 0 ? 'primary.light' : 'divider' }} />
      
      {actions.length === 0 ? (
        <Box sx={{ 
          textAlign: 'center', 
          py: 2,
          color: 'text.secondary'
        }}>
          <Typography variant="body2" sx={{ fontStyle: 'italic' }}>
            {emptyMessage}
          </Typography>
        </Box>
      ) : (
        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 0.25 }}>
          {actions.map((action) => (
            <ActionLink
              key={action.id}
              action={action}
              onClick={onActionClick}
              showUsageCount={showUsageCount}
            />
          ))}
        </Box>
      )}
    </CardContent>
  </Card>
);

export function QuickActions({ onViewChange, showSeeAllLink = true }: QuickActionsProps) {
  const registry = UserActionRegistry.Instance;
  const [actionsInitialized, setActionsInitialized] = useState(false);

  // Check if actions are initialized with persistent checking
  React.useEffect(() => {
    let checkInterval: NodeJS.Timeout;
    
    const checkActions = () => {
      const actionCount = registry.getAllActions().length;
      if (actionCount > 0) {
        setActionsInitialized(true);
        if (checkInterval) {
          clearInterval(checkInterval);
        }
      }
    };
    
    // Check immediately
    checkActions();
    
    // If not initialized, keep checking every 500ms until actions are loaded
    if (!actionsInitialized) {
      checkInterval = setInterval(checkActions, 500);
    }
    
    return () => {
      if (checkInterval) {
        clearInterval(checkInterval);
      }
    };
  }, [registry, actionsInitialized]);

  if (!actionsInitialized) {
    return (
      <Box sx={{ padding: 2, textAlign: 'center' }}>
        <Typography variant="body2" color="textSecondary">
          Loading actions...
        </Typography>
      </Box>
    );
  }

  const handleActionClick = async (actionId: string) => {
    try {
      await registry.executeAction(actionId);
      // Record that this action was used
      UserActionData.Instance.recordActionUsage(actionId);
    } catch (error) {
      console.error('Failed to execute action:', error);
    }
  };

  const handleSeeAllClick = () => {
    if (onViewChange) {
      onViewChange('actions');
    }
  };

  return (
    <ObserveState
      listenTo={[UserActionData.Instance]}
      properties={['favoriteActionIds', 'actionUsageStats']}
      control={() => {
        // Don't render until actions are initialized
        if (!actionsInitialized) {
          return (
            <Box sx={{ p: 2, textAlign: 'center' }}>
              <Typography variant="body2" sx={{ color: 'text.secondary' }}>
                Loading actions...
              </Typography>
            </Box>
          );
        }

        const userActionData = UserActionData.Instance;
        // //console.log('QuickActions: ObserveState triggered, favorites count:', userActionData.favoriteActionIds.length);

        // Helper function to get action by ID if it exists
        const getActionById = (actionId: string): IUserAction | undefined => {
          return registry.getAllActions().find(action => action.id === actionId);
        };

        // Get favorite actions that still exist
        const favoriteActions = userActionData.favoriteActionIds
          .map(id => getActionById(id))
          .filter((action): action is IUserAction => action !== undefined);

        // Get popular actions that still exist
        const popularActionStats = userActionData.getMostPopularActions(10);
        const popularActions = popularActionStats
          .map(stats => getActionById(stats.actionId))
          .filter((action): action is IUserAction => action !== undefined);

        // Determine how many popular actions to show (same as favorites, min 3)
        const numToShow = Math.max(3, favoriteActions.length);
        const displayedPopularActions = popularActions.slice(0, numToShow);

        return (
          <Box>
            {/* Favorite and Popular Actions Section */}
            <Grid container spacing={1} sx={{ mb: showSeeAllLink ? 1.5 : 0 }}>
              {/* Favorite Actions */}
              <Grid item xs={12} md={6}>
                <SpecialActionSection
                  title="Favorite Actions"
                  icon={StarIcon}
                  actions={favoriteActions}
                  onActionClick={handleActionClick}
                  emptyMessage="No favorite actions yet."
                />
              </Grid>

              {/* Popular Actions */}
              <Grid item xs={12} md={6}>
                <SpecialActionSection
                  title="Popular Actions"
                  icon={TrendingUpIcon}
                  actions={displayedPopularActions}
                  onActionClick={handleActionClick}
                  showUsageCount={true}
                  emptyMessage="No usage data yet."
                />
              </Grid>
            </Grid>

            {/* See All Link */}
            {showSeeAllLink && (
              <Box sx={{ textAlign: 'center', mt: 1 }}>
                <Link
                  component="button"
                  variant="body2"
                  onClick={handleSeeAllClick}
                  sx={{
                    display: 'inline-flex',
                    alignItems: 'center',
                    gap: 0.5,
                    textDecoration: 'none',
                    color: 'primary.main',
                    fontWeight: 500,
                    '&:hover': {
                      textDecoration: 'underline',
                    },
                  }}
                >
                  <VisibilityIcon sx={{ fontSize: 16 }} />
                  See All Actions
                </Link>
              </Box>
            )}
          </Box>
        );
      }}
    />
  );
}
