  // Travel limits method with caching
  async GetTravelLimits(): Promise<TravelLimitsResult | null> {
    // Return cached value if available
    if (this.cachedTravelLimits) {
      return this.cachedTravelLimits;
    }

    try {
      const response = await this.api.apiCNCConfigurationGetTravelLimitsGet();

      // Check if we got valid axis data
      if (!response.axes || response.axes.length === 0) {
        Logger.Instance.log(LogCategory.System, 'No travel limits available from API');
        return null;
      }

      // Find X, Y, Z axes in the response
      const xAxis = response.axes.find(a => a.axisLabel === 'X');
      const yAxis = response.axes.find(a => a.axisLabel === 'Y');
      const zAxis = response.axes.find(a => a.axisLabel === 'Z');

      // If we don't have all three primary axes, return null
      if (!xAxis || !yAxis || !zAxis) {
        Logger.Instance.log(LogCategory.System, 'Travel limits missing required X, Y, or Z axis');
        return null;
      }

      // Extract limits (API returns in MachineHome coordinates)
      const minX = xAxis.minusLimit ?? 0;
      const maxX = xAxis.plusLimit ?? 0;
      const minY = yAxis.minusLimit ?? 0;
      const maxY = yAxis.plusLimit ?? 0;
      const minZ = zAxis.minusLimit ?? 0;
      const maxZ = zAxis.plusLimit ?? 0;

      // Create CNCPoints in MachineHome coordinates
      const min = new CNCPoint(minX, minY, minZ, CoordinateType.MachineHome);
      const max = new CNCPoint(maxX, maxY, maxZ, CoordinateType.MachineHome);

      // Cache the result
      this.cachedTravelLimits = { min, max };

      Logger.Instance.log(
        LogCategory.System,
        `Retrieved travel limits from API: X[${minX} to ${maxX}], Y[${minY} to ${maxY}], Z[${minZ} to ${maxZ}] (MachineHome coordinates)`
      );

      return this.cachedTravelLimits;
    } catch (error) {
      Logger.Instance.logError(LogCategory.System, 'Failed to get travel limits from API:', error);
      return null;
    }
  }

  /**
   * Clear the cached travel limits (call when machine configuration changes)
   */
  public clearTravelLimitsCache(): void {
    this.cachedTravelLimits = null;
  }
