import {
    Alert,
    FormControl,
    InputLabel,
    MenuItem,
    Select,
    SelectChangeEvent
} from '@mui/material';
import React, { useEffect, useState } from 'react';
import { Flow } from '../../flow/Flow';
import { FlowStep } from '../../flow/FlowStep';
import { FlowStepData } from '../../flow/FlowStepData';

export interface FlowDataSelectorProps {
    flow: Flow; // Required - flow context must be available
    flowStep: FlowStep; // Required - current step context
    allowedTypes: string[]; // Array of allowed type names (e.g., ['cncpoint', 'number', 'boolean', 'string'])
    currentSelection: string[]; // Array of currently selected paths (for single select, use first item)
    onChange: (selectedPaths: string[], selectedValues: any[]) => void; // Callback for selection changes
    label?: string;
    multiSelect?: boolean; // Whether to allow multiple selections (default: false)
}

interface SelectableItem {
    path: string;
    name: string;
    value: any;
    type: string;
}

export function FlowDataSelector({
    flow,
    flowStep,
    allowedTypes,
    currentSelection,
    onChange,
    label = 'Select Data',
    multiSelect = false
}: FlowDataSelectorProps) {

    // State for flow data (since getDataAtStep is async)
    const [flowData, setFlowData] = useState<FlowStepData | undefined>(undefined);

    // Get flow data asynchronously when flow and flowStep change
    useEffect(() => {
        flow.getDataAtStep(flowStep.id).then(data => {
            setFlowData(data);
        }).catch(error => {
            console.error('Failed to get flow data:', error);
            setFlowData(undefined);
        });
    }, [flow, flowStep]);

    // Get all selectable items from flow data
    const selectableItems = React.useMemo(() => {
        if (!flowData) return [];

        const items: SelectableItem[] = [];

        const addSelectableItems = (obj: any, parentPath: string = '') => {
            if (!obj || typeof obj !== 'object') return;

            Object.keys(obj).forEach(key => {
                const value = obj[key];
                const currentPath = parentPath ? `${parentPath}.${key}` : key;
                const type = getValueType(value);

                // Skip adding raw 'elements' array items - they're not meaningful for selection
                const isElementsArray = key === 'elements' && Array.isArray(value);

                // Only add items that match allowed types (or if allowedTypes is empty, allow all)
                // but skip elements arrays
                if (!isElementsArray && (allowedTypes.length === 0 || allowedTypes.includes(type))) {
                    items.push({
                        path: currentPath,
                        name: formatDisplayName(currentPath),
                        value,
                        type
                    });
                }

                // Recursively check nested objects
                if (typeof value === 'object' && value !== null && !Array.isArray(value)) {
                    addSelectableItems(value, currentPath);
                }

                // Also check array elements, but skip the raw elements array
                if (Array.isArray(value) && !isElementsArray) {
                    value.forEach((item, index) => {
                        const arrayPath = `${currentPath}[${index}]`;
                        const itemType = getValueType(item);

                        if (allowedTypes.length === 0 || allowedTypes.includes(itemType)) {
                            items.push({
                                path: arrayPath,
                                name: formatDisplayName(arrayPath),
                                value: item,
                                type: itemType
                            });
                        }

                        // Recursively check array objects
                        if (typeof item === 'object' && item !== null && !Array.isArray(item)) {
                            addSelectableItems(item, arrayPath);
                        }
                    });
                }
            });
        };

        // Get all data from FlowStepData (both elements and variables)
        const allData = flowData.getAllData();
        addSelectableItems(allData);

        return items;
    }, [flowData, allowedTypes]);

    const handleSelectionChange = (event: SelectChangeEvent<string>) => {
        const selectedPath = event.target.value;
        const selectedItem = selectableItems.find(item => item.path === selectedPath);

        if (selectedItem) {
            onChange([selectedPath], [selectedItem.value]);
        } else {
            onChange([], []);
        }
    };

    // No flow data available yet
    if (!flowData) {
        return (
            <Alert severity="info" sx={{ mt: 1 }}>
                Loading flow data... Run previous steps to populate data.
            </Alert>
        );
    }

    // No selectable items found
    if (selectableItems.length === 0) {
        return (
            <Alert severity="warning" sx={{ mt: 1 }}>
                No {allowedTypes.join(' or ')} data found in flow.
            </Alert>
        );
    }

    const currentValue = currentSelection.length > 0 ? currentSelection[0] : '';

    return (
        <FormControl fullWidth margin="normal">
            <InputLabel>{label}</InputLabel>
            <Select
                value={currentValue}
                label={label}
                onChange={handleSelectionChange}
            >
                <MenuItem value="">
                    <em>None</em>
                </MenuItem>
                {selectableItems.map((item) => (
                    <MenuItem key={item.path} value={item.path}>
                        {item.name} ({item.type})
                    </MenuItem>
                ))}
            </Select>
        </FormControl>
    );
}

/**
 * Determine the type of a value for filtering
 */
function getValueType(value: any): string {
    if (value === null || value === undefined) {
        return 'null';
    }

    if (typeof value === 'number') {
        return 'number';
    }

    if (typeof value === 'boolean') {
        return 'boolean';
    }

    if (typeof value === 'string') {
        return 'string';
    }

    // Check for CNCPoint
    if (value && typeof value === 'object' && 'x' in value && 'y' in value && 'z' in value) {
        return 'cncpoint';
    }

    // Check for Tool
    if (value && typeof value === 'object' && 'toolNumber' in value) {
        return 'tool';
    }

    if (Array.isArray(value)) {
        return 'array';
    }

    if (typeof value === 'object') {
        return 'object';
    }

    return 'unknown';
}

/**
 * Format a path for display (make it more readable)
 */
function formatDisplayName(path: string): string {
    return path
        .split('.')
        .map(part => {
            // Capitalize first letter and add spaces before uppercase letters
            return part.charAt(0).toUpperCase() + part.slice(1).replace(/([A-Z])/g, ' $1');
        })
        .join(' → ');
}