import { ContentCopy, ExpandMore, Info } from '@mui/icons-material';
import {
  Accordion,
  AccordionDetails,
  AccordionSummary,
  Alert,
  Box,
  Button,
  FormControl,
  FormControlLabel,
  Grid,
  InputLabel,
  MenuItem,
  Select,
  Switch,
  TextField,
  Typography
} from '@mui/material';
import React, { useEffect, useState } from 'react';
import { CNCPoint } from '../../../data/CNCPoint';
import { CoordinateType } from '../../../data/Common/CoordinateType';
import { UnitOfMeasure } from '../../../data/Common/UnitOfMeasure';
import { MachineData, XDirection, ZZeroLocation } from '../../../data/MachineData';
import { MachineStateData } from '../../../data/MachineStateData';
import { UserMessageQueue } from '../../../data/UserMessageQueue';
import { ConfirmDialogManager } from '../../../utils/ConfirmDialogManager';
import { CoordinateUtil } from '../../../utils/CoordinateUtil';
import { SoftLimitsUtil } from '../../../utils/SoftLimitsUtil';
import { ObserveMultiProperties } from '../../../utils/statemanager/ObserveMultiProperties';
import { StateManager } from '../../../utils/statemanager/StateManager';
import { ATCToolClampComponent } from '../../Common/ATCToolHolderComponent';
import { NumberInput } from '../../Common/NumberInput';

export const CoordinateSystemTab: React.FC = () => {
  const [expandedSections, setExpandedSections] = useState<Record<string, boolean>>({
    general: false,
    machineZero: false,
    simulatorOrigin: false,
    softLimits: false,
    atcConfiguration: false,
    fixedTouchPlate: false,
    movableTouchPlate: false
  });

  const [limitsFromAPI, setLimitsFromAPI] = useState<boolean>(false);

  // Check if soft limits are from API when component mounts or soft limits section expands
  useEffect(() => {
    if (expandedSections.softLimits) {
      setLimitsFromAPI(SoftLimitsUtil.areLimitsFromAPI());
    }
  }, [expandedSections.softLimits]);

  const handleSectionToggle = (section: string) => {
    setExpandedSections(prev => ({
      ...prev,
      [section]: !prev[section]
    }));
  };

  const handleCaptureLowerLimits = () => {
    const machine = MachineData.Instance;
    const currentPos = MachineStateData.Instance.currentMachinePoint;

    machine.xLowerSoftLimitFromMachineZero = currentPos.x;
    machine.yLowerSoftLimitFromMachineZero = currentPos.y;
    machine.zLowerSoftLimitFromMachineZero = currentPos.z;
  };

  const handleCaptureUpperLimits = () => {
    const machine = MachineData.Instance;
    const currentPos = MachineStateData.Instance.currentMachinePoint;

    machine.xUpperSoftLimitFromMachineZero = currentPos.x;
    machine.yUpperSoftLimitFromMachineZero = currentPos.y;
    machine.zUpperSoftLimitFromMachineZero = currentPos.z;
  };

  const handleCaptureMachineZero = async () => {
    // Show warning dialog before proceeding
    const confirmed = await ConfirmDialogManager.Instance.showConfirm({
      title: 'Capture Machine Zero',
      message: 'Changing machine zero will affect all machine coordinate references including ATC positions, touch probe locations, turning center, and other machine features. This may invalidate previously configured positions. Are you sure you want to continue?',
      confirmText: 'Yes, Capture Machine Zero',
      severity: 'warning',
    });

    if (!confirmed) {
      return;
    }

    const machine = MachineData.Instance;
    const machineState = MachineStateData.Instance;
    const currentPos = machineState.currentMachinePoint;

    // Capture the current position in Machine Home coordinates before we change the offset
    const machineHomePos = CoordinateUtil.toMachineHome(currentPos);

    // Update the Machine Zero offset to make the current position be at (0,0,0) in Machine Zero coordinates
    machine.machineZeroCoordinatesFromMachineHomeX = machineHomePos.x;
    machine.machineZeroCoordinatesFromMachineHomeY = machineHomePos.y;
    machine.machineZeroCoordinatesFromMachineHomeZ = machineHomePos.z;

    // The machine didn't physically move, so update the current position to be (0,0,0) in the new Machine Zero coordinates
    machineState.currentMachinePoint = CoordinateUtil.toMachineZero(machineHomePos);
  };

  const handleCopyCoordinatesToClipboard = async () => {
    const machine = MachineData.Instance;

    // Get computed offsets from CoordinateUtil
    const simulatorOffsetFromMachineZero = CoordinateUtil.getSimulatorOffsetFromMachineZero();
    const machineHomeOffsetFromMachineZero = CoordinateUtil.getMachineHomeOffsetFromMachineZero();
    const workZeroOffsetFromMachineZero = CoordinateUtil.getWorkZeroOffsetFromMachineZero();
    const workZeroWithOffsetsOffsetFromMachineZero = CoordinateUtil.getWorkZeroWithOffsetsOffsetFromMachineZero();

    // Create points at (0,0,0) in their native coordinate systems, then convert to MachineZero
    const simulatorOrigin = new CNCPoint(0, 0, 0, CoordinateType.Simulator);
    const machineHomeOrigin = new CNCPoint(0, 0, 0, CoordinateType.MachineHome);
    const machineZeroOrigin = new CNCPoint(0, 0, 0, CoordinateType.MachineZero);

    // Convert all to MachineZero coordinate system
    const simulatorOriginInMachineZero = CoordinateUtil.toMachineZero(simulatorOrigin);
    const machineHomeOriginInMachineZero = CoordinateUtil.toMachineZero(machineHomeOrigin);
    const machineZeroOriginInMachineZero = CoordinateUtil.toMachineZero(machineZeroOrigin); // Should be 0,0,0

    // Also convert to MachineHome for legacy display
    const simulatorOriginInMachineHome = CoordinateUtil.toMachineHome(simulatorOrigin);
    const machineZeroInMachineHome = CoordinateUtil.toMachineHome(machineZeroOrigin);
    const machineHomeInMachineHome = CoordinateUtil.toMachineHome(machineHomeOrigin); // Should be 0,0,0

    // Get vertical table box for debugging
    const machineState = MachineStateData.Instance;
    const verticalTableBox = CoordinateUtil.getVerticalTableBox(machineState);
    const baseTopCorner = CoordinateUtil.getMachineBaseTopCornerPosition();

    // Build clipboard text
    const clipboardText = `HavenCNC Coordinate System Information
==========================================

ORIGIN POINTS CONVERTED TO MACHINEZERO COORDINATES:
----------------------------------------------------
Simulator Origin (0,0,0 in Simulator) → MachineZero:
  X: ${simulatorOriginInMachineZero.x.toFixed(3)}
  Y: ${simulatorOriginInMachineZero.y.toFixed(3)}
  Z: ${simulatorOriginInMachineZero.z.toFixed(3)}

Machine Home Origin (0,0,0 in MachineHome) → MachineZero:
  X: ${machineHomeOriginInMachineZero.x.toFixed(3)}
  Y: ${machineHomeOriginInMachineZero.y.toFixed(3)}
  Z: ${machineHomeOriginInMachineZero.z.toFixed(3)}

Machine Zero Origin (0,0,0 in MachineZero) → MachineZero:
  X: ${machineZeroOriginInMachineZero.x.toFixed(3)}
  Y: ${machineZeroOriginInMachineZero.y.toFixed(3)}
  Z: ${machineZeroOriginInMachineZero.z.toFixed(3)}


KEY COORDINATES (in Machine Home coordinate system):
---------------------------------------------------
Simulator Origin (0,0,0):
  X: ${simulatorOriginInMachineHome.x.toFixed(3)}
  Y: ${simulatorOriginInMachineHome.y.toFixed(3)}
  Z: ${simulatorOriginInMachineHome.z.toFixed(3)}

Machine Zero:
  X: ${machineZeroInMachineHome.x.toFixed(3)}
  Y: ${machineZeroInMachineHome.y.toFixed(3)}
  Z: ${machineZeroInMachineHome.z.toFixed(3)}

Machine Home:
  X: ${machineHomeInMachineHome.x.toFixed(3)}
  Y: ${machineHomeInMachineHome.y.toFixed(3)}
  Z: ${machineHomeInMachineHome.z.toFixed(3)}


STORED CONFIGURATION VALUES:
-----------------------------
Machine Zero Coordinates from Machine Home:
  X: ${machine.machineZeroCoordinatesFromMachineHomeX.toFixed(3)}
  Y: ${machine.machineZeroCoordinatesFromMachineHomeY.toFixed(3)}
  Z: ${machine.machineZeroCoordinatesFromMachineHomeZ.toFixed(3)}

Base Height: ${machine.baseHeight.toFixed(3)}

Machine Base Top Corner from Machine Zero:
  X: ${machine.machineBaseTopCornerFromMachineZeroX.toFixed(3)}
  Y: ${machine.machineBaseTopCornerFromMachineZeroY.toFixed(3)}
  Z: ${machine.machineBaseTopCornerFromMachineZeroZ.toFixed(3)}


COMPUTED OFFSETS FROM MACHINEZERO (from CoordinateUtil):
---------------------------------------------------------
Simulator Offset from MachineZero:
  X: ${simulatorOffsetFromMachineZero.x.toFixed(3)}
  Y: ${simulatorOffsetFromMachineZero.y.toFixed(3)}
  Z: ${simulatorOffsetFromMachineZero.z.toFixed(3)}

Machine Home Offset from MachineZero:
  X: ${machineHomeOffsetFromMachineZero.x.toFixed(3)}
  Y: ${machineHomeOffsetFromMachineZero.y.toFixed(3)}
  Z: ${machineHomeOffsetFromMachineZero.z.toFixed(3)}

Work Zero Offset from MachineZero:
  X: ${workZeroOffsetFromMachineZero.x.toFixed(3)}
  Y: ${workZeroOffsetFromMachineZero.y.toFixed(3)}
  Z: ${workZeroOffsetFromMachineZero.z.toFixed(3)}

Work Zero With Offsets (Tool Tip) Offset from MachineZero:
  X: ${workZeroWithOffsetsOffsetFromMachineZero.x.toFixed(3)}
  Y: ${workZeroWithOffsetsOffsetFromMachineZero.y.toFixed(3)}
  Z: ${workZeroWithOffsetsOffsetFromMachineZero.z.toFixed(3)}


VERTICAL TABLE DEBUG:
---------------------
Machine Base Top Corner Position (MachineZero coords):
  X: ${baseTopCorner.x.toFixed(3)}
  Y: ${baseTopCorner.y.toFixed(3)}
  Z: ${baseTopCorner.z.toFixed(3)}

Vertical Table Offset (from base top):
  X: ${machine.verticalTableOffsetX.toFixed(3)}
  Y: ${machine.verticalTableOffsetY.toFixed(3)}
  Z: ${machine.verticalTableOffsetZ.toFixed(3)}

Vertical Table Dimensions:
  Width: ${machine.verticalTableWidth.toFixed(3)}
  Thickness: ${machine.verticalTableThickness.toFixed(3)}
  Height: ${machine.verticalTableHeight.toFixed(3)}

${verticalTableBox ? `Vertical Table Box Origin (MachineZero coords):
  X: ${verticalTableBox.origin.x.toFixed(3)}
  Y: ${verticalTableBox.origin.y.toFixed(3)}
  Z: ${verticalTableBox.origin.z.toFixed(3)}` : 'Vertical Table: DISABLED'}


COORDINATE SYSTEM REFERENCE:
----------------------------
- Simulator Origin (0,0,0): Physical machine base corner (front-left-bottom)
- Machine Home: Maximum travel limits corner
- Machine Zero: Reference point for all machine operations
- Points shown above are created at (0,0,0) in their native coordinate system and converted
`;

    try {
      await navigator.clipboard.writeText(clipboardText);
      UserMessageQueue.Instance.addMessage('✓ Coordinate information copied to clipboard');
    } catch (error) {
      UserMessageQueue.Instance.addMessage('❌ Failed to copy to clipboard');
    }
  };

  const machine = MachineData.Instance;

  // Build listenTo array to watch MachineData and individual axis configs
  const listenToObjects: Array<{ object: any; properties: string[] }> = [
    {
      object: machine,
      properties: [
        'machineName', 'unitOfMeasure', 'xDirection', 'zLocation',
        'machineZeroCoordinatesFromMachineHomeX',
        'machineZeroCoordinatesFromMachineHomeY',
        'machineZeroCoordinatesFromMachineHomeZ',
        'machineBaseTopCornerFromMachineZeroX',
        'machineBaseTopCornerFromMachineZeroY',
        'machineBaseTopCornerFromMachineZeroZ',
        'baseHeight',
        'xLowerSoftLimitFromMachineZero', 'xUpperSoftLimitFromMachineZero',
        'yLowerSoftLimitFromMachineZero', 'yUpperSoftLimitFromMachineZero',
        'zLowerSoftLimitFromMachineZero', 'zUpperSoftLimitFromMachineZero',
        'hasATC', 'atcNumberOfTools', 'atcToolClamps',
        'xyApproachSpeed', 'zApproachSpeed', 'xyDockSpeed', 'zDockSpeed',
        'atcVerticalClearance', 'atcHorizontalClearance', 'atcApproachAxis',
        'hasFixedTouchPlate', 'fixedTouchPlateX', 'fixedTouchPlateY', 'fixedTouchPlateZ',
        'fixedTouchPlateFastSpeed', 'fixedTouchPlateSlowSpeed',
        'hasMovableTouchPlate', 'movableTouchPlateFastSpeed', 'movableTouchPlateSlowSpeed', 'movableTouchPlateHeight'
      ]
    }
  ];

  return (
    <ObserveMultiProperties
      key="coordinate-system-tab"
      listenTo={listenToObjects}
      control={() => (
        <Box sx={{ p: 3 }}>
          <Typography variant="h6" gutterBottom>
            Coordinate System Configuration
          </Typography>
          <Typography variant="body2" color="text.secondary" sx={{ mb: 3 }}>
            Configure coordinate system settings, machine zero position, and travel limits.
          </Typography>

          {/* General */}
          <Accordion
            expanded={expandedSections.general}
            onChange={() => handleSectionToggle('general')}
            sx={{ mb: 2 }}
          >
            <AccordionSummary expandIcon={<ExpandMore />}>
              <Typography variant="h6">General</Typography>
            </AccordionSummary>
            <AccordionDetails>
              <Box sx={{ mb: 2, p: 2, backgroundColor: '#f5f5f5', borderRadius: 1 }}>
                <Typography variant="body2" color="text.secondary">
                  <strong>Reference Point:</strong> General machine configuration settings that apply globally to all machine operations.
                  These settings define the fundamental coordinate system orientation, units of measurement, and machine identification.
                </Typography>
              </Box>
              <Grid container spacing={3}>
                <Grid item xs={12} md={6}>
                  <TextField
                    fullWidth
                    label="Machine Name"
                    value={machine.machineName}
                    onChange={(e) => machine.machineName = e.target.value}
                    margin="normal"
                  />

                  <FormControl fullWidth margin="normal">
                    <InputLabel>Unit of Measure</InputLabel>
                    <Select
                      value={machine.unitOfMeasure}
                      onChange={(e) => machine.unitOfMeasure = e.target.value as UnitOfMeasure}
                    >
                      <MenuItem value={UnitOfMeasure.Inches}>Inches</MenuItem>
                      <MenuItem value={UnitOfMeasure.Millimeters}>Millimeters</MenuItem>
                    </Select>
                  </FormControl>
                </Grid>

                <Grid item xs={12} md={6}>
                  <FormControl fullWidth margin="normal">
                    <InputLabel>X Direction</InputLabel>
                    <Select
                      value={machine.xDirection}
                      onChange={(e) => machine.xDirection = e.target.value as XDirection}
                    >
                      <MenuItem value={XDirection.Across}>Across</MenuItem>
                      <MenuItem value={XDirection.Side}>Side</MenuItem>
                    </Select>
                  </FormControl>

                  <FormControl fullWidth margin="normal">
                    <InputLabel>Z Zero Location</InputLabel>
                    <Select
                      value={machine.zLocation}
                      onChange={(e) => machine.zLocation = e.target.value as ZZeroLocation}
                    >
                      <MenuItem value={ZZeroLocation.Top}>Top</MenuItem>
                      <MenuItem value={ZZeroLocation.Bed}>Bed</MenuItem>
                    </Select>
                  </FormControl>
                </Grid>
              </Grid>
            </AccordionDetails>
          </Accordion>

          {/* Machine Zero Coordinates from Limits */}
          <Accordion
            expanded={expandedSections.machineZero}
            onChange={() => handleSectionToggle('machineZero')}
            sx={{ mb: 2 }}
          >
            <AccordionSummary expandIcon={<ExpandMore />}>
              <Typography variant="h6">Machine Zero Coordinates (from Machine Home)</Typography>
            </AccordionSummary>
            <AccordionDetails>
              <Box sx={{ mb: 2, p: 2, backgroundColor: '#f5f5f5', borderRadius: 1 }}>
                <Typography variant="body2" color="text.secondary">
                  These values define the offset of machine zero from the machine home position.
                </Typography>
              </Box>

              <Grid container spacing={3}>
                <Grid item xs={4}>
                  <NumberInput
                    label="X Offset"
                    value={machine.machineZeroCoordinatesFromMachineHomeX}
                    onChange={(value) => machine.machineZeroCoordinatesFromMachineHomeX = value}
                    precision={1}
                    fullWidth
                    helperText="X position offset from home"
                  />
                </Grid>
                <Grid item xs={4}>
                  <NumberInput
                    label="Y Offset"
                    value={machine.machineZeroCoordinatesFromMachineHomeY}
                    onChange={(value) => machine.machineZeroCoordinatesFromMachineHomeY = value}
                    precision={1}
                    fullWidth
                    helperText="Y position offset from home"
                  />
                </Grid>
                <Grid item xs={4}>
                  <NumberInput
                    label="Z Offset"
                    value={machine.machineZeroCoordinatesFromMachineHomeZ}
                    onChange={(value) => machine.machineZeroCoordinatesFromMachineHomeZ = value}
                    precision={1}
                    fullWidth
                    helperText="Z position offset from home"
                  />
                </Grid>

                {/* Capture Machine Zero Button */}
                <Grid item xs={12}>
                  <Button
                    fullWidth
                    variant="outlined"
                    onClick={handleCaptureMachineZero}
                    sx={{ mt: 1 }}
                  >
                    Capture Machine Zero (Set Current Position as Machine Zero)
                  </Button>
                </Grid>
              </Grid>
            </AccordionDetails>
          </Accordion>

          {/* Simulator Origin */}
          <Accordion
            expanded={expandedSections.simulatorOrigin}
            onChange={() => handleSectionToggle('simulatorOrigin')}
            sx={{ mb: 2 }}
          >
            <AccordionSummary expandIcon={<ExpandMore />}>
              <Typography variant="h6">Simulator Origin</Typography>
            </AccordionSummary>
            <AccordionDetails>
              <Box sx={{ mb: 2, p: 2, backgroundColor: '#f5f5f5', borderRadius: 1 }}>
                <Typography variant="body2" color="text.secondary">
                  <strong>Reference Point:</strong> These values define the 3D rendering coordinate system origin.
                  The Simulator Origin is at the front-left-bottom corner of the machine base (0,0,0 in 3D world).
                  These offsets specify where Machine Home is located relative to that origin, measured in Machine Zero coordinates.
                </Typography>
              </Box>

              <Grid container spacing={3}>
                <Grid item xs={12}>
                  <Typography variant="subtitle1" sx={{ mb: 1 }}>Machine Home Position (from Simulator Origin, in Machine Zero coordinates)</Typography>
                  <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                    These values position the machine home corner relative to the 3D rendering origin (Simulator 0,0,0).
                    They define where the maximum travel limits are located in the 3D visualization.
                  </Typography>
                </Grid>

                <Grid item xs={4}>
                  <NumberInput
                    label="X Offset from Simulator Origin"
                    value={machine.machineBaseTopCornerFromMachineZeroX}
                    onChange={(value) => machine.machineBaseTopCornerFromMachineZeroX = value}
                    precision={1}
                    fullWidth
                    helperText="X distance from base corner to machine home"
                  />
                </Grid>
                <Grid item xs={4}>
                  <NumberInput
                    label="Y Offset from Simulator Origin"
                    value={machine.machineBaseTopCornerFromMachineZeroY}
                    onChange={(value) => machine.machineBaseTopCornerFromMachineZeroY = value}
                    precision={1}
                    fullWidth
                    helperText="Y distance from base corner to machine home"
                  />
                </Grid>
                <Grid item xs={4}>
                  <NumberInput
                    label="Z Offset from Base Top"
                    value={machine.machineBaseTopCornerFromMachineZeroZ}
                    onChange={(value) => machine.machineBaseTopCornerFromMachineZeroZ = value}
                    precision={1}
                    fullWidth
                    helperText="Z distance from base top to machine home"
                  />
                </Grid>

                <Grid item xs={12}>
                  <Typography variant="subtitle1" sx={{ mt: 2, mb: 1 }}>Machine Base Height</Typography>
                  <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                    Physical height of the machine base/table structure. This is the Z-height from Simulator Origin (0,0,0) to the top surface of the base.
                  </Typography>
                </Grid>

                <Grid item xs={12} md={6}>
                  <NumberInput
                    label="Base Height"
                    value={machine.baseHeight}
                    onChange={(value) => machine.baseHeight = value}
                    precision={1}
                    fullWidth
                    helperText="Height of machine base structure"
                  />
                </Grid>

                {/* Copy Coordinates Button */}
                <Grid item xs={12}>
                  <Button
                    fullWidth
                    variant="outlined"
                    startIcon={<ContentCopy />}
                    onClick={handleCopyCoordinatesToClipboard}
                    sx={{ mt: 2 }}
                  >
                    Copy Coordinate System Information to Clipboard
                  </Button>
                  <Typography variant="caption" color="text.secondary" sx={{ mt: 1, display: 'block' }}>
                    Copies key coordinates (Simulator Origin, Machine Zero, Machine Home) and offsets in Machine Home coordinate system
                  </Typography>
                </Grid>
              </Grid>
            </AccordionDetails>
          </Accordion>

          {/* Soft Limits */}
          <Accordion
            expanded={expandedSections.softLimits}
            onChange={() => handleSectionToggle('softLimits')}
            sx={{ mb: 2 }}
          >
            <AccordionSummary expandIcon={<ExpandMore />}>
              <Typography variant="h6">Soft Limits</Typography>
            </AccordionSummary>
            <AccordionDetails>
              {limitsFromAPI && (
                <Alert
                  severity="info"
                  icon={<Info />}
                  sx={{ mb: 3 }}
                >
                  <Typography variant="body2">
                    <strong>Travel Limits from Machine Controller:</strong> These limits are provided by the machine controller
                    and cannot be edited here. To change these limits, configure them in the machine controller settings.
                  </Typography>
                </Alert>
              )}
              <Grid container spacing={3}>
                <Grid item xs={12} md={6}>
                  <NumberInput
                    fullWidth
                    label="X Lower Soft Limit"
                    value={machine.xLowerSoftLimitFromMachineZero}
                    onChange={(value) => machine.xLowerSoftLimitFromMachineZero = value}
                    margin="normal"
                    precision={1}
                    disabled={limitsFromAPI}
                  />
                </Grid>

                <Grid item xs={12} md={6}>
                  <NumberInput
                    fullWidth
                    label="X Upper Soft Limit"
                    value={machine.xUpperSoftLimitFromMachineZero}
                    onChange={(value) => machine.xUpperSoftLimitFromMachineZero = value}
                    margin="normal"
                    precision={1}
                    disabled={limitsFromAPI}
                  />
                </Grid>

                <Grid item xs={12} md={6}>
                  <NumberInput
                    fullWidth
                    label="Y Lower Soft Limit"
                    value={machine.yLowerSoftLimitFromMachineZero}
                    onChange={(value) => machine.yLowerSoftLimitFromMachineZero = value}
                    margin="normal"
                    precision={1}
                    disabled={limitsFromAPI}
                  />
                </Grid>

                <Grid item xs={12} md={6}>
                  <NumberInput
                    fullWidth
                    label="Y Upper Soft Limit"
                    value={machine.yUpperSoftLimitFromMachineZero}
                    onChange={(value) => machine.yUpperSoftLimitFromMachineZero = value}
                    margin="normal"
                    precision={1}
                    disabled={limitsFromAPI}
                  />
                </Grid>

                <Grid item xs={12} md={6}>
                  <NumberInput
                    fullWidth
                    label="Z Lower Soft Limit"
                    value={machine.zLowerSoftLimitFromMachineZero}
                    onChange={(value) => machine.zLowerSoftLimitFromMachineZero = value}
                    margin="normal"
                    precision={1}
                    disabled={limitsFromAPI}
                  />
                </Grid>

                <Grid item xs={12} md={6}>
                  <NumberInput
                    fullWidth
                    label="Z Upper Soft Limit"
                    value={machine.zUpperSoftLimitFromMachineZero}
                    onChange={(value) => machine.zUpperSoftLimitFromMachineZero = value}
                    margin="normal"
                    precision={1}
                    disabled={limitsFromAPI}
                  />
                </Grid>

                {/* Capture Buttons */}
                <Grid item xs={12} md={6}>
                  <Button
                    fullWidth
                    variant="outlined"
                    onClick={handleCaptureLowerLimits}
                    disabled={limitsFromAPI}
                    sx={{ mt: 1 }}
                  >
                    Capture Lower Limits (Front, Left, Bottom)
                  </Button>
                </Grid>

                <Grid item xs={12} md={6}>
                  <Button
                    fullWidth
                    variant="outlined"
                    onClick={handleCaptureUpperLimits}
                    disabled={limitsFromAPI}
                    sx={{ mt: 1 }}
                  >
                    Capture Upper Limits (Back, Right, Top)
                  </Button>
                </Grid>
              </Grid>
            </AccordionDetails>
          </Accordion>

          {/* ATC Configuration */}
          <Accordion
            expanded={expandedSections.atcConfiguration}
            onChange={() => handleSectionToggle('atcConfiguration')}
            sx={{ mb: 2 }}
          >
            <AccordionSummary expandIcon={<ExpandMore />}>
              <Typography variant="h6">ATC Configuration</Typography>
            </AccordionSummary>
            <AccordionDetails>
              <Box sx={{ mb: 2, p: 2, backgroundColor: '#f5f5f5', borderRadius: 1 }}>
                <Typography variant="body2" color="text.secondary">
                  Configure basic ATC settings including whether the machine has an ATC, the number of tool holders, and individual tool holder positions.
                  Tool holder positions are automatically arranged in a linear pattern, but can be individually adjusted.
                </Typography>
              </Box>
              <Grid container spacing={3}>
                {/* Has ATC Switch */}
                <Grid item xs={12}>
                  <FormControlLabel
                    control={
                      <Switch
                        checked={machine.hasATC}
                        onChange={(e) => machine.hasATC = e.target.checked}
                      />
                    }
                    label="Has ATC (Automatic Tool Changer)"
                  />
                </Grid>

                {/* ATC Configuration - Only show if hasATC is true */}
                {machine.hasATC && (
                  <>
                    {/* Number of Tools */}
                    <Grid item xs={12} md={6}>
                      <NumberInput
                        fullWidth
                        label="Number of Tools"
                        value={machine.atcNumberOfTools}
                        onChange={(value) => machine.atcNumberOfTools = value}
                        margin="normal"
                        precision={0}
                      />
                      <Typography variant="caption" color="text.secondary">
                        Total number of tool holders in the ATC
                      </Typography>
                    </Grid>

                    {/* Tool Change Speed Settings */}
                    <Grid item xs={12}>
                      <Typography variant="subtitle1" sx={{ mt: 2, mb: 1 }}>Tool Change Speed Settings</Typography>
                      <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                        Configure movement speeds during tool change operations (in/min)
                      </Typography>
                    </Grid>

                    <Grid item xs={12} md={6}>
                      <NumberInput
                        fullWidth
                        label="XY Approach Speed"
                        value={machine.xyApproachSpeed}
                        onChange={(value) => machine.xyApproachSpeed = value}
                        margin="normal"
                        precision={0}
                        min={1}
                        max={1000}
                      />
                      <Typography variant="caption" color="text.secondary">
                        XY axis speed when approaching tool holder (default: 200 in/min)
                      </Typography>
                    </Grid>

                    <Grid item xs={12} md={6}>
                      <NumberInput
                        fullWidth
                        label="Z Approach Speed"
                        value={machine.zApproachSpeed}
                        onChange={(value) => machine.zApproachSpeed = value}
                        margin="normal"
                        precision={0}
                        min={1}
                        max={1000}
                      />
                      <Typography variant="caption" color="text.secondary">
                        Z axis speed when approaching tool holder (default: 100 in/min)
                      </Typography>
                    </Grid>

                    <Grid item xs={12} md={6}>
                      <NumberInput
                        fullWidth
                        label="XY Dock Speed"
                        value={machine.xyDockSpeed}
                        onChange={(value) => machine.xyDockSpeed = value}
                        margin="normal"
                        precision={0}
                        min={1}
                        max={1000}
                      />
                      <Typography variant="caption" color="text.secondary">
                        XY axis speed when docking/undocking tool (default: 30 in/min)
                      </Typography>
                    </Grid>

                    <Grid item xs={12} md={6}>
                      <NumberInput
                        fullWidth
                        label="Z Dock Speed"
                        value={machine.zDockSpeed}
                        onChange={(value) => machine.zDockSpeed = value}
                        margin="normal"
                        precision={0}
                        min={1}
                        max={1000}
                      />
                      <Typography variant="caption" color="text.secondary">
                        Z axis speed when docking/undocking tool (default: 30 in/min)
                      </Typography>
                    </Grid>

                    {/* ATC Clearance Settings */}
                    <Grid item xs={12}>
                      <Typography variant="subtitle1" sx={{ mt: 2, mb: 1 }}>ATC Clearance Settings</Typography>
                      <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                        Safety clearance distances for tool change movements
                      </Typography>
                    </Grid>

                    <Grid item xs={12} md={6}>
                      <NumberInput
                        fullWidth
                        label="Vertical Clearance"
                        value={machine.atcVerticalClearance}
                        onChange={(value) => machine.atcVerticalClearance = value}
                        margin="normal"
                        precision={3}
                      />
                      <Typography variant="caption" color="text.secondary">
                        Z-axis clearance above tool holder (default: 3.000, can be negative)
                      </Typography>
                    </Grid>

                    <Grid item xs={12} md={6}>
                      <NumberInput
                        fullWidth
                        label="Horizontal Clearance"
                        value={machine.atcHorizontalClearance}
                        onChange={(value) => machine.atcHorizontalClearance = value}
                        margin="normal"
                        precision={3}
                      />
                      <Typography variant="caption" color="text.secondary">
                        Horizontal clearance from tool holder (default: 4.000, can be negative)
                      </Typography>
                    </Grid>

                    {/* Approach Axis Selection */}
                    <Grid item xs={12}>
                      <Typography variant="subtitle1" sx={{ mt: 2, mb: 1 }}>Approach Axis</Typography>
                      <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                        Select which axis to use for horizontal approach movements
                      </Typography>
                      <Box sx={{ display: 'flex', gap: 1 }}>
                        <Button
                          variant={machine.atcApproachAxis === 'X' ? 'contained' : 'outlined'}
                          onClick={() => machine.atcApproachAxis = 'X'}
                        >
                          X-Axis
                        </Button>
                        <Button
                          variant={machine.atcApproachAxis === 'Y' ? 'contained' : 'outlined'}
                          onClick={() => machine.atcApproachAxis = 'Y'}
                        >
                          Y-Axis
                        </Button>
                      </Box>
                    </Grid>

                    {/* Tool Holder Positions */}
                    <Grid item xs={12}>
                      <Typography variant="subtitle1" sx={{ mt: 2, mb: 1 }}>Tool Holder Positions</Typography>
                      <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                        Individual tool holder positions relative to the ATC bar center. Use the layout button to automatically arrange tool holders.
                      </Typography>
                      <Box sx={{ mb: 2 }}>
                        <Button
                          variant="contained"
                          onClick={() => {
                            machine.layoutATCClampsApprox();
                          }}
                        >
                          Lay Out ATC Holders (Approx)
                        </Button>
                      </Box>
                    </Grid>

                    {/* Tool Clamp List */}
                    {machine.atcToolClamps.map((clamp: any, index: number) => (
                      <ATCToolClampComponent
                        key={clamp.clampNumber}
                        toolClamp={clamp}
                        onChange={() => {
                          StateManager.propertyChanged(machine, 'atcToolHolders');
                        }}
                      />
                    ))}
                  </>
                )}
              </Grid>
            </AccordionDetails>
          </Accordion>

          {/* Fixed Touch Plate */}
          <Accordion
            expanded={expandedSections.fixedTouchPlate}
            onChange={() => handleSectionToggle('fixedTouchPlate')}
            sx={{ mb: 2 }}
          >
            <AccordionSummary expandIcon={<ExpandMore />}>
              <Typography variant="h6">Fixed Touch Plate</Typography>
            </AccordionSummary>
            <AccordionDetails>
              <Box sx={{ mb: 2, p: 2, backgroundColor: '#f5f5f5', borderRadius: 1 }}>
                <Typography variant="body2" color="text.secondary">
                  Configure a fixed touch plate mounted at a known position on the machine. Used for precise tool length measurement.
                </Typography>
              </Box>
              <Grid container spacing={3}>
                {/* Has Fixed Touch Plate Switch */}
                <Grid item xs={12}>
                  <FormControlLabel
                    control={
                      <Switch
                        checked={machine.hasFixedTouchPlate}
                        onChange={(e) => machine.hasFixedTouchPlate = e.target.checked}
                      />
                    }
                    label="Has Fixed Touch Plate"
                  />
                </Grid>

                {/* Fixed Touch Plate Configuration - Only show if enabled */}
                {machine.hasFixedTouchPlate && (
                  <>
                    {/* Position Coordinates */}
                    <Grid item xs={12}>
                      <Typography variant="subtitle1" sx={{ mt: 1, mb: 1 }}>Touch Plate Position</Typography>
                      <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                        X, Y, Z coordinates of the fixed touch plate surface (in machine zero coordinates)
                      </Typography>
                    </Grid>

                    <Grid item xs={12} md={4}>
                      <NumberInput
                        fullWidth
                        label="X Position"
                        value={machine.fixedTouchPlateX}
                        onChange={(value) => machine.fixedTouchPlateX = value}
                        margin="normal"
                        precision={3}
                      />
                    </Grid>

                    <Grid item xs={12} md={4}>
                      <NumberInput
                        fullWidth
                        label="Y Position"
                        value={machine.fixedTouchPlateY}
                        onChange={(value) => machine.fixedTouchPlateY = value}
                        margin="normal"
                        precision={3}
                      />
                    </Grid>

                    <Grid item xs={12} md={4}>
                      <NumberInput
                        fullWidth
                        label="Z Position"
                        value={machine.fixedTouchPlateZ}
                        onChange={(value) => machine.fixedTouchPlateZ = value}
                        margin="normal"
                        precision={3}
                      />
                    </Grid>

                    {/* Probing Speeds */}
                    <Grid item xs={12}>
                      <Typography variant="subtitle1" sx={{ mt: 2, mb: 1 }}>Probing Speeds</Typography>
                      <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                        Fast and slow probing speeds for accurate touch-off (in/min)
                      </Typography>
                    </Grid>

                    <Grid item xs={12} md={6}>
                      <NumberInput
                        fullWidth
                        label="Fast Probing Speed"
                        value={machine.fixedTouchPlateFastSpeed}
                        onChange={(value) => machine.fixedTouchPlateFastSpeed = value}
                        margin="normal"
                        precision={0}
                        min={1}
                        max={1000}
                      />
                      <Typography variant="caption" color="text.secondary">
                        Initial approach speed (default: 100 in/min)
                      </Typography>
                    </Grid>

                    <Grid item xs={12} md={6}>
                      <NumberInput
                        fullWidth
                        label="Slow Probing Speed"
                        value={machine.fixedTouchPlateSlowSpeed}
                        onChange={(value) => machine.fixedTouchPlateSlowSpeed = value}
                        margin="normal"
                        precision={0}
                        min={1}
                        max={1000}
                      />
                      <Typography variant="caption" color="text.secondary">
                        Final precise measurement speed (default: 10 in/min)
                      </Typography>
                    </Grid>
                  </>
                )}
              </Grid>
            </AccordionDetails>
          </Accordion>

          {/* Movable Touch Plate */}
          <Accordion
            expanded={expandedSections.movableTouchPlate}
            onChange={() => handleSectionToggle('movableTouchPlate')}
            sx={{ mb: 2 }}
          >
            <AccordionSummary expandIcon={<ExpandMore />}>
              <Typography variant="h6">Movable Touch Plate</Typography>
            </AccordionSummary>
            <AccordionDetails>
              <Box sx={{ mb: 2, p: 2, backgroundColor: '#f5f5f5', borderRadius: 1 }}>
                <Typography variant="body2" color="text.secondary">
                  Configure a movable touch plate that can be placed on the workpiece for tool length measurement.
                </Typography>
              </Box>
              <Grid container spacing={3}>
                {/* Has Movable Touch Plate Switch */}
                <Grid item xs={12}>
                  <FormControlLabel
                    control={
                      <Switch
                        checked={machine.hasMovableTouchPlate}
                        onChange={(e) => machine.hasMovableTouchPlate = e.target.checked}
                      />
                    }
                    label="Has Movable Touch Plate"
                  />
                </Grid>

                {/* Movable Touch Plate Configuration - Only show if enabled */}
                {machine.hasMovableTouchPlate && (
                  <>
                    {/* Probing Speeds */}
                    <Grid item xs={12}>
                      <Typography variant="subtitle1" sx={{ mt: 1, mb: 1 }}>Probing Speeds</Typography>
                      <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                        Fast and slow probing speeds for accurate touch-off (in/min)
                      </Typography>
                    </Grid>

                    <Grid item xs={12} md={6}>
                      <NumberInput
                        fullWidth
                        label="Fast Probing Speed"
                        value={machine.movableTouchPlateFastSpeed}
                        onChange={(value) => machine.movableTouchPlateFastSpeed = value}
                        margin="normal"
                        precision={0}
                        min={1}
                        max={1000}
                      />
                      <Typography variant="caption" color="text.secondary">
                        Initial approach speed (default: 100 in/min)
                      </Typography>
                    </Grid>

                    <Grid item xs={12} md={6}>
                      <NumberInput
                        fullWidth
                        label="Slow Probing Speed"
                        value={machine.movableTouchPlateSlowSpeed}
                        onChange={(value) => machine.movableTouchPlateSlowSpeed = value}
                        margin="normal"
                        precision={0}
                        min={1}
                        max={1000}
                      />
                      <Typography variant="caption" color="text.secondary">
                        Final precise measurement speed (default: 10 in/min)
                      </Typography>
                    </Grid>

                    {/* Touch Plate Height */}
                    <Grid item xs={12}>
                      <Typography variant="subtitle1" sx={{ mt: 2, mb: 1 }}>Touch Plate Height</Typography>
                      <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                        Physical height/thickness of the movable touch plate
                      </Typography>
                    </Grid>

                    <Grid item xs={12} md={6}>
                      <NumberInput
                        fullWidth
                        label="Touch Plate Height"
                        value={machine.movableTouchPlateHeight}
                        onChange={(value) => machine.movableTouchPlateHeight = value}
                        margin="normal"
                        precision={3}
                        min={0}
                      />
                      <Typography variant="caption" color="text.secondary">
                        Height of touch plate block (default: 3.000)
                      </Typography>
                    </Grid>
                  </>
                )}
              </Grid>
            </AccordionDetails>
          </Accordion>
        </Box>
      )}
    />
  );
};