import React from 'react';
import { SimulatorView } from '../../../data/Common/SimulatorView';
import { ViewStyle } from '../../../data/Common/ViewStyle';
import { MachineStateData } from '../../../data/MachineStateData';
import { MachineData } from '../../../data/MachineData';
import { CoordinateUtil } from '../../../utils/CoordinateUtil';
import { ToolLibrary } from '../../../data/Common/ToolLibrary';
import { ConfigurationData } from '../../../data/ConfigurationData';
import { ObserveMultiProperties } from '../../../utils/statemanager/ObserveMultiProperties';
import { Tool } from './Tool';

export interface MachinePositionedToolProps {
  simulatorView: SimulatorView;
  machineState: MachineStateData;
  machineData: MachineData;
}

/**
 * Machine-positioned tool component
 * Renders the current tool at the machine's current X/Y/Z position
 * Extends downward from the tool holder position
 */
export function MachinePositionedTool({
  simulatorView,
  machineState,
  machineData
}: MachinePositionedToolProps) {
  return (
    <ObserveMultiProperties
      listenTo={[
        { object: machineState, properties: ['currentMachinePoint', 'proposedSpindlePosition', 'currentToolNumber'] },
        { object: simulatorView, properties: ['tool'] },
        { object: ConfigurationData.Instance, properties: ['toolTransparency'] }
      ]}
      control={() => {
        // Get current tool from tool library using tool number
        const toolLibrary = ToolLibrary.Instance;
        const currentToolNumber = machineState.currentToolNumber;
        const currentTool = toolLibrary.tools.find(tool => tool.toolNumber === currentToolNumber);
        
        // Don't render if no tool, tool not found, or tool visibility is hidden
        if (!currentTool || currentToolNumber === 0 || simulatorView.tool === ViewStyle.Hide) {
          return null;
        }

        // Get current machine position - use proposed position if it exists (during drag), otherwise use current position
        // This matches the logic in the Spindle component to ensure they move together
        const machinePos = machineState.proposedSpindlePosition || machineState.currentMachinePoint;
        
        // Convert machine position to simulator coordinates
        const simulatorPosition = CoordinateUtil.toSimulator(machinePos);
        
        // Calculate tool position - tool top should be at machine Z and extend downward
        // lengthBelowHolder is now stored as negative values (e.g., -3.0 for 3" below spindle)
        // The Tool component renders with bottom at Y=0 and top at Y=lengthBelowHolder
        // To have the tool TOP at machine Z: groupY = machineZ + lengthBelowHolder (since lengthBelowHolder is negative)
        const toolPosition: [number, number, number] = [
          simulatorPosition.x,
          simulatorPosition.y,
          simulatorPosition.z + currentTool.lengthBelowHolder
        ];
        
        // Tool needs same rotation as spindle/tool holder (90 degrees around X to make it vertical)
        const toolRotation: [number, number, number] = [Math.PI / 2, 0, 0];

        // Apply transparency if semi-transparent mode
        const visible = simulatorView.tool === ViewStyle.Show || simulatorView.tool === ViewStyle.SemiTransparent;
        const config = ConfigurationData.Instance;
        const isTransparent = simulatorView.tool === ViewStyle.SemiTransparent;
        const toolOpacity = isTransparent ? config.toolTransparency : 1.0;
        
        return (
          <Tool
            tool={currentTool}
            position={toolPosition}
            rotation={toolRotation}
            visible={visible}
            transparent={isTransparent}
            opacity={toolOpacity}
          />
        );
      }}
    />
  );
}