import { SwapHoriz as MoveTypeIcon } from '@mui/icons-material';
import { Box, Button, Typography } from '@mui/material';
import React from 'react';
import { Machine } from '../../../../machine/Machine';
import { MoveType } from '../../../../machine/MoveType';
import { DataUtilities } from '../../../../utils/storage/DataUtilities';
import { FlowStep } from "../../../FlowStep";
import { FlowStepData } from "../../../FlowStepData";

export class GetMoveTypeStep extends FlowStep {
    readonly __type = 'GetMoveTypeStep';
    readonly category = ['Machine', 'Movement'];
    readonly name = 'Get Move Type';
    readonly description = 'Gets the current movement type (relative or absolute)';
    
    // Icon is created dynamically, not stored
    get icon(): React.ReactNode {
        return React.createElement(MoveTypeIcon, { sx: { color: 'info.main' } });
    }

    static readonly ABSOLUTE_PATH = 'absolute';
    static readonly RELATIVE_PATH = 'relative';

    async execute(data: FlowStepData, prototypeRun: boolean): Promise<string | null> {
        if (prototypeRun) {
            return GetMoveTypeStep.ABSOLUTE_PATH;
        }

        try {
            const moveType = await Machine.getInstance().movement.GetMoveType();
            return moveType === MoveType.Absolute ? GetMoveTypeStep.ABSOLUTE_PATH : GetMoveTypeStep.RELATIVE_PATH;
        } catch (error) {
            console.error('GetMoveType failed:', error);
            return GetMoveTypeStep.ABSOLUTE_PATH; // Default to absolute on error
        }
    }

    results(): string[] {
        return [GetMoveTypeStep.ABSOLUTE_PATH, GetMoveTypeStep.RELATIVE_PATH];
    }

    renderResultsUI(data: FlowStepData, result: string): React.ReactNode {
        const moveTypeText = result === GetMoveTypeStep.ABSOLUTE_PATH ? 'Absolute' : 'Relative';
        return (
            <Typography variant="caption">
                Current move type: {moveTypeText}
            </Typography>
        );
    }

    renderEditUI(props: { onClose: () => void }): React.ReactNode {
        return (
            <Box sx={{ p: 2, minWidth: 300 }}>
                <Typography variant="h6" gutterBottom>Get Move Type</Typography>
                <Typography variant="body2" color="text.secondary">
                    This step retrieves the current movement coordinate system setting.
                </Typography>

                <Box sx={{ mt: 2 }}>
                    <Typography variant="subtitle2" gutterBottom>Possible Results:</Typography>
                    <Typography variant="body2" sx={{ color: 'primary.main' }}>
                        • Absolute: Machine uses absolute coordinates
                    </Typography>
                    <Typography variant="body2" sx={{ color: 'primary.main' }}>
                        • Relative: Machine uses relative coordinates
                    </Typography>
                </Box>

                <Box sx={{ display: 'flex', gap: 1, justifyContent: 'flex-end', mt: 2 }}>
                    <Button variant="contained" onClick={props.onClose}>OK</Button>
                </Box>
            </Box>
        );
    }

    public toJSON(): any {
        const data = DataUtilities.getStorageData(this, ['icon']) as any;
        data.__type = this.__type;
        return data;
    }

    public fromJSON(data: any): void {
        DataUtilities.loadStorageData(this, data);
    }
}