import { Flow, FlowType } from './Flow';
import { FlowStep } from './FlowStep';
import { FlowStepData } from './FlowStepData';

export interface FlowExecutionResult {
    success: boolean;
    stepsExecuted: string[];
    finalStep: string | null;
    executionTime: number;
    error?: string;
}

export interface FlowExecutionOptions {
    maxSteps?: number; // Maximum steps to execute (prevents infinite loops)
    prototypeRun?: boolean; // Whether this is a prototype/test run
    stepTimeout?: number; // Timeout per step in milliseconds
}

export class FlowEngine {
    private static readonly DEFAULT_MAX_STEPS = 1000;
    private static readonly DEFAULT_STEP_TIMEOUT = 30000; // 30 seconds

    /**
     * Execute a flow starting from the root step
     * @param flow The flow to execute
     * @param data The data context for execution
     * @param options Execution options
     * @returns Promise with execution result
     */
    static async execute(
        flow: Flow,
        data: FlowStepData,
        options: FlowExecutionOptions = {}
    ): Promise<FlowExecutionResult> {
        const startTime = performance.now();
        const stepsExecuted: string[] = [];
        const maxSteps = options.maxSteps || this.DEFAULT_MAX_STEPS;
        const prototypeRun = options.prototypeRun || false;
        const stepTimeout = options.stepTimeout || this.DEFAULT_STEP_TIMEOUT;

        try {
            // Validate input parameters based on flow type
            this.validateFlowInputs(flow, data);

            // Find the root step (should be StartStep)
            const rootSteps = flow.getRootSteps();
            if (rootSteps.length === 0) {
                throw new Error('No root step found in flow');
            }
            if (rootSteps.length > 1) {
                throw new Error('Multiple root steps found in flow');
            }

            let currentStep: FlowStep | undefined = rootSteps[0];
            let stepCount = 0;

            while (currentStep && stepCount < maxSteps) {
                stepsExecuted.push(currentStep.id);

                // Execute the current step with timeout
                const outcomePath = await this.executeStepWithTimeout(
                    currentStep,
                    data,
                    prototypeRun,
                    stepTimeout
                );

                // If step returns null, execution stops
                if (outcomePath === null) {
                    return {
                        success: true,
                        stepsExecuted,
                        finalStep: currentStep.id,
                        executionTime: performance.now() - startTime
                    };
                }

                // Find the next step using the outcome path
                const nextStep = flow.getNextStep(currentStep.id, outcomePath);
                if (!nextStep) {
                    throw new Error(
                        `No next step found for step '${currentStep.id}' with outcome path '${outcomePath}'`
                    );
                }

                currentStep = nextStep;
                stepCount++;
            }

            // If we exit the loop due to max steps, it's likely an infinite loop
            if (stepCount >= maxSteps) {
                throw new Error(`Maximum step limit (${maxSteps}) reached. Possible infinite loop detected.`);
            }

            // Should not reach here under normal circumstances
            return {
                success: true,
                stepsExecuted,
                finalStep: currentStep?.id || null,
                executionTime: performance.now() - startTime
            };

        } catch (error) {
            return {
                success: false,
                stepsExecuted,
                finalStep: null,
                executionTime: performance.now() - startTime,
                error: error instanceof Error ? error.message : String(error)
            };
        }
    }

    /**
     * Validate input parameters based on flow type
     */
    private static validateFlowInputs(flow: Flow, data: FlowStepData): void {
        const flowType = flow.FlowType;

        if (flowType === FlowType.ToolChange) {
            // Tool Change flows require ToTool parameter
            const toTool = data.getVariable('ToTool');
            if (toTool === undefined || toTool === null) {
                throw new Error('Tool Change flow requires "ToTool" parameter in data');
            }
            if (typeof toTool !== 'number' || isNaN(toTool)) {
                throw new Error('Tool Change flow "ToTool" parameter must be a valid number');
            }
        } else if (flowType === FlowType.NumberInput) {
            // Number Input flows require NumberValue parameter
            const numberValue = data.getVariable('NumberValue');
            if (numberValue === undefined || numberValue === null) {
                throw new Error('Number Input flow requires "NumberValue" parameter in data');
            }
            if (typeof numberValue !== 'number' || isNaN(numberValue)) {
                throw new Error('Number Input flow "NumberValue" parameter must be a valid number');
            }
        }
        // General flows don't require specific input validation
    }

    /**
     * Execute a single step with timeout protection
     */
    private static async executeStepWithTimeout(
        step: FlowStep,
        data: FlowStepData,
        prototypeRun: boolean,
        timeoutMs: number
    ): Promise<string | null> {
        return new Promise((resolve, reject) => {
            const timeoutId = setTimeout(() => {
                reject(new Error(`Step '${step.id}' execution timed out after ${timeoutMs}ms`));
            }, timeoutMs);

            try {
                // Execute the step
                const result = step.execute(data, prototypeRun);
                clearTimeout(timeoutId);
                resolve(result);
            } catch (error) {
                clearTimeout(timeoutId);
                reject(new Error(`Step '${step.id}' execution failed: ${error instanceof Error ? error.message : String(error)}`));
            }
        });
    }

    /**
     * Validate a flow before execution
     * @param flow The flow to validate
     * @returns Validation result with any issues found
     */
    static validateFlow(flow: Flow): {
        isValid: boolean;
        issues: string[];
        warnings: string[];
    } {
        const issues: string[] = [];
        const warnings: string[] = [];

        // Check for root steps
        const rootSteps = flow.getRootSteps();
        if (rootSteps.length === 0) {
            issues.push('No root step found in flow');
        } else if (rootSteps.length > 1) {
            issues.push('Multiple root steps found in flow');
        }

        // Check for leaf steps
        const leafSteps = flow.getLeafSteps();
        if (leafSteps.length === 0) {
            warnings.push('No leaf steps found in flow');
        }

        // Check for orphaned steps
        for (const step of flow.steps) {
            const incomingConnections = flow.getConnectionsToStep(step.id);
            const outgoingConnections = flow.getConnectionsFromStep(step.id);

            if (incomingConnections.length === 0 && step.__type !== 'StartStep') {
                warnings.push(`Step '${step.id}' has no incoming connections`);
            }

            if (outgoingConnections.length === 0 && step.__type !== 'EndStep') {
                warnings.push(`Step '${step.id}' has no outgoing connections`);
            }

            // Check if all result paths have connections
            const resultPaths = step.results();
            for (const path of resultPaths) {
                const hasConnection = outgoingConnections.some(conn => conn.fromStepPath === path);
                if (!hasConnection) {
                    warnings.push(`Step '${step.id}' result path '${path}' has no connection`);
                }
            }
        }

        return {
            isValid: issues.length === 0,
            issues,
            warnings
        };
    }

    /**
     * Get execution statistics for a flow
     */
    static getFlowStatistics(flow: Flow): {
        totalSteps: number;
        stepsByCategory: Record<string, number>;
        totalConnections: number;
        averageConnectionsPerStep: number;
        rootSteps: number;
        leafSteps: number;
    } {
        const steps = flow.steps;
        const connections = flow.connections;

        const stepsByCategory: Record<string, number> = {};
        for (const step of steps) {
            const categoryKey = step.category.join('/');
            stepsByCategory[categoryKey] = (stepsByCategory[categoryKey] || 0) + 1;
        }

        return {
            totalSteps: steps.length,
            stepsByCategory,
            totalConnections: connections.length,
            averageConnectionsPerStep: steps.length > 0 ? connections.length / steps.length : 0,
            rootSteps: flow.getRootSteps().length,
            leafSteps: flow.getLeafSteps().length
        };
    }
}
