import { StateManager } from '../../utils/statemanager/StateManager';
import { Wizard } from './Wizard';

export class WizardManager {
  private static _instance: WizardManager;
  private _currentWizard: Wizard | null = null;
  private _wizardStack: Wizard[] = [];

  public static get Instance(): WizardManager {
    if (!WizardManager._instance) {
      WizardManager._instance = new WizardManager();
    }
    return WizardManager._instance;
  }

  private constructor() {
    // Private constructor for singleton pattern
  }

  public get currentWizard(): Wizard | null {
    return this._currentWizard;
  }

  public get isWizardOpen(): boolean {
    return this._currentWizard !== null;
  }

  /**
   * Start a new wizard. If another wizard is currently running,
   * this will be added to the stack and shown after the current one completes.
   */
  public start(wizard: Wizard): void {
    if (this._currentWizard === null) {
      // No wizard currently running, start immediately
      this._currentWizard = wizard;
      wizard.onClose = () => this._onWizardClose(wizard);
      StateManager.propertyChanged(this, 'currentWizard');
    } else {
      // Add to stack to be shown later
      this._wizardStack.push(wizard);
    }
  }

  /**
   * Force start a wizard, replacing the current one.
   * The replaced wizard will be lost.
   */
  public forceStart(wizard: Wizard): void {
    this._currentWizard = wizard;
    wizard.onClose = () => this._onWizardClose(wizard);
    StateManager.propertyChanged(this, 'currentWizard');
  }

  /**
   * Close the current wizard without starting the next one in the stack.
   */
  public close(): void {
    if (this._currentWizard) {
      this._currentWizard = null;
      StateManager.propertyChanged(this, 'currentWizard');
    }
  }

  /**
   * Close all wizards and clear the stack.
   */
  public closeAll(): void {
    this._currentWizard = null;
    this._wizardStack = [];
    StateManager.propertyChanged(this, 'currentWizard');
  }

  /**
   * Get the number of wizards waiting in the stack.
   */
  public get stackCount(): number {
    return this._wizardStack.length;
  }

  private _onWizardClose(closingWizard: Wizard): void {
    // Only process if this is the current wizard
    if (this._currentWizard === closingWizard) {
      this._currentWizard = null;
      
      // Check if there are more wizards in the stack
      if (this._wizardStack.length > 0) {
        const nextWizard = this._wizardStack.shift()!;
        this._currentWizard = nextWizard;
        nextWizard.onClose = () => this._onWizardClose(nextWizard);
      }
      
      StateManager.propertyChanged(this, 'currentWizard');
    }
  }
}
