import { Speed as SpeedIcon } from '@mui/icons-material';
import { Box, TextField, Typography } from '@mui/material';
import React, { useState } from 'react';
import { Machine } from '../../../../machine/Machine';
import { DataUtilities } from '../../../../utils/storage/DataUtilities';
import { FlowStep } from "../../../FlowStep";
import { FlowStepData } from "../../../FlowStepData";

export class AdjustSpindleSpeedStep extends FlowStep {
    readonly __type = 'AdjustSpindleSpeedStep';
    readonly category = ['Machine', 'Spindle'];
    readonly name = 'Adjust Spindle Speed';
    readonly description = 'Adjusts the spindle speed by a multiplication factor';
    
    // Icon is created dynamically, not stored
    get icon(): React.ReactNode {
        return React.createElement(SpeedIcon, { sx: { color: 'primary.main' } });
    }

    // Step parameters
    public factor: number = 1.0;

    static readonly DONE_PATH = 'done';

    async execute(data: FlowStepData, prototypeRun: boolean): Promise<string | null> {
        if (prototypeRun) {
            return AdjustSpindleSpeedStep.DONE_PATH;
        }

        try {
            await Machine.getInstance().spindle.AdjustSpindleSpeed(this.factor);
            return AdjustSpindleSpeedStep.DONE_PATH;
        } catch (error) {
            console.error('AdjustSpindleSpeed failed:', error);
            return AdjustSpindleSpeedStep.DONE_PATH; // Still done, just with error logged
        }
    }

    results(): string[] {
        return [AdjustSpindleSpeedStep.DONE_PATH];
    }

    renderResultsUI(data: FlowStepData, result: string): React.ReactNode {
        const percentage = (this.factor * 100).toFixed(1);
        return (
            <Typography variant="caption">
                Adjust spindle speed by factor {this.factor} ({percentage}%): {result}
            </Typography>
        );
    }

    renderEditUI(props: { onClose: () => void }): React.ReactNode {
        const AdjustSpindleSpeedEditUI: React.FC = () => {
            const [factor, setFactor] = useState(this.factor.toString());

            // Update the instance when the local state changes
            React.useEffect(() => {
                this.factor = parseFloat(factor) || 1.0;
            }, [factor]);

            return (
                <Box sx={{ p: 2, minWidth: 300 }}>
                    <Typography variant="h6" gutterBottom>Adjust Spindle Speed</Typography>
                    <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                        Multiply the current spindle speed by the specified factor.
                    </Typography>

                    <TextField
                        label="Speed Adjustment Factor"
                        type="number"
                        value={factor}
                        onChange={(e) => setFactor(e.target.value)}
                        fullWidth
                        margin="normal"
                        inputProps={{
                            step: 0.1,
                            min: 0.1,
                            max: 5.0
                        }}
                        helperText="1.0 = no change, 0.5 = half speed, 2.0 = double speed"
                    />

                    <Box sx={{ mt: 2 }}>
                        <Typography variant="subtitle2" gutterBottom>Current Setting:</Typography>
                        <Typography variant="body2" color="primary.main">
                            Factor: {parseFloat(factor) || 1.0} ({((parseFloat(factor) || 1.0) * 100).toFixed(1)}%)
                        </Typography>
                    </Box>
                </Box>
            );
        };

        return <AdjustSpindleSpeedEditUI />;
    }

    public toJSON(): any {
        const data = DataUtilities.getStorageData(this, ['icon']) as any;
        data.__type = this.__type;
        return data;
    }

    public fromJSON(data: any): void {
        DataUtilities.loadStorageData(this, data);
    }
}