import {
  Box,
  ListItem,
  Typography
} from '@mui/material';
import { ConfigurationData } from '../../data/ConfigurationData';
import { InputWithState } from '../../data/IOStateData';

interface InputItemProps {
  input: InputWithState;
  isActive: boolean;
}

export function InputItem({ input, isActive }: InputItemProps) {
  const config = ConfigurationData.Instance;

  const displayText = isActive ? input.activeText : input.inactiveText;
  const activeColor = config.primaryColor;

  return (
    <ListItem
      sx={{
        py: 0.75,
        px: 1.5,
        borderBottom: `1px solid ${config.borderColor}`,
        minHeight: 48,
        display: 'flex',
        alignItems: 'center'
      }}
    >
      <Box sx={{
        display: 'flex',
        alignItems: 'center',
        width: '100%',
        gap: 1
      }}>
        {/* Input Number in Solid Box */}
        <Box
          sx={{
            width: 28,
            height: 24,
            backgroundColor: isActive ? activeColor : config.borderColor,
            color: isActive ? 'white' : config.mutedTextColor,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            borderRadius: 1,
            fontSize: '0.75rem',
            fontWeight: 'bold',
            flexShrink: 0
          }}
        >
          {input.number}
        </Box>

        {/* Input Name */}
        <Box sx={{ flex: 1, minWidth: 0 }}>
          <Typography
            variant="body2"
            sx={{
              fontSize: '0.8rem',
              fontWeight: 500,
              color: config.darkTextColor,
              overflow: 'hidden',
              textOverflow: 'ellipsis',
              whiteSpace: 'nowrap'
            }}
          >
            {input.name}
          </Typography>
        </Box>

        {/* Active/Inactive Status Text */}
        <Box sx={{
          minWidth: 80,
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'flex-end'
        }}>
          <Typography
            variant="caption"
            sx={{
              fontSize: '0.7rem',
              fontWeight: isActive ? 'bold' : 'normal',
              color: isActive ? activeColor : config.mutedTextColor,
              textAlign: 'right'
            }}
          >
            {displayText}
          </Typography>
        </Box>
      </Box>
    </ListItem>
  );
}
