import { StateManager } from "../utils/statemanager/StateManager";
import { DataUtilities } from "../utils/storage/DataUtilities";
import { IStorable } from "../utils/storage/IStorable";
import { FlowStep } from "./FlowStep";
import { FlowStepConnection } from "./FlowStepConnection";
import { FlowStepData } from "./FlowStepData";
import { FlowStepLibrary } from "./FlowStepLibrary";
import { EndStep } from "./steps/EndStep";
import { StartStep } from "./steps/StartStep";

export enum FlowType {
    General = 'General',
    NumberInput = 'Number Input',
    ToolChange = 'Tool Change'
}

export class Flow implements IStorable {
    private _steps: FlowStep[] = [];
    private _connections: FlowStepConnection[] = [];
    private _category: string = 'General';

    private _flowType: FlowType = FlowType.General;
    get FlowType(): FlowType {
        return this._flowType;
    }
    set FlowType(value: FlowType) {
        this._flowType = value;
        StateManager.propertyChanged(this, 'FlowType');
    }

    _canBeSubFlow: boolean = true;

    get canBeSubFlow(): boolean {
        return this._canBeSubFlow;
    }
    set canBeSubFlow(value: boolean) {
        this._canBeSubFlow = value;
        StateManager.propertyChanged(this, 'canBeSubFlow');
    }


    // Transient property (not persisted) to track manual viewport panning
    public hasUserManuallyPannedViewport: boolean = false;

    constructor(category: string = 'General') {
        this._category = category;

        // Initialize with default start -> end flow
        const startStep = new StartStep();
        const endStep = new EndStep();

        this._steps.push(startStep);
        this._steps.push(endStep);

        const connection = new FlowStepConnection(startStep.id, endStep.id, StartStep.OUTPUT_PATH);
        this._connections.push(connection);
    }    // Accessors
    get category(): string {
        return this._category;
    }

    set category(value: string) {
        this._category = value;
        StateManager.propertyChanged(this, 'category');
    }

    // Accessors
    get steps(): FlowStep[] {
        return [...(this._steps || [])]; // Return a copy to prevent external modification, handle null case
    }

    get connections(): FlowStepConnection[] {
        return [...(this._connections || [])]; // Return a copy to prevent external modification, handle null case
    }

    // Step management methods
    addStep(step: FlowStep, afterStepId: string, fromPath: string): void {
        // Validate that afterStepId exists
        const afterStep = this.getStepById(afterStepId);
        if (!afterStep) {
            throw new Error(`Step with id '${afterStepId}' not found`);
        }

        // Validate that fromPath exists in the after step's results
        const availablePaths = afterStep.results();
        if (!availablePaths.includes(fromPath)) {
            throw new Error(`Path '${fromPath}' not available in step '${afterStepId}'. Available paths: ${availablePaths.join(', ')}`);
        }

        // Add the step to the collection
        this._steps.push(step);

        // Find any existing connection from afterStepId using fromPath
        const existingConnectionIndex = this._connections.findIndex(conn =>
            conn.fromStepId === afterStepId && conn.fromStepPath === fromPath
        );

        let nextStepId: string | undefined;

        if (existingConnectionIndex !== -1) {
            // There's an existing connection, we need to insert between steps
            const existingConnection = this._connections[existingConnectionIndex];
            nextStepId = existingConnection.toStepId;

            // Remove the old connection
            this._connections.splice(existingConnectionIndex, 1);
        }

        // Create connection from afterStep to new step
        const newConnection = new FlowStepConnection(afterStepId, step.id, fromPath);
        this._connections.push(newConnection);

        // If there was a next step, connect new step to it
        if (nextStepId) {
            // Use the first available output path from the new step
            const newStepPaths = step.results();
            if (newStepPaths.length > 0) {
                const connectionToNext = new FlowStepConnection(step.id, nextStepId, newStepPaths[0]);
                this._connections.push(connectionToNext);

                // For any remaining unconnected paths, create EndSteps
                this.createEndStepsForUnconnectedPaths(step);
            }
        } else {
            // No next step, create EndSteps for all output paths
            this.createEndStepsForUnconnectedPaths(step);
        }

        // Clean up any orphaned connections
        this.cleanup();

        // Notify UI of changes
        StateManager.propertiesChanged(this, ['steps', 'connections']);
    }

    /**
     * Create EndSteps for any unconnected output paths of a step
     */
    private createEndStepsForUnconnectedPaths(step: FlowStep): void {
        const outputPaths = step.results();

        for (const path of outputPaths) {
            // Check if this path already has a connection
            const hasConnection = this._connections.some(conn =>
                conn.fromStepId === step.id && conn.fromStepPath === path
            );

            if (!hasConnection) {
                // Create a new EndStep for this unconnected path
                // Use a clean ID without spaces to avoid edge parsing issues
                const endStep = new EndStep();
                this._steps.push(endStep);

                // Connect the path to this EndStep
                const connection = new FlowStepConnection(step.id, endStep.id, path);
                this._connections.push(connection);
            }
        }
    }

    removeStep(stepId: string): void {
        // Find the step to remove
        const stepIndex = this._steps.findIndex(step => step.id === stepId);
        if (stepIndex === -1) return;

        // Get all connections from this step
        const outgoingConnections = this._connections.filter(conn => conn.fromStepId === stepId);

        // Get all connections to this step
        const incomingConnections = this._connections.filter(conn => conn.toStepId === stepId);

        // Remove the step
        this._steps.splice(stepIndex, 1);

        // Remove all connections involving this step
        this._connections = this._connections.filter(conn =>
            conn.fromStepId !== stepId && conn.toStepId !== stepId
        );

        // Handle reconnection logic
        if (incomingConnections.length > 0 && outgoingConnections.length === 1) {
            // Single outgoing connection: reconnect parent to child
            const childStepId = outgoingConnections[0].toStepId;
            incomingConnections.forEach(incomingConn => {
                const newConnection = new FlowStepConnection(
                    incomingConn.fromStepId,
                    childStepId,
                    incomingConn.fromStepPath
                );
                this._connections.push(newConnection);
            });
        } else if (outgoingConnections.length > 1) {
            // Multiple outgoing connections: delete orphaned steps
            const childStepIds = outgoingConnections.map(conn => conn.toStepId);
            this.removeOrphanedSteps(childStepIds);
        }

        // Clean up any remaining unused connections
        this.cleanup();

        // Notify UI of changes
        StateManager.propertiesChanged(this, ['steps', 'connections']);
    }

    private removeOrphanedSteps(stepIds: string[]): void {
        stepIds.forEach(stepId => {
            // Check if this step has any incoming connections from remaining steps
            const hasIncomingConnections = this._connections.some(conn =>
                conn.toStepId === stepId && this._steps.some(step => step.id === conn.fromStepId)
            );

            if (!hasIncomingConnections) {
                // This step is orphaned, remove it recursively
                this.removeStep(stepId);
            }
        });
    }

    cleanup(): void {
        const stepIds = new Set(this._steps.map(step => step.id));

        // Remove connections that reference non-existent steps
        this._connections = this._connections.filter(conn =>
            stepIds.has(conn.fromStepId) && stepIds.has(conn.toStepId)
        );

        // Remove orphaned steps (steps with no incoming connections, except StartStep)
        const stepsWithIncoming = new Set(this._connections.map(conn => conn.toStepId));
        const orphanedSteps = this._steps.filter(step =>
            !stepsWithIncoming.has(step.id) && step.__type !== 'StartStep'
        );

        // Remove orphaned steps and their outgoing connections
        orphanedSteps.forEach(step => {
            this._steps = this._steps.filter(s => s.id !== step.id);
            this._connections = this._connections.filter(conn => conn.fromStepId !== step.id);
        });

        // Ensure all non-EndStep output paths are connected
        this.ensureAllPathsTerminated();
    }

    /**
     * Ensure all output paths from non-EndStep steps are connected to something
     * Creates EndSteps for any unconnected paths
     */
    ensureAllPathsTerminated(): void {
        const nonEndSteps = this._steps.filter(step => step.__type !== 'EndStep');

        for (const step of nonEndSteps) {
            this.createEndStepsForUnconnectedPaths(step);
        }
    }

    // Utility methods
    getStepById(stepId: string): FlowStep | undefined {
        return this._steps.find(step => step.id === stepId);
    }

    getNextStep(stepId: string, fromPath: string): FlowStep | undefined {
        const connection = this._connections.find(conn =>
            conn.fromStepId === stepId && conn.fromStepPath === fromPath
        );

        if (connection) {
            return this.getStepById(connection.toStepId);
        }

        return undefined;
    }

    getConnectionsFromStep(stepId: string): FlowStepConnection[] {
        return this._connections.filter(conn => conn.fromStepId === stepId);
    }

    getConnectionsToStep(stepId: string): FlowStepConnection[] {
        return this._connections.filter(conn => conn.toStepId === stepId);
    }

    getRootSteps(): FlowStep[] {
        const stepsWithIncoming = new Set(this._connections.map(conn => conn.toStepId));
        return this._steps.filter(step => !stepsWithIncoming.has(step.id));
    }

    getLeafSteps(): FlowStep[] {
        const stepsWithOutgoing = new Set(this._connections.map(conn => conn.fromStepId));
        return this._steps.filter(step => !stepsWithOutgoing.has(step.id));
    }

    // Check if fromStepId can reach toStepId (i.e., toStepId is downstream from fromStepId)
    isStepUpstreamOf(fromStepId: string, toStepId: string): boolean {
        if (fromStepId === toStepId) return true; // Same step is considered upstream

        const visited = new Set<string>();
        const queue: string[] = [fromStepId];

        while (queue.length > 0) {
            const currentStepId = queue.shift()!;

            if (visited.has(currentStepId)) continue;
            visited.add(currentStepId);

            // Get all outgoing connections from current step
            const outgoingConnections = this.getConnectionsFromStep(currentStepId);

            for (const connection of outgoingConnections) {
                if (connection.toStepId === toStepId) {
                    return true; // Found path to target
                }

                if (!visited.has(connection.toStepId)) {
                    queue.push(connection.toStepId);
                }
            }
        }

        return false; // No path found
    }

    // Get all steps that are valid redirect targets for an EndStep
    getValidRedirectTargets(endStepId: string): FlowStep[] {
        return this._steps.filter(step => {
            // Exclude the step itself
            if (step.id === endStepId) return false;

            // Exclude other EndSteps as redirect targets
            if (step.__type === 'EndStep') return false;

            // Exclude steps that are upstream (can reach the endStep)
            return !this.isStepUpstreamOf(step.id, endStepId);
        });
    }

    // Redirect an EndStep to a different target
    redirectEndStep(endStepId: string, newTargetStepId: string): void {
        const endStep = this.getStepById(endStepId);
        if (!endStep || !(endStep instanceof EndStep)) {
            throw new Error('Invalid end step');
        }

        const newTarget = this.getStepById(newTargetStepId);
        if (!newTarget) {
            throw new Error('Target step not found');
        }

        // Check if target is valid (not upstream)
        if (this.isStepUpstreamOf(newTargetStepId, endStepId)) {
            throw new Error('Cannot redirect to upstream step - would create a cycle');
        }

        // Get incoming connections to the end step
        const incomingConnections = this.getConnectionsToStep(endStepId);

        // Create new connections from the incoming steps to the target FIRST
        incomingConnections.forEach(connection => {
            const newConnection = new FlowStepConnection(
                connection.fromStepId,
                newTargetStepId,
                connection.fromStepPath
            );
            this._connections.push(newConnection);
        });

        // Remove the end step (this also removes its connections)
        this.removeStep(endStepId);

        // Notify UI of changes
        StateManager.propertiesChanged(this, ['steps', 'connections']);
    }

    /**
     * Serialize to JSON - handle steps and connections arrays explicitly
     */
    toJSON(): any {
        const baseData = DataUtilities.getStorageData(this, ['_steps', '_connections', 'hasUserManuallyPannedViewport']); // Exclude arrays and transient properties from auto-processing

        // Handle arrays explicitly with proper serialization
        const stepsJson = this._steps.map((step, index) => {
            const stepJson = step.toJSON();

            if (!stepJson.__type) {
                console.error(`Step ${index} missing __type in serialized data!`, step);
            }

            return stepJson;
        });

        return {
            ...baseData,
            steps: stepsJson,
            connections: this._connections.map(connection => connection.toJSON())
        };
    }

    /**
     * Load from JSON - handle steps and connections arrays explicitly using fromJSON
     */
    fromJSON(json: any): void {
        // Load basic properties
        DataUtilities.loadStorageData(this, json, ['_steps', '_connections', 'hasUserManuallyPannedViewport']); // Exclude arrays and transient properties from auto-processing

        // Handle steps array explicitly with polymorphic creation
        if (json.steps && Array.isArray(json.steps)) {
            this._steps = json.steps.map((stepData: any, index: number) => {
                try {
                    // get the step type from the JSON data
                    const stepType = stepData.__type;
                    if (!stepType) {
                        throw new Error(`Step at index ${index} missing __type property`);
                    }

                    const step = FlowStepLibrary.createStep(stepType);
                    step.fromJSON(stepData);

                    return step;
                } catch (error) {
                    // Re-throw without logging to reduce test noise
                    throw error;
                }
            });
        } else if (json.hasOwnProperty('steps') && json.steps === null) {
            // Explicitly reset arrays if they're explicitly set to null in JSON
            this._steps = [];
        }

        // Handle connections array explicitly
        if (json.connections && Array.isArray(json.connections)) {
            this._connections = json.connections.map((connectionData: any) => {
                const connection = new FlowStepConnection('', '', '');
                connection.fromJSON(connectionData);
                return connection;
            });
        } else if (json.hasOwnProperty('connections') && (json.connections === null || json.connections === undefined)) {
            // Explicitly reset arrays if they're explicitly set to null/undefined in JSON
            this._connections = [];
        }

        // Ensure _connections is always an array before cleanup
        if (!Array.isArray(this._connections)) {
            this._connections = [];
        }

        // Clean up invalid connections (connections referencing missing paths)
        this.cleanupInvalidConnections();
    }

    /**
     * Remove connections that reference paths that don't exist on their source step
     * This prevents flow from failing when step result paths change
     */
    private cleanupInvalidConnections(): void {
        const validConnections: FlowStepConnection[] = [];

        for (const connection of this._connections) {
            const fromStep = this.getStepById(connection.fromStepId);

            if (!fromStep) {
                // Skip connections from missing steps
                continue;
            }

            const availablePaths = fromStep.results();

            // Check if the connection's path exists in the step's available paths
            if (availablePaths.includes(connection.fromStepPath)) {
                validConnections.push(connection);
            }
            // If path doesn't exist, skip this connection (it will be removed)
        }

        this._connections = validConnections;
    }

    /**
     * Move a step up in the execution order if there is exactly one step above it
     */
    moveStepUp(stepId: string): boolean {
        const step = this.getStepById(stepId);
        if (!step) return false;

        // Get steps that feed into this step
        const incomingConnections = this.getConnectionsToStep(stepId);

        // Only allow move if there's exactly one step above
        if (incomingConnections.length !== 1) return false;

        const parentStepId = incomingConnections[0].fromStepId;
        const parentStep = this.getStepById(parentStepId);
        if (!parentStep || parentStep.__type === 'StartStep') return false;

        // Get the parent's incoming connections
        const parentIncomingConnections = this.getConnectionsToStep(parentStepId);

        // Get this step's outgoing connections
        const stepOutgoingConnections = this.getConnectionsFromStep(stepId);

        // Swap the connections
        // Remove existing connections
        this._connections = this._connections.filter(conn =>
            !(conn.toStepId === stepId || conn.fromStepId === stepId ||
                conn.toStepId === parentStepId || conn.fromStepId === parentStepId)
        );

        // Reconnect: parent's parents -> this step
        parentIncomingConnections.forEach((conn: FlowStepConnection) => {
            const newConnection = new FlowStepConnection(
                conn.fromStepId,
                stepId,
                conn.fromStepPath
            );
            this._connections.push(newConnection);
        });

        // Connect: this step -> parent
        const connectionFromStepToParent = new FlowStepConnection(
            stepId,
            parentStepId,
            step.results()[0] || 'success'
        );
        this._connections.push(connectionFromStepToParent);

        // Reconnect: parent -> this step's children
        stepOutgoingConnections.forEach((conn: FlowStepConnection) => {
            const newConnection = new FlowStepConnection(
                parentStepId,
                conn.toStepId,
                parentStep.results()[0] || 'success'
            );
            this._connections.push(newConnection);
        });

        // Notify UI of changes
        StateManager.propertiesChanged(this, ['steps', 'connections']);
        return true;
    }

    /**
     * Move a step down in the execution order if there is exactly one step below it
     */
    moveStepDown(stepId: string): boolean {
        const step = this.getStepById(stepId);
        if (!step) return false;

        // Get steps that this step feeds into
        const outgoingConnections = this.getConnectionsFromStep(stepId);

        // Only allow move if there's exactly one step below
        if (outgoingConnections.length !== 1) return false;

        const childStepId = outgoingConnections[0].toStepId;
        const childStep = this.getStepById(childStepId);
        if (!childStep || childStep.__type === 'EndStep') return false;

        // Get this step's incoming connections
        const stepIncomingConnections = this.getConnectionsToStep(stepId);

        // Get the child's outgoing connections
        const childOutgoingConnections = this.getConnectionsFromStep(childStepId);

        // Swap the connections
        // Remove existing connections
        this._connections = this._connections.filter(conn =>
            !(conn.toStepId === stepId || conn.fromStepId === stepId ||
                conn.toStepId === childStepId || conn.fromStepId === childStepId)
        );

        // Reconnect: this step's parents -> child
        stepIncomingConnections.forEach((conn: FlowStepConnection) => {
            const newConnection = new FlowStepConnection(
                conn.fromStepId,
                childStepId,
                conn.fromStepPath
            );
            this._connections.push(newConnection);
        });

        // Connect: child -> this step
        const connectionFromChildToStep = new FlowStepConnection(
            childStepId,
            stepId,
            childStep.results()[0] || 'success'
        );
        this._connections.push(connectionFromChildToStep);

        // Reconnect: this step -> child's children
        childOutgoingConnections.forEach((conn: FlowStepConnection) => {
            const newConnection = new FlowStepConnection(
                stepId,
                conn.toStepId,
                step.results()[0] || 'success'
            );
            this._connections.push(newConnection);
        });

        // Notify UI of changes
        StateManager.propertiesChanged(this, ['steps', 'connections']);
        return true;
    }

    /**
     * Check if a step can be moved up (has exactly one parent step that's not StartStep)
     */
    canMoveStepUp(stepId: string): boolean {
        const incomingConnections = this.getConnectionsToStep(stepId);
        if (incomingConnections.length !== 1) return false;

        const parentStep = this.getStepById(incomingConnections[0].fromStepId);
        return parentStep !== undefined && parentStep.__type !== 'StartStep';
    }

    /**
     * Check if a step can be moved down (has exactly one child step that's not EndStep)
     */
    canMoveStepDown(stepId: string): boolean {
        const outgoingConnections = this.getConnectionsFromStep(stepId);
        if (outgoingConnections.length !== 1) return false;

        const childStep = this.getStepById(outgoingConnections[0].toStepId);
        return childStep !== undefined && childStep.__type !== 'EndStep';
    }

    /**
     * Execute all steps before the specified step in prototype mode and return the accumulated data
     * @param stepId The ID of the step to stop before
     * @returns Promise with FlowStepData containing all data accumulated up to the specified step
     */
    async getDataAtStep(stepId: string): Promise<FlowStepData> {
        const targetStep = this.getStepById(stepId);
        if (!targetStep) {
            throw new Error(`Step with id '${stepId}' not found`);
        }

        // Create a new FlowStepData instance to accumulate data
        const data = new FlowStepData();

        // Find all steps that come before the target step by traversing backwards
        const stepsToExecute = this.getStepsBeforeStep(stepId);

        // Execute steps in order
        for (const step of stepsToExecute) {
            try {
                // Execute step in prototype mode (prototypeRun = true)
                const outcomePath = step.execute(data, true);

                // If step returns null, execution stops (shouldn't happen for prototype mode)
                if (outcomePath === null) {
                    break;
                }
            } catch (error) {
                // In prototype mode, we continue even if steps fail
                console.warn(`Step '${step.id}' failed during prototype execution: ${error}`);
            }
        }

        return data;
    }

    /**
     * Get all steps that should be executed before the specified step
     * This traverses the flow backwards from the target step to find all predecessors
     */
    private getStepsBeforeStep(stepId: string): FlowStep[] {
        const result: FlowStep[] = [];
        const visited = new Set<string>();
        const stack: string[] = [];

        // Start with the target step and work backwards
        stack.push(stepId);

        while (stack.length > 0) {
            const currentStepId = stack.pop()!;

            if (visited.has(currentStepId)) {
                continue;
            }
            visited.add(currentStepId);

            // Don't include the target step itself in the result
            if (currentStepId !== stepId) {
                const step = this.getStepById(currentStepId);
                if (step) {
                    result.unshift(step); // Add to beginning to maintain execution order
                }
            }

            // Find all steps that feed into this step
            const incomingConnections = this.getConnectionsToStep(currentStepId);
            for (const connection of incomingConnections) {
                if (!visited.has(connection.fromStepId)) {
                    stack.push(connection.fromStepId);
                }
            }
        }

        return result;
    }
}
