import {
  Add as AddIcon,
  Delete as DeleteIcon,
  Edit as EditIcon
} from '@mui/icons-material';
import {
  Box,
  Button,
  Chip,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  Grid,
  IconButton,
  Paper,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  TextField,
  Typography
} from '@mui/material';
import React, { useState } from 'react';
import { Clamp } from '../../../data/Common/Clamp';
import { ClampLibrary } from '../../../data/Common/ClampLibrary';
import { ConfigurationData } from '../../../data/ConfigurationData';
import { ObserveState } from '../../../utils/statemanager/ObserveState';
import { ColorPicker } from '../../Common/ColorPicker';
import { NumberInput } from '../../Common/NumberInput';
import { OffsetEditor } from '../../Common/OffsetEditor';

interface ClampDialogProps {
  open: boolean;
  clamp: Clamp | null;
  onClose: () => void;
  onSave: (clamp: Clamp) => void;
}

const ClampDialog: React.FC<ClampDialogProps> = ({ open, clamp, onClose, onSave }) => {
  const [formData, setFormData] = useState<Clamp>(() => clamp || new Clamp());

  React.useEffect(() => {
    setFormData(clamp || new Clamp());
  }, [clamp]);

  // Helper function to update clamp properties
  const updateClampProperty = (property: keyof Clamp, value: any) => {
    const newClamp = new Clamp();
    // Copy all existing properties
    newClamp.clampname = formData.clampname;
    newClamp.clampColor = formData.clampColor;
    newClamp.clampXWidth = formData.clampXWidth;
    newClamp.clampYWidth = formData.clampYWidth;
    newClamp.clampHeight = formData.clampHeight;
    newClamp.clampShape = formData.clampShape;
    // Copy CNCOffset
    newClamp.clampOffset.setValues(
      formData.clampOffsetX,
      formData.clampOffsetY,
      formData.clampOffsetZ
    );

    // Update the specific property
    (newClamp as any)[property] = value;
    setFormData(newClamp);
  };

  const handleSave = () => {
    onSave(formData);
    onClose();
  };

  return (
    <Dialog open={open} onClose={onClose} maxWidth="md" fullWidth>
      <DialogTitle>{clamp ? 'Edit Clamp' : 'Add New Clamp'}</DialogTitle>
      <DialogContent>
        <Grid container spacing={2} sx={{ mt: 1 }}>
          <Grid item xs={12} md={6}>
            <TextField
              fullWidth
              label="Clamp Name"
              value={formData.clampname}
              onChange={(e) => updateClampProperty('clampname', e.target.value)}
            />
          </Grid>

          <Grid item xs={12} md={6}>
            <ColorPicker
              label="Clamp Color"
              value={formData.clampColor}
              onChange={(color) => updateClampProperty('clampColor', color)}
            />
          </Grid>

          <Grid item xs={12} md={4}>
            <NumberInput
              fullWidth
              label="Width"
              value={formData.clampXWidth}
              onChange={(value) => updateClampProperty('clampXWidth', value)}
              precision={1}
            />
          </Grid>

          <Grid item xs={12} md={4}>
            <NumberInput
              fullWidth
              label="Height"
              value={formData.clampYWidth}
              onChange={(value) => updateClampProperty('clampYWidth', value)}
              precision={1}
            />
          </Grid>

          <Grid item xs={12} md={4}>
            <NumberInput
              fullWidth
              label="Length"
              value={formData.clampHeight}
              onChange={(value) => updateClampProperty('clampHeight', value)}
              precision={1}
            />
          </Grid>

          <Grid item xs={12}>
            <Typography variant="subtitle2" gutterBottom sx={{ mt: 2 }}>
              Position Offset (relative to material corner)
            </Typography>
          </Grid>

          <Grid item xs={12}>
            <OffsetEditor
              offset={formData.clampOffset}
              onOffsetChange={(newOffset) => {
                formData.clampOffset.setValues(newOffset.x, newOffset.y, newOffset.z);
                updateClampProperty('clampOffset', formData.clampOffset);
              }}
              xLabel="X Offset"
              yLabel="Y Offset"
              zLabel="Z Offset"
            />
          </Grid>
        </Grid>
      </DialogContent>
      <DialogActions>
        <Button onClick={onClose}>Cancel</Button>
        <Button onClick={handleSave} variant="contained">Save</Button>
      </DialogActions>
    </Dialog>
  );
};

export const ClampLibraryTab: React.FC = () => {
  const [library] = useState(() => ClampLibrary.Instance);
  const [dialogOpen, setDialogOpen] = useState(false);
  const [editingClamp, setEditingClamp] = useState<Clamp | null>(null);

  const handleAddClamp = () => {
    setEditingClamp(null);
    setDialogOpen(true);
  };

  const handleEditClamp = (clamp: Clamp) => {
    setEditingClamp(clamp);
    setDialogOpen(true);
  };

  const handleDeleteClamp = (clamp: Clamp) => {
    library.removeClamp(clamp);
  };

  const handleSaveClamp = (clamp: Clamp) => {
    if (editingClamp) {
      // Update existing clamp
      library.updateClamp(editingClamp, clamp);
    } else {
      // Add new clamp
      library.addClamp(clamp);
    }
  };

  return (
    <ObserveState
      listenTo={library}
      control={() => (
        <Box sx={{ p: 3 }}>
          <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 3 }}>
            <Typography variant="h6">Clamp Library</Typography>
            <Button
              variant="contained"
              startIcon={<AddIcon />}
              onClick={handleAddClamp}
            >
              Add Clamp
            </Button>
          </Box>

          <TableContainer component={Paper}>
            <Table>
              <TableHead>
                <TableRow>
                  <TableCell>Name</TableCell>
                  <TableCell>Dimensions (W × H × L)</TableCell>
                  <TableCell>Color</TableCell>
                  <TableCell align="right">Actions</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {library.clamps.map((clamp, index) => (
                  <TableRow key={index}>
                    <TableCell>{clamp.clampname}</TableCell>
                    <TableCell>
                      {clamp.clampXWidth} × {clamp.clampYWidth} × {clamp.clampHeight}
                    </TableCell>
                    <TableCell>
                      <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                        <Box
                          sx={{
                            width: 24,
                            height: 24,
                            backgroundColor: clamp.clampColor,
                            border: `1px solid ${ConfigurationData.Instance.secondaryBorderColor}`,
                            borderRadius: 1
                          }}
                        />
                        <Chip
                          label={clamp.clampColor}
                          size="small"
                          style={{ backgroundColor: clamp.clampColor, color: ConfigurationData.Instance.lightTextColor }}
                        />
                      </Box>
                    </TableCell>
                    <TableCell align="right">
                      <IconButton
                        size="small"
                        onClick={() => handleEditClamp(clamp)}
                        color="primary"
                      >
                        <EditIcon />
                      </IconButton>
                      <IconButton
                        size="small"
                        onClick={() => handleDeleteClamp(clamp)}
                        color="error"
                      >
                        <DeleteIcon />
                      </IconButton>
                    </TableCell>
                  </TableRow>
                ))}
                {library.clamps.length === 0 && (
                  <TableRow>
                    <TableCell colSpan={4} align="center" sx={{ py: 4, color: 'text.secondary' }}>
                      No clamps found. Click "Add Clamp" to create your first clamp.
                    </TableCell>
                  </TableRow>
                )}
              </TableBody>
            </Table>
          </TableContainer>

          <ClampDialog
            open={dialogOpen}
            clamp={editingClamp}
            onClose={() => setDialogOpen(false)}
            onSave={handleSaveClamp}
          />
        </Box>
      )}
    />
  );
};
