import {
  Input as InputIcon,
  Output as OutputIcon
} from '@mui/icons-material';
import {
  Alert,
  Box,
  CircularProgress,
  List,
  Paper,
  Typography
} from '@mui/material';
import { Component } from 'react';
import { ConfigurationData } from '../../data/ConfigurationData';
import { IOStateData } from '../../data/IOStateData';
import { UserMessageQueue } from '../../data/UserMessageQueue';
import { Machine } from '../../machine/Machine';
import { LogCategory, Logger } from '../../utils/Logger';
import { ObserveState } from '../../utils/statemanager/ObserveState';
import { InputItem } from './InputItem';
import { OutputItem } from './OutputItem';

interface InputOutputDrawerProps {
  onViewChange?: (view: string) => void;
}

interface InputOutputDrawerState {
  loading: boolean;
  error: string | null;
  // Note: Override tracking moved to ConfigurationState for non-persistent storage
}
interface InputOutputDrawerState {
  loading: boolean;
  error: string | null;
}

export class InputOutputDrawer extends Component<InputOutputDrawerProps, InputOutputDrawerState> {

  constructor(props: InputOutputDrawerProps) {
    super(props);
    this.state = {
      loading: false,
      error: null
    };
  }

  private handleOutputToggle = async (outputNumber: number, newState: boolean) => {
    try {
      const machine = Machine.getInstance();
      if (!machine) {
        throw new Error('Machine instance not available');
      }

      await machine.io.SetOutputState(outputNumber, newState);

      // Find output for notification
      const output = IOStateData.Instance.getOutputByNumber(outputNumber);
      const outputName = output?.name || `Output ${outputNumber}`;

      UserMessageQueue.Instance.addMessage(`${outputName} turned ${newState ? 'ON' : 'OFF'}`);
    } catch (error) {
      Logger.Instance.logError(LogCategory.UserInterface, 'Failed to set output state:', error);
    }
  }

  render() {
    const { loading, error } = this.state;

    return (
      <ObserveState
        key="input-output-drawer"
        listenTo={IOStateData.Instance}
        properties={['inputs', 'outputs', 'isInitialized']}
        control={() => {
          const config = ConfigurationData.Instance;
          const ioState = IOStateData.Instance;

          const inputs = ioState.inputs;
          const outputs = ioState.outputs;

          return (
            <Box
              sx={{
                height: '100%',
                display: 'flex',
                flexDirection: 'column',
                backgroundColor: config.lightBackgroundColor
              }}
            >
              {/* Error Display */}
              {error && (
                <Alert severity="error" sx={{ m: 1 }}>
                  {error}
                </Alert>
              )}

              {/* Loading Indicator */}
              {loading && (
                <Box sx={{ display: 'flex', justifyContent: 'center', p: 2 }}>
                  <CircularProgress size={24} />
                </Box>
              )}

              {/* Scrollable Content */}
              <Box sx={{ flex: 1, overflow: 'auto' }}>
                {/* Inputs Section */}
                {inputs.length > 0 && (
                  <Paper sx={{ m: 1, overflow: 'hidden' }} variant="outlined">
                    <Box sx={{
                      p: 1.5,
                      backgroundColor: config.lightBackgroundColor,
                      borderBottom: `1px solid ${config.secondaryBorderColor}`
                    }}>
                      <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5 }}>
                        <InputIcon sx={{ color: config.primaryColor, fontSize: 18 }} />
                        <Typography variant="subtitle2" sx={{ fontWeight: 'bold', fontSize: '0.85rem' }}>
                          Inputs ({inputs.length})
                        </Typography>
                      </Box>
                    </Box>

                    <List sx={{ py: 0 }}>
                      {inputs.map((input) => (
                        <InputItem
                          key={`input-${input.number}`}
                          input={input}
                          isActive={input.isActive}
                        />
                      ))}
                    </List>
                  </Paper>
                )}

                {/* Outputs Section */}
                {outputs.length > 0 && (
                  <Paper sx={{ m: 1, overflow: 'hidden' }} variant="outlined">
                    <Box sx={{
                      p: 1.5,
                      backgroundColor: config.lightBackgroundColor,
                      borderBottom: `1px solid ${config.secondaryBorderColor}`
                    }}>
                      <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5 }}>
                        <OutputIcon sx={{ color: config.primaryColor, fontSize: 18 }} />
                        <Typography variant="subtitle2" sx={{ fontWeight: 'bold', fontSize: '0.85rem' }}>
                          Outputs ({outputs.length})
                        </Typography>
                      </Box>
                    </Box>

                    <List sx={{ py: 0 }}>
                      {outputs.map((output) => (
                        <OutputItem
                          key={`output-${output.number}`}
                          output={output}
                          isActive={output.isActive}
                          onToggle={this.handleOutputToggle}
                        />
                      ))}
                    </List>
                  </Paper>
                )}

                {/* No I/O configured message */}
                {inputs.length === 0 && outputs.length === 0 && (
                  <Box sx={{ p: 3, textAlign: 'center' }}>
                    <Typography variant="body2" sx={{ color: config.mutedTextColor }}>
                      No inputs or outputs configured
                    </Typography>
                  </Box>
                )}
              </Box>
            </Box>
          );
        }}
      />
    );
  }
}