/// <reference path="../three-jsx.d.ts" />
import { CNCPoint } from '../../../data/CNCPoint';
import { CoordinateType } from '../../../data/Common/CoordinateType';
import { CoordinateUtil } from '../../../utils/CoordinateUtil';

/**
 * Renders a bright magenta sphere at the Simulator origin (0,0,0)
 * This is the physical machine base corner and the origin of the 3D world
 */
export function SimulatorOrigin() {
    console.log('🔴🔴🔴 SimulatorOrigin function CALLED!!!');

    // Always convert to Simulator coordinates for rendering (defensive programming)
    const originPoint = new CNCPoint(0, 0, 0, CoordinateType.Simulator);
    console.log('🔴 Created originPoint:', originPoint);

    const position = CoordinateUtil.toSimulator(originPoint);
    console.log('🔴 Converted position:', position.x, position.y, position.z);

    return (
        <mesh position={[position.x, position.y, position.z]}>
            <sphereGeometry args={[10.0, 32, 32]} />
            <meshBasicMaterial color="#ff00ff" depthTest={false} depthWrite={false} />
        </mesh>
    );
}
