export enum ZAxisReferenceType {
  BED = 'bed',
  SPOILBOARD = 'spoilboard', 
  MATERIAL = 'material'
}

export enum TouchOffMethod {
  MANUAL = 'manual',
  TOUCHPLATE = 'touchplate'
}

// Step constants for better readability
export enum TouchplateStep {
  MATERIAL_POSITION_CHECK = 1,
  TEST_TOUCHPLATE = 2,
  POSITION_TOUCHPLATE = 3,
  PROGRESS = 4,
  RESULTS = 5
}

export enum ManualStep {
  INSTRUCTIONS = 1,
  JOG_CONTROLS = 2,
  RESULTS = 3
}

export interface CalibrationState {
  method: TouchOffMethod | null;
  currentStep: number;
  isProcessing: boolean;
  referenceType: ZAxisReferenceType;
  touchplateDetected: boolean;
  startZ: number | null;
  resultZ: number | null;
  height: number | null;
  isComplete: boolean;
  error: string | null;
}

export interface TouchplateConfig {
  probeSpeed: number;
  retractDistance: number;
  probeDistance: number;
  touchplateThickness: number;
}

export interface ManualJogSettings {
  incrementX: number;
  incrementY: number;
  incrementZ: number;
  fastJogRate: number;
  slowJogRate: number;
}

export interface CalibrationResult {
  success: boolean;
  referenceType: ZAxisReferenceType;
  finalZ: number;
  touchplateThickness?: number;
  notes?: string;
  timestamp: Date;
}

// Default configuration values
export const DEFAULT_TOUCHPLATE_CONFIG: TouchplateConfig = {
  probeSpeed: 50, // mm/min
  retractDistance: 2, // mm
  probeDistance: 10, // mm
  touchplateThickness: 19.05 // mm (3/4 inch)
};

export const DEFAULT_JOG_SETTINGS: ManualJogSettings = {
  incrementX: 1.0,
  incrementY: 1.0,
  incrementZ: 0.1,
  fastJogRate: 1000, // mm/min
  slowJogRate: 100  // mm/min
};
