import { Box, Typography } from '@mui/material';
import React from 'react';
import { StateManager } from "../utils/statemanager/StateManager";
import { DataUtilities } from "../utils/storage/DataUtilities";
import { IStorable } from "../utils/storage/IStorable";
import { FlowStepData } from "./FlowStepData";

export abstract class FlowStep implements IStorable {
    private static idCounter = 0;

    id: string;

    // Custom name for this step instance (overrides the default name)
    private _customName?: string;

    // Manual positioning support
    manualPosition?: { x: number; y: number };
    isManuallyPositioned: boolean = false;

    constructor(id?: string) {
        // Generate unique ID if not provided, except for StartStep which should always be 'start'
        this.id = id || this.generateUniqueId();
    }

    private generateUniqueId(): string {
        FlowStep.idCounter++;
        const typeName = this.constructor.name.replace('Step', '');
        const timestamp = Date.now();
        const random = Math.floor(Math.random() * 1000);
        return `${typeName.toLowerCase()}_${FlowStep.idCounter}_${timestamp}_${random}`;
    }

    abstract get __type(): string; // Unique identifier for the step type
    abstract get category(): string[]; // Category path for tree-like grouping of steps
    abstract get name(): string; // Display name for the step
    abstract get description(): string; // Description of what this step does

    // Whether this step type can be added via the step insert dialog
    readonly canAdd: boolean = true;

    // Get the display name (custom name if set, otherwise default name)
    getDisplayName(): string {
        return this._customName || this.name;
    }

    // Getter and setter for customName with StateManager notification
    get customName(): string | undefined {
        return this._customName;
    }

    set customName(value: string | undefined) {
        this._customName = value;
        StateManager.propertyChanged(this, 'customName');
    }

    // Optional icon for the step - implemented as getter to prevent serialization
    get icon(): React.ReactNode | undefined {
        return undefined;
    }

    abstract execute(data: FlowStepData, prototypeRun: boolean): Promise<string | null>; // Returns outcome path or null to stop
    abstract results(): string[];

    // Default implementation for step UI rendering - can be overridden
    renderStepUI(): React.ReactNode {
        return (
            <Box display="flex" alignItems="center" gap={0.5} sx={{ minWidth: 0, width: '100%' }}>
                {this.icon && (
                    <Box sx={{
                        display: 'flex',
                        alignItems: 'center',
                        fontSize: '0.75rem',
                        flexShrink: 0 // Prevent icon from shrinking
                    }}>
                        {this.icon}
                    </Box>
                )}
                <Box sx={{ minWidth: 0, flex: 1 }}>
                    <Typography
                        variant="body2"
                        fontWeight="bold"
                        sx={{
                            fontSize: '0.75rem',
                            lineHeight: 1.2,
                            overflow: 'hidden',
                            textOverflow: 'ellipsis',
                            whiteSpace: 'nowrap'
                        }}
                        title={this.getDisplayName()} // Show full name on hover
                    >
                        {this.getDisplayName()}
                    </Typography>
                </Box>
            </Box>
        );
    }

    abstract renderResultsUI(data: FlowStepData, result: string): React.ReactNode;

    // Default implementation for edit UI - shows description in a dialog
    // Override this method only if the step has editable properties
    renderEditUI(props: { onClose: () => void, flow: any, flowStep?: any }): React.ReactNode {
        return (
            <Box sx={{ p: 3, minWidth: 400 }}>
                <Typography variant="body1" color="text.secondary" sx={{ mb: 3 }}>
                    {this.description}
                </Typography>
            </Box>
        );
    }

    toJSON(): any {
        // Exclude icon from serialization - icons should be hard-coded in components
        const data = DataUtilities.getStorageData(this, ['icon']) as any;
        // Always include __type for polymorphic serialization
        data.__type = this.__type;
        return data;
    }

    fromJSON(json: any): void {
        DataUtilities.loadStorageData(this, json);
    }
}
