import React from 'react';
import { 
  Box,
  Button,
  Typography,
  Paper,
  Collapse,
  IconButton
} from '@mui/material';
import { ExpandMore, ExpandLess } from '@mui/icons-material';
import { CNCViewType } from './MachineViewer';
import { FullSizeCNCViewer } from './MachineViewer/FullSizeCNCViewer';
import { MachineStateData } from '../data/MachineStateData';
import { MachineData } from '../data/MachineData';
import { ConfigurationData } from '../data/ConfigurationData';
import { Job } from '../data/Job';
import { SystemIcons } from '../SystemIcons';

export interface CNCViewerDemoProps {
}

export const CNCSimulatorView: React.FC<CNCViewerDemoProps> = () => {
  // Create instances of the data objects
  const machineState = MachineStateData.Instance;
  const machineData = MachineData.Instance;
  const [viewType, setViewType] = React.useState<CNCViewType>(CNCViewType.Perspective);
  const [showInstructions, setShowInstructions] = React.useState(false);
  
  // Get the appropriate simulator view based on current view type
  const getSimulatorView = () => {
    const config = ConfigurationData.Instance;
    return viewType === CNCViewType.Top ? config.topWorkpieceView : config.defaultView;
  };

  const currentSimulatorView = getSimulatorView();
  const config = ConfigurationData.Instance;

  return (
    <Box sx={{ position: 'relative', height: '100%' }}>
      {/* 3D Viewer - Full Container */}
      <Box sx={{ height: '100%' }}>
        {/* View Type Buttons - Floating in bottom right */}
        <Box sx={{ 
          position: 'absolute', 
          bottom: 16, 
          right: 16, 
          zIndex: 10,
          display: 'flex',
          flexDirection: 'column',
          gap: 1
        }}>
            {Object.values(CNCViewType)
              .filter(type => 
                type !== CNCViewType.ZAxisCalibration && 
                type !== CNCViewType.DefaultTop
              )
              .map((type) => (
              <Button
                key={type}
                variant={viewType === type ? 'contained' : 'outlined'}
                onClick={() => setViewType(type)}
                sx={{ 
                  minWidth: 80,
                  fontSize: '0.875rem'
                }}
              >
                {type}
              </Button>
            ))}
          </Box>

        {/* Instructions Overlay - Floating in top left */}
        <Box sx={{ 
          position: 'absolute', 
          top: 16, 
          left: 16, 
          zIndex: 20,
          maxWidth: '500px' // Increased width
        }}>
          {/* Title and Collapsible Instructions */}
          <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: showInstructions ? 2 : 0 }}>
            <Typography variant="h5" sx={{ color: config.darkTextColor, fontWeight: 'bold' }}>
              Simulator View
            </Typography>
            <IconButton 
              onClick={() => setShowInstructions(!showInstructions)}
              size="small"
              sx={{ 
                color: config.primaryColor,
                backgroundColor: 'rgba(255, 255, 255, 0.9)',
                '&:hover': {
                  backgroundColor: 'rgba(255, 255, 255, 1)',
                }
              }}
            >
              {showInstructions ? <ExpandLess /> : <ExpandMore />}
            </IconButton>
            <Typography 
              variant="body2" 
              sx={{ 
                color: config.darkTextColor, 
                cursor: 'pointer',
                backgroundColor: 'rgba(255, 255, 255, 0.9)',
                padding: '4px 8px',
                borderRadius: 1,
                '&:hover': {
                  backgroundColor: 'rgba(255, 255, 255, 1)',
                }
              }}
              onClick={() => setShowInstructions(!showInstructions)}
            >
              {showInstructions ? 'Hide Instructions' : 'Show Instructions'}
            </Typography>
          </Box>
          
          <Collapse in={showInstructions}>
            <Paper 
              elevation={3} 
              sx={{ 
                p: 2, 
                backgroundColor: 'rgba(255, 255, 255, 0.95)',
                borderLeft: `4px solid ${config.primaryColor}`,
                backdropFilter: 'blur(10px)'
              }}
            >
              <Typography variant="h6" sx={{ color: config.darkTextColor, mb: 1.5, fontSize: '1rem' }}>
                How to Use the 3D Viewer
              </Typography>
              
              <Box component="ul" sx={{ 
                color: config.darkTextColor, 
                lineHeight: 1.6, 
                pl: 2, 
                m: 0,
                '& li': {
                  mb: 0.8,
                  display: 'flex',
                  alignItems: 'flex-start',
                  gap: 1
                }
              }}>
                <li>
                  <Box sx={{ minWidth: 'fit-content' }}>
                    <strong>Drag to rotate:</strong>
                  </Box>
                  <span>Click and drag anywhere to rotate the camera</span>
                </li>
                <li>
                  <Box sx={{ minWidth: 'fit-content' }}>
                    <strong>Move spindle:</strong>
                  </Box>
                  <span>When viewing from Top, click the spindle to position it</span>
                </li>
                <li>
                  <Box sx={{ minWidth: 'fit-content', display: 'flex', alignItems: 'center', gap: 0.5 }}>
                    <strong>Reset view:</strong>
                    <Box sx={{ 
                      display: 'inline-flex', 
                      alignItems: 'center',
                      backgroundColor: config.lightOverlay,
                      padding: '2px 6px',
                      borderRadius: '4px',
                      fontSize: '0.75rem'
                    }}>
                      {SystemIcons.home}
                    </Box>
                  </Box>
                  <span>Use the Home button in zoom controls to reset the camera</span>
                </li>
                <li>
                  <Box sx={{ minWidth: 'fit-content', display: 'flex', alignItems: 'center', gap: 0.5 }}>
                    <strong>Change settings:</strong>
                    <Box sx={{ 
                      display: 'inline-flex', 
                      alignItems: 'center',
                      backgroundColor: config.lightOverlay,
                      padding: '2px 6px',
                      borderRadius: '4px',
                      fontSize: '0.75rem'
                    }}>
                      {SystemIcons.viewerSettings}
                    </Box>
                  </Box>
                  <span>Click the Settings button to customize the view</span>
                </li>
              </Box>
            </Paper>
          </Collapse>
        </Box>
        
        <FullSizeCNCViewer
          simulatorView={currentSimulatorView}
          machineState={machineState}
          machineData={machineData}
          job={machineState.currentJob || Job.createTestJob()}
          viewType={viewType}
          isHardcodedSettings={false}
          enableClampDragging={false}
        />
      </Box>
    </Box>
  );
};
