import {
  Box,
  Card,
  CardContent,
  Typography,
} from '@mui/material';
import React from 'react';
import { Handle, NodeProps, Position } from 'reactflow';
import { ConfigurationData } from '../../data/ConfigurationData';
import { FlowStep } from '../../flow/FlowStep';
import { ObserveState } from '../../utils/statemanager/ObserveState';

interface FlowStepNodeData {
  step: FlowStep;
  onDelete?: (stepId: string) => void;
  onResetPosition?: (stepId: string) => void;
  onEdit?: (step: FlowStep) => void;
  onMoveUp?: (stepId: string) => void;
  onMoveDown?: (stepId: string) => void;
  canMoveUp?: boolean;
  canMoveDown?: boolean;
  onStepClick?: (step: FlowStep) => void;
}

export const FlowStepNode: React.FC<NodeProps<FlowStepNodeData>> = ({ data, selected }) => {
  const { step, onStepClick } = data;

  const handleStepClick = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (onStepClick) {
      onStepClick(step);
    }
  };

  const outputPaths = step.results();

  return (
    <ObserveState
      key={`flow-step-node-${step.id}`}
      listenTo={step}
      properties={['customName']}
      control={() => (
        <Card
          onClick={handleStepClick}
          sx={{
            minWidth: 200,
            maxWidth: 250,
            cursor: 'pointer',
            border: selected
              ? `2px solid ${ConfigurationData.Instance.primaryColor}`
              : step.isManuallyPositioned
                ? `2px solid ${ConfigurationData.Instance.primaryColor}`
                : `1px solid ${ConfigurationData.Instance.borderColor}`,
            '&:hover': {
              boxShadow: 3,
            },
          }}
        >
          {/* Input handle */}
          {step.__type !== 'StartStep' && (
            <Handle
              type="target"
              position={Position.Top}
              style={{
                background: ConfigurationData.Instance.veryDarkColor,
                width: 8,
                height: 8,
                left: '50%',
              }}
            />
          )}

          <CardContent sx={{ padding: 1, minHeight: 'unset' }}>
            <Box display="flex" alignItems="center" justifyContent="space-between">
              <Box display="flex" alignItems="center" gap={0.5}>
                {/* Use the step's renderStepUI method */}
                {step.renderStepUI()}
              </Box>
            </Box>
          </CardContent>

          {/* Output handles for each result path */}
          {outputPaths.map((path, index) => {
            // Center single handles, distribute multiple handles
            const leftPosition = outputPaths.length === 1
              ? '50%'
              : `${25 + (index * 50)}%`;

            return (
              <Handle
                key={path}
                type="source"
                position={Position.Bottom}
                id={path}
                style={{
                  background: ConfigurationData.Instance.primaryColor,
                  width: 8,
                  height: 8,
                  left: leftPosition,
                }}
              />
            );
          })}

          {/* Output path labels */}
          {outputPaths.length > 1 && (
            <Box
              sx={{
                position: 'absolute',
                bottom: -20,
                left: 0,
                right: 0,
                display: 'flex',
                justifyContent: 'space-around',
                pointerEvents: 'none',
              }}
            >
              {outputPaths.map((path) => (
                <Typography
                  key={path}
                  variant="caption"
                  sx={{
                    fontSize: '0.65rem',
                    color: 'text.secondary',
                    background: ConfigurationData.Instance.lightOverlay,
                    padding: '2px 4px',
                    borderRadius: 1,
                  }}
                >
                  {path}
                </Typography>
              ))}
            </Box>
          )}
        </Card>
      )}
    />
  );
};
