import React from 'react';
import { Grid, Typography, Button } from '@mui/material';
import { NumberInput } from './NumberInput';
import { ATCLocation } from '../../data/MachineData';
import { MachineStateData } from '../../data/MachineStateData';

interface ATCLocationComponentProps {
  atcLocation: ATCLocation;
  onChange: () => void;
  title?: string;
  showSetButtons?: boolean;
}

export function ATCLocationComponent({
  atcLocation,
  onChange,
  title = "Location (from Machine Zero)",
  showSetButtons = true
}: ATCLocationComponentProps) {
  
  const handleSetXY = () => {
    const machineState = MachineStateData.Instance;
    atcLocation.x = machineState.currentMachinePoint.x;
    atcLocation.y = machineState.currentMachinePoint.y;
    onChange();
  };

  const handleSetXYZ = () => {
    const machineState = MachineStateData.Instance;
    atcLocation.x = machineState.currentMachinePoint.x;
    atcLocation.y = machineState.currentMachinePoint.y;
    atcLocation.z = machineState.currentMachinePoint.z;
    onChange();
  };

  return (
    <>
      <Grid item xs={12}>
        <Typography variant="subtitle1" sx={{ mt: 2, mb: 1 }}>{title}</Typography>
      </Grid>
      
      <Grid item xs={12} md={3}>
        <NumberInput
          fullWidth
          label="X Position"
          value={atcLocation.x}
          onChange={(value) => {
            atcLocation.x = value;
            onChange();
          }}
          margin="normal"
          precision={3}
        />
        <Typography variant="caption" color="text.secondary">
          X coordinate from machine zero
        </Typography>
      </Grid>
      
      <Grid item xs={12} md={3}>
        <NumberInput
          fullWidth
          label="Y Position"
          value={atcLocation.y}
          onChange={(value) => {
            atcLocation.y = value;
            onChange();
          }}
          margin="normal"
          precision={3}
        />
        <Typography variant="caption" color="text.secondary">
          Y coordinate from machine zero
        </Typography>
      </Grid>
      
      <Grid item xs={12} md={3}>
        <NumberInput
          fullWidth
          label="Z Position"
          value={atcLocation.z}
          onChange={(value) => {
            atcLocation.z = value;
            onChange();
          }}
          margin="normal"
          precision={3}
        />
        <Typography variant="caption" color="text.secondary">
          Z coordinate from machine zero
        </Typography>
      </Grid>

      {showSetButtons && (
        <Grid item xs={12} md={3} sx={{ display: 'flex', flexDirection: 'column', justifyContent: 'center', gap: 1, pt: 2 }}>
          <Button 
            variant="outlined" 
            onClick={handleSetXY}
            size="small"
          >
            Set XY
          </Button>
          <Button 
            variant="outlined" 
            onClick={handleSetXYZ}
            size="small"
          >
            Set XYZ
          </Button>
        </Grid>
      )}
    </>
  );
}
