import {
    DROEvent,
    JobCompletedEvent,
    JobInfoEvent,
    JobStartedEvent,
    MessageEvent,
    StepExecutionEvent,
} from './SignalR/SignalREventTypes';
import { SignalRManager } from '../utils/SignalRManager';
import { StateManager } from '../utils/statemanager/StateManager';

export interface MessageDisplay {
    id: number;
    timestamp: Date;
    type: string;
    message: string;
    severity?: 'Info' | 'Warning' | 'Error';
    eventCode?: number;      // Centroid error code for coloring
    eventType?: string;      // Classification type for coloring
    data?: any;
}

/**
 * Singleton data class that stores SignalR messages for display.
 * Automatically subscribes to all SignalR events and maintains a circular buffer
 * of the last 1000 messages.
 */
export class SignalRMessagesData {
    private static _instance: SignalRMessagesData;
    private _messages: MessageDisplay[] = [];
    private _messageIdCounter: number = 0;
    private _maxMessages: number = 1000;
    private _isListening: boolean = false;

    private constructor() {
        // Private constructor for singleton pattern
    }

    public static get Instance(): SignalRMessagesData {
        if (!SignalRMessagesData._instance) {
            SignalRMessagesData._instance = new SignalRMessagesData();
        }
        return SignalRMessagesData._instance;
    }

    /**
     * Start listening to SignalR events and storing messages.
     * Safe to call multiple times - will only register listeners once.
     */
    public startListening(): void {
        if (this._isListening) {
            return;
        }

        const manager = SignalRManager.Instance;

        manager.addEventListener('MessageEvent', this.handleMessageEvent);
        manager.addEventListener('DROEvent', this.handleDROEvent);
        manager.addEventListener('JobInfoEvent', this.handleJobInfoEvent);
        manager.addEventListener('JobStartedEvent', this.handleJobStartedEvent);
        manager.addEventListener('JobCompletedEvent', this.handleJobCompletedEvent);
        manager.addEventListener('StepExecutionEvent', this.handleStepExecutionEvent);

        this._isListening = true;
    }

    /**
     * Stop listening to SignalR events.
     * Typically not needed as we want to collect messages throughout the session.
     */
    public stopListening(): void {
        if (!this._isListening) {
            return;
        }

        const manager = SignalRManager.Instance;

        manager.removeEventListener('MessageEvent', this.handleMessageEvent);
        manager.removeEventListener('DROEvent', this.handleDROEvent);
        manager.removeEventListener('JobInfoEvent', this.handleJobInfoEvent);
        manager.removeEventListener('JobStartedEvent', this.handleJobStartedEvent);
        manager.removeEventListener('JobCompletedEvent', this.handleJobCompletedEvent);
        manager.removeEventListener('StepExecutionEvent', this.handleStepExecutionEvent);

        this._isListening = false;
    }

    private handleMessageEvent = (event: MessageEvent) => {
        this.addMessage({
            id: ++this._messageIdCounter,
            timestamp: event.timestamp,
            type: 'Message',
            message: event.data.message,
            severity: 'Info',
            eventCode: event.data.eventCode,      // Store for color logic
            eventType: event.data.eventType,      // Store for color logic
            data: event.data,
        });
    };

    private handleDROEvent = (event: DROEvent) => {
        // Only show DRO events occasionally to avoid flooding (every 10th event)
        if (this._messageIdCounter % 10 === 0) {
            this.addMessage({
                id: ++this._messageIdCounter,
                timestamp: event.timestamp,
                type: 'DRO Update',
                message: `Position - X: ${event.data.axis1.toFixed(3)}, Y: ${event.data.axis2.toFixed(3)}, Z: ${event.data.axis3.toFixed(3)}`,
                data: event.data,
            });
        } else {
            // Still increment counter even when not showing, so we maintain the 1-in-10 pattern
            this._messageIdCounter++;
        }
    };

    private handleJobInfoEvent = (event: JobInfoEvent) => {
        this.addMessage({
            id: ++this._messageIdCounter,
            timestamp: event.timestamp,
            type: 'Job Info',
            message: `${event.data.jobName} - Line ${event.data.lineNumber}`,
            data: event.data,
        });
    };

    private handleJobStartedEvent = (event: JobStartedEvent) => {
        this.addMessage({
            id: ++this._messageIdCounter,
            timestamp: event.timestamp,
            type: 'Job Started',
            message: `Job started: ${event.data.message}`,
            severity: 'Info',
            data: event.data,
        });
    };

    private handleJobCompletedEvent = (event: JobCompletedEvent) => {
        this.addMessage({
            id: ++this._messageIdCounter,
            timestamp: event.timestamp,
            type: 'Job Completed',
            message: event.data.success
                ? `Job completed: ${event.data.message}`
                : `Job failed: ${event.data.message} - ${event.data.errorMessage}`,
            severity: event.data.success ? 'Info' : 'Error',
            data: event.data,
        });
    };

    private handleStepExecutionEvent = (event: StepExecutionEvent) => {
        this.addMessage({
            id: ++this._messageIdCounter,
            timestamp: event.timestamp,
            type: 'Step Execution',
            message: `Line ${event.data.lineNumber}: ${event.data.currentLine}`,
            data: event.data,
        });
    };

    private addMessage(message: MessageDisplay): void {
        // Add message to the beginning of the array
        this._messages.unshift(message);

        // Keep only the last N messages (circular buffer)
        if (this._messages.length > this._maxMessages) {
            this._messages = this._messages.slice(0, this._maxMessages);
        }

        // Notify observers that messages have changed
        StateManager.propertyChanged(this, 'messages');
    }

    /**
     * Get all stored messages (most recent first)
     */
    public get messages(): MessageDisplay[] {
        return this._messages;
    }

    /**
     * Clear all stored messages
     */
    public clearMessages(): void {
        this._messages = [];
        this._messageIdCounter = 0;
        StateManager.propertyChanged(this, 'messages');
    }

    /**
     * Get the number of stored messages
     */
    public get messageCount(): number {
        return this._messages.length;
    }

    /**
     * Get whether we're currently listening for events
     */
    public get isListening(): boolean {
        return this._isListening;
    }
}
