import { PlayArrow as PlayIcon, Save as SaveIcon } from '@mui/icons-material';
import {
    Box,
    Button,
    Dialog,
    DialogActions,
    DialogContent,
    DialogTitle,
    TextField,
    Typography
} from '@mui/material';
import { useState } from 'react';
import { ConfigurationData } from '../../data/ConfigurationData';

interface GCodePreviewDialogProps {
    open: boolean;
    title: string;
    gcode: string[];
    onRun: () => void;
    onCancel: () => void;
}

export function GCodePreviewDialog({
    open,
    title,
    gcode,
    onRun,
    onCancel
}: GCodePreviewDialogProps) {
    const config = ConfigurationData.Instance;
    const [gcodeText] = useState(gcode.join('\n'));

    const handleSave = () => {
        const blob = new Blob([gcodeText], { type: 'text/plain' });
        const url = URL.createObjectURL(blob);
        const link = document.createElement('a');
        link.href = url;
        link.download = `tool_change_${Date.now()}.nc`;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
        URL.revokeObjectURL(url);
    };

    return (
        <Dialog
            open={open}
            onClose={onCancel}
            maxWidth="md"
            fullWidth
            sx={{
                zIndex: 3000
            }}
            PaperProps={{
                sx: {
                    borderRadius: 2,
                    boxShadow: 3
                }
            }}
        >
            <DialogTitle sx={{
                color: config.primaryColor,
                fontWeight: 'bold',
                pb: 1
            }}>
                {title}
            </DialogTitle>
            <DialogContent>
                <Box sx={{ mb: 2 }}>
                    <Typography variant="body2" sx={{ mb: 1 }}>
                        Review the G-code that will be executed:
                    </Typography>
                </Box>
                <TextField
                    multiline
                    fullWidth
                    rows={20}
                    value={gcodeText}
                    InputProps={{
                        readOnly: true,
                        sx: {
                            fontFamily: 'monospace',
                            fontSize: '0.9rem'
                        }
                    }}
                    sx={{
                        '& .MuiOutlinedInput-root': {
                            '& fieldset': {
                                borderColor: config.borderColor
                            }
                        }
                    }}
                />
            </DialogContent>
            <DialogActions sx={{ justifyContent: 'flex-end', gap: 1, p: 2 }}>
                <Button
                    onClick={onCancel}
                    variant="outlined"
                >
                    Cancel
                </Button>
                <Button
                    onClick={handleSave}
                    variant="text"
                    startIcon={<SaveIcon />}
                >
                    Save
                </Button>
                <Button
                    onClick={onRun}
                    variant="contained"
                    startIcon={<PlayIcon />}
                    sx={{
                        backgroundColor: config.primaryColor,
                        '&:hover': {
                            backgroundColor: config.primaryColor,
                            opacity: 0.9
                        }
                    }}
                >
                    Run
                </Button>
            </DialogActions>
        </Dialog>
    );
}
