import { Box, Button, Dialog, DialogActions, DialogContent, DialogTitle } from '@mui/material';
import { useState } from 'react';
import { ConfigurationData } from '../../data/ConfigurationData';
import { MachineStateData } from '../../data/MachineStateData';
import { Machine } from '../../machine/Machine';
import { AxisCoordinateDisplay } from '../Common/AxisCoordinateDisplay';
import { MachineActionsPanel } from '../Common/MachineActionsPanel';
import { MessageViewer } from '../Common/MessageViewer';
import { SafeModeControl } from '../Common/SafeModeControl';
import { ClampEditorForm } from '../Views/ClampEditorForm';
import { MaterialEditor } from '../Views/MaterialEditor';

/**
 * Right sidebar containing Safe Mode, Coordinates, Messages, and Actions
 * Displayed to the right of the 1200px main content area
 */
export function RightSidebar() {
    const config = ConfigurationData.Instance;
    const machineState = MachineStateData.Instance;
    const [materialEditorOpen, setMaterialEditorOpen] = useState(false);
    const [clampEditorOpen, setClampEditorOpen] = useState(false);

    // Skin event numbers from PLC template
    const SKIN_EVENT_RESET = 56;      // SkinResetButtonPressed_M
    const SKIN_EVENT_CYCLE_CANCEL = 46; // SkinCycleCancel_SV (Stop)
    const SKIN_EVENT_CYCLE_START = 50;  // SkinCycleStart_SV (Run)

    const handleReset = async () => {
        try {
            const machine = Machine.getInstance();
            await machine.system.TriggerSkinEvent(SKIN_EVENT_RESET);
        } catch (error) {
            console.error('Failed to trigger reset:', error);
        }
    };

    const handleStop = async () => {
        try {
            const machine = Machine.getInstance();
            await machine.system.TriggerSkinEvent(SKIN_EVENT_CYCLE_CANCEL);
        } catch (error) {
            console.error('Failed to trigger stop:', error);
        }
    };

    const handleRun = async () => {
        try {
            const machine = Machine.getInstance();
            await machine.system.TriggerSkinEvent(SKIN_EVENT_CYCLE_START);
        } catch (error) {
            console.error('Failed to trigger run:', error);
        }
    };

    return (
        <Box
            sx={{
                width: '100%',
                height: '100vh',
                display: 'flex',
                flexDirection: 'column',
                backgroundColor: config.lightBackgroundColor,
                borderLeft: `1px solid ${config.borderColor}`,
                overflow: 'hidden',
            }}
        >
            {/* Machine Control Buttons */}
            <Box sx={{ display: 'flex', gap: 2, px: 2, pt: 2, flexShrink: 0 }}>
                <Button
                    variant="contained"
                    sx={{
                        flex: 1,
                        height: '60px',
                        fontSize: '1.25rem',
                        fontWeight: 'bold',
                        backgroundColor: '#000000',
                        color: config.lightTextColor,
                        '&:hover': {
                            backgroundColor: '#000000',
                            opacity: 0.9,
                        }
                    }}
                    onClick={handleReset}
                >
                    Reset
                </Button>
                <Button
                    variant="contained"
                    sx={{
                        flex: 1,
                        height: '60px',
                        fontSize: '1.25rem',
                        fontWeight: 'bold',
                        backgroundColor: config.errorColor,
                        color: config.lightTextColor,
                        '&:hover': {
                            backgroundColor: config.errorColor,
                            opacity: 0.9,
                        }
                    }}
                    onClick={handleStop}
                >
                    Stop
                </Button>
                <Button
                    variant="contained"
                    sx={{
                        flex: 1,
                        height: '60px',
                        fontSize: '1.25rem',
                        fontWeight: 'bold',
                        backgroundColor: config.successColor,
                        color: config.lightTextColor,
                        '&:hover': {
                            backgroundColor: config.successColor,
                            opacity: 0.9,
                        }
                    }}
                    onClick={handleRun}
                >
                    Run
                </Button>
            </Box>

            {/* Top Section: Coordinates and Actions side by side */}
            <Box sx={{ display: 'flex', gap: 2, px: 2, pt: 2, flexShrink: 0 }}>
                {/* Coordinates */}
                <Box sx={{ flex: 1 }}>
                    <AxisCoordinateDisplay
                        axes={['X', 'Y', 'Z', 'A']}
                        showButtons={true}
                    />
                </Box>

                {/* Actions Panel */}
                <Box sx={{ flexShrink: 0 }}>
                    <MachineActionsPanel
                        onEditMaterial={() => setMaterialEditorOpen(true)}
                        onEditClamps={() => setClampEditorOpen(true)}
                    />
                </Box>
            </Box>

            {/* Safe Mode Control */}
            <Box sx={{ px: 2, pt: 2, flexShrink: 0 }}>
                <SafeModeControl />
            </Box>

            {/* Messages - Scrollable */}
            <Box sx={{ flex: 1, minHeight: 0, overflow: 'hidden', mx: 2, my: 2 }}>
                <MessageViewer />
            </Box>

            {/* Material Editor Dialog */}
            <MaterialEditor
                open={materialEditorOpen}
                onClose={() => setMaterialEditorOpen(false)}
                machineState={machineState}
            />

            {/* Clamp Editor Dialog */}
            <Dialog
                open={clampEditorOpen}
                onClose={() => setClampEditorOpen(false)}
                maxWidth="lg"
                fullWidth
                PaperProps={{
                    sx: { height: '80vh' }
                }}
            >
                <DialogTitle>Clamp Setup</DialogTitle>
                <DialogContent sx={{ p: 2, height: 'calc(100% - 120px)', overflow: 'auto' }}>
                    <ClampEditorForm
                        onSaveToLibrary={() => {
                            // Save to library implementation
                        }}
                        onLoadFromLibrary={() => {
                            // Load from library implementation
                        }}
                        height="100%"
                    />
                </DialogContent>
                <DialogActions sx={{ p: 2, justifyContent: 'flex-end' }}>
                    <Button onClick={() => setClampEditorOpen(false)} variant="contained">
                        Done
                    </Button>
                </DialogActions>
            </Dialog>
        </Box>
    );
}
