import { Code as CodeIcon } from '@mui/icons-material';
import { Typography } from '@mui/material';
import React from 'react';
import { Machine } from '../../../../machine/Machine';
import { LogCategory, Logger } from '../../../../utils/Logger';
import { DataUtilities } from '../../../../utils/storage/DataUtilities';
import { FlowStep } from "../../../FlowStep";
import { FlowStepData } from "../../../FlowStepData";

export class GetCurrentGCodeStep extends FlowStep {
    readonly __type = 'GetCurrentGCodeStep';
    readonly category = ['Machine', 'Program'];
    readonly name = 'Get Current G-Code';
    readonly description = 'Gets the currently loaded G-Code program';
    
    // Icon is created dynamically, not stored
    get icon(): React.ReactNode {
        return React.createElement(CodeIcon, { sx: { color: 'primary.main' } });
    }

    static readonly SUCCESS_PATH = 'success';

    async execute(data: FlowStepData, prototypeRun: boolean): Promise<string | null> {
        if (prototypeRun) {
            //Logger.Instance.log(LogCategory.System, 'Prototype: Get current G-code');
            data.setVariable('currentGCode', ['G0 X0 Y0 Z0', 'M3 S1000', 'G1 X10 Y10']);
            return GetCurrentGCodeStep.SUCCESS_PATH;
        }

        try {
            const gcode = await Machine.getInstance().program.GetCurrentGCode();
            data.setVariable('currentGCode', gcode);
            //Logger.Instance.log(LogCategory.System, `Retrieved ${gcode.length} G-code lines`);
            return GetCurrentGCodeStep.SUCCESS_PATH;
        } catch (error) {
            Logger.Instance.logError(LogCategory.System, 'Get current G-code failed:', error);
            // Still return success with empty array - the step completed its attempt  
            data.setVariable('currentGCode', []);
            return GetCurrentGCodeStep.SUCCESS_PATH;
        }
    }

    results(): string[] {
        return [GetCurrentGCodeStep.SUCCESS_PATH];
    }

    renderResultsUI(data: FlowStepData, result: string): React.ReactNode {
        const gcode = data.getVariable('currentGCode') as string[] || [];
        return (
            <Typography variant="caption">
                Get G-code ({gcode.length} lines): {result}
            </Typography>
        );
    }

    public toJSON(): any {
        const data = DataUtilities.getStorageData(this, ['icon']) as any;
        data.__type = this.__type;
        return data;
    }

    public fromJSON(data: any): void {
        DataUtilities.loadStorageData(this, data);
    }
}






