import { StateManager } from '../../utils/statemanager/StateManager';
import { DataUtilities } from '../../utils/storage/DataUtilities';
import { IStorable } from '../../utils/storage/IStorable';

export enum ComparisonType {
    Value = 'value',
    DataElement = 'dataElement'
}

export class EqualsStepData implements IStorable {
    private _dataType: string = 'string'; // 'string', 'boolean', 'number'
    private _leftDataPath: string = '';
    private _comparisonType: ComparisonType = ComparisonType.Value;
    private _rightDataPath: string = '';
    private _stringValue: string = '';
    private _numberValue: number = 0;
    private _booleanValue: boolean = false;

    // Data type selection
    get dataType(): string {
        return this._dataType;
    }

    set dataType(value: string) {
        this._dataType = value;
        StateManager.propertyChanged(this, 'dataType');
    }

    // Left side data element selection
    get leftDataPath(): string {
        return this._leftDataPath;
    }

    set leftDataPath(value: string) {
        this._leftDataPath = value;
        StateManager.propertyChanged(this, 'leftDataPath');
    }

    // Comparison type (value vs data element)
    get comparisonType(): ComparisonType {
        return this._comparisonType;
    }

    set comparisonType(value: ComparisonType) {
        this._comparisonType = value;
        StateManager.propertyChanged(this, 'comparisonType');
    }

    // Right side data element selection (when comparing to another data element)
    get rightDataPath(): string {
        return this._rightDataPath;
    }

    set rightDataPath(value: string) {
        this._rightDataPath = value;
        StateManager.propertyChanged(this, 'rightDataPath');
    }

    // Value inputs for different types
    get stringValue(): string {
        return this._stringValue;
    }

    set stringValue(value: string) {
        this._stringValue = value;
        StateManager.propertyChanged(this, 'stringValue');
    }

    get numberValue(): number {
        return this._numberValue;
    }

    set numberValue(value: number) {
        this._numberValue = value;
        StateManager.propertyChanged(this, 'numberValue');
    }

    get booleanValue(): boolean {
        return this._booleanValue;
    }

    set booleanValue(value: boolean) {
        this._booleanValue = value;
        StateManager.propertyChanged(this, 'booleanValue');
    }

    // Get the current value based on data type
    getCurrentValue(): any {
        switch (this._dataType) {
            case 'string':
                return this._stringValue;
            case 'number':
                return this._numberValue;
            case 'boolean':
                return this._booleanValue;
            default:
                return null;
        }
    }

    // Set the current value based on data type
    setCurrentValue(value: any): void {
        switch (this._dataType) {
            case 'string':
                this.stringValue = String(value || '');
                break;
            case 'number':
                this.numberValue = Number(value || 0);
                break;
            case 'boolean':
                this.booleanValue = Boolean(value);
                break;
        }
    }

    // Get allowed types for data selector (excludes cncpoint)
    getAllowedTypes(): string[] {
        return ['string', 'boolean', 'number'];
    }

    // Get the currently selected type as an array for the data selector
    getSelectedDataType(): string[] {
        return [this._dataType];
    }

    // IStorable implementation
    public toJSON(): any {
        return DataUtilities.getStorageData(this);
    }

    public fromJSON(data: any): void {
        DataUtilities.loadStorageData(this, data);
    }
}