/**
 * Machine Output definition
 * Static configuration for outputs - actual number and state come from API/SignalR
 */
export class MachineOutput {
  public readonly centroidName: string;
  public name: string;
  public activeText: string;
  public inactiveText: string;

  constructor(
    centroidName: string,
    name: string = '',
    activeText: string = 'Active',
    inactiveText: string = 'Inactive'
  ) {
    this.centroidName = centroidName;
    this.name = name;
    this.activeText = activeText;
    this.inactiveText = inactiveText;
  }

  /**
   * Create a copy of this output definition
   */
  public clone(): MachineOutput {
    return new MachineOutput(
      this.centroidName,
      this.name,
      this.activeText,
      this.inactiveText
    );
  }
}