import React from "react";
import { Box, Button, Typography } from '@mui/material';
import { BaseWizardStep } from "../../../Wizard/BaseWizardStep";
import { Wizard } from "../../../Wizard/Wizard";
import { WizardStep } from "../../../Wizard/WizardStep";
import { ConfigurationData } from '../../../../data/ConfigurationData';

export class TestTouchplateStep extends BaseWizardStep {
  constructor(wizard: Wizard, priorStep: WizardStep | null = null) {
    super(wizard, priorStep, "Next", "Back");
  }

  getTitle(): string {
    return "Test Touch Plate Connection";
  }

  nextStep(): WizardStep | null {
    const { PositionTouchplateStep } = require('./PositionTouchplateStep');
    return new PositionTouchplateStep(this.wizard, this);
  }

  render(): React.ReactNode {
    const handleTestTouchplate = () => {
      this.wizard.state.touchplateDetected = true;
      // //console.log('Touchplate detected! Advancing in 2 seconds...');
      
      // Auto-advance after 2 seconds
      setTimeout(() => {
        this.wizard.state.touchplateDetected = false;
        this.handleNext();
      }, 2000);
    };

    return (
      <div style={{ height: '100%', display: 'flex', flexDirection: 'column' }}>
        <div style={{ flex: 1 }}>
          <Box sx={{ display: 'flex', height: '100%' }}>
            <Box sx={{ flex: 1, pr: 3, display: 'flex', flexDirection: 'column', justifyContent: 'center' }}>
              <Typography variant="h6" sx={{ mb: 2 }}>Test Touch Plate Connection</Typography>
              <Typography variant="body1" sx={{ mb: 2 }}>
                Touch the touch plate to the tool to confirm it's working properly.
              </Typography>
              <Typography variant="body1" sx={{ mb: 3 }}>
                We will automatically advance when we detect the touchoff.
              </Typography>
              <Button
                variant="outlined"
                onClick={handleTestTouchplate}
                sx={{ alignSelf: 'flex-start' }}
              >
                Simulate Touch Detection (Testing)
              </Button>
            </Box>
            
            <Box sx={{ flex: 1, minHeight: 0 }}>
              <div style={{ width: '100%', height: '100%', border: `1px solid ${ConfigurationData.Instance.secondaryBorderColor}`, borderRadius: '4px' }}>
                <Typography variant="caption" sx={{ p: 2, color: 'text.secondary' }}>
                  3D Viewer placeholder for touchplate test
                </Typography>
              </div>
            </Box>
          </Box>
        </div>
        {this.renderButtons()}
      </div>
    );
  }
}
