import * as THREE from 'three';
import { CNCPoint } from '../data/CNCPoint';
import { Box } from '../data/Common/Box';
import { CoordinateType } from '../data/Common/CoordinateType';
import { PlaneOffset } from '../data/Common/PlaneOffset';
import { ConfigurationData } from '../data/ConfigurationData';
import { ConfigurationState } from '../data/ConfigurationState';
import { CoordinateUtil } from './CoordinateUtil';
import { SoftLimitsUtil } from './SoftLimitsUtil';

export interface CollisionResult {
  hasCollision: boolean;
  collisionType: CollisionType | null;
  collisionTarget: string | null;
  intersectionPoint: CNCPoint | null;
  faceName: string | null;
  suggestedMove: CNCPoint | null;
}

export enum CollisionType {
  SoftLimits = 'SoftLimits',
  MachineBed = 'MachineBed',
  Spoilboard = 'Spoilboard',
  Material = 'Material',
  Clamps = 'Clamps',
  VerticalTable = 'VerticalTable'
}

export enum CollisionAction {
  Cancel = 'cancel',
  Proceed = 'proceed',
  MoveSafe = 'moveSafe'
}

export interface CollisionCheckOptions {
  checkSoftLimits: boolean;
  checkMachineBed: boolean;
  checkSpoilboard: boolean;
  checkMaterial: boolean;
  checkClamps: boolean;
  checkVerticalTable: boolean;
  safetyOffset: number; // Distance to maintain from obstacles
}

export interface CollisionCheckInputs {
  softLimitsBoxes: Box[];
  machineBedBoxes: Box[];
  spoilboardBoxes: Box[];
  materialBoxes: Box[];
  clampBoxes: Box[];
  verticalTableBoxes: Box[];
}

export class CollisionDetection {
  /**
   * Check for collisions along a move path
   */
  static checkMoveCollision(
    fromPoint: CNCPoint,
    toPoint: CNCPoint,
    inputs: CollisionCheckInputs,
    options: Partial<CollisionCheckOptions> = {}
  ): CollisionResult {
    const defaultOptions: CollisionCheckOptions = {
      checkSoftLimits: true,
      checkMachineBed: true, // Always check machine bed/base
      checkSpoilboard: true, // Always check spoilboard
      checkMaterial: true,
      checkClamps: true,
      checkVerticalTable: true,
      safetyOffset: 0.1 // 0.1" safety margin
    };

    const checkOptions = { ...defaultOptions, ...options };

    // Check safe mode overrides
    const configState = ConfigurationState.Instance;
    if (configState.softLimitsOff) {
      checkOptions.checkSoftLimits = false;
    }
    if (configState.collisionOff) {
      // Disable all collision checking when collision override is active
      checkOptions.checkSoftLimits = false;
      checkOptions.checkMachineBed = false;
      checkOptions.checkSpoilboard = false;
      checkOptions.checkMaterial = false;
      checkOptions.checkClamps = false;
      checkOptions.checkVerticalTable = false;
    }

    // Convert points to machine coordinates for consistent checking
    const fromMachine = CoordinateUtil.toMachineZero(fromPoint);
    const toMachine = CoordinateUtil.toMachineZero(toPoint);

    // Early exit: If from and to points are the same (within tolerance), no collision possible
    const tolerance = 1e-6;
    if (Math.abs(fromMachine.x - toMachine.x) < tolerance &&
      Math.abs(fromMachine.y - toMachine.y) < tolerance &&
      Math.abs(fromMachine.z - toMachine.z) < tolerance) {
      return {
        hasCollision: false,
        collisionType: null,
        collisionTarget: null,
        intersectionPoint: null,
        faceName: null,
        suggestedMove: null
      };
    }

    // Check each collision type in order of priority
    const collisionChecks = [
      { type: CollisionType.SoftLimits, enabled: checkOptions.checkSoftLimits, boxes: inputs.softLimitsBoxes },
      { type: CollisionType.MachineBed, enabled: checkOptions.checkMachineBed, boxes: inputs.machineBedBoxes },
      { type: CollisionType.Spoilboard, enabled: checkOptions.checkSpoilboard, boxes: inputs.spoilboardBoxes },
      { type: CollisionType.Material, enabled: checkOptions.checkMaterial, boxes: inputs.materialBoxes },
      { type: CollisionType.Clamps, enabled: checkOptions.checkClamps, boxes: inputs.clampBoxes },
      { type: CollisionType.VerticalTable, enabled: checkOptions.checkVerticalTable, boxes: inputs.verticalTableBoxes }
    ];

    for (const check of collisionChecks) {
      if (!check.enabled) continue;

      // Check collision with each box in the array
      for (const box of check.boxes) {
        const result = CollisionDetection.checkCollisionWithBox(
          fromMachine,
          toMachine,
          box,
          check.type,
          checkOptions.safetyOffset
        );

        if (result.hasCollision) {
          return result;
        }
      }
    }

    return {
      hasCollision: false,
      collisionType: null,
      collisionTarget: null,
      intersectionPoint: null,
      faceName: null,
      suggestedMove: null
    };
  }

  /**
   * Check collision with a specific box
   */
  private static checkCollisionWithBox(
    fromPoint: CNCPoint,
    toPoint: CNCPoint,
    box: Box,
    collisionType: CollisionType,
    safetyOffset: number
  ): CollisionResult {
    let targetName: string;
    let checkInside = false; // Whether we're checking for intersection inside the box

    switch (collisionType) {
      case CollisionType.SoftLimits:
        targetName = 'Soft Limits';
        checkInside = true; // We want to stay INSIDE soft limits
        break;

      case CollisionType.MachineBed:
        targetName = 'Machine Bed';
        break;

      case CollisionType.Spoilboard:
        targetName = 'Spoilboard';
        break;

      case CollisionType.Material:
        targetName = 'Material';
        break;

      case CollisionType.Clamps:
        targetName = 'Clamps';
        break;

      case CollisionType.VerticalTable:
        targetName = 'Vertical Table';
        break;

      default:
        return {
          hasCollision: false,
          collisionType: null,
          collisionTarget: null,
          intersectionPoint: null,
          faceName: null,
          suggestedMove: null
        };
    }

    if (!box) {
      return {
        hasCollision: false,
        collisionType: null,
        collisionTarget: null,
        intersectionPoint: null,
        faceName: null,
        suggestedMove: null
      };
    }

    // Debug logging for material collisions
    if (collisionType === CollisionType.Material) {
      // // //console.log('Material collision check:', {
      //   fromPoint: `(${fromPoint.x}, ${fromPoint.y}, ${fromPoint.z})`,
      //   toPoint: `(${toPoint.x}, ${toPoint.y}, ${toPoint.z})`,
      //   materialBox: {
      //     origin: `(${box.origin.x}, ${box.origin.y}, ${box.origin.z})`,
      //     dimensions: `${box.width} x ${box.length} x ${box.height}`,
      //     coordinateType: box.origin.coordinateType
      //   },
      //   boxPoints: {
      //     frontLeftLower: `(${box.boxPoints.frontLeftLower.x}, ${box.boxPoints.frontLeftLower.y}, ${box.boxPoints.frontLeftLower.z})`,
      //     frontLeftUpper: `(${box.boxPoints.frontLeftUpper.x}, ${box.boxPoints.frontLeftUpper.y}, ${box.boxPoints.frontLeftUpper.z})`
      //   }
      // });
    }

    // Debug logging for machine bed collisions
    if (collisionType === CollisionType.MachineBed) {
      // // //console.log('Machine bed collision check:', {
      //   fromPoint: `(${fromPoint.x}, ${fromPoint.y}, ${fromPoint.z})`,
      //   toPoint: `(${toPoint.x}, ${toPoint.y}, ${toPoint.z})`,
      //   machineBedBox: {
      //     origin: `(${box.origin.x}, ${box.origin.y}, ${box.origin.z})`,
      //     dimensions: `${box.width} x ${box.length} x ${box.height}`,
      //     coordinateType: box.origin.coordinateType
      //   },
      //   boxPoints: {
      //     frontLeftLower: `(${box.boxPoints.frontLeftLower.x}, ${box.boxPoints.frontLeftLower.y}, ${box.boxPoints.frontLeftLower.z})`,
      //     frontLeftUpper: `(${box.boxPoints.frontLeftUpper.x}, ${box.boxPoints.frontLeftUpper.y}, ${box.boxPoints.frontLeftUpper.z})`,
      //     rearRightUpper: `(${box.boxPoints.rearRightUpper.x}, ${box.boxPoints.rearRightUpper.y}, ${box.boxPoints.rearRightUpper.z})`
      //   }
      // });
    }

    // Check for intersection
    const intersectionResult = CoordinateUtil.computeIntersectionWithBox(
      box,
      fromPoint,
      toPoint,
      safetyOffset,
      checkInside ? PlaneOffset.Inside : PlaneOffset.Outside
    );

    let hasCollision = intersectionResult.intersectionPoint !== null;

    // Special case: If both points are inside the box, always warn (collision = true)
    // The only exception is if it's an escape movement
    if (!checkInside) { // Only for boxes we should stay OUTSIDE of
      const fromMachine = CoordinateUtil.toMachineZero(fromPoint);
      const toMachine = CoordinateUtil.toMachineZero(toPoint);
      const boxMachine = box.toMachineZero();

      const fromInside = CollisionDetection.isPointInsideBox(fromMachine, boxMachine);
      const toInside = CollisionDetection.isPointInsideBox(toMachine, boxMachine);

      if (fromInside && toInside) {
        // Both points are inside the box - always warn (collision = true)
        hasCollision = true;

        // Check if this is an escape movement - if so, allow it
        const isEscapeMovement = CollisionDetection.isEscapeMovement(fromPoint, toPoint, box);
        if (isEscapeMovement) {
          hasCollision = false; // Override - allow escape movement
        }
      } else if (hasCollision && fromInside) {
        // Start point is inside, and there's a collision detected
        // Check if this is an escape movement - if so, allow it
        const isEscapeMovement = CollisionDetection.isEscapeMovement(fromPoint, toPoint, box);
        if (isEscapeMovement) {
          hasCollision = false; // Override - allow escape movement
        }
      }
    }

    // Debug logging for material intersection results
    if (collisionType === CollisionType.Material) {
      // // //console.log('Material intersection result:', {
      //   hasCollision,
      //   intersectionPoint: intersectionResult.intersectionPoint ? 
      //     `(${intersectionResult.intersectionPoint.x}, ${intersectionResult.intersectionPoint.y}, ${intersectionResult.intersectionPoint.z})` : 
      //     'null',
      //   faceName: intersectionResult.faceName
      // });
    }

    // Debug logging for machine bed intersection results
    if (collisionType === CollisionType.MachineBed) {
      // // //console.log('Machine bed intersection result:', {
      //   hasCollision,
      //   intersectionPoint: intersectionResult.intersectionPoint ? 
      //     `(${intersectionResult.intersectionPoint.x}, ${intersectionResult.intersectionPoint.y}, ${intersectionResult.intersectionPoint.z})` : 
      //     'null',
      //   faceName: intersectionResult.faceName,
      //   moveZRange: `${Math.min(fromPoint.z, toPoint.z)} to ${Math.max(fromPoint.z, toPoint.z)}`,
      //   bedZRange: `${box.boxPoints.frontLeftLower.z} to ${box.boxPoints.frontLeftUpper.z}`
      // });
    }

    if (!hasCollision) {
      return {
        hasCollision: false,
        collisionType: null,
        collisionTarget: null,
        intersectionPoint: null,
        faceName: null,
        suggestedMove: null
      };
    }

    // Generate suggested safe move
    const suggestedMove = CollisionDetection.generateSafeMove(
      fromPoint,
      toPoint,
      box,
      safetyOffset,
      checkInside
    );

    return {
      hasCollision: true,
      collisionType,
      collisionTarget: targetName,
      intersectionPoint: intersectionResult.intersectionPoint,
      faceName: intersectionResult.faceName,
      suggestedMove
    };
  }

  /**
   * Generate a safe move that avoids collision using Three.js for nearest intersection
   */
  private static generateSafeMove(
    fromPoint: CNCPoint,
    toPoint: CNCPoint,
    box: Box,
    safetyOffset: number,
    stayInside: boolean
  ): CNCPoint {
    return CollisionDetection.generateSafeMoveWithThreeJS(fromPoint, toPoint, box, safetyOffset, stayInside);
  }

  /**
   * Generate a safe move using Three.js to find the nearest intersection point
   * More accurate than the legacy method which could find far planes
   */
  private static generateSafeMoveWithThreeJS(
    fromPoint: CNCPoint,
    toPoint: CNCPoint,
    box: Box,
    safetyOffset: number,
    stayInside: boolean
  ): CNCPoint {
    try {
      // Convert points to machine zero for consistent calculations
      const fromMachineZero = CoordinateUtil.toMachineZero(fromPoint);
      const toMachineZero = CoordinateUtil.toMachineZero(toPoint);
      const machineZeroBox = box.toMachineZero();

      // Get the configurable safety distance
      const safeXYDistance = ConfigurationData.Instance.safeXYDistance;

      // Use existing intersection method - don't change this logic!
      const intersectionResult = CoordinateUtil.computeIntersectionWithBox(machineZeroBox, fromMachineZero, toMachineZero);

      if (!intersectionResult.intersectionPoint) {
        // No intersection, return target point
        return toPoint;
      }

      // Calculate the actual box bounds (min/max coordinates) for face detection
      const boxPoints = machineZeroBox.boxPoints;
      const minX = Math.min(boxPoints.frontLeftLower.x, boxPoints.frontRightLower.x, boxPoints.rearLeftLower.x, boxPoints.rearRightLower.x);
      const maxX = Math.max(boxPoints.frontLeftLower.x, boxPoints.frontRightLower.x, boxPoints.rearLeftLower.x, boxPoints.rearRightLower.x);
      const minY = Math.min(boxPoints.frontLeftLower.y, boxPoints.frontRightLower.y, boxPoints.rearLeftLower.y, boxPoints.rearRightLower.y);
      const maxY = Math.max(boxPoints.frontLeftLower.y, boxPoints.frontRightLower.y, boxPoints.rearLeftLower.y, boxPoints.rearRightLower.y);
      const minZ = Math.min(boxPoints.frontLeftLower.z, boxPoints.frontLeftUpper.z, boxPoints.frontRightLower.z, boxPoints.frontRightUpper.z);
      const maxZ = Math.max(boxPoints.frontLeftLower.z, boxPoints.frontLeftUpper.z, boxPoints.frontRightLower.z, boxPoints.frontRightUpper.z);

      // Use Three.js to determine which face was hit and calculate safe position
      const intersectionPoint = new THREE.Vector3(intersectionResult.intersectionPoint.x, intersectionResult.intersectionPoint.y, intersectionResult.intersectionPoint.z);
      let safePosition = new THREE.Vector3().copy(intersectionPoint);
      const tolerance = 0.1; // Tolerance for face detection

      // Check which face was hit and move away by safe distance
      // When distances are similar, prioritize based on movement direction
      const rayDirection = new THREE.Vector3(toMachineZero.x - fromMachineZero.x, toMachineZero.y - fromMachineZero.y, toMachineZero.z - fromMachineZero.z).normalize();

      if (Math.abs(intersectionPoint.x - minX) < tolerance && Math.abs(intersectionPoint.y - minY) < tolerance) {
        // Corner case - choose based on primary movement direction
        if (Math.abs(rayDirection.x) > Math.abs(rayDirection.y)) {
          // Primarily moving in X direction, hit left face
          safePosition.x = minX - safeXYDistance;
        } else {
          // Primarily moving in Y direction, hit front face  
          safePosition.y = minY - safeXYDistance;
        }
      } else if (Math.abs(intersectionPoint.x - minX) < tolerance) {
        // Hit left face - move left by safe distance
        safePosition.x = minX - safeXYDistance;
      } else if (Math.abs(intersectionPoint.x - maxX) < tolerance) {
        // Hit right face - move right by safe distance
        safePosition.x = maxX + safeXYDistance;
      } else if (Math.abs(intersectionPoint.y - minY) < tolerance) {
        // Hit front face - move forward by safe distance
        safePosition.y = minY - safeXYDistance;
      } else if (Math.abs(intersectionPoint.y - maxY) < tolerance) {
        // Hit back face - move back by safe distance
        safePosition.y = maxY + safeXYDistance;
      } else if (Math.abs(intersectionPoint.z - minZ) < tolerance) {
        // Hit bottom face - move down by safe distance (or maintain Z if respectBottom)
        safePosition.z = minZ - safeXYDistance;
      } else if (Math.abs(intersectionPoint.z - maxZ) < tolerance) {
        // Hit top face - move up by safe distance
        safePosition.z = maxZ + safeXYDistance;
      } else {
        // Interior intersection - move back along ray by safe distance
        const backupDirection = new THREE.Vector3().copy(rayDirection).negate();
        safePosition.add(backupDirection.multiplyScalar(safeXYDistance));
      }

      // For stayInside logic (soft limits), we want to stay inside the bounds
      if (stayInside) {
        safePosition.x = Math.max(minX + safeXYDistance, Math.min(maxX - safeXYDistance, safePosition.x));
        safePosition.y = Math.max(minY + safeXYDistance, Math.min(maxY - safeXYDistance, safePosition.y));
        safePosition.z = Math.max(minZ + safeXYDistance, Math.min(maxZ - safeXYDistance, safePosition.z));
      }

      return new CNCPoint(safePosition.x, safePosition.y, safePosition.z, CoordinateType.MachineZero);

    } catch (error) {
      console.warn('Error in generateSafeMoveWithThreeJS, falling back to legacy method:', error);

      // Fallback to legacy method
      const safePoint = CoordinateUtil.moveAwayFromBoxEdge(
        box,
        toPoint,
        stayInside ? PlaneOffset.Inside : PlaneOffset.Outside,
        safetyOffset,
        true // respect bottom of box
      );

      return safePoint;
    }
  }

  /**
   * @deprecated Use generateSafeMoveWithThreeJS instead
   * Generate a safe move that avoids collision (legacy method)
   */
  private static generateSafeMoveLegacy(
    fromPoint: CNCPoint,
    toPoint: CNCPoint,
    box: Box,
    safetyOffset: number,
    stayInside: boolean
  ): CNCPoint {
    // Use moveAwayFromBoxEdge to find a safe position near the target
    const safePoint = CoordinateUtil.moveAwayFromBoxEdge(
      box,
      toPoint,
      stayInside ? PlaneOffset.Inside : PlaneOffset.Outside,
      safetyOffset,
      true // respect bottom of box
    );

    return safePoint;
  }

  /**
   * Get a user-friendly description of the collision
   */
  static getCollisionDescription(result: CollisionResult): string {
    if (!result.hasCollision) {
      return 'No collision detected';
    }

    const direction = result.collisionType === CollisionType.SoftLimits ? 'outside' : 'into';
    const face = result.faceName ? ` (${result.faceName} face)` : '';

    return `Move would go ${direction} ${result.collisionTarget}${face}`;
  }

  /**
   * Generate comprehensive debug information for collision detection
   */
  static async generateDebugInfo(
    fromPoint: CNCPoint,
    toPoint: CNCPoint,
    inputs: CollisionCheckInputs,
    result: CollisionResult
  ): Promise<string> {
    const machineData = require('../data/MachineData').MachineData.Instance;
    const machineStateData = require('../data/MachineStateData').MachineStateData.Instance;

    // Convert points to MachineZero for consistency
    const fromMachine = CoordinateUtil.toMachineZero(fromPoint);
    const toMachine = CoordinateUtil.toMachineZero(toPoint);

    const debugInfo = {
      timestamp: new Date().toISOString(),
      collision: {
        hasCollision: result.hasCollision,
        collisionType: result.collisionType,
        collisionTarget: result.collisionTarget,
        faceName: result.faceName,
        intersectionPoint: result.intersectionPoint ? {
          x: result.intersectionPoint.x,
          y: result.intersectionPoint.y,
          z: result.intersectionPoint.z,
          coordinateType: result.intersectionPoint.coordinateType
        } : null
      },
      movement: {
        from: {
          original: { x: fromPoint.x, y: fromPoint.y, z: fromPoint.z, coordinateType: fromPoint.coordinateType },
          machineZero: { x: fromMachine.x, y: fromMachine.y, z: fromMachine.z }
        },
        to: {
          original: { x: toPoint.x, y: toPoint.y, z: toPoint.z, coordinateType: toPoint.coordinateType },
          machineZero: { x: toMachine.x, y: toMachine.y, z: toMachine.z }
        }
      },
      machineState: {
        currentWorkZero: {
          x: machineStateData.currentWorkZero.x,
          y: machineStateData.currentWorkZero.y,
          z: machineStateData.currentWorkZero.z,
          coordinateType: machineStateData.currentWorkZero.coordinateType
        },
        currentJob: machineStateData.currentJob ? {
          materialXOffset: machineStateData.currentJob.materialXOffset,
          materialYOffset: machineStateData.currentJob.materialYOffset,
          material: {
            xLength: machineStateData.currentJob.material.xLength,
            yLength: machineStateData.currentJob.material.yLength,
            height: machineStateData.currentJob.material.height
          },
          clampsCount: machineStateData.currentJob.clamps.length
        } : null,
        spoilboard: {
          x: machineStateData.spoilboardX,
          y: machineStateData.spoilboardY,
          width: machineStateData.spoilBoardWidth,
          length: machineStateData.spoilBoardYLength,
          height: machineStateData.spoilBoardHeight
        }
      },
      machineData: {
        baseWidth: machineData.baseWidth,
        baseLength: machineData.baseLength,
        baseHeight: machineData.baseHeight,
        bedWidth: machineData.bedWidth,
        bedLength: machineData.bedLength,
        bedHeight: machineData.bedHeight,
        softLimits: await (async () => {
          const limits = await SoftLimitsUtil.getSoftLimits();
          return {
            zLower: limits.min.z,
            zUpper: limits.max.z
          };
        })()
      },
      boxes: {
        softLimits: inputs.softLimitsBoxes.map(box => CollisionDetection.serializeBox(box, 'SoftLimits')),
        machineBed: inputs.machineBedBoxes.map(box => CollisionDetection.serializeBox(box, 'MachineBed')),
        spoilboard: inputs.spoilboardBoxes.map(box => CollisionDetection.serializeBox(box, 'Spoilboard')),
        material: inputs.materialBoxes.map(box => CollisionDetection.serializeBox(box, 'Material')),
        clamps: inputs.clampBoxes.map(box => CollisionDetection.serializeBox(box, 'Clamps')),
        verticalTable: inputs.verticalTableBoxes.map(box => CollisionDetection.serializeBox(box, 'VerticalTable'))
      },
      generatedBoxes: {
        bedBox: CollisionDetection.serializeBox(CoordinateUtil.getBedBox(machineStateData), 'Generated Bed'),
        softLimitsBox: CollisionDetection.serializeBox(await CoordinateUtil.getSoftLimitsBox(machineStateData), 'Generated SoftLimits'),
        spoilboardBox: CollisionDetection.serializeBox(CoordinateUtil.getSpoilboardBox(machineStateData), 'Generated Spoilboard'),
        materialBox: machineStateData.currentJob ?
          CollisionDetection.serializeBox(CoordinateUtil.getMaterialBox(machineStateData), 'Generated Material') :
          null,
        clampsBoxes: CoordinateUtil.getClampsBoxes(machineStateData).map((box, index) =>
          CollisionDetection.serializeBox(box, `Generated Clamp ${index + 1}`)
        ),
        verticalTableBox: CoordinateUtil.getVerticalTableBox(machineStateData) ?
          CollisionDetection.serializeBox(CoordinateUtil.getVerticalTableBox(machineStateData)!, 'Generated Vertical Table') :
          null
      }
    };

    return JSON.stringify(debugInfo, null, 2);
  }

  /**
   * Serialize a box for debug output
   */
  private static serializeBox(box: Box, type: string): any {
    const machineZeroBox = box.toMachineZero();
    return {
      type,
      original: {
        origin: { x: box.origin.x, y: box.origin.y, z: box.origin.z, coordinateType: box.origin.coordinateType },
        dimensions: { width: box.width, length: box.length, height: box.height }
      },
      machineZero: {
        origin: { x: machineZeroBox.origin.x, y: machineZeroBox.origin.y, z: machineZeroBox.origin.z },
        dimensions: { width: machineZeroBox.width, length: machineZeroBox.length, height: machineZeroBox.height },
        boxPoints: {
          frontLeftLower: { x: machineZeroBox.boxPoints.frontLeftLower.x, y: machineZeroBox.boxPoints.frontLeftLower.y, z: machineZeroBox.boxPoints.frontLeftLower.z },
          frontRightLower: { x: machineZeroBox.boxPoints.frontRightLower.x, y: machineZeroBox.boxPoints.frontRightLower.y, z: machineZeroBox.boxPoints.frontRightLower.z },
          frontLeftUpper: { x: machineZeroBox.boxPoints.frontLeftUpper.x, y: machineZeroBox.boxPoints.frontLeftUpper.y, z: machineZeroBox.boxPoints.frontLeftUpper.z },
          frontRightUpper: { x: machineZeroBox.boxPoints.frontRightUpper.x, y: machineZeroBox.boxPoints.frontRightUpper.y, z: machineZeroBox.boxPoints.frontRightUpper.z },
          rearLeftLower: { x: machineZeroBox.boxPoints.rearLeftLower.x, y: machineZeroBox.boxPoints.rearLeftLower.y, z: machineZeroBox.boxPoints.rearLeftLower.z },
          rearRightLower: { x: machineZeroBox.boxPoints.rearRightLower.x, y: machineZeroBox.boxPoints.rearRightLower.y, z: machineZeroBox.boxPoints.rearRightLower.z },
          rearLeftUpper: { x: machineZeroBox.boxPoints.rearLeftUpper.x, y: machineZeroBox.boxPoints.rearLeftUpper.y, z: machineZeroBox.boxPoints.rearLeftUpper.z },
          rearRightUpper: { x: machineZeroBox.boxPoints.rearRightUpper.x, y: machineZeroBox.boxPoints.rearRightUpper.y, z: machineZeroBox.boxPoints.rearRightUpper.z }
        }
      }
    };
  }

  /**
   * Get collision prevention options for UI
   */
  static getCollisionOptions(result: CollisionResult): Array<{
    action: CollisionAction;
    label: string;
    description: string;
    point?: CNCPoint;
  }> {
    if (!result.hasCollision) {
      return [];
    }

    const options: Array<{
      action: CollisionAction;
      label: string;
      description: string;
      point?: CNCPoint;
    }> = [
        {
          action: CollisionAction.Cancel,
          label: 'Cancel Move',
          description: 'Cancel the move and stay at current position'
        },
        {
          action: CollisionAction.Proceed,
          label: 'Move Anyway',
          description: 'Proceed with the move despite the collision warning'
        }
      ];

    if (result.suggestedMove) {
      options.push({
        action: CollisionAction.MoveSafe,
        label: 'Move to Safe Position',
        description: 'Move to the closest safe position near the target',
        point: result.suggestedMove
      });
    }

    return options;
  }

  /**
   * Convenience method to create collision inputs from MachineStateData
   */
  static async createInputsFromMachineState(machineState: any): Promise<CollisionCheckInputs> {
    const inputs: CollisionCheckInputs = {
      softLimitsBoxes: [],
      machineBedBoxes: [],
      spoilboardBoxes: [],
      materialBoxes: [],
      clampBoxes: [],
      verticalTableBoxes: []
    };

    // Add soft limits box if available
    const softLimitsBox = await CoordinateUtil.getSoftLimitsBox(machineState);
    if (softLimitsBox) {
      inputs.softLimitsBoxes.push(softLimitsBox);
    }

    // Add machine bed box if available
    const bedBox = CoordinateUtil.getBedBox(machineState);
    if (bedBox) {
      inputs.machineBedBoxes.push(bedBox);
    }

    // Add spoilboard box if available
    const spoilboardBox = CoordinateUtil.getSpoilboardBox(machineState);
    if (spoilboardBox) {
      inputs.spoilboardBoxes.push(spoilboardBox);
    }

    // Add material box if available
    const materialBox = CoordinateUtil.getMaterialBox(machineState);
    if (materialBox) {
      inputs.materialBoxes.push(materialBox);
    }

    // Add clamps boxes if available
    const clampsBoxes = CoordinateUtil.getClampsBoxes(machineState);
    if (clampsBoxes.length > 0) {
      inputs.clampBoxes.push(...clampsBoxes);
    }

    // Add vertical table box if available
    const verticalTableBox = CoordinateUtil.getVerticalTableBox(machineState);
    if (verticalTableBox) {
      inputs.verticalTableBoxes.push(verticalTableBox);
    }

    return inputs;
  }


  /**
   * Serialize a box for debug output
   */
  private static serializeBoxForDebug(box: Box, type: string): any {
    const machineZeroBox = box.toMachineZero();
    return {
      type,
      original: {
        origin: { x: box.origin.x, y: box.origin.y, z: box.origin.z, coordinateType: box.origin.coordinateType },
        dimensions: { width: box.width, length: box.length, height: box.height }
      },
      machineZero: {
        origin: { x: machineZeroBox.origin.x, y: machineZeroBox.origin.y, z: machineZeroBox.origin.z },
        dimensions: { width: machineZeroBox.width, length: machineZeroBox.length, height: machineZeroBox.height },
        bounds: {
          xRange: `${machineZeroBox.origin.x} to ${machineZeroBox.origin.x + machineZeroBox.width}`,
          yRange: `${machineZeroBox.origin.y} to ${machineZeroBox.origin.y + machineZeroBox.length}`,
          zRange: `${machineZeroBox.origin.z} to ${machineZeroBox.origin.z + machineZeroBox.height}`
        }
      }
    };
  }

  /**
   * Determines if a movement represents an escape from inside an object
   * An escape movement is one where the tool starts inside an object and moves further away from the object's center
   */
  private static isEscapeMovement(fromPoint: CNCPoint, toPoint: CNCPoint, box: Box): boolean {
    // Convert points to machine coordinates for consistent checking
    const fromMachine = CoordinateUtil.toMachineZero(fromPoint);
    const toMachine = CoordinateUtil.toMachineZero(toPoint);
    const boxMachine = box.toMachineZero();

    // Calculate box center
    const boxCenter = {
      x: boxMachine.origin.x + boxMachine.width / 2,
      y: boxMachine.origin.y + boxMachine.length / 2,
      z: boxMachine.origin.z + boxMachine.height / 2
    };

    // Check if the starting point is inside the box
    const isFromInsideBox = CollisionDetection.isPointInsideBox(fromMachine, boxMachine);

    if (!isFromInsideBox) {
      // Starting point is not inside the box, so this is not an escape movement
      return false;
    }

    // Calculate distances from box center
    const fromDistance = Math.sqrt(
      Math.pow(fromMachine.x - boxCenter.x, 2) +
      Math.pow(fromMachine.y - boxCenter.y, 2) +
      Math.pow(fromMachine.z - boxCenter.z, 2)
    );

    const toDistance = Math.sqrt(
      Math.pow(toMachine.x - boxCenter.x, 2) +
      Math.pow(toMachine.y - boxCenter.y, 2) +
      Math.pow(toMachine.z - boxCenter.z, 2)
    );

    // If the distance to the box center is increasing, this is an escape movement
    return toDistance > fromDistance;
  }

  /**
   * Check if a point is inside a box
   */
  private static isPointInsideBox(point: CNCPoint, box: Box): boolean {
    const boxMachine = box.toMachineZero();

    return point.x >= boxMachine.origin.x &&
      point.x <= boxMachine.origin.x + boxMachine.width &&
      point.y >= boxMachine.origin.y &&
      point.y <= boxMachine.origin.y + boxMachine.length &&
      point.z >= boxMachine.origin.z &&
      point.z <= boxMachine.origin.z + boxMachine.height;
  }
}
