import {
    Add as AddIcon,
    Delete as DeleteIcon,
    Edit as EditIcon,
    Folder as FlowIcon
} from '@mui/icons-material';
import {
    Box,
    Button,
    Divider,
    IconButton,
    List,
    ListItem,
    Paper,
    Typography
} from '@mui/material';
import React, { useEffect, useState } from 'react';
import { ConfigurationDataColors } from '../../data/ConfigurationDataColors';
import { UserMessageQueue } from '../../data/UserMessageQueue';
import { Flow, FlowType } from '../../flow/Flow';
import { Storage, StorageType } from '../../machine/ICNCProgramStorage';
import { Machine } from '../../machine/Machine';
import { ConfirmDialogManager } from '../../utils/ConfirmDialogManager';
import { LogCategory, Logger } from '../../utils/Logger';
import { FlowCreateDialog } from './FlowCreateDialog';

interface FlowManagementViewProps {
    onOpenFlow: (flow: Flow, flowName: string) => void;
}

interface FlowListItem {
    name: string;
    createdAt: Date;
    updatedAt: Date;
    categoryName: string;
    exposeAsAction: boolean;
    flowType: FlowType;
    canBeCalledAsStep: boolean;
}

export function FlowManagementView({ onOpenFlow }: FlowManagementViewProps) {
    const [flows, setFlows] = useState<FlowListItem[]>([]);
    const [loading, setLoading] = useState(true);
    const [createDialogOpen, setCreateDialogOpen] = useState(false);

    // Load flows from storage
    const loadFlows = async () => {
        try {
            setLoading(true);
            const storage = Machine.getInstance().storage;
            const flowNames = await storage.getFlowStorageNames();

            const flowItems: FlowListItem[] = [];
            for (const name of flowNames) {
                const storageData = await storage.getStorageData(name);
                if (storageData && storageData.storageType === StorageType.Flow) {
                    // Parse flow data to get flow type
                    let flowType = FlowType.General;
                    try {
                        const flowData = JSON.parse(storageData.data);
                        flowType = flowData.FlowType || FlowType.General;
                    } catch {
                        // Default to General if parsing fails
                    }

                    flowItems.push({
                        name: storageData.name,
                        createdAt: storageData.createdAt,
                        updatedAt: storageData.updatedAt,
                        categoryName: storageData.categoryName,
                        exposeAsAction: storageData.exposeAsAction,
                        flowType: flowType,
                        canBeCalledAsStep: storageData.canBeCalledAsStep ?? false
                    });
                }
            }

            // Sort by most recently updated
            flowItems.sort((a, b) => b.updatedAt.getTime() - a.updatedAt.getTime());
            setFlows(flowItems);

        } catch (error) {
            Logger.Instance.logError(LogCategory.DataManager, 'Failed to load flows:', error);
            UserMessageQueue.Instance.addMessage('❌ Failed to load flows');
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        loadFlows();
    }, []);

    const handleCreateFlow = async (name: string, flowType: FlowType, categoryName?: string, canBeCalledAsStep?: boolean) => {
        try {
            const newFlow = new Flow(name);
            newFlow.FlowType = flowType; // Set the flow type

            // Create storage entry
            const storage = new Storage();
            storage.name = name;
            storage.storageType = StorageType.Flow;
            storage.categoryName = categoryName || '';
            storage.exposeAsAction = false;
            storage.canBeCalledAsStep = canBeCalledAsStep ?? false;
            storage.data = JSON.stringify(newFlow.toJSON());
            storage.createdAt = new Date();
            storage.updatedAt = new Date();

            await Machine.getInstance().storage.saveStorageData(storage);
            UserMessageQueue.Instance.addMessage('✓ Flow created successfully');

            // Reload the list
            await loadFlows();

            // Open the newly created flow
            onOpenFlow(newFlow, name);

        } catch (error) {
            Logger.Instance.logError(LogCategory.DataManager, 'Failed to create flow:', error);
            UserMessageQueue.Instance.addMessage('❌ Failed to create flow');
        }
    };

    const handleOpenFlow = async (flowName: string) => {
        try {
            const storage = Machine.getInstance().storage;
            const storageData = await storage.getStorageData(flowName);

            if (!storageData) {
                UserMessageQueue.Instance.addMessage('❌ Flow not found');
                return;
            }

            // Parse the flow data
            const flowData = JSON.parse(storageData.data);
            const flow = new Flow(flowData.name);
            flow.fromJSON(flowData);

            onOpenFlow(flow, flowName);

        } catch (error) {
            Logger.Instance.logError(LogCategory.DataManager, 'Failed to open flow:', error);
            UserMessageQueue.Instance.addMessage('❌ Failed to open flow');
        }
    };

    const handleDeleteFlow = async (flowName: string) => {
        const confirmed = await ConfirmDialogManager.Instance.showDeleteConfirm(`flow "${flowName}"`);
        if (!confirmed) return;

        try {
            await Machine.getInstance().storage.deleteStorageData(flowName);
            UserMessageQueue.Instance.addMessage('✓ Flow deleted successfully');
            await loadFlows();
        } catch (error) {
            Logger.Instance.logError(LogCategory.DataManager, 'Failed to delete flow:', error);
            UserMessageQueue.Instance.addMessage('❌ Failed to delete flow');
        }
    };

    if (loading) {
        return (
            <Box sx={{ p: 3, textAlign: 'center' }}>
                <Typography>Loading flows...</Typography>
            </Box>
        );
    }

    return (
        <Box sx={{ p: 3, height: '100%', display: 'flex', flexDirection: 'column' }}>
            {/* Header */}
            <Box sx={{ mb: 3, display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <Typography variant="h4" component="h1">
                    Flow Library
                </Typography>
                <Button
                    variant="contained"
                    startIcon={<AddIcon />}
                    onClick={() => setCreateDialogOpen(true)}
                    sx={{
                        backgroundColor: ConfigurationDataColors.Instance.primaryColor,
                        color: ConfigurationDataColors.Instance.lightTextColor,
                        '&:hover': {
                            backgroundColor: ConfigurationDataColors.Instance.primaryColor,
                            filter: 'brightness(0.9)',
                        },
                    }}
                >
                    Create Flow
                </Button>
            </Box>

            {/* Flow List */}
            {flows.length === 0 ? (
                <Paper sx={{ p: 4, textAlign: 'center', flex: 1, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                    <Box>
                        <FlowIcon sx={{ fontSize: 64, color: 'text.secondary', mb: 2 }} />
                        <Typography variant="h6" color="text.secondary" gutterBottom>
                            No flows found
                        </Typography>
                        <Typography variant="body2" color="text.secondary" sx={{ mb: 3 }}>
                            Create your first flow to get started with automation
                        </Typography>
                        <Button
                            variant="outlined"
                            startIcon={<AddIcon />}
                            onClick={() => setCreateDialogOpen(true)}
                        >
                            Create Flow
                        </Button>
                    </Box>
                </Paper>
            ) : (
                <Paper sx={{ flex: 1, overflow: 'auto' }}>
                    {/* Grid Header */}
                    <Box sx={{
                        display: 'grid',
                        gridTemplateColumns: '48px 1fr 120px 120px 180px',
                        gap: 2,
                        px: 2,
                        py: 1.5,
                        borderBottom: 1,
                        borderColor: 'divider',
                        backgroundColor: 'background.default',
                        position: 'sticky',
                        top: 0,
                        zIndex: 1
                    }}>
                        <Box />
                        <Typography variant="subtitle2" fontWeight="bold" color="text.secondary">Name</Typography>
                        <Typography variant="subtitle2" fontWeight="bold" color="text.secondary">Type</Typography>
                        <Typography variant="subtitle2" fontWeight="bold" color="text.secondary">Callable</Typography>
                        <Typography variant="subtitle2" fontWeight="bold" color="text.secondary" textAlign="right">Actions</Typography>
                    </Box>

                    <List sx={{ pt: 0 }}>
                        {flows.map((flow, index) => (
                            <React.Fragment key={flow.name}>
                                <ListItem
                                    sx={{
                                        py: 2,
                                        display: 'grid',
                                        gridTemplateColumns: '48px 1fr 120px 120px 180px',
                                        gap: 2,
                                        alignItems: 'center',
                                        '&:hover': {
                                            backgroundColor: 'action.hover',
                                        },
                                    }}
                                >
                                    <FlowIcon sx={{ color: ConfigurationDataColors.Instance.primaryColor }} />

                                    <Typography variant="body1" fontWeight="medium">
                                        {flow.name}
                                    </Typography>

                                    <Typography variant="body2" color="text.secondary">
                                        {flow.flowType}
                                    </Typography>

                                    <Typography variant="body2" color="text.secondary">
                                        {flow.canBeCalledAsStep ? 'Yes' : 'No'}
                                    </Typography>

                                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, justifyContent: 'flex-end' }}>
                                        <Button
                                            size="small"
                                            variant="outlined"
                                            startIcon={<EditIcon />}
                                            onClick={() => handleOpenFlow(flow.name)}
                                            sx={{
                                                color: ConfigurationDataColors.Instance.primaryColor,
                                                borderColor: ConfigurationDataColors.Instance.primaryColor,
                                                '&:hover': {
                                                    backgroundColor: `${ConfigurationDataColors.Instance.primaryColor}10`,
                                                }
                                            }}
                                        >
                                            Open
                                        </Button>
                                        <IconButton
                                            size="small"
                                            onClick={() => handleDeleteFlow(flow.name)}
                                            sx={{
                                                color: ConfigurationDataColors.Instance.errorColor,
                                                '&:hover': {
                                                    backgroundColor: `${ConfigurationDataColors.Instance.errorColor}10`,
                                                }
                                            }}
                                        >
                                            <DeleteIcon />
                                        </IconButton>
                                    </Box>
                                </ListItem>
                                {index < flows.length - 1 && <Divider />}
                            </React.Fragment>
                        ))}
                    </List>
                </Paper>
            )}

            {/* Create Flow Dialog */}
            <FlowCreateDialog
                open={createDialogOpen}
                onClose={() => setCreateDialogOpen(false)}
                onCreateFlow={handleCreateFlow}
            />
        </Box>
    );
}