import { ICNCFeatures } from '../machine/ICNCFeatures';
import { CNCProgramApi } from '../services/src/apis/CNCProgramApi';
import { RunGCodeCommandRequest } from '../services/src/models';
import { CoordinateUtil } from '../utils/CoordinateUtil';
import { LogCategory, Logger } from '../utils/Logger';
import { MachineInterfaceManager } from '../utils/MachineInterfaceManager';

export class CentroidCNCFeatures implements ICNCFeatures {
  private readonly programApi: CNCProgramApi;

  constructor() {
    const config = MachineInterfaceManager.Instance.getServiceConfiguration();
    this.programApi = new CNCProgramApi(config || undefined);
  }

  async ChangeToTool(toolNumber: number, returnToCurrentPosition: boolean): Promise<void> {
    try {
      // Generate G-code for tool change
      // M6 T{toolNumber} - Tool change command
      const gcode = `M6 T${toolNumber}`;

      // Get proposed fixture point from CoordinateUtil
      const proposedFixturePoint = CoordinateUtil.toAPIFixtureOffset();

      const request: RunGCodeCommandRequest = {
        gCode: gcode,
        fixturePoint: {
          x: proposedFixturePoint.x,
          y: proposedFixturePoint.y,
          z: proposedFixturePoint.z
        }
      };

      await this.programApi.apiCNCProgramRunGCodeCommandPost({ runGCodeCommandRequest: request });
      Logger.Instance.log(LogCategory.Tools, `Changed to tool ${toolNumber}${returnToCurrentPosition ? ' (return to position)' : ''}`);
    } catch (error) {
      Logger.Instance.logError(LogCategory.Tools, 'Failed to change tool:', error);
      throw error;
    }
  }

  async GetCurrentToolNumber(): Promise<number> {
    throw new Error('GetCurrentToolNumber not implemented - will be implemented with G-code commands in Centroid');
  }

  async CheckTool(): Promise<void> {
    throw new Error('CheckTool not implemented - will be implemented with G-code commands in Centroid');
  }

  async MeasureCurrentTool(): Promise<void> {
    throw new Error('MeasureCurrentTool not implemented - will be implemented with G-code commands in Centroid');
  }

  async MeasureAllTools(): Promise<void> {
    throw new Error('MeasureAllTools not implemented - will be implemented with G-code commands in Centroid');
  }

  async TouchOff(): Promise<void> {
    throw new Error('TouchOff not implemented - will be implemented with G-code commands in Centroid');
  }
}