import React, { useState, useEffect, useMemo, useRef } from 'react';
import {
  Box,
  Typography,
  Paper,
  List,
  ListItem,
  ListItemText,
  Chip,
  TextField,
  Button,
  Collapse,
  IconButton,
  ToggleButton,
  ToggleButtonGroup,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  FormControlLabel,
  Checkbox
} from '@mui/material';
import { Clear, FilterList, ExpandMore, ExpandLess, ContentCopy } from '@mui/icons-material';
import { Logger, LogLevel, LogEntry } from '../../utils/Logger';
import { ConfigurationState } from '../../data/ConfigurationState';

const getLogLevelColor = (level: LogLevel): string => {
  switch (level) {
    case LogLevel.Error:
      return '#f44336'; // Red
    case LogLevel.Info:
      return '#2196f3'; // Blue
    case LogLevel.Debug:
      return '#9c27b0'; // Purple
    default:
      return '#666666'; // Gray
  }
};

const formatTimestamp = (timestamp: Date): string => {
  return timestamp.toLocaleTimeString() + '.' + timestamp.getMilliseconds().toString().padStart(3, '0');
};

export function LogViewer() {
  const [logs, setLogs] = useState<LogEntry[]>([]);
  const [searchText, setSearchText] = useState('');
  const [selectedLevels, setSelectedLevels] = useState<LogLevel[]>([LogLevel.Info, LogLevel.Error, LogLevel.Debug]);
  const [filtersExpanded, setFiltersExpanded] = useState(false);
  const [categoryDialogOpen, setCategoryDialogOpen] = useState(false);
  const listContainerRef = useRef<HTMLDivElement>(null);
  
  // Get configuration state for category management
  const configState = ConfigurationState.Instance;

  // Update logs when logger changes
  useEffect(() => {
    const updateLogs = () => {
      const newLogs = [...Logger.Instance.logEntries];
      setLogs(newLogs);
      
      // Track session categories in ConfigurationState
      newLogs.forEach(log => {
        configState.addSessionLogCategory(log.category);
      });
      
      // Removed auto-scroll behavior - let user control scrolling manually
    };

    // Initial load
    updateLogs();

    // Listen for log changes (polling approach since we don't have events)
    const interval = setInterval(updateLogs, 1000);
    return () => clearInterval(interval);
  }, [configState]);

  // Filtered logs
  const filteredLogs = useMemo(() => {
    return logs.filter(log => {
      // Level filter
      if (selectedLevels.length > 0 && !selectedLevels.includes(log.level)) {
        return false;
      }
      
      // Category filter - exclude categories that are in the excluded list
      if (configState.isCategoryExcluded(log.category)) {
        return false;
      }
      
      // Search filter
      if (searchText) {
        const searchLower = searchText.toLowerCase();
        const messageText = Array.isArray(log.message) 
          ? log.message.join(' ')
          : log.message;
        return messageText.toLowerCase().includes(searchLower) ||
               log.category.toLowerCase().includes(searchLower);
      }
      
      return true;
    });
  }, [logs, selectedLevels, searchText, configState]);

  const handleClearLogs = () => {
    Logger.Instance.clearLogs();
    setLogs([]);
  };

  const handleCopyLogsToClipboard = async () => {
    try {
      // Format the filtered logs for clipboard
      const logText = filteredLogs.map(log => {
        const timestamp = formatTimestamp(log.timestamp);
        const message = Array.isArray(log.message) ? log.message.join(' ') : log.message;
        return `${log.level.toUpperCase()}\t${log.category}\t${timestamp}\t${message}`;
      }).join('\n');
      
      await navigator.clipboard.writeText(logText);
      
      // Could add a toast notification here if desired
      console.log('Logs copied to clipboard');
    } catch (error) {
      console.error('Failed to copy logs to clipboard:', error);
      // Fallback for older browsers
      const textArea = document.createElement('textarea');
      const logText = filteredLogs.map(log => {
        const timestamp = formatTimestamp(log.timestamp);
        const message = Array.isArray(log.message) ? log.message.join(' ') : log.message;
        return `${log.level.toUpperCase()}\t${log.category}\t${timestamp}\t${message}`;
      }).join('\n');
      textArea.value = logText;
      document.body.appendChild(textArea);
      textArea.select();
      document.execCommand('copy');
      document.body.removeChild(textArea);
    }
  };

  return (
    <Box sx={{ display: 'flex', flexDirection: 'column', height: '100%' }}>
      {/* Collapsible Filter Controls */}
      <Paper sx={{ mx: 2, mt: 2, mb: 1 }}>
        <Box sx={{ 
          display: 'flex', 
          alignItems: 'center', 
          justifyContent: 'space-between',
          p: 1,
          cursor: 'pointer'
        }} onClick={() => setFiltersExpanded(!filtersExpanded)}>
          <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
            <FilterList fontSize="small" />
            <Typography variant="body2" fontWeight="bold">
              Filters
            </Typography>
            {(selectedLevels.length < 3 || configState.excludedLogCategories.length > 0 || searchText) && (
              <Chip
                label="Active"
                size="small"
                color="primary"
                variant="outlined"
              />
            )}
          </Box>
          <IconButton size="small">
            {filtersExpanded ? <ExpandLess /> : <ExpandMore />}
          </IconButton>
        </Box>
        
        <Collapse in={filtersExpanded}>
          <Box sx={{ p: 2, pt: 0 }}>
            <Box sx={{ display: 'flex', gap: 2, alignItems: 'center', flexWrap: 'wrap', mb: 2 }}>
              <TextField
                size="small"
                placeholder="Search logs..."
                value={searchText}
                onChange={(e) => setSearchText(e.target.value)}
                InputProps={{
                  endAdornment: searchText && (
                    <Button
                      size="small"
                      onClick={() => setSearchText('')}
                      sx={{ minWidth: 'auto', p: 0.5 }}
                    >
                      <Clear fontSize="small" />
                    </Button>
                  ),
                }}
                sx={{ flex: 1, minWidth: 200 }}
              />
              
              <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1 }}>
                <Typography variant="caption" sx={{ fontWeight: 'bold' }}>
                  Levels
                </Typography>
                <ToggleButtonGroup
                  value={selectedLevels}
                  onChange={(event, newLevels: LogLevel[]) => {
                    setSelectedLevels(newLevels);
                  }}
                  size="small"
                  sx={{ 
                    flexWrap: 'wrap',
                    '& .MuiToggleButton-root': {
                      border: '1px solid #1976d2',
                      color: '#1976d2',
                      '&.Mui-selected': {
                        backgroundColor: '#1976d2',
                        color: '#fff',
                        '&:hover': {
                          backgroundColor: '#1565c0',
                        }
                      },
                      '&:hover': {
                        backgroundColor: 'rgba(25, 118, 210, 0.08)',
                      }
                    }
                  }}
                >
                  <ToggleButton value={LogLevel.Error}>
                    Error
                  </ToggleButton>
                  <ToggleButton value={LogLevel.Info}>
                    Info
                  </ToggleButton>
                  <ToggleButton value={LogLevel.Debug}>
                    Debug
                  </ToggleButton>
                </ToggleButtonGroup>
              </Box>

              <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1 }}>
                <Typography variant="caption" sx={{ fontWeight: 'bold' }}>
                  Categories
                </Typography>
                <Button
                  variant="outlined"
                  size="small"
                  onClick={() => setCategoryDialogOpen(true)}
                  sx={{ minWidth: 140 }}
                >
                  {configState.excludedLogCategories.length === 0 
                    ? 'All Categories' 
                    : `${configState.sessionLogCategories.length - configState.excludedLogCategories.length} of ${configState.sessionLogCategories.length}`
                  }
                </Button>
              </Box>
            </Box>

            <Box sx={{ display: 'flex', gap: 1, alignItems: 'center' }}>
              <Button
                variant="outlined"
                size="small"
                onClick={handleClearLogs}
                startIcon={<Clear />}
                color="error"
              >
                Clear
              </Button>
              
              <Button
                variant="outlined"
                size="small"
                onClick={handleCopyLogsToClipboard}
                startIcon={<ContentCopy />}
                disabled={filteredLogs.length === 0}
              >
                Copy Logs
              </Button>
              
              <Typography variant="caption" color="text.secondary" sx={{ ml: 'auto' }}>
                Showing {filteredLogs.length} of {logs.length} log entries
              </Typography>
            </Box>
          </Box>
        </Collapse>
      </Paper>

      {/* Log Messages */}
      <Box sx={{ flex: 1, overflow: 'hidden', mx: 2, mb: 2 }}>
        <Paper sx={{ height: '100%', display: 'flex', flexDirection: 'column' }}>
          <Box 
            ref={listContainerRef}
            sx={{ 
              flex: 1, 
              overflow: 'auto',
              '&::-webkit-scrollbar': {
                width: '8px',
              },
              '&::-webkit-scrollbar-track': {
                background: '#f1f1f1',
              },
              '&::-webkit-scrollbar-thumb': {
                background: '#888',
                borderRadius: '4px',
              },
              '&::-webkit-scrollbar-thumb:hover': {
                background: '#555',
              },
            }}
          >
            <List sx={{ p: 0 }}>
              {filteredLogs.length === 0 ? (
                <ListItem>
                  <ListItemText
                    primary="No log messages"
                    secondary="No log entries match the current filters"
                  />
                </ListItem>
              ) : (
                filteredLogs.map((log, index) => (
                  <ListItem
                    key={`${log.timestamp}-${index}`}
                    sx={{
                      borderBottom: '1px solid',
                      borderColor: 'divider',
                      alignItems: 'flex-start'
                    }}
                  >
                    <ListItemText
                      primary={
                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 0.5 }}>
                          <Typography
                            variant="caption"
                            sx={{
                              color: getLogLevelColor(log.level),
                              fontWeight: 'bold',
                              minWidth: 50
                            }}
                          >
                            {log.level.toUpperCase()}
                          </Typography>
                          <Chip
                            label={log.category}
                            size="small"
                            variant="outlined"
                            sx={{ fontSize: '0.7rem', height: 20 }}
                          />
                          <Typography variant="caption" color="text.secondary">
                            {formatTimestamp(log.timestamp)}
                          </Typography>
                        </Box>
                      }
                      secondary={
                        <Typography
                          variant="body2"
                          component="div"
                          sx={{
                            fontFamily: 'monospace',
                            whiteSpace: 'pre-wrap',
                            wordBreak: 'break-all'
                          }}
                        >
                          {Array.isArray(log.message) ? log.message.join(' ') : log.message}
                        </Typography>
                      }
                    />
                  </ListItem>
                ))
              )}
            </List>
          </Box>
        </Paper>
      </Box>
      
      {/* Category Selection Dialog */}
      <Dialog 
        open={categoryDialogOpen} 
        onClose={() => setCategoryDialogOpen(false)}
        maxWidth="sm"
        fullWidth
      >
        <DialogTitle>Select Log Categories</DialogTitle>
        <DialogContent>
          <Typography variant="body2" sx={{ mb: 2 }}>
            Choose which categories to show. All categories are included by default.
          </Typography>
          {configState.sessionLogCategories.map((category) => (
            <FormControlLabel
              key={category}
              control={
                <Checkbox
                  checked={!configState.isCategoryExcluded(category)}
                  onChange={() => configState.toggleCategoryExclusion(category)}
                />
              }
              label={category}
            />
          ))}
          {configState.sessionLogCategories.length === 0 && (
            <Typography variant="body2" color="text.secondary">
              No log categories available. Categories will appear here as logs are generated.
            </Typography>
          )}
        </DialogContent>
        <DialogActions>
          <Button 
            onClick={() => {
              // Clear all exclusions (include all)
              configState.excludedLogCategories = [];
            }}
          >
            Include All
          </Button>
          <Button onClick={() => setCategoryDialogOpen(false)} variant="contained">
            Done
          </Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
}
