import { Wizard } from "../../../Wizard/Wizard";
import { WizardStep } from "../../../Wizard/WizardStep";
import { SpindlePositionStep } from "../../SpindlePositionStep";
import { ZAxisReferenceType } from '../common/types';

export class MaterialPositionCheckStep extends SpindlePositionStep {
  constructor(wizard: Wizard, priorStep: WizardStep | null = null) {
    const referenceType = wizard.state.referenceType;
    let title = "Position Spindle for Touch Plate";
    let instructions = "Position the tool where you want to perform the touch plate calibration.";
    
    switch (referenceType) {
      case ZAxisReferenceType.BED:
        title = "Position Spindle Over Machine Bed";
        instructions = "Position the tool over the machine bed where you want to set the Z reference. Place the touch plate on the bed surface below the tool.";
        break;
      case ZAxisReferenceType.SPOILBOARD:
        title = "Position Spindle Over Spoilboard";
        instructions = "Position the tool over the spoilboard where you want to set the Z reference. Place the touch plate on the spoilboard surface below the tool.";
        break;
      case ZAxisReferenceType.MATERIAL:
        title = "Position Spindle Over Material";
        instructions = "Position the tool over the material surface where you want to set the Z reference. Place the touch plate on the material surface below the tool.";
        break;
    }

    super(wizard, priorStep, {
      nextStepFactory: () => {
        // Import here to avoid circular dependency
        const { TestTouchplateStep } = require('./TestTouchplateStep');
        return new TestTouchplateStep(wizard, this);
      },
      title,
      instructions
    });
  }
}
