import { StateManager } from '../utils/statemanager/StateManager';
import { DataUtilities } from '../utils/storage/DataUtilities';
import { CNCOffset } from './CNCOffset';
import { CNCPoint } from './CNCPoint';
import { CoordinateType } from './Common/CoordinateType';
import { FixtureLibrary } from './Common/FixtureLibrary';
import { SaveableDataBase } from './Common/SaveableDataBase';
import { ConfigurationState } from './ConfigurationState';
import { Job } from './Job';

/**
 * Machine state data structure
 * Direct conversion from C# MachineStateData class
 * Implemented as singleton pattern
 */
export class MachineStateData extends SaveableDataBase {
  private static _instance: MachineStateData;

  /**
   * Filename for saving/loading machine state data
   */
  protected get filename(): string {
    return 'machine-state-data.json';
  }

  // Spoil board dimensions
  private _spoilBoardWidth: number = 22;
  private _spoilBoardYLength: number = 30;
  private _spoilBoardHeight: number = 0.75;
  private _spoilboardPosition: CNCOffset = new CNCOffset(1, 1, 0);

  // Current machine position (in machine coordinates)
  // Set to match work zero so machine starts at work coordinates (0,0,0)
  private _currentMachinePoint: CNCPoint = new CNCPoint(6, 5, -6, CoordinateType.MachineZero);

  // Proposed spindle position (used during spindle drag operations)
  private _proposedSpindlePosition: CNCPoint | null = null;

  // User-entered coordinates for jog controls (nullable for each axis)
  private _enteredLocationX: number | null = null;
  private _enteredLocationY: number | null = null;
  private _enteredLocationZ: number | null = null;
  private _enteredLocationA: number | null = null;

  // Feed rates and speeds
  private _currentFeedRate: number = 100;
  private _currentSpindleSpeed: number = 10000;
  private _currentFastTravelRate: number = 200;

  // Fixture and tool info
  private _currentFixtureNumber: string = "G54";
  private _currentFixtureSaved: boolean = false;
  private _currentToolNumber: number = 1; // Default to tool 1 for testing

  // Machine state
  private _isHomed: boolean = false;
  private _currentJob?: Job = undefined;
  private _proposedJob?: Job = undefined; // Job being prepared/edited before becoming current
  private _lastJob?: Job = undefined; // Previous job for reference/restore
  private _testJob?: Job = undefined; // Cached test job to prevent recreating

  // Z-axis calibration references (in machine coordinates)
  private _materialTopZ: number | null = null; // Z position of material top surface

  // Camera positions for different views
  private _cameraPositions: { [viewType: string]: { x: number; y: number; z: number } } = {
    perspective: { x: 10, y: 10, z: 10 },
    front: { x: 0, y: 0, z: 10 },
    side: { x: 10, y: 0, z: 0 },
    top: { x: 0, y: 10, z: 0 }
  };

  private _cameraTargets: { [viewType: string]: { x: number; y: number; z: number } } = {
    perspective: { x: 0, y: 0, z: 0 },
    front: { x: 0, y: 0, z: 0 },
    side: { x: 0, y: 0, z: 0 },
    top: { x: 0, y: 0, z: 0 }
  };

  // Safe mode settings
  private _safeModeOffUtil?: Date; // Date when safe mode is not respected
  private _softLimitsOffUtil?: Date; // Date when soft limits are not respected

  // Rotary axis state
  private _rotaryInstalled: boolean = false;

  // Selected clamp for UI highlighting/editing
  private _selectedClampId: string | null = null;

  // Input override state (for testing purposes only)
  private _isOverridingInputs: boolean = false;

  // Output override state (for testing purposes only)
  private _isOverridingOutputs: boolean = false;

  // Connection state - tracks whether machine is connected
  // This is NOT persisted (runtime state only)
  private _isConnected: boolean = false;

  // Getter and setter methods with StateManager property change notifications

  // Connection state
  public get isConnected(): boolean {
    return this._isConnected;
  }

  public set isConnected(value: boolean) {
    const wasDisconnected = !this._isConnected;
    const isNowConnected = value;

    this._isConnected = value;
    StateManager.propertyChanged(this, 'isConnected');

    // If we just connected (transition from disconnected to connected)
    // Re-establish the fixture point with the machine
    if (wasDisconnected && isNowConnected) {
      this._handleReconnection();
    }
  }

  /**
   * Handle reconnection - re-establish fixture/work zero with the machine
   */
  private async _handleReconnection(): Promise<void> {
    try {
      const { Machine } = await import('../machine/Machine');
      const machine = Machine.getInstance();

      // Re-establish the fixture point (work zero)
      await machine.movement.SetCurrentFixturePoint();

      const { Logger, LogCategory } = await import('../utils/Logger');
      Logger.Instance.log(LogCategory.Network, 'Re-established fixture point after connection');
    } catch (error) {
      const { Logger, LogCategory } = await import('../utils/Logger');
      Logger.Instance.logError(LogCategory.Network, 'Failed to re-establish fixture point after connection:', error);
    }
  }

  // Spoil board dimensions
  public get spoilBoardWidth(): number {
    return this._spoilBoardWidth;
  }

  public set spoilBoardWidth(value: number) {
    this._spoilBoardWidth = value;
    StateManager.propertyChanged(this, 'spoilBoardWidth');
  }

  public get spoilBoardYLength(): number {
    return this._spoilBoardYLength;
  }

  public set spoilBoardYLength(value: number) {
    this._spoilBoardYLength = value;
    StateManager.propertyChanged(this, 'spoilBoardYLength');
  }

  public get spoilBoardHeight(): number {
    return this._spoilBoardHeight;
  }

  public set spoilBoardHeight(value: number) {
    this._spoilBoardHeight = value;
    StateManager.propertyChanged(this, 'spoilBoardHeight');
  }

  public get spoilboardPosition(): CNCOffset {
    // Ensure we always return a CNCOffset, even for old data
    if (!this._spoilboardPosition) {
      this._spoilboardPosition = new CNCOffset(0, 0, 0);
    }
    return this._spoilboardPosition;
  }

  public get spoilboardX(): number {
    return this.spoilboardPosition.x;
  }

  public set spoilboardX(value: number) {
    this.spoilboardPosition.x = value;
    StateManager.propertyChanged(this, 'spoilboardX');
  }

  public get spoilboardY(): number {
    return this.spoilboardPosition.y;
  }

  public set spoilboardY(value: number) {
    this.spoilboardPosition.y = value;
    StateManager.propertyChanged(this, 'spoilboardY');
  }

  // Current machine position
  public get currentMachinePoint(): CNCPoint {
    return this._currentMachinePoint;
  }

  public set currentMachinePoint(value: CNCPoint) {
    this._currentMachinePoint = value;
    StateManager.propertyChanged(this, 'currentMachinePoint');
  }

  // Proposed spindle position
  public get proposedSpindlePosition(): CNCPoint | null {
    return this._proposedSpindlePosition;
  }

  public set proposedSpindlePosition(value: CNCPoint | null) {
    this._proposedSpindlePosition = value;
    StateManager.propertyChanged(this, 'proposedSpindlePosition');
  }

  // User-entered coordinates for jog controls
  public get enteredLocationX(): number | null {
    return this._enteredLocationX;
  }

  public set enteredLocationX(value: number | null) {
    this._enteredLocationX = value;
    StateManager.propertyChanged(this, 'enteredLocationX');
  }

  public get enteredLocationY(): number | null {
    return this._enteredLocationY;
  }

  public set enteredLocationY(value: number | null) {
    this._enteredLocationY = value;
    StateManager.propertyChanged(this, 'enteredLocationY');
  }

  public get enteredLocationZ(): number | null {
    return this._enteredLocationZ;
  }

  public set enteredLocationZ(value: number | null) {
    this._enteredLocationZ = value;
    StateManager.propertyChanged(this, 'enteredLocationZ');
  }

  public get enteredLocationA(): number | null {
    return this._enteredLocationA;
  }

  public set enteredLocationA(value: number | null) {
    this._enteredLocationA = value;
    StateManager.propertyChanged(this, 'enteredLocationA');
  }

  // Feed rates and speeds
  public get currentFeedRate(): number {
    return this._currentFeedRate;
  }

  public set currentFeedRate(value: number) {
    this._currentFeedRate = value;
    StateManager.propertyChanged(this, 'currentFeedRate');
  }

  public get currentSpindleSpeed(): number {
    return this._currentSpindleSpeed;
  }

  public set currentSpindleSpeed(value: number) {
    this._currentSpindleSpeed = value;
    StateManager.propertyChanged(this, 'currentSpindleSpeed');
  }

  public get currentFastTravelRate(): number {
    return this._currentFastTravelRate;
  }

  public set currentFastTravelRate(value: number) {
    this._currentFastTravelRate = value;
    StateManager.propertyChanged(this, 'currentFastTravelRate');
  }

  // Work coordinate system
  public get currentWorkZero(): CNCPoint {
    // Get the current fixture from ConfigurationState
    let currentFixture = ConfigurationState.Instance.currentFixture;

    // If no current fixture is set, look it up by current fixture number and store it
    if (!currentFixture) {
      const foundFixture = FixtureLibrary.getFixtureByNumber(this._currentFixtureNumber);
      if (foundFixture) {
        currentFixture = foundFixture;
        ConfigurationState.Instance.currentFixture = currentFixture;
      }
    }

    // Use the fixture's actual CNCPoint - no new object creation
    if (currentFixture) {
      return currentFixture.workZeroPoint;
    } else {
      // Default fallback - just return a default point
      return new CNCPoint(6, 5, -6, CoordinateType.MachineZero);
    }
  }

  public set currentWorkZero(value: CNCPoint) {
    // Get the current fixture from ConfigurationState
    let currentFixture = ConfigurationState.Instance.currentFixture;

    // If no current fixture is set, look it up by current fixture number and store it
    if (!currentFixture) {
      const foundFixture = FixtureLibrary.getFixtureByNumber(this._currentFixtureNumber);
      if (foundFixture) {
        currentFixture = foundFixture;
        ConfigurationState.Instance.currentFixture = currentFixture;
      }
    }

    // Update the fixture's offset values directly
    if (currentFixture) {
      currentFixture.xOffset = value.x;
      currentFixture.yOffset = value.y;
      currentFixture.zOffset = value.z;
    }

    StateManager.propertyChanged(this, 'currentWorkZero');
  }

  // Z-axis calibration references
  public get materialTopZ(): number | null {
    return this._materialTopZ;
  }

  public set materialTopZ(value: number | null) {
    this._materialTopZ = value;
    StateManager.propertyChanged(this, 'materialTopZ');
  }

  // Fixture and tool info
  public get currentFixtureNumber(): string {
    return this._currentFixtureNumber;
  }

  public set currentFixtureNumber(value: string) {
    this._currentFixtureNumber = value;
    StateManager.propertyChanged(this, 'currentFixtureNumber');
    StateManager.propertyChanged(this, 'currentWorkZero'); // Update work zero when fixture changes

    // Call API to update fixture point on the machine
    this.updateAPIFixturePoint();
  }

  public get currentFixtureSaved(): boolean {
    return this._currentFixtureSaved;
  }

  public set currentFixtureSaved(value: boolean) {
    this._currentFixtureSaved = value;
    StateManager.propertyChanged(this, 'currentFixtureSaved');
  }

  public get currentToolNumber(): number {
    return this._currentToolNumber;
  }

  public set currentToolNumber(value: number) {
    this._currentToolNumber = value;
    StateManager.propertyChanged(this, 'currentToolNumber');
    // Also notify that current work point changed (tool offsets affect displayed position)
    StateManager.propertyChanged(this, 'currentWorkPoint');
    StateManager.propertyChanged(this, 'currentMachinePoint');

    // Call API to update fixture point on the machine (tool offsets affect fixture calculation)
    this.updateAPIFixturePoint();
  }

  /**
   * Get the current tool from the tool library
   */
  public get currentTool() {
    const { ToolLibrary } = require('./Common/ToolLibrary');
    return ToolLibrary.Instance.getToolByNumber(this._currentToolNumber);
  }

  /**
   * Get current tool offsets for the loaded tool
   * Returns zero offsets if no tool is loaded
   */
  public get currentToolOffsets(): CNCOffset {
    const tool = this.currentTool;
    if (!tool) {
      return new CNCOffset(0, 0, 0);
    }
    return new CNCOffset(
      tool.toolOffsetX || 0,
      tool.toolOffsetY || 0,
      tool.length || 0  // Tool length is the Z offset
    );
  }

  // Machine state
  public get isHomed(): boolean {
    return this._isHomed;
  }

  public set isHomed(value: boolean) {
    this._isHomed = value;
    StateManager.propertyChanged(this, 'isHomed');
  }

  public get currentJob(): Job | undefined {
    // Return cached test job if no current job is set
    if (!this._currentJob) {
      if (!this._testJob) {
        this._testJob = Job.createTestJob();
      }
      return this._testJob;
    }
    return this._currentJob;
  }

  public set currentJob(value: Job | undefined) {
    this._currentJob = value;
    StateManager.propertyChanged(this, 'currentJob');
  }

  public get proposedJob(): Job | undefined {
    return this._proposedJob;
  }

  public set proposedJob(value: Job | undefined) {
    this._proposedJob = value;
    StateManager.propertyChanged(this, 'proposedJob');
  }

  public get lastJob(): Job | undefined {
    return this._lastJob;
  }

  public set lastJob(value: Job | undefined) {
    this._lastJob = value;
    StateManager.propertyChanged(this, 'lastJob');
  }

  // Safe mode getters/setters
  public get safeModeOffUtil(): Date | undefined {
    return this._safeModeOffUtil;
  }

  public set safeModeOffUtil(value: Date | undefined) {
    this._safeModeOffUtil = value;
    StateManager.propertyChanged(this, 'safeModeOffUtil');
  }

  public get softLimitsOffUtil(): Date | undefined {
    return this._softLimitsOffUtil;
  }

  public set softLimitsOffUtil(value: Date | undefined) {
    this._softLimitsOffUtil = value;
    StateManager.propertyChanged(this, 'softLimitsOffUtil');
  }

  // Rotary axis state getters/setters
  public get rotaryInstalled(): boolean {
    return this._rotaryInstalled;
  }

  public set rotaryInstalled(value: boolean) {
    this._rotaryInstalled = value;
    StateManager.propertyChanged(this, 'rotaryInstalled');
  }

  // Selected clamp getters/setters
  public get selectedClampId(): string | null {
    return this._selectedClampId;
  }

  public set selectedClampId(value: string | null) {
    this._selectedClampId = value;
    StateManager.propertyChanged(this, 'selectedClampId');
  }

  // Input override getters/setters (for testing purposes only)
  public get isOverridingInputs(): boolean {
    return this._isOverridingInputs;
  }

  public set isOverridingInputs(value: boolean) {
    this._isOverridingInputs = value;
    StateManager.propertyChanged(this, 'isOverridingInputs');
  }

  // Output override getters/setters (for testing purposes only)
  public get isOverridingOutputs(): boolean {
    return this._isOverridingOutputs;
  }

  public set isOverridingOutputs(value: boolean) {
    this._isOverridingOutputs = value;
    StateManager.propertyChanged(this, 'isOverridingOutputs');
  }

  // Camera position methods
  public getCameraPosition(viewType: string): { x: number; y: number; z: number } {
    return this._cameraPositions[viewType] || { x: 10, y: 10, z: 10 };
  }

  public setCameraPosition(viewType: string, position: { x: number; y: number; z: number }): void {
    this._cameraPositions[viewType] = { ...position };
    StateManager.propertyChanged(this, 'cameraPositions');
  }

  public getCameraTarget(viewType: string): { x: number; y: number; z: number } {
    return this._cameraTargets[viewType] || { x: 0, y: 0, z: 0 };
  }

  public setCameraTarget(viewType: string, target: { x: number; y: number; z: number }): void {
    this._cameraTargets[viewType] = { ...target };
    StateManager.propertyChanged(this, 'cameraTargets');
  }

  private constructor() {
    super();

    // All initialization is done inline above
    // Note: setupAutoSave() will be called after instance creation to avoid constructor issues
  }

  /**
   * Serialize to JSON - handle CNCPoint and Job sub-objects explicitly
   */
  public toJSON(): any {
    const baseData = DataUtilities.getStorageData(this, ['_instance', '_currentMachinePoint', '_proposedSpindlePosition', '_spoilboardPosition', '_currentJob', '_proposedJob', '_lastJob', '_testJob', '_enteredLocationX', '_enteredLocationY', '_enteredLocationZ', '_enteredLocationA', '_isConnected']); // Exclude sub-objects and runtime-only properties

    // Handle sub-objects explicitly with proper serialization
    return {
      ...baseData,
      _currentMachinePoint: this._currentMachinePoint.toJSON(),
      _proposedSpindlePosition: this._proposedSpindlePosition ? this._proposedSpindlePosition.toJSON() : null,
      _spoilboardPosition: this._spoilboardPosition.toJSON(),
      _currentJob: this._currentJob ? this._currentJob.toJSON() : null,
      _proposedJob: this._proposedJob ? this._proposedJob.toJSON() : null,
      _lastJob: this._lastJob ? this._lastJob.toJSON() : null,
      _testJob: this._testJob ? this._testJob.toJSON() : null
    };
  }

  /**
   * Load from JSON - handle CNCPoint and Job sub-objects explicitly
   */
  public fromJSON(data: any): void {
    // Load basic properties automatically
    DataUtilities.loadStorageData(this, data, ['_instance', '_currentMachinePoint', '_proposedSpindlePosition', '_spoilboardPosition', '_currentJob', '_proposedJob', '_lastJob', '_testJob']); // Exclude sub-objects that need special handling

    // Handle CNCPoint sub-objects explicitly
    if (data._currentMachinePoint) {
      this._currentMachinePoint.fromJSON(data._currentMachinePoint);
    }
    if (data._proposedSpindlePosition) {
      if (!this._proposedSpindlePosition) {
        this._proposedSpindlePosition = new CNCPoint(0, 0, 0, CoordinateType.MachineZero);
      }
      this._proposedSpindlePosition.fromJSON(data._proposedSpindlePosition);
    }

    // Handle CNCOffset sub-objects explicitly
    if (data._spoilboardPosition) {
      this._spoilboardPosition.fromJSON(data._spoilboardPosition);
    }

    // Handle Job sub-objects explicitly
    if (data._currentJob) {
      this._currentJob = new Job();
      this._currentJob.fromJSON(data._currentJob);
    }
    if (data._proposedJob) {
      this._proposedJob = new Job();
      this._proposedJob.fromJSON(data._proposedJob);
    }
    if (data._lastJob) {
      this._lastJob = new Job();
      this._lastJob.fromJSON(data._lastJob);
    }
    if (data._testJob) {
      this._testJob = new Job();
      this._testJob.fromJSON(data._testJob);
    }
  }

  /**
   * Get the singleton instance
   */
  public static get Instance(): MachineStateData {
    if (!MachineStateData._instance) {
      MachineStateData._instance = new MachineStateData();
      // Setup auto-save after instance is fully created
      MachineStateData._instance.setupAutoSave();
      // Initialize connection state asynchronously
      MachineStateData._instance.initializeConnectionState();
    }
    return MachineStateData._instance;
  }

  /**
   * Initialize connection state by checking machine connection
   */
  private async initializeConnectionState(): Promise<void> {
    try {
      const { Machine } = await import('../machine/Machine');
      const machine = Machine.getInstance();
      const isConnected = await machine.system.IsConnectedToServer();
      this.isConnected = isConnected;
    } catch (error) {
      // If we can't check connection, assume disconnected
      this.isConnected = false;
    }
  }

  /**
   * Call the API to update the fixture point on the machine
   */
  private updateAPIFixturePoint(): void {
    // Use async IIFE to call the API method
    (async () => {
      try {
        const Machine = require('../Machine').Machine;
        await Machine.getInstance().movement.SetCurrentFixturePoint();
      } catch (error) {
        // Silently fail - errors are already logged by the movement implementation
      }
    })();
  }
}
