import { CNCPoint } from '../../../data/CNCPoint';
import { CoordinateType } from '../../../data/Common/CoordinateType';
import { SimulatorView } from '../../../data/Common/SimulatorView';
import { ToolLibrary } from '../../../data/Common/ToolLibrary';
import { ViewStyle } from '../../../data/Common/ViewStyle';
import { ConfigurationData } from '../../../data/ConfigurationData';
import { ATCToolClamp, MachineData } from '../../../data/MachineData';
import { CoordinateUtil } from '../../../utils/CoordinateUtil';
import { ObserveState } from '../../../utils/statemanager/ObserveState';
import { Tool } from './Tool';

export interface ATCPositionedToolProps {
  clamp: ATCToolClamp;
  simulatorView: SimulatorView;
  machineData: MachineData;
  toolClampHeight: number;
}

/**
 * ATC positioned tool component
 * Renders a tool at a specific ATC tool clamp position
 * Tool extends downward from the ISO30 tool holder position
 */
export function ATCPositionedTool({
  clamp,
  simulatorView,
  machineData,
  toolClampHeight
}: ATCPositionedToolProps) {
  // Get tool from tool library using clamp number (which corresponds to tool number)
  const toolLibrary = ToolLibrary.Instance;
  const toolNumber = clamp.clampNumber;
  const tool = toolLibrary.tools.find(t => t.toolNumber === toolNumber);

  // Don't render if no tool, tool not found, or tool visibility is hidden
  if (!tool || toolNumber === 0 || simulatorView.tool === ViewStyle.Hide) {
    return null;
  }

  // Calculate tool position at this ATC clamp
  const atcLocation = machineData.atcLocation;
  const atcStructure = machineData.atcStructure;

  // Calculate tool holder position: base top corner + ATC offset + clamp offset
  const baseTopCorner = CoordinateUtil.getMachineBaseTopCornerPosition();
  const atcPositionInMachineZero = CNCPoint.addOffset(baseTopCorner, atcLocation.offset);
  const clampPositionInMachineZero = CNCPoint.addOffset(atcPositionInMachineZero, clamp.offset);
  const toolHolderPos = CoordinateUtil.toSimulator(clampPositionInMachineZero);

  // Calculate Z adjustment for tool holder height
  const barHeightSimulator = atcStructure.barHeight / 2 + toolClampHeight / 2;
  const toolSimulatorPos = new CNCPoint(
    toolHolderPos.x,
    toolHolderPos.y,
    toolHolderPos.z + barHeightSimulator,
    CoordinateType.Simulator
  );

  // Calculate tool position - tool extends downward from the ISO30 holder bottom
  // The ISO30 holder has a certain height, and the tool should start from its bottom
  const iso30HolderHeight = 2.0; // Height of the ISO30 holder (from ISO30ToolHolder.tsx)

  // Position tool below the ISO30 holder
  // lengthBelowHolder is now stored as negative values (e.g., -3.0 for 3" below holder)
  const toolPosition: [number, number, number] = [
    toolSimulatorPos.x,
    toolSimulatorPos.y,
    toolSimulatorPos.z - iso30HolderHeight / 2 + tool.lengthBelowHolder
  ];

  // Tool needs same rotation as spindle/tool holder (90 degrees around X to make it vertical)
  const toolRotation: [number, number, number] = [Math.PI / 2, 0, 0];

  return (
    <ObserveState
      listenTo={ConfigurationData.Instance}
      properties={['toolTransparency']}
      control={() => {
        // Apply transparency if semi-transparent mode - calculate inside control for reactivity
        const config = ConfigurationData.Instance;
        const visible = simulatorView.tool === ViewStyle.Show || simulatorView.tool === ViewStyle.SemiTransparent;
        const isTransparent = simulatorView.tool === ViewStyle.SemiTransparent;
        const toolOpacity = isTransparent ? config.toolTransparency : 1.0;

        return (
          <Tool
            tool={tool}
            position={toolPosition}
            rotation={toolRotation}
            visible={visible}
            transparent={isTransparent}
            opacity={toolOpacity}
          />
        );
      }}
    />
  );
}
