import { Box, Button, IconButton, Paper, Toolbar, Typography } from '@mui/material';
import ELK from 'elkjs/lib/elk.bundled.js';
import React, { useCallback, useEffect, useState } from 'react';
import {
  Background,
  BackgroundVariant,
  Connection,
  Edge,
  MiniMap,
  Node,
  ReactFlow,
  ReactFlowProvider,
  useEdgesState,
  useNodesState,
  useReactFlow,
} from 'reactflow';
import { ConfigurationDataColors } from '../../data/ConfigurationDataColors';
import { UserMessageQueue } from '../../data/UserMessageQueue';
import { Flow } from '../../flow/Flow';
import { FlowStep } from '../../flow/FlowStep';
import { FlowStepConnection } from '../../flow/FlowStepConnection';
import { Storage, StorageType } from '../../machine/ICNCProgramStorage';
import { Machine } from '../../machine/Machine';
import { SystemIcons } from '../../SystemIcons';
import { LogCategory, Logger } from '../../utils/Logger';
import { FlowStepEdge } from './FlowStepEdge';
import { FlowStepNode } from './FlowStepNode';
import { StepDetailsDialog } from './StepDetailsDialog';
import { StepInsertDialog } from './StepInsertDialog';

import 'reactflow/dist/style.css';

interface FlowEditorProps {
  flow: Flow;
  flowName?: string;
  width?: string | number;
  height?: string | number;
  onFlowChange?: (flow: Flow) => void;
  onClose?: () => void;
}

interface FlowNodeData {
  step: FlowStep;
  onDelete: (stepId: string) => void;
  onResetPosition?: (stepId: string) => void;
  onEdit?: (step: FlowStep) => void;
  onMoveUp?: (stepId: string) => void;
  onMoveDown?: (stepId: string) => void;
  canMoveUp?: boolean;
  canMoveDown?: boolean;
  onStepClick?: (step: FlowStep) => void;
}

// Define nodeTypes and edgeTypes outside component to prevent recreation on each render
const nodeTypes = {
  flowStep: FlowStepNode,
};

const edgeTypes = {
  flowStepEdge: FlowStepEdge,
};

// Internal FlowEditor component that uses ReactFlow hooks
const FlowEditorInternal: React.FC<FlowEditorProps> = ({
  flow,
  flowName,
  width = '100%',
  height = 600,
  onFlowChange,
  onClose,
}) => {
  const [insertDialogOpen, setInsertDialogOpen] = useState(false);
  const [insertPosition, setInsertPosition] = useState<{
    afterStepId: string;
    fromPath: string;
  } | null>(null);

  const [stepDetailsDialogOpen, setStepDetailsDialogOpen] = useState(false);
  const [selectedStep, setSelectedStep] = useState<FlowStep | null>(null);
  const [canBeCalledAsStep, setCanBeCalledAsStep] = useState(false);
  // Note: hasUserPanned is now tracked on the flow object as flow.hasUserManuallyPannedViewport

  // ReactFlow instance for zoom/fit controls
  const reactFlowInstance = useReactFlow();

  // Load canBeCalledAsStep from Storage when component mounts
  useEffect(() => {
    const loadStorageMetadata = async () => {
      if (!flowName) return;

      try {
        const machineStorage = Machine.getInstance().storage;
        const existingStorage = await machineStorage.getStorageData(flowName);
        if (existingStorage) {
          setCanBeCalledAsStep(existingStorage.canBeCalledAsStep ?? false);
        }
      } catch (error) {
        Logger.Instance.logError(LogCategory.DataManager, 'Failed to load flow metadata:', error);
      }
    };

    loadStorageMetadata();
  }, [flowName]);

  // Handle step deletion
  const handleDeleteStep = useCallback((stepId: string) => {
    flow.removeStep(stepId);
    onFlowChange?.(flow);
  }, [flow, onFlowChange]);

  // Reset manual positioning for a step
  const resetStepToAutoLayout = useCallback((stepId: string) => {
    const step = flow.steps.find(s => s.id === stepId);
    if (step) {
      step.isManuallyPositioned = false;
      step.manualPosition = undefined;
      onFlowChange?.(flow);
    }
  }, [flow, onFlowChange]);

  // Handle step editing
  const handleEditStep = useCallback((step: FlowStep) => {
    // TODO: Open modal dialog with step.renderEditUI()
    //console.log('Edit step:', step.name);
  }, []);

  // Handle step click to open details dialog
  const handleStepClick = useCallback((step: FlowStep) => {
    setSelectedStep(step);
    setStepDetailsDialogOpen(true);
  }, []);

  // Reset panning flag when flow structure changes significantly
  const resetPanningFlag = useCallback(() => {
    // Set transient property on flow object (not persisted)
    flow.hasUserManuallyPannedViewport = false;
  }, [flow]);

  // Handle step move up
  const handleMoveStepUp = useCallback((stepId: string) => {
    if (flow.moveStepUp(stepId)) {
      onFlowChange?.(flow);
    }
  }, [flow, onFlowChange]);

  // Handle step move down
  const handleMoveStepDown = useCallback((stepId: string) => {
    if (flow.moveStepDown(stepId)) {
      onFlowChange?.(flow);
    }
  }, [flow, onFlowChange]);

  // Handle node drag end - mark as manually positioned
  const onNodeDragStop = useCallback((event: React.MouseEvent, node: Node) => {
    const step = flow.steps.find(s => s.id === node.id);
    if (step) {
      step.manualPosition = node.position;
      step.isManuallyPositioned = true;

      // Delay the callback to avoid immediate re-render during drag
      setTimeout(() => {
        onFlowChange?.(flow);
      }, 50);
    }
  }, [flow, onFlowChange]);

  // Convert Flow steps to ReactFlow nodes
  const convertToNodes = useCallback((flowInstance: Flow): Node[] => {
    const steps = flowInstance.steps;
    const connections = flowInstance.connections;

    // Calculate layout positions (respecting manual positions)
    const nodePositions = calculateHybridLayout(steps, connections);

    return steps.map((step) => ({
      id: step.id,
      type: 'flowStep',
      position: nodePositions[step.id] || { x: 0, y: 0 },
      data: {
        step,
        onDelete: handleDeleteStep,
        onResetPosition: resetStepToAutoLayout,
        onEdit: handleEditStep,
        onMoveUp: handleMoveStepUp,
        onMoveDown: handleMoveStepDown,
        canMoveUp: flow.canMoveStepUp(step.id),
        canMoveDown: flow.canMoveStepDown(step.id),
        onStepClick: handleStepClick,
      } as FlowNodeData,
      draggable: true, // Enable dragging for manual positioning
    }));
  }, [handleDeleteStep, resetStepToAutoLayout, handleEditStep, handleMoveStepUp, handleMoveStepDown, handleStepClick, flow]);

  // Handle edge click for insertion
  const handleEdgeClick = useCallback((event: React.MouseEvent, edgeId: string) => {
    event.stopPropagation();

    // Parse edge ID to get connection info
    const parts = edgeId.split('-');
    if (parts.length >= 3) {
      const fromStepId = parts[0];
      const fromPath = parts.slice(2).join('-'); // Handle paths with dashes

      setInsertPosition({ afterStepId: fromStepId, fromPath });
      setInsertDialogOpen(true);
    }
  }, []);

  // Convert Flow connections to ReactFlow edges
  const convertToEdges = useCallback((flowInstance: Flow): Edge[] => {
    return flowInstance.connections.map((connection) => ({
      id: `${connection.fromStepId}-${connection.toStepId}-${connection.fromStepPath}`,
      source: connection.fromStepId,
      target: connection.toStepId,
      sourceHandle: connection.fromStepPath,
      type: 'flowStepEdge',
      animated: true,
      style: {
        strokeWidth: 2,
      },
      data: {
        onEdgeClick: handleEdgeClick,
      },
      // No labels needed since output ports are labeled
      // No arrows for cleaner look
    }));
  }, [handleEdgeClick]);

  const [nodes, setNodes, onNodesChange] = useNodesState(convertToNodes(flow));
  const [edges, setEdges, onEdgesChange] = useEdgesState(convertToEdges(flow));

  // Only update when the structure changes (steps added/removed, connections changed)
  // Don't update during dragging to avoid conflicts
  React.useEffect(() => {
    const newNodes = convertToNodes(flow);
    const newEdges = convertToEdges(flow);
    setNodes(newNodes);
    setEdges(newEdges);
  }, [flow.steps.length, flow.connections.length, convertToNodes, convertToEdges, flow, setNodes, setEdges]);

  // Handle node position updates during drag
  const handleNodesChange = useCallback((changes: any[]) => {
    // Apply the changes to ReactFlow state first
    onNodesChange(changes);

    // Update manual positions in the flow data for position changes, but don't trigger callbacks
    changes.forEach(change => {
      if (change.type === 'position' && change.position) {
        const step = flow.steps.find(s => s.id === change.id);
        if (step) {
          step.manualPosition = change.position;
          step.isManuallyPositioned = true;
          // Don't call onFlowChange here to avoid triggering re-renders during drag
        }
      }
    });
  }, [onNodesChange, flow.steps]);

  // Auto-layout using ELK (only affects non-manually positioned nodes)
  const applyAutoLayout = useCallback(async (direction: 'DOWN' | 'RIGHT' = 'DOWN') => {
    const elk = new ELK();

    // Only process non-manually positioned nodes
    const autoLayoutNodes = nodes.filter(node => {
      const step = flow.steps.find(s => s.id === node.id);
      return step && !step.isManuallyPositioned;
    });

    if (autoLayoutNodes.length === 0) return;

    // Create ELK graph structure
    const elkGraph = {
      id: 'root',
      layoutOptions: {
        'elk.algorithm': 'layered',
        'elk.direction': direction,
        'elk.spacing.nodeNode': '80',        // Increased horizontal spacing between nodes at same level
        'elk.layered.spacing.nodeNodeBetweenLayers': '100',  // Increased vertical spacing between layers
        'elk.spacing.edgeNode': '20',        // Increased edge spacing
        'elk.spacing.edgeEdge': '15',        // Increased edge-to-edge spacing
        'elk.layered.nodePlacement.strategy': 'NETWORK_SIMPLEX',  // Better placement for complex layouts
        'elk.layered.crossingMinimization.strategy': 'LAYER_SWEEP'  // Reduce crossing edges
      },
      children: autoLayoutNodes.map(node => ({
        id: node.id,
        width: 220,   // Increased width to account for proper spacing
        height: 90    // Increased height to accommodate icon + text content with better spacing
      })),
      edges: edges
        .filter(edge => {
          const sourceStep = flow.steps.find(s => s.id === edge.source);
          const targetStep = flow.steps.find(s => s.id === edge.target);
          return sourceStep && targetStep &&
            !sourceStep.isManuallyPositioned &&
            !targetStep.isManuallyPositioned;
        })
        .map(edge => ({
          id: edge.id,
          sources: [edge.source],
          targets: [edge.target]
        }))
    };

    try {
      const layoutedGraph = await elk.layout(elkGraph);

      const layoutedNodes = nodes.map(node => {
        const step = flow.steps.find(s => s.id === node.id);

        if (step?.isManuallyPositioned && step.manualPosition) {
          // Keep manual position
          return {
            ...node,
            position: step.manualPosition
          };
        } else {
          // Apply ELK layout
          const elkNode = layoutedGraph.children?.find(n => n.id === node.id);
          if (elkNode) {
            return {
              ...node,
              position: {
                x: elkNode.x || 0,
                y: elkNode.y || 0
              }
            };
          }
        }

        return node;
      });

      // Post-process to adjust auto-positioned steps that follow manual steps
      // We need to do this iteratively to handle chains of auto steps after manual steps
      const MAX_Y_SPACING = 120; // Increased spacing for better visual separation
      const MIN_X_SPACING = 250; // Minimum horizontal spacing between nodes at same level

      const adjustNodePositions = (nodes: any[]) => {
        return nodes.map(node => {
          const step = flow.steps.find(s => s.id === node.id);

          if (step && !step.isManuallyPositioned) {
            // Find predecessors of this auto-positioned step
            const predecessorConnections = flow.connections.filter(conn => conn.toStepId === step.id);

            let manualPredecessorPosition: { x: number; y: number } | null = null;
            let maxPredecessorY = 0;

            for (const conn of predecessorConnections) {
              const predecessorStep = flow.steps.find(s => s.id === conn.fromStepId);
              if (predecessorStep?.isManuallyPositioned && predecessorStep.manualPosition) {
                // If predecessor is manually positioned, use its position as reference

                // For multi-path scenarios, we need to consider the path index
                // Find all connections from this manual predecessor
                const allConnectionsFromPredecessor = flow.connections.filter(c => c.fromStepId === predecessorStep.id);
                const currentConnection = allConnectionsFromPredecessor.find(c => c.toStepId === step.id);

                // Position based on manual predecessor with horizontal offset for multiple paths
                let xOffset = 0;
                if (allConnectionsFromPredecessor.length > 1 && currentConnection) {
                  // Get the path order directly from the predecessor step's results()
                  const predecessorPaths = predecessorStep.results();
                  const pathIndex = predecessorPaths.indexOf(currentConnection.fromStepPath);

                  if (pathIndex >= 0) {
                    // Calculate horizontal spread based on number of paths and path index from step definition
                    const totalWidth = (predecessorPaths.length - 1) * MIN_X_SPACING;
                    const startX = predecessorStep.manualPosition.x - (totalWidth / 2);
                    xOffset = startX + (pathIndex * MIN_X_SPACING) - predecessorStep.manualPosition.x;
                  }
                }

                manualPredecessorPosition = {
                  x: predecessorStep.manualPosition.x + xOffset,
                  y: predecessorStep.manualPosition.y + MAX_Y_SPACING
                };
                break; // Use the first manual predecessor found
              } else {
                // If predecessor is auto-positioned, find its current position in nodes
                const predecessorNode = nodes.find(n => n.id === conn.fromStepId);
                if (predecessorNode) {
                  // For auto-positioned predecessors, also check for multi-path scenarios
                  const predecessorStep = flow.steps.find(s => s.id === conn.fromStepId);
                  if (predecessorStep) {
                    const allConnectionsFromPredecessor = flow.connections.filter(c => c.fromStepId === predecessorStep.id);
                    if (allConnectionsFromPredecessor.length > 1) {
                      // This is a multi-path scenario from an auto-positioned step
                      const currentConnection = allConnectionsFromPredecessor.find(c => c.toStepId === step.id);
                      if (currentConnection) {
                        // Get the path order directly from the predecessor step's results()
                        const predecessorPaths = predecessorStep.results();
                        const pathIndex = predecessorPaths.indexOf(currentConnection.fromStepPath);

                        if (pathIndex >= 0) {
                          const totalWidth = (predecessorPaths.length - 1) * MIN_X_SPACING;
                          const startX = predecessorNode.position.x - (totalWidth / 2);
                          const adjustedX = startX + (pathIndex * MIN_X_SPACING);
                          maxPredecessorY = Math.max(maxPredecessorY, predecessorNode.position.y + MAX_Y_SPACING);

                          // Store the adjusted X position for this path
                          if (!manualPredecessorPosition) {
                            manualPredecessorPosition = {
                              x: adjustedX,
                              y: predecessorNode.position.y + MAX_Y_SPACING
                            };
                          }
                        }
                      }
                    } else {
                      maxPredecessorY = Math.max(maxPredecessorY, predecessorNode.position.y + MAX_Y_SPACING);
                    }
                  } else {
                    maxPredecessorY = Math.max(maxPredecessorY, predecessorNode.position.y + MAX_Y_SPACING);
                  }
                }
              }
            }

            let newPosition = node.position;

            // If we found a manual predecessor, position relative to it
            if (manualPredecessorPosition) {
              newPosition = {
                x: manualPredecessorPosition.x,  // Align X with manual step
                y: manualPredecessorPosition.y   // Position below manual step
              };
            }
            // If we found auto predecessors, ensure we're below the highest one
            else if (maxPredecessorY > 0) {
              // For auto-positioned steps following other auto-positioned steps,
              // we need to check if those predecessors were positioned due to manual steps
              let bestXPosition = node.position.x;

              // Try to maintain horizontal alignment with the closest positioned predecessor
              // and handle multi-path scenarios
              for (const conn of predecessorConnections) {
                const predecessorNode = nodes.find(n => n.id === conn.fromStepId);
                if (predecessorNode) {
                  const predecessorStep = flow.steps.find(s => s.id === conn.fromStepId);
                  if (predecessorStep) {
                    const allConnectionsFromPredecessor = flow.connections.filter(c => c.fromStepId === predecessorStep.id);
                    if (allConnectionsFromPredecessor.length > 1) {
                      // Multi-path scenario: calculate proper horizontal positioning
                      const currentConnection = allConnectionsFromPredecessor.find(c => c.toStepId === step.id);
                      if (currentConnection) {
                        // Get the path order directly from the predecessor step's results()
                        const predecessorPaths = predecessorStep.results();
                        const pathIndex = predecessorPaths.indexOf(currentConnection.fromStepPath);

                        if (pathIndex >= 0) {
                          const totalWidth = (predecessorPaths.length - 1) * MIN_X_SPACING;
                          const startX = predecessorNode.position.x - (totalWidth / 2);
                          bestXPosition = startX + (pathIndex * MIN_X_SPACING);
                          break;
                        }
                      }
                    } else if (predecessorNode.position.y === maxPredecessorY - MAX_Y_SPACING) {
                      bestXPosition = predecessorNode.position.x;
                      break;
                    }
                  }
                }
              }

              newPosition = {
                x: bestXPosition,     // Use calculated position for multi-path or alignment
                y: maxPredecessorY    // Use calculated Y from predecessors
              };
            }
            // If no predecessors but ELK positioned it too far from origin, constrain it
            else if (node.position.y > 50 + MAX_Y_SPACING) {
              // Find the minimum Y position this node should be at based on its level in the flow
              const nodeLevel = calculateNodeLevel(step.id, flow.connections);
              newPosition = {
                x: node.position.x,
                y: 50 + (nodeLevel * MAX_Y_SPACING)  // Use consistent spacing based on level
              };
            }

            return {
              ...node,
              position: newPosition
            };
          }

          return node;
        });
      };

      let adjustedNodes = [...layoutedNodes];
      let hasChanges = true;
      let iterations = 0;
      const maxIterations = 20; // Increased iterations for multi-path scenarios

      while (hasChanges && iterations < maxIterations) {
        iterations++;
        const previousNodes = adjustedNodes.map(n => ({ ...n, position: { ...n.position } }));
        adjustedNodes = adjustNodePositions(adjustedNodes);

        // Check if any positions changed
        hasChanges = adjustedNodes.some((node, index) =>
          node.position.x !== previousNodes[index].position.x ||
          node.position.y !== previousNodes[index].position.y
        );
      }

      // Final spacing adjustment - only adjust spacing without changing order
      const finalAdjustedNodes = adjustedNodes.map(node => ({ ...node }));

      // Group nodes by Y position (same level) to check for spacing conflicts
      const nodesByLevel = new Map<number, any[]>();
      finalAdjustedNodes.forEach(node => {
        const level = Math.round(node.position.y / MAX_Y_SPACING);
        if (!nodesByLevel.has(level)) {
          nodesByLevel.set(level, []);
        }
        nodesByLevel.get(level)!.push(node);
      });

      // For each level, ensure proper spacing without changing the order
      nodesByLevel.forEach(levelNodes => {
        if (levelNodes.length > 1) {
          // Sort by current X position to process left to right
          levelNodes.sort((a, b) => a.position.x - b.position.x);

          // Adjust positions to ensure proper spacing while preserving order
          for (let i = 1; i < levelNodes.length; i++) {
            const prevNode = levelNodes[i - 1];
            const currentNode = levelNodes[i];

            const minX = prevNode.position.x + MIN_X_SPACING;
            if (currentNode.position.x < minX) {
              // Only push to the right if there's insufficient spacing
              currentNode.position.x = minX;
            }
          }
        }
      });

      setNodes(finalAdjustedNodes);

      // Position viewport to show all content if user hasn't manually panned
      if (!flow.hasUserManuallyPannedViewport) {
        setTimeout(() => {
          // Calculate bounds of all nodes
          const nodeBounds = finalAdjustedNodes.reduce(
            (bounds, node) => {
              const nodeWidth = 220; // Same as ELK width
              const nodeHeight = 90;  // Same as ELK height
              return {
                minX: Math.min(bounds.minX, node.position.x),
                maxX: Math.max(bounds.maxX, node.position.x + nodeWidth),
                minY: Math.min(bounds.minY, node.position.y),
                maxY: Math.max(bounds.maxY, node.position.y + nodeHeight),
              };
            },
            { minX: Infinity, maxX: -Infinity, minY: Infinity, maxY: -Infinity }
          );

          // Add padding around content
          const padding = 50;
          const viewportX = nodeBounds.minX - padding;
          const viewportY = nodeBounds.minY - padding;

          reactFlowInstance.setViewport({
            x: -viewportX, // Negative because viewport x/y work opposite to content positioning
            y: -viewportY,
            zoom: 1
          });
        }, 100);
      }
    } catch (error) {
      console.error('ELK layout failed:', error);
      // Fallback to simple positioning if ELK fails
      const MIN_X_SPACING = 250; // Define locally for fallback
      const MAX_Y_SPACING = 120; // Define locally for fallback
      const simpleLayoutedNodes = autoLayoutNodes.map((node, index) => ({
        ...node,
        position: { x: 50 + index * MIN_X_SPACING, y: 50 + Math.floor(index / 3) * MAX_Y_SPACING }  // Use consistent spacing
      }));
      setNodes(simpleLayoutedNodes);

      // Position viewport to show all content if user hasn't manually panned
      if (!flow.hasUserManuallyPannedViewport) {
        setTimeout(() => {
          // Calculate bounds of all nodes for fallback layout
          const nodeBounds = simpleLayoutedNodes.reduce(
            (bounds, node) => {
              const nodeWidth = 220;
              const nodeHeight = 90;
              return {
                minX: Math.min(bounds.minX, node.position.x),
                maxX: Math.max(bounds.maxX, node.position.x + nodeWidth),
                minY: Math.min(bounds.minY, node.position.y),
                maxY: Math.max(bounds.maxY, node.position.y + nodeHeight),
              };
            },
            { minX: Infinity, maxX: -Infinity, minY: Infinity, maxY: -Infinity }
          );

          // Add padding around content
          const padding = 50;
          const viewportX = nodeBounds.minX - padding;
          const viewportY = nodeBounds.minY - padding;

          reactFlowInstance.setViewport({
            x: -viewportX,
            y: -viewportY,
            zoom: 1
          });
        }, 100);
      }
    }
  }, [nodes, edges, setNodes, flow, reactFlowInstance]);

  // Reset all steps to auto layout
  const resetAllToAutoLayout = useCallback(() => {
    flow.steps.forEach(step => {
      step.isManuallyPositioned = false;
      step.manualPosition = undefined;
    });
    resetPanningFlag(); // Reset panning when doing full reset
    onFlowChange?.(flow);

    // Trigger layout recalculation
    setTimeout(() => applyAutoLayout('DOWN'), 100);
  }, [flow, onFlowChange, applyAutoLayout, resetPanningFlag]);

  // Auto-layout when nodes change (after add/remove operations)
  React.useEffect(() => {
    if (nodes.length > 0 && !flow.hasUserManuallyPannedViewport) {
      // Only auto-layout if user hasn't panned AND there's actually a layout change needed
      const timer = setTimeout(() => {
        // Double-check that user hasn't panned during the timeout
        if (!flow.hasUserManuallyPannedViewport) {
          applyAutoLayout('DOWN');
        }
      }, 100);
      return () => clearTimeout(timer);
    }
  }, [nodes.length, applyAutoLayout, flow]); // Use flow object instead of specific property

  // Handle step insertion
  const handleInsertStep = useCallback((stepType: string) => {
    if (!insertPosition) return;

    try {
      const { FlowStepFactory } = require('../../flow/FlowStepFactory');

      const newStep = FlowStepFactory.Instance.getStepByType(stepType);
      if (!newStep) {
        console.error(`Failed to create step of type: ${stepType}`);
        return;
      }

      flow.addStep(newStep, insertPosition.afterStepId, insertPosition.fromPath);
      resetPanningFlag(); // Reset panning when adding steps
      onFlowChange?.(flow);

      setInsertDialogOpen(false);
      setInsertPosition(null);

      // The auto-layout effect will handle any spacing issues automatically
    } catch (error) {
      console.error('Failed to create step:', error);
    }
  }, [flow, insertPosition, onFlowChange, resetPanningFlag]);

  // Handle user interaction to detect manual panning - make it immediate
  const handleUserInteraction = useCallback((event: React.WheelEvent) => {
    // Immediately mark as manually panned for any wheel interaction
    flow.hasUserManuallyPannedViewport = true;
    event.stopPropagation(); // Prevent any interference
  }, [flow]);

  // Handle mouse down on ReactFlow background for panning detection - make it immediate
  const handleBackgroundClick = useCallback((event: React.MouseEvent) => {
    // Immediately mark as panned for any mouse interaction that could be panning
    flow.hasUserManuallyPannedViewport = true;
  }, [flow]);

  // Save functionality
  const handleSave = async () => {
    Logger.Instance.log(LogCategory.DataManager, `Starting flow save process for: ${flowName}`);

    if (!flowName) {
      Logger.Instance.logError(LogCategory.DataManager, 'Flow save failed: No flow name provided');
      UserMessageQueue.Instance.addMessage('❌ No flow name provided for saving');
      return;
    }

    try {
      Logger.Instance.log(LogCategory.DataManager, 'Creating storage object...');
      const storage = new Storage();
      storage.name = flowName;
      storage.storageType = StorageType.Flow;

      Logger.Instance.log(LogCategory.DataManager, 'Serializing flow to JSON...');
      const flowJson = flow.toJSON();
      storage.data = JSON.stringify(flowJson);
      storage.updatedAt = new Date();

      Logger.Instance.log(LogCategory.DataManager, `Flow serialized, data length: ${storage.data.length} characters`);

      // Get existing storage to preserve metadata
      Logger.Instance.log(LogCategory.DataManager, 'Checking for existing storage metadata...');
      const machineStorage = Machine.getInstance().storage;
      Logger.Instance.log(LogCategory.DataManager, `Machine storage instance: ${machineStorage ? 'available' : 'null'}`);

      const existingStorage = await machineStorage.getStorageData(flowName);
      if (existingStorage) {
        Logger.Instance.log(LogCategory.DataManager, 'Found existing storage, preserving metadata');
        // Ensure we have valid Date objects
        storage.createdAt = existingStorage.createdAt instanceof Date ? existingStorage.createdAt : new Date(existingStorage.createdAt);
        storage.categoryName = existingStorage.categoryName;
        storage.exposeAsAction = existingStorage.exposeAsAction;

        // Validate the dates are valid
        if (isNaN(storage.createdAt.getTime())) {
          Logger.Instance.log(LogCategory.DataManager, 'Invalid createdAt date found, using current date');
          storage.createdAt = new Date();
        }
      } else {
        Logger.Instance.log(LogCategory.DataManager, 'No existing storage found, using defaults');
        storage.createdAt = new Date();
        storage.categoryName = '';
        storage.exposeAsAction = false;
      }

      // Save canBeCalledAsStep from component state
      storage.canBeCalledAsStep = canBeCalledAsStep;

      // Ensure updatedAt is also valid
      if (isNaN(storage.updatedAt.getTime())) {
        Logger.Instance.log(LogCategory.DataManager, 'Invalid updatedAt date, using current date');
        storage.updatedAt = new Date();
      }

      Logger.Instance.log(LogCategory.DataManager, 'Calling saveStorageData...');
      Logger.Instance.log(LogCategory.DataManager, `Storage dates - created: ${storage.createdAt}, updated: ${storage.updatedAt}`);
      Logger.Instance.log(LogCategory.DataManager, `Date validation - created valid: ${!isNaN(storage.createdAt.getTime())}, updated valid: ${!isNaN(storage.updatedAt.getTime())}`);

      await machineStorage.saveStorageData(storage);

      Logger.Instance.log(LogCategory.DataManager, `✓ Flow '${flowName}' saved successfully`);
      UserMessageQueue.Instance.addMessage('✓ Flow saved successfully');

      // Close the flow editor after successful save
      if (onClose) {
        onClose();
      }

    } catch (error) {
      Logger.Instance.logError(LogCategory.DataManager, `Failed to save flow '${flowName}':`, error);
      Logger.Instance.logError(LogCategory.DataManager, `Error details - Name: ${error.name}, Message: ${error.message}`);
      if (error.stack) {
        Logger.Instance.logError(LogCategory.DataManager, `Error stack: ${error.stack}`);
      }
      UserMessageQueue.Instance.addMessage(`❌ Failed to save flow: ${error.message}`);
    }
  };

  const handleCancel = () => {
    if (onClose) {
      onClose();
    }
  };

  // Prevent new connections from being created by users
  const onConnect = useCallback((params: Edge | Connection) => {
    // Don't allow manual connection creation
    return;
  }, []);

  return (
    <Box sx={{ width, height, position: 'relative', overflow: 'hidden' }}>
      <Paper elevation={1} sx={{ width: '100%', height: '100%', display: 'flex', flexDirection: 'column', position: 'relative', zIndex: 1 }}>
        {/* Toolbar */}
        <Toolbar variant="dense" sx={{ borderBottom: 1, borderColor: 'divider', minHeight: 48, px: 2 }}>
          {/* Left side - Flow name */}
          <Box sx={{ display: 'flex', alignItems: 'center' }}>
            {flowName ? (
              <Typography variant="h6" sx={{ fontWeight: 500 }}>
                {flowName} ({flow.FlowType})
              </Typography>
            ) : (
              <Typography variant="body2">
                Flow Editor - Drag nodes to position manually
              </Typography>
            )}
          </Box>

          {/* Right side - Controls and Save/Cancel buttons */}
          <Box sx={{ flexGrow: 1, display: 'flex', justifyContent: 'flex-end', alignItems: 'center', gap: 1 }}>
            {/* Toggle Callable as Step */}
            <IconButton
              size="small"
              onClick={() => setCanBeCalledAsStep(prev => !prev)}
              title={canBeCalledAsStep ? "Flow can be called from other flows (click to disable)" : "Flow cannot be called from other flows (click to enable)"}
              sx={{
                color: canBeCalledAsStep ? '#fff' : 'text.secondary',
                backgroundColor: canBeCalledAsStep ? 'primary.main' : 'transparent',
                border: canBeCalledAsStep ? 'none' : '1px solid',
                borderColor: 'divider',
                '&:hover': {
                  backgroundColor: canBeCalledAsStep ? 'primary.dark' : 'action.hover',
                  color: canBeCalledAsStep ? '#fff' : 'text.primary'
                }
              }}
            >
              {SystemIcons.callableAsStep}
            </IconButton>

            {/* Reset Manual Positioning */}
            <IconButton
              size="small"
              onClick={resetAllToAutoLayout}
              title="Reset All Steps to Auto Positioning"
              disabled={!flow.steps.some(step => step.isManuallyPositioned)}
              sx={{
                opacity: flow.steps.some(step => step.isManuallyPositioned) ? 1 : 0.5,
                color: flow.steps.some(step => step.isManuallyPositioned) ? 'warning.main' : 'inherit'
              }}
            >
              {SystemIcons.refresh}
            </IconButton>

            {onClose && (
              <>
                <Button
                  size="small"
                  variant="contained"
                  onClick={handleSave}
                  sx={{
                    backgroundColor: ConfigurationDataColors.Instance.primaryColor,
                    color: ConfigurationDataColors.Instance.lightTextColor,
                    '&:hover': {
                      backgroundColor: ConfigurationDataColors.Instance.primaryColor,
                      filter: 'brightness(0.9)',
                    },
                  }}
                >
                  Save
                </Button>
                <Button
                  size="small"
                  variant="outlined"
                  onClick={handleCancel}
                  sx={{
                    borderColor: ConfigurationDataColors.Instance.borderColor,
                    color: ConfigurationDataColors.Instance.darkTextColor,
                  }}
                >
                  Cancel
                </Button>
              </>
            )}
          </Box>
        </Toolbar>

        {/* ReactFlow Container */}
        <Box
          sx={{ flex: 1, minHeight: 0, position: 'relative', overflow: 'hidden' }}
          onWheel={handleUserInteraction}
          onMouseDown={handleBackgroundClick}
          onKeyDown={() => flow.hasUserManuallyPannedViewport = true} // Catch arrow key panning
          tabIndex={0} // Make focusable for keyboard events
        >
          <ReactFlow
            nodes={nodes}
            edges={edges}
            onNodesChange={handleNodesChange}
            onEdgesChange={onEdgesChange}
            onConnect={onConnect}
            onNodeDragStop={onNodeDragStop}
            nodeTypes={nodeTypes}
            edgeTypes={edgeTypes}
            nodesDraggable={true}
            nodesConnectable={false}
            snapToGrid={true}
            snapGrid={[15, 15]}
            defaultViewport={{ x: 50, y: 50, zoom: 1 }}
            style={{ width: '100%', height: '100%' }}
          >
            <MiniMap />
            <Background variant={BackgroundVariant.Dots} gap={12} size={1} />
          </ReactFlow>
        </Box>
      </Paper>

      <StepInsertDialog
        open={insertDialogOpen}
        onClose={() => {
          setInsertDialogOpen(false);
          setInsertPosition(null);
        }}
        onInsertStep={handleInsertStep}
      />

      <StepDetailsDialog
        open={stepDetailsDialogOpen}
        step={selectedStep}
        flow={flow}
        onClose={() => {
          setStepDetailsDialogOpen(false);
          setSelectedStep(null);
        }}
        onEdit={handleEditStep}
        onDelete={handleDeleteStep}
        onMoveUp={handleMoveStepUp}
        onMoveDown={handleMoveStepDown}
        onResetPosition={resetStepToAutoLayout}
        canMoveUp={selectedStep ? flow.canMoveStepUp(selectedStep.id) : false}
        canMoveDown={selectedStep ? flow.canMoveStepDown(selectedStep.id) : false}
      />
    </Box>
  );
};

// Wrapper component that provides ReactFlow context
export const FlowEditor: React.FC<FlowEditorProps> = (props) => {
  return (
    <ReactFlowProvider>
      <FlowEditorInternal {...props} />
    </ReactFlowProvider>
  );
};

// Helper function to calculate the level of a node in the flow (how many steps from start)
function calculateNodeLevel(nodeId: string, connections: FlowStepConnection[]): number {
  const visited = new Set<string>();
  const queue = [{ id: nodeId, level: 0 }];

  while (queue.length > 0) {
    const { id, level } = queue.shift()!;

    if (visited.has(id)) continue;
    visited.add(id);

    // Find predecessors
    const predecessors = connections.filter(conn => conn.toStepId === id);
    if (predecessors.length === 0) {
      // This is a start node
      return level;
    }

    // Add predecessors to queue with incremented level
    for (const pred of predecessors) {
      if (!visited.has(pred.fromStepId)) {
        queue.push({ id: pred.fromStepId, level: level + 1 });
      }
    }
  }

  return 0; // Fallback
}

// Simple layout calculation that works with ELK-based auto-layout
function calculateHybridLayout(
  steps: FlowStep[],
  connections: FlowStepConnection[]
): Record<string, { x: number; y: number }> {
  const positions: Record<string, { x: number; y: number }> = {};

  // Set manual positions immediately
  const manuallyPositioned = new Set<string>();
  steps.forEach(step => {
    if (step.isManuallyPositioned && step.manualPosition) {
      positions[step.id] = { ...step.manualPosition };
      manuallyPositioned.add(step.id);
    }
  });

  // Simple grid layout for auto-positioned steps as initial positioning
  // The ELK-based applyAutoLayout will improve these positions
  const autoPositionSteps = steps.filter(step => !manuallyPositioned.has(step.id));
  autoPositionSteps.forEach((step, index) => {
    positions[step.id] = {
      x: 50 + (index % 4) * 250,        // Start from upper left (50px margin)
      y: 50 + Math.floor(index / 4) * 120  // Start from upper left (50px margin)
    };
  });

  return positions;
}
