import { Api, ExpandMore, Refresh } from '@mui/icons-material';
import {
  Accordion,
  AccordionDetails,
  AccordionSummary,
  Box,
  Button,
  Chip,
  Typography
} from '@mui/material';
import React, { useEffect, useState } from 'react';
import { ConfigurationData } from '../../../../data/ConfigurationData';
import { LogCategory, Logger } from '../../../../utils/Logger';
import { MachineInterfaceManager } from '../../../../utils/MachineInterfaceManager';
import { ApiInputDialog } from './ApiInputDialog';
import { ApiMethodRegistry } from './ApiMethodRegistry';
import { ApiTestStats } from './ApiTestStats';
import { FeaturesApiTests } from './components/FeaturesApiTests';
import { IOApiTests } from './components/IOApiTests';
import { MovementApiTests } from './components/MovementApiTests';
import { ProgramApiTests } from './components/ProgramApiTests';
import { SetupApiTests } from './components/SetupApiTests';
import { SpindleApiTests } from './components/SpindleApiTests';
import { SystemApiTests } from './components/SystemApiTests';

interface InputApiTestState {
  title: string;
  methodName: string;
  defaultInputs: any;
  result: any;
  error?: string;
  loading: boolean;
  executionTime?: number;
}

export function ApiTestingTab() {
  const config = ConfigurationData.Instance;
  const machineManager = MachineInterfaceManager.Instance;
  const configInfo = machineManager.getConfigurationInfo();
  const serviceConfig = machineManager.getServiceConfiguration();
  
  // State for API calls (both with and without inputs)
  const [inputDialogState, setInputDialogState] = useState<InputApiTestState>({
    title: '',
    methodName: '',
    defaultInputs: {},
    result: undefined,
    error: undefined,
    loading: false,
    executionTime: undefined
  });
  const [inputDialogOpen, setInputDialogOpen] = useState(false);
  const [expandedPanel, setExpandedPanel] = useState<string | false>('system');
  const [statsUpdateTrigger, setStatsUpdateTrigger] = useState(0); // Used to force re-render when stats change

  // Debug logging for dialog state changes
  useEffect(() => {
    // console.log('Dialog state changed:', { inputDialogOpen, inputDialogState });
  }, [inputDialogOpen, inputDialogState]);

  const handleAccordionChange = (panel: string) => (event: React.SyntheticEvent, isExpanded: boolean) => {
    setExpandedPanel(isExpanded ? panel : false);
  };

  const handleTestClick = (methodId: string, title: string) => {
    const methodInfo = ApiMethodRegistry.getInstance().getMethod(methodId);
    if (!methodInfo) {
      Logger.Instance.logError(LogCategory.System, `API Test: Method not found: ${methodId}`);
      return;
    }
    
    const defaultInputs = methodInfo.hasParameters && methodInfo.getDefaultParameters 
      ? methodInfo.getDefaultParameters() 
      : null;
    
    setInputDialogState({
      title,
      methodName: methodId, // Store methodId as methodName for consistency
      defaultInputs,
      result: undefined,
      error: undefined,
      loading: false,
      executionTime: undefined
    });
    setInputDialogOpen(true);
  };

  const executeInputApiCall = async (inputs: any) => {
    const startTime = performance.now();
    setInputDialogState(prev => ({ ...prev, loading: true, result: undefined, error: undefined, executionTime: undefined }));
    
    try {
      Logger.Instance.log(LogCategory.System, `API Test: Starting ${inputDialogState.title} with inputs:`, inputs);
      Logger.Instance.log(LogCategory.System, `API Test: Service configuration basePath: ${serviceConfig?.basePath || 'undefined'}`);
      Logger.Instance.log(LogCategory.System, `API Test: Using ${configInfo.usingCentroid ? 'Centroid' : 'Simulator'} interface`);
      
      const methodId = inputDialogState.methodName; // This is actually methodId now
      const methodInfo = ApiMethodRegistry.getInstance().getMethod(methodId);
      
      if (!methodInfo) {
        throw new Error(`Method not found in registry: ${methodId}`);
      }
      
      // Execute using the registry's execute function
      const result = await methodInfo.execute(inputs);
      
      const endTime = performance.now();
      const executionTime = Math.round(endTime - startTime);
      
      Logger.Instance.log(LogCategory.System, `API Test: ${inputDialogState.title} completed successfully in ${executionTime}ms`);
      Logger.Instance.log(LogCategory.System, `API Test: ${inputDialogState.title} result:`, result);
      Logger.Instance.log(LogCategory.System, `API Test: ${inputDialogState.title} result type: ${typeof result}`);
      Logger.Instance.log(LogCategory.System, `API Test: ${inputDialogState.title} result length: ${result !== undefined ? JSON.stringify(result).length : 0}`);
      
      // Record successful execution using methodId
      ApiTestStats.getInstance().recordSuccess(methodId);
      setStatsUpdateTrigger(prev => prev + 1); // Trigger UI update
      
      setInputDialogState(prev => ({
        ...prev,
        result,
        loading: false,
        executionTime
      }));
      
    } catch (error) {
      const endTime = performance.now();
      const executionTime = Math.round(endTime - startTime);
      const errorMessage = error instanceof Error ? error.message : String(error);
      
      Logger.Instance.logError(LogCategory.System, `API Test: ${inputDialogState.title} failed after ${executionTime}ms:`, error);
      
      // Record failed execution
      ApiTestStats.getInstance().recordError(inputDialogState.methodName);
      setStatsUpdateTrigger(prev => prev + 1); // Trigger UI update
      
      setInputDialogState(prev => ({
        ...prev,
        error: errorMessage,
        loading: false,
        executionTime
      }));
    }
  };

  // Helper function to render a button with execution stats
  const renderStatsButton = (methodId: string) => {
    const methodInfo = ApiMethodRegistry.getInstance().getMethod(methodId);
    if (!methodInfo) {
      return <Typography color="error">Method not found: {methodId}</Typography>;
    }
    
    const stats = ApiTestStats.getInstance().getStats(methodId);
    const hasStats = stats.successCount > 0 || stats.errorCount > 0;
    
    // Force re-render when stats change (statsUpdateTrigger dependency)
    // eslint-disable-next-line @typescript-eslint/no-unused-vars
    const _trigger = statsUpdateTrigger; // This forces the component to re-render when stats change
    
    return (
      <Box sx={{ position: 'relative', display: 'inline-block', width: '100%' }}>
        <Button
          variant="outlined"
          fullWidth
          sx={{ 
            minHeight: '48px',
            '&:hover': {
              backgroundColor: 'action.hover'
            }
          }}
          onClick={() => handleTestClick(methodId, methodInfo.title)}
        >
          {methodInfo.title}
        </Button>
        {hasStats && (
          <Box sx={{ 
            position: 'absolute', 
            top: '-8px', 
            right: '-8px', 
            display: 'flex', 
            gap: 0.5 
          }}>
            {stats.successCount > 0 && (
              <Chip
                size="small"
                label={stats.successCount}
                sx={{
                  backgroundColor: 'success.main',
                  color: 'success.contrastText',
                  fontSize: '0.7rem',
                  height: '18px',
                  minWidth: '18px',
                  '& .MuiChip-label': {
                    padding: '0 4px'
                  }
                }}
              />
            )}
            {stats.errorCount > 0 && (
              <Chip
                size="small"
                label={stats.errorCount}
                sx={{
                  backgroundColor: 'error.main',
                  color: 'error.contrastText',
                  fontSize: '0.7rem',
                  height: '18px',
                  minWidth: '18px',
                  '& .MuiChip-label': {
                    padding: '0 4px'
                  }
                }}
              />
            )}
          </Box>
        )}
      </Box>
    );
  };

  // Reset functions
  const handleResetAllStats = () => {
    ApiTestStats.getInstance().resetStats();
    setStatsUpdateTrigger(prev => prev + 1);
  };

  const handleResetMethodStats = (methodName: string) => {
    ApiTestStats.getInstance().resetStats(methodName);
    setStatsUpdateTrigger(prev => prev + 1);
  };

  const handleCloseInputDialog = () => {
    setInputDialogOpen(false);
    setInputDialogState({
      title: '',
      methodName: '',
      defaultInputs: {},
      result: undefined,
      error: undefined,
      loading: false,
      executionTime: undefined
    });
  };

  return (
    <Box sx={{ p: 3, height: '100%', overflow: 'auto' }}>
      {/* Header */}
      <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', mb: 3 }}>
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
          <Api color="primary" />
          <Typography variant="h5">
            API Testing
          </Typography>
          <Chip 
            label="Development Tool" 
            size="small" 
            color="secondary"
          />
        </Box>
        
        {/* Stats Summary and Reset Button */}
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
          {(() => {
            const totalStats = ApiTestStats.getInstance().getTotalStats();
            const hasStats = totalStats.totalSuccess > 0 || totalStats.totalErrors > 0;
            
            return hasStats ? (
              <>
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                  <Typography variant="body2" color="text.secondary">
                    Total:
                  </Typography>
                  {totalStats.totalSuccess > 0 && (
                    <Chip
                      size="small"
                      label={`✓ ${totalStats.totalSuccess}`}
                      sx={{
                        backgroundColor: 'success.main',
                        color: 'success.contrastText',
                        fontSize: '0.75rem'
                      }}
                    />
                  )}
                  {totalStats.totalErrors > 0 && (
                    <Chip
                      size="small"
                      label={`✗ ${totalStats.totalErrors}`}
                      sx={{
                        backgroundColor: 'error.main',
                        color: 'error.contrastText',
                        fontSize: '0.75rem'
                      }}
                    />
                  )}
                </Box>
                <Button
                  size="small"
                  variant="outlined"
                  color="warning"
                  startIcon={<Refresh />}
                  onClick={handleResetAllStats}
                  sx={{ minWidth: 'auto' }}
                >
                  Reset All
                </Button>
              </>
            ) : null;
          })()}
        </Box>
      </Box>

      {/* Configuration Info */}
      <Box sx={{
        mb: 3,
        p: 2,
        backgroundColor: config.lightBackgroundColor,
        borderRadius: 1,
        border: `1px solid ${config.borderColor}`
      }}>
        <Typography variant="body2" color="text.secondary">
          <strong>Current Configuration:</strong> {configInfo.usingCentroid ? 'Centroid CNC' : 'Simulator'} • 
          Base Path: {serviceConfig?.basePath || 'Not configured'}
        </Typography>
      </Box>

      {/* API Test Sections */}
      <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
        
        {/* System APIs */}
        <Accordion expanded={expandedPanel === 'system'} onChange={handleAccordionChange('system')}>
          <AccordionSummary expandIcon={<ExpandMore />}>
            <Typography variant="h6">System APIs</Typography>
          </AccordionSummary>
          <AccordionDetails>
            <SystemApiTests renderButton={renderStatsButton} />
          </AccordionDetails>
        </Accordion>

        {/* Setup APIs */}
        <Accordion expanded={expandedPanel === 'setup'} onChange={handleAccordionChange('setup')}>
          <AccordionSummary expandIcon={<ExpandMore />}>
            <Typography variant="h6">Setup APIs</Typography>
          </AccordionSummary>
          <AccordionDetails>
            <SetupApiTests renderButton={renderStatsButton} />
          </AccordionDetails>
        </Accordion>

        {/* Movement APIs */}
        <Accordion expanded={expandedPanel === 'movement'} onChange={handleAccordionChange('movement')}>
          <AccordionSummary expandIcon={<ExpandMore />}>
            <Typography variant="h6">Movement APIs</Typography>
          </AccordionSummary>
          <AccordionDetails>
            <MovementApiTests renderButton={renderStatsButton} />
          </AccordionDetails>
        </Accordion>

        {/* Spindle APIs */}
        <Accordion expanded={expandedPanel === 'spindle'} onChange={handleAccordionChange('spindle')}>
          <AccordionSummary expandIcon={<ExpandMore />}>
            <Typography variant="h6">Spindle APIs</Typography>
          </AccordionSummary>
          <AccordionDetails>
            <SpindleApiTests renderButton={renderStatsButton} />
          </AccordionDetails>
        </Accordion>

        {/* Program APIs */}
        <Accordion expanded={expandedPanel === 'program'} onChange={handleAccordionChange('program')}>
          <AccordionSummary expandIcon={<ExpandMore />}>
            <Typography variant="h6">Program APIs</Typography>
          </AccordionSummary>
          <AccordionDetails>
            <ProgramApiTests renderButton={renderStatsButton} />
          </AccordionDetails>
        </Accordion>

        {/* Features APIs */}
        <Accordion expanded={expandedPanel === 'features'} onChange={handleAccordionChange('features')}>
          <AccordionSummary expandIcon={<ExpandMore />}>
            <Typography variant="h6">Features APIs</Typography>
          </AccordionSummary>
          <AccordionDetails>
            <FeaturesApiTests renderButton={renderStatsButton} />
          </AccordionDetails>
        </Accordion>

        {/* I/O APIs */}
        <Accordion expanded={expandedPanel === 'io'} onChange={handleAccordionChange('io')}>
          <AccordionSummary expandIcon={<ExpandMore />}>
            <Typography variant="h6">I/O APIs</Typography>
          </AccordionSummary>
          <AccordionDetails>
            <IOApiTests renderButton={renderStatsButton} />
          </AccordionDetails>
        </Accordion>

      </Box>

      {/* API Input Dialog - Used for both parameterized and non-parameterized methods */}
      <ApiInputDialog
        open={inputDialogOpen}
        onClose={handleCloseInputDialog}
        title={inputDialogState.title}
        methodId={inputDialogState.methodName}
        defaultInputs={inputDialogState.defaultInputs}
        result={inputDialogState.result}
        error={inputDialogState.error || null}
        loading={inputDialogState.loading}
        executionTime={inputDialogState.executionTime}
        onExecute={executeInputApiCall}
        onResetStats={handleResetMethodStats}
      />
    </Box>
  );
}