import React from "react";
import {
  Box,
  Button,
  Typography,
} from '@mui/material';
import { WizardStep } from "../../../Wizard/WizardStep";
import { Wizard } from "../../../Wizard/Wizard";
import { TouchOffMethod, ZAxisReferenceType } from "../common/types";
import { getReferenceTitle } from "../common/utils";
import { ConfigurationData } from "../../../../data/ConfigurationData";

export class ZAxisMethodSelectionStep extends WizardStep {
  constructor(wizard: Wizard, priorStep: WizardStep | null = null) {
    super(wizard, priorStep);
  }

  getTitle(): string {
    return `Select Method - ${getReferenceTitle(this.wizard.state.referenceType)}`;
  }

  nextStep(): WizardStep | null {
    if (this.wizard.state.method === TouchOffMethod.TOUCHPLATE) {
      // For touchplate: Method Selection → Positioning → Test Touchplate
      const MaterialPositionCheckStep = require("./MaterialPositionCheckStep").MaterialPositionCheckStep;
      return new MaterialPositionCheckStep(this.wizard, this);
    } else if (this.wizard.state.method === TouchOffMethod.MANUAL) {
      // For manual: Method Selection → Instructions → Positioning → Jog Controls
      const InstructionsStep = require("./InstructionsStep").InstructionsStep;
      return new InstructionsStep(this.wizard, this);
    }
    return null; // Close wizard if no method selected
  }

  backStep(): WizardStep | null {
    return null; // This is typically the first step
  }

  render(): React.ReactNode {
    const handleMethodSelect = (method: TouchOffMethod) => {
      this.wizard.state.method = method;
      // Advance to the next step
      this.wizard.advanceToNextStep();
    };

    const getReferenceTitle = () => {
      switch (this.wizard.state.referenceType) {
        case ZAxisReferenceType.BED:
          return 'Machine Bed';
        case ZAxisReferenceType.SPOILBOARD:
          return 'Spoilboard';
        case ZAxisReferenceType.MATERIAL:
          return 'Material Surface';
        default:
          return 'Surface';
      }
    };

    return (
      <div style={{ height: '100%', display: 'flex', flexDirection: 'column' }}>
        <div style={{ flex: 1 }}>
          <Box sx={{ display: 'flex', flexDirection: 'column', height: '100%', justifyContent: 'center' }}>
            <Typography variant="h6" sx={{ mb: 4, textAlign: 'center' }}>
              We need to go through a few steps to locate the current Z offset for the {getReferenceTitle().toLowerCase()}. How would you like to do this?
            </Typography>
            
            <Box sx={{ display: 'flex', gap: 4, justifyContent: 'center', mb: 3 }}>
              <Button
                variant="outlined"
                size="large"
                sx={{ 
                  minWidth: '45%', 
                  minHeight: 300, 
                  fontSize: '1.2rem',
                  display: 'flex',
                  flexDirection: 'column',
                  gap: 2,
                  p: 3
                }}
                onClick={() => handleMethodSelect(TouchOffMethod.MANUAL)}
              >
                <Box sx={{ 
                  width: '100%', 
                  height: 150, 
                  backgroundColor: ConfigurationData.Instance.lightBackgroundColor, 
                  borderRadius: 1,
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center'
                }}>
                  <Typography variant="body2" color="text.secondary">
                    [Manual positioning icon]
                  </Typography>
                </Box>
                <Typography variant="h6">
                  Manual Positioning
                </Typography>
              </Button>

              <Button
                variant="outlined"
                size="large"
                sx={{ 
                  minWidth: '45%', 
                  minHeight: 300, 
                  fontSize: '1.2rem',
                  display: 'flex',
                  flexDirection: 'column',
                  gap: 2,
                  p: 3
                }}
                onClick={() => handleMethodSelect(TouchOffMethod.TOUCHPLATE)}
              >
                <Box sx={{ 
                  width: '100%', 
                  height: 150, 
                  backgroundColor: ConfigurationData.Instance.lightBackgroundColor, 
                  borderRadius: 1,
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center'
                }}>
                  <Typography variant="body2" color="text.secondary">
                    [Touch plate icon]
                  </Typography>
                </Box>
                <Typography variant="h6">
                  Use Touch Plate
                </Typography>
              </Button>
            </Box>
            
            <Box sx={{ textAlign: 'center' }}>
              <Button 
                variant="text" 
                sx={{ textDecoration: 'underline' }}
                onClick={() => window.open('https://example.com/z-axis-video', '_blank')}
              >
                Watch video on setting z axis
              </Button>
            </Box>
          </Box>
        </div>
      </div>
    );
  }
}
