import { Speed as SpindleIcon } from '@mui/icons-material';
import { Box, FormControl, Grid, InputLabel, MenuItem, Select, TextField, Typography } from '@mui/material';
import React, { useState } from 'react';
import { Machine } from '../../../../machine/Machine';
import { DataUtilities } from '../../../../utils/storage/DataUtilities';
import { FlowStep } from "../../../FlowStep";
import { FlowStepData } from "../../../FlowStepData";

export class SetSpindleSpeedStep extends FlowStep {
    readonly __type = 'SetSpindleSpeedStep';
    readonly category = ['Machine', 'Spindle'];
    readonly name = 'Set Spindle Speed';
    readonly description = 'Sets the spindle rotation speed in RPM';
    
    // Icon is created dynamically, not stored
    get icon(): React.ReactNode {
        return React.createElement(SpindleIcon, { sx: { color: 'primary.main' } });
    }

    // Step parameters
    public rpm: number = 1000;
    public waitForRamp: boolean = true;

    static readonly DONE_PATH = 'done';

    async execute(data: FlowStepData, prototypeRun: boolean): Promise<string | null> {
        if (prototypeRun) {
            return SetSpindleSpeedStep.DONE_PATH;
        }

        try {
            await Machine.getInstance().spindle.SetSpindleSpeed(this.rpm);
            return SetSpindleSpeedStep.DONE_PATH;
        } catch (error) {
            console.error('SetSpindleSpeed failed:', error);
            return SetSpindleSpeedStep.DONE_PATH; // Still done, just with error logged
        }
    }

    results(): string[] {
        return [SetSpindleSpeedStep.DONE_PATH];
    }

    renderResultsUI(data: FlowStepData, result: string): React.ReactNode {
        return (
            <Typography variant="caption">
                Set spindle to {this.rpm} RPM: {result}
            </Typography>
        );
    }

    renderEditUI(props: { onClose: () => void }): React.ReactNode {
        const EditUI: React.FC = () => {
            const [rpm, setRpm] = useState(this.rpm);
            const [waitForRamp, setWaitForRamp] = useState(this.waitForRamp);

            // Update the instance when the local state changes
            React.useEffect(() => {
                this.rpm = rpm;
                this.waitForRamp = waitForRamp;
            }, [rpm, waitForRamp]);

            return (
                <Box sx={{ p: 2, minWidth: 400 }}>
                    <Grid container spacing={2}>
                        <Grid item xs={12}>
                            <TextField
                                label="RPM"
                                type="number"
                                value={rpm}
                                onChange={(e) => setRpm(Number(e.target.value))}
                                fullWidth
                                size="small"
                                inputProps={{ min: 0, max: 24000 }}
                            />
                        </Grid>

                        <Grid item xs={12}>
                            <FormControl fullWidth size="small">
                                <InputLabel>Wait for Ramp</InputLabel>
                                <Select
                                    value={waitForRamp ? 'true' : 'false'}
                                    label="Wait for Ramp"
                                    onChange={(e) => setWaitForRamp(e.target.value === 'true')}
                                >
                                    <MenuItem value="true">Yes</MenuItem>
                                    <MenuItem value="false">No</MenuItem>
                                </Select>
                            </FormControl>
                        </Grid>
                    </Grid>

                    <Typography variant="caption" color="text.secondary" sx={{ mt: 2, display: 'block' }}>
                        Wait for ramp: Whether to wait for the spindle to reach the target speed before continuing.
                    </Typography>
                </Box>
            );
        };

        return React.createElement(EditUI);
    }

    public toJSON(): any {
        const data = DataUtilities.getStorageData(this, ['icon']) as any;
        data.__type = this.__type;
        return data;
    }

    public fromJSON(data: any): void {
        DataUtilities.loadStorageData(this, data);
    }
}





