import React from "react";
import { AutoBind } from "../AutoBind";
import { DataUtilities } from "./DataUtilities";
import { StateManager } from "./StateManager";

/**
 <ObserveState
 key="unique-component-identifier"
 listenTo={anobject}
 properties={['currentJob', 'selectedClampId']}
 control={() => {
        return (

        );
    }}
 />

 CRITICAL: Always provide a unique 'key' prop to prevent React reconciliation issues.
 Missing keys can cause components to not update properly when the component tree changes.

 **/

export class ObserveState extends React.Component<{
    key?: string; // RECOMMENDED: Unique identifier to prevent React reconciliation issues
    listenTo: object | null | undefined;
    control: () => React.JSX.Element | React.ReactNode;
    properties?: string[];
    onWillUnmount?: () => void;
}> {
    render() {
        return this.props.control();
    }

    componentDidMount() {
        if (this.props.listenTo) StateManager.addObserver(this.props.listenTo, this, this.props.properties || []);
    }

    componentDidUpdate(prevProps: {
        key?: string;
        listenTo: object | null | undefined;
        control: () => React.JSX.Element | React.ReactNode;
        properties?: string[];
        onWillUnmount?: () => void;
    }) {
        if (prevProps.listenTo !== this.props.listenTo) {
            if (prevProps.listenTo) StateManager.removeObserver(prevProps.listenTo, this);

            if (this.props.listenTo) StateManager.addObserver(this.props.listenTo, this, this.props.properties || []);
        }
    }

    componentWillUnmount() {
        if (this.props.listenTo) StateManager.removeObserver(this.props.listenTo, this);

        if (this.props.onWillUnmount) {
            this.props.onWillUnmount();
        }
    }

    @AutoBind
    update() {
        this.setState({ key: DataUtilities.generateUniqueId() });
        this.forceUpdate();
    }
}
