import { ICNCIO, InputMapping, OutputMapping } from '../machine/ICNCIO';
import { CNCIOApi } from '../services/src/apis/CNCIOApi';
import { SetOutputRequest } from '../services/src/models';
import { LogCategory, Logger } from '../utils/Logger';
import { MachineInterfaceManager } from '../utils/MachineInterfaceManager';

export class CentroidCNCIO implements ICNCIO {
  private readonly api: CNCIOApi;
  private readonly basePath: string;
  private inputDefinitionsCache: InputMapping[] | null = null;
  private outputDefinitionsCache: OutputMapping[] | null = null;

  constructor() {
    const config = MachineInterfaceManager.Instance.getServiceConfiguration();
    Logger.Instance.log(LogCategory.System, `CentroidCNCIO: Using shared service configuration:`, config);

    this.basePath = config?.basePath || '';
    this.api = new CNCIOApi(config || undefined);
  }

  async GetCurrentInputs(): Promise<Record<number, boolean>> {
    try {
      const response = await this.api.apiCNCIOGetCurrentInputsGetRaw();
      const inputStates = await response.value();
      Logger.Instance.log(LogCategory.System, 'GetCurrentInputs: Received input states', inputStates);

      // Convert string keys to number keys and return the inputs dictionary
      const result: Record<number, boolean> = {};
      if (inputStates && typeof inputStates === 'object') {
        Object.entries(inputStates).forEach(([key, value]) => {
          const numKey = parseInt(key, 10);
          if (!isNaN(numKey)) {
            result[numKey] = value;
          }
        });
      }

      return result;
    } catch (error) {
      Logger.Instance.logError(LogCategory.System, 'Failed to get current inputs:', error);
      throw error;
    }
  }

  async GetCurrentOutputs(): Promise<Record<number, boolean>> {
    try {
      const response = await this.api.apiCNCIOGetCurrentOutputsGetRaw();
      const outputStates = await response.value();
      Logger.Instance.log(LogCategory.System, 'GetCurrentOutputs: Received output states', outputStates);

      // Convert string keys to number keys and return the outputs dictionary
      const result: Record<number, boolean> = {};
      if (outputStates && typeof outputStates === 'object') {
        Object.entries(outputStates).forEach(([key, value]) => {
          const numKey = parseInt(key, 10);
          if (!isNaN(numKey)) {
            result[numKey] = value;
          }
        });
      }

      return result;
    } catch (error) {
      Logger.Instance.logError(LogCategory.System, 'Failed to get current outputs:', error);
      throw error;
    }
  }

  async GetAvailableInputs(): Promise<Record<number, string>> {
    try {
      Logger.Instance.log(LogCategory.System, 'GetAvailableInputs: Starting API call...');
      Logger.Instance.log(LogCategory.System, 'GetAvailableInputs: API instance:', this.api);

      // Log the actual URL that will be called
      const fullUrl = `${this.basePath}/api/CNCIO/GetAvailableInputs`;
      Logger.Instance.log(LogCategory.System, `GetAvailableInputs: Full URL: ${fullUrl}`);

      const response = await this.api.apiCNCIOGetAvailableInputsGetRaw();
      Logger.Instance.log(LogCategory.System, 'GetAvailableInputs: Raw response received', response);
      Logger.Instance.log(LogCategory.System, 'GetAvailableInputs: Response status:', response.raw.status);
      Logger.Instance.log(LogCategory.System, 'GetAvailableInputs: Response headers:', response.raw.headers);

      // Let's also check what the response body actually contains
      try {
        const responseText = await response.raw.clone().text();
        Logger.Instance.log(LogCategory.System, 'GetAvailableInputs: Response body text (first 200 chars):', responseText.substring(0, 200));
      } catch (textError) {
        Logger.Instance.logError(LogCategory.System, 'GetAvailableInputs: Could not read response text:', textError);
      }

      Logger.Instance.log(LogCategory.System, 'GetAvailableInputs: About to call response.value()...');
      const inputNumbers = await response.value(); // Use the typed value() method
      Logger.Instance.log(LogCategory.System, 'GetAvailableInputs: Received input numbers', inputNumbers);
      Logger.Instance.log(LogCategory.System, 'GetAvailableInputs: Input numbers type:', typeof inputNumbers);
      Logger.Instance.log(LogCategory.System, 'GetAvailableInputs: Is array:', Array.isArray(inputNumbers));

      // Transform array of numbers into Record<number, string>
      const result: Record<number, string> = {};
      if (inputNumbers && Array.isArray(inputNumbers)) {
        inputNumbers.forEach(num => {
          result[num] = `Input ${num}`;
        });
      }

      Logger.Instance.log(LogCategory.System, 'GetAvailableInputs: Returning result', result);
      return result;
    } catch (error) {
      Logger.Instance.logError(LogCategory.System, 'Failed to get available inputs - Error details:', error);
      Logger.Instance.logError(LogCategory.System, 'Error type:', typeof error);
      Logger.Instance.logError(LogCategory.System, 'Error constructor:', error?.constructor?.name);
      Logger.Instance.logError(LogCategory.System, 'Error message:', error?.message || 'No message');
      Logger.Instance.logError(LogCategory.System, 'Error stack:', error?.stack || 'No stack');

      // If it's a fetch error, let's try to get more details
      if (error?.response) {
        Logger.Instance.logError(LogCategory.System, 'Error response status:', error.response.status);
        Logger.Instance.logError(LogCategory.System, 'Error response statusText:', error.response.statusText);
        try {
          const errorText = await error.response.text();
          Logger.Instance.logError(LogCategory.System, 'Error response body:', errorText);
        } catch (e) {
          Logger.Instance.logError(LogCategory.System, 'Could not read error response body:', e);
        }
      }

      throw error;
    }
  }

  async GetAvailableOutputs(): Promise<Record<number, string>> {
    try {
      const response = await this.api.apiCNCIOGetAvailableOutputsGetRaw();
      const outputNumbers = await response.value(); // Use the typed value() method
      Logger.Instance.log(LogCategory.System, 'GetAvailableOutputs: Received output numbers', outputNumbers);

      // Transform array of numbers into Record<number, string>
      const result: Record<number, string> = {};
      if (outputNumbers && Array.isArray(outputNumbers)) {
        outputNumbers.forEach(num => {
          result[num] = `Output ${num}`;
        });
      }

      return result;
    } catch (error) {
      Logger.Instance.logError(LogCategory.System, 'Failed to get available outputs:', error);
      throw error;
    }
  }

  async GetInputDefinitions(): Promise<InputMapping[]> {
    // Return cached result if available
    if (this.inputDefinitionsCache !== null) {
      Logger.Instance.log(LogCategory.System, 'GetInputDefinitions: Returning cached definitions');
      return this.inputDefinitionsCache;
    }

    try {
      // Get I/O definitions from the API (name and number from Centroid PLC source)
      const response = await this.api.apiCNCIOGetIODefinitionsGet({ sourcePath: undefined });

      if (!response.inputs) {
        Logger.Instance.log(LogCategory.System, 'GetInputDefinitions: No inputs found');
        this.inputDefinitionsCache = [];
        return [];
      }

      // Map API IODefinition to our InputMapping interface
      const result: InputMapping[] = response.inputs.map(input => ({
        number: input.number ?? 0,
        centroidName: input.name ?? ''  // Centroid name is the name from API
      }));

      // Cache the result
      this.inputDefinitionsCache = result;
      Logger.Instance.log(LogCategory.System, 'GetInputDefinitions: Retrieved and cached definitions', result);
      return result;
    } catch (error) {
      Logger.Instance.logError(LogCategory.System, 'Failed to get input definitions:', error);
      throw error;
    }
  }

  async GetOutputDefinitions(): Promise<OutputMapping[]> {
    // Return cached result if available
    if (this.outputDefinitionsCache !== null) {
      Logger.Instance.log(LogCategory.System, 'GetOutputDefinitions: Returning cached definitions');
      return this.outputDefinitionsCache;
    }

    try {
      // Get I/O definitions from the API (name and number from Centroid PLC source)
      const response = await this.api.apiCNCIOGetIODefinitionsGet({ sourcePath: undefined });

      if (!response.outputs) {
        Logger.Instance.log(LogCategory.System, 'GetOutputDefinitions: No outputs found');
        this.outputDefinitionsCache = [];
        return [];
      }

      // Map API IODefinition to our OutputMapping interface
      const result: OutputMapping[] = response.outputs.map(output => ({
        number: output.number ?? 0,
        centroidName: output.name ?? ''  // Centroid name is the name from API
      }));

      // Cache the result
      this.outputDefinitionsCache = result;
      Logger.Instance.log(LogCategory.System, 'GetOutputDefinitions: Retrieved and cached definitions', result);
      return result;
    } catch (error) {
      Logger.Instance.logError(LogCategory.System, 'Failed to get output definitions:', error);
      throw error;
    }
  }

  async GetIOAvailability(): Promise<Record<string, boolean>> {
    try {
      // Since GetIOAvailability endpoint no longer exists, we'll combine the available inputs and outputs
      const [availableInputs, availableOutputs] = await Promise.all([
        this.GetAvailableInputs(),
        this.GetAvailableOutputs()
      ]);

      const result: Record<string, boolean> = {};

      // Add inputs to availability map
      Object.keys(availableInputs).forEach(inputNum => {
        result[`input_${inputNum}`] = true;
      });

      // Add outputs to availability map
      Object.keys(availableOutputs).forEach(outputNum => {
        result[`output_${outputNum}`] = true;
      });

      Logger.Instance.log(LogCategory.System, 'GetIOAvailability: Combined availability', result);
      return result;
    } catch (error) {
      Logger.Instance.logError(LogCategory.System, 'Failed to get IO availability:', error);
      throw error;
    }
  }

  async GetSystemInfo(): Promise<Record<string, any>> {
    try {
      const response = await this.api.apiCNCIOGetSystemInfoGetRaw();
      const systemInfo = await response.value();
      Logger.Instance.log(LogCategory.System, 'GetSystemInfo: Response received', systemInfo);

      // Try to parse the string response as JSON, or return it as a simple object
      try {
        if (typeof systemInfo === 'string') {
          const parsed = JSON.parse(systemInfo);
          return parsed;
        } else if (typeof systemInfo === 'object') {
          return systemInfo;
        } else {
          return { info: systemInfo };
        }
      } catch (parseError) {
        // If JSON parsing fails, return the string as a property
        return { systemInfo: systemInfo };
      }
    } catch (error) {
      Logger.Instance.logError(LogCategory.System, 'Failed to get system info:', error);
      throw error;
    }
  }

  async IsInputActive(inputNumber: number): Promise<boolean> {
    try {
      const response = await this.api.apiCNCIOIsInputActiveInputNumberGetRaw({ inputNumber });
      const isActive = await response.value();
      Logger.Instance.log(LogCategory.System, 'IsInputActive: Response received', isActive);
      return isActive ?? false;
    } catch (error) {
      Logger.Instance.logError(LogCategory.System, 'Failed to check input status:', error);
      throw error;
    }
  }

  async IsOutputActive(outputNumber: number): Promise<boolean> {
    try {
      const response = await this.api.apiCNCIOIsOutputActiveOutputNumberGetRaw({ outputNumber });
      const isActive = await response.value();
      Logger.Instance.log(LogCategory.System, 'IsOutputActive: Response received', isActive);
      return isActive ?? false;
    } catch (error) {
      Logger.Instance.logError(LogCategory.System, 'Failed to check output status:', error);
      throw error;
    }
  }

  async IsInputAvailable(inputNumber: number): Promise<boolean> {
    try {
      const response = await this.api.apiCNCIOIsInputAvailableInputNumberGetRaw({ inputNumber });
      const isAvailable = await response.value();
      Logger.Instance.log(LogCategory.System, `IsInputAvailable: Input ${inputNumber} availability:`, isAvailable);
      return isAvailable ?? false;
    } catch (error) {
      // If the call fails, the input is not available
      Logger.Instance.log(LogCategory.System, `IsInputAvailable: Input ${inputNumber} is not available (error occurred)`);
      return false;
    }
  }

  async IsOutputAvailable(outputNumber: number): Promise<boolean> {
    try {
      const response = await this.api.apiCNCIOIsOutputAvailableOutputNumberGetRaw({ outputNumber });
      const isAvailable = await response.value();
      Logger.Instance.log(LogCategory.System, `IsOutputAvailable: Output ${outputNumber} availability:`, isAvailable);
      return isAvailable ?? false;
    } catch (error) {
      // If the call fails, the output is not available
      Logger.Instance.log(LogCategory.System, `IsOutputAvailable: Output ${outputNumber} is not available (error occurred)`);
      return false;
    }
  }

  async SetOutputState(outputNumber: number, state: boolean): Promise<void> {
    try {
      const request: SetOutputRequest = {
        number: outputNumber,
        value: state
      };
      await this.api.apiCNCIOSetOutputStatePost({ setOutputRequest: request });
      Logger.Instance.log(LogCategory.System, `Set output ${outputNumber} to ${state}`);
    } catch (error) {
      Logger.Instance.logError(LogCategory.System, 'Failed to set output state:', error);
      throw error;
    }
  }
}
