import React from 'react';
import { SimulatorView } from '../../data/Common/SimulatorView';
import { ViewStyle } from '../../data/Common/ViewStyle';
import { Job } from '../../data/Job';
import { MachineData } from '../../data/MachineData';
import { MachineStateData } from '../../data/MachineStateData';
import { ObserveState } from '../../utils/statemanager/ObserveState';
import { ATC, Clamps, DragLine, Gantry, MachineBed, MachineHome, MachinePositionedTool, MachineZeroCrosshair, Material, Rotary, SoftLimitsBox, Spindle, SpoilBoard, Toolpaths, VerticalTable, WorkHomeIndicator } from './components';
import { SimulatorOrigin } from './components/SimulatorOrigin';

export interface CNCMachineProps {
  simulatorView: SimulatorView;
  machineState: MachineStateData;
  machineData: MachineData;
  job?: Job; // Optional job - can be null, only use what's passed in
  orbitControlsRef?: React.RefObject<any>;
  enableClampDragging?: boolean;
  enableSpindleDrag?: boolean;
  isTopDownView?: () => boolean;
}

export function CNCMachine({
  simulatorView,
  machineState,
  machineData,
  job, // Optional job override
  orbitControlsRef,
  enableClampDragging = false,
  enableSpindleDrag = true,
  isTopDownView
}: CNCMachineProps) {
  return (
    <ObserveState
      listenTo={simulatorView}
      properties={[
        'workHome', 'toolpaths', 'softLimits', 'machineZero', 'machineHome',
        'gantry', 'base', 'spindle', 'bed', 'spoilBoard', 'material', 'workPiece', 'clamps', 'tool',
        'rotary', 'verticalTable', 'laser', 'laserPointer', 'drillHead', 'atc'
      ]}
      control={() => (
        <group rotation={[0, 0, 0]}>
          {/* DEBUG: Simulator Origin Marker */}
          <SimulatorOrigin />

          {/* Machine Bed - Always render as it contains both base and bed with separate controls */}
          <MachineBed
            simulatorView={simulatorView}
            machineData={machineData}
          />

          {/* Gantry */}
          {simulatorView.gantry !== ViewStyle.Hide && (
            <Gantry
              simulatorView={simulatorView}
              machineData={machineData}
              machineState={machineState}
            />
          )}

          {/* Spindle */}
          {simulatorView.spindle !== ViewStyle.Hide && (
            <Spindle
              simulatorView={simulatorView}
              machineState={machineState}
              machineData={machineData}
              orbitControlsRef={orbitControlsRef}
              enableSpindleDrag={enableSpindleDrag}
              isTopDownView={isTopDownView}
            />
          )}

          {/* Spoil Board */}
          {simulatorView.spoilBoard !== ViewStyle.Hide && (
            <SpoilBoard
              simulatorView={simulatorView}
              machineState={machineState}
              machineData={machineData}
            />
          )}

          {/* Material */}
          {simulatorView.material !== ViewStyle.Hide && (
            <Material
              simulatorView={simulatorView}
              machineState={machineState}
              machineData={machineData}
              job={job}
            />
          )}

          {/* Clamps */}
          {simulatorView.clamps !== ViewStyle.Hide && (
            <Clamps
              simulatorView={simulatorView}
              machineState={machineState}
              machineData={machineData}
              job={job}
              enableClampDragging={enableClampDragging}
              orbitControlsRef={orbitControlsRef}
            />
          )}

          {/* Tool at Machine Position */}
          {simulatorView.tool !== ViewStyle.Hide && (
            <MachinePositionedTool
              simulatorView={simulatorView}
              machineState={machineState}
              machineData={machineData}
            />
          )}

          {/* Work Home Indicator */}
          {simulatorView.workHome && (
            <WorkHomeIndicator
              simulatorView={simulatorView}
              machineState={machineState}
            />
          )}

          {/* Toolpaths */}
          {simulatorView.toolpaths && (
            <Toolpaths
              simulatorView={simulatorView}
              machineState={machineState}
              machineData={machineData}
              job={job}
            />
          )}

          {/* Soft Limits */}
          {simulatorView.softLimits && (
            <SoftLimitsBox
              simulatorView={simulatorView}
              machineData={machineData}
            />
          )}

          {/* Machine Zero Crosshair */}
          {simulatorView.machineZero && (
            <MachineZeroCrosshair />
          )}

          {/* Machine Home */}
          {simulatorView.machineHome && (
            <MachineHome />
          )}

          {/* Optional Machine Elements - only render if enabled in MachineData */}

          {/* Rotary Axis */}
          {simulatorView.rotary !== ViewStyle.Hide && machineData.rotaryAxis !== 'None' && (
            <Rotary simulatorView={simulatorView} />
          )}

          {/* Vertical Table */}
          {simulatorView.verticalTable !== ViewStyle.Hide && machineData.hasVerticalTable && (
            <VerticalTable simulatorView={simulatorView} />
          )}

          {/* Laser */}
          {simulatorView.laser !== ViewStyle.Hide && machineData.hasLaser && (
            // TODO: Implement Laser component
            // <Laser
            //   simulatorView={simulatorView}
            //   machineState={machineState}
            //   machineData={machineData}
            // />
            null // Placeholder until Laser component is implemented
          )}

          {/* Laser Pointer */}
          {simulatorView.laserPointer !== ViewStyle.Hide && machineData.hasLaserPointer && (
            // TODO: Implement LaserPointer component
            // <LaserPointer
            //   simulatorView={simulatorView}
            //   machineState={machineState}
            //   machineData={machineData}
            // />
            null // Placeholder until LaserPointer component is implemented
          )}

          {/* Drill Head */}
          {simulatorView.drillHead !== ViewStyle.Hide && machineData.hasDrillHead && (
            // TODO: Implement DrillHead component
            // <DrillHead
            //   simulatorView={simulatorView}
            //   machineState={machineState}
            //   machineData={machineData}
            // />
            null // Placeholder until DrillHead component is implemented
          )}

          {/* ATC (Automatic Tool Changer) */}
          {simulatorView.atc !== ViewStyle.Hide && machineData.hasATC && (
            <ATC simulatorView={simulatorView} />
          )}

          {/* Drag Line - shows path from current to proposed position during drag */}
          <DragLine machineState={machineState} />
        </group>
      )}
    />
  );
}
