import React from 'react';
import { CNCPoint } from '../../../data/CNCPoint';
import { CoordinateType } from '../../../data/Common/CoordinateType';
import { SimulatorView } from '../../../data/Common/SimulatorView';
import { ViewStyle } from '../../../data/Common/ViewStyle';
import { ConfigurationData } from '../../../data/ConfigurationData';
import { MachineData } from '../../../data/MachineData';
import { MachineStateData } from '../../../data/MachineStateData';
import { ActionBus } from '../../../utils/actions/ActionBus';
import { MoveAction, MoveType } from '../../../utils/actions/MoveAction';
import { CoordinateUtil } from '../../../utils/CoordinateUtil';
import { ObserveMultiProperties } from '../../../utils/statemanager/ObserveMultiProperties';
import { Box } from './Box';

export interface SpoilBoardProps {
  simulatorView: SimulatorView;
  machineState: MachineStateData;
  machineData: MachineData;
}

export const SpoilBoard: React.FC<SpoilBoardProps> = ({
  simulatorView,
  machineState,
  machineData
}) => {
  // Get configuration colors
  const config = ConfigurationData.Instance;

  // State for tracking which sphere is hovered
  const [hoveredSphere, setHoveredSphere] = React.useState<number | null>(null);

  return (
    <ObserveMultiProperties
      listenTo={[
        { object: simulatorView, properties: ['spoilBoard'] },
        { object: machineState, properties: [] },
        { object: ConfigurationData.Instance, properties: ['spoilboardTransparency', 'spoilBoardColor'] }
      ]}
      control={() => {
        const spoilBoardWidth = machineState.spoilBoardWidth;
        const spoilBoardLength = machineState.spoilBoardYLength;
        const spoilBoardHeight = machineState.spoilBoardHeight;
        const spoilBoardX = machineState.spoilboardX;
        const spoilBoardY = machineState.spoilboardY;

        // Use centralized spoilboard box for dimensions and positioning
        const spoilboardBox = CoordinateUtil.getSpoilboardBox(machineState);

        // Convert origin to simulator coordinates first, then add half dimensions for center
        const spoilBoardOriginSim = CoordinateUtil.toSimulator(spoilboardBox.origin);
        const spoilBoardPosition = new CNCPoint(
          spoilBoardOriginSim.x + spoilboardBox.width / 2,
          spoilBoardOriginSim.y + spoilboardBox.length / 2,
          spoilBoardOriginSim.z + spoilboardBox.height / 2,
          CoordinateType.Simulator
        );

        // Target sphere positions: corners, edges, center
        // Calculate positions in MachineZero coordinates, then convert to Simulator
        const spoilboardTopZ = spoilboardBox.origin.z + spoilboardBox.height;
        const spoilboardMinX = spoilboardBox.origin.x;
        const spoilboardMaxX = spoilboardBox.origin.x + spoilboardBox.width;
        const spoilboardMinY = spoilboardBox.origin.y;
        const spoilboardMaxY = spoilboardBox.origin.y + spoilboardBox.length;
        const spoilboardCenterX = spoilboardBox.origin.x + spoilboardBox.width / 2;
        const spoilboardCenterY = spoilboardBox.origin.y + spoilboardBox.length / 2;

        // Define CNCPoint positions for corners, edges, center (in MachineZero coordinates)
        const spherePositions = [
          // Corners
          new CNCPoint(spoilboardMinX, spoilboardMinY, spoilboardTopZ, CoordinateType.MachineZero), // Front Left
          new CNCPoint(spoilboardMaxX, spoilboardMinY, spoilboardTopZ, CoordinateType.MachineZero), // Front Right
          new CNCPoint(spoilboardMinX, spoilboardMaxY, spoilboardTopZ, CoordinateType.MachineZero), // Back Left
          new CNCPoint(spoilboardMaxX, spoilboardMaxY, spoilboardTopZ, CoordinateType.MachineZero), // Back Right
          // Edges
          new CNCPoint(spoilboardCenterX, spoilboardMinY, spoilboardTopZ, CoordinateType.MachineZero), // Front Center
          new CNCPoint(spoilboardCenterX, spoilboardMaxY, spoilboardTopZ, CoordinateType.MachineZero), // Back Center
          new CNCPoint(spoilboardMinX, spoilboardCenterY, spoilboardTopZ, CoordinateType.MachineZero), // Left Center
          new CNCPoint(spoilboardMaxX, spoilboardCenterY, spoilboardTopZ, CoordinateType.MachineZero), // Right Center
          // Center
          new CNCPoint(spoilboardCenterX, spoilboardCenterY, spoilboardTopZ, CoordinateType.MachineZero), // Center
        ];

        // Handler to move machine to target sphere location
        const handleTargetClick = (x: number, y: number) => {
          // Keep current Z position unchanged
          const currentZ = machineState.currentMachinePoint.z;
          // Create and execute move action - only change X and Y, use same coordinate type as current point
          const moveAction = new MoveAction(machineState.currentMachinePoint.coordinateType, x, y, currentZ, undefined, MoveType.Coordinates);
          ActionBus.Instance.addAction(moveAction);
        };

        return (
          <>
            <Box
              position={[spoilBoardPosition.x, spoilBoardPosition.y, spoilBoardPosition.z]}
              size={[spoilboardBox.width, spoilboardBox.length, spoilboardBox.height]}
              color={config.spoilBoardColor}
              viewStyle={simulatorView.spoilBoard}
              opacity={simulatorView.spoilBoard === ViewStyle.SemiTransparent ? config.spoilboardTransparency : 1}
            />
            {spherePositions.map((pos, idx) => {
              // Convert to simulator coordinates
              const sim = CoordinateUtil.toSimulator(pos);
              const isHovered = hoveredSphere === idx;
              return (
                <mesh
                  key={idx}
                  position={[sim.x, sim.y, sim.z]}
                  onClick={() => handleTargetClick(pos.x, pos.y)}
                  onPointerOver={() => setHoveredSphere(idx)}
                  onPointerOut={() => setHoveredSphere(null)}
                  castShadow
                  receiveShadow
                >
                  <sphereGeometry args={[ConfigurationData.Instance.targetSphereSize, 16, 16]} />
                  <meshStandardMaterial
                    color={isHovered ? config.highlightColor : config.mutedTextColor}
                    transparent={true}
                    opacity={isHovered ? 1.0 : 0.0}
                  />
                </mesh>
              );
            })}
          </>
        );
      }}
    />
  );
};
