import { Wizard } from "../../../Wizard/Wizard";
import { WizardStep } from "../../../Wizard/WizardStep";
import { SpindlePositionStep } from "../../SpindlePositionStep";
import { ZAxisReferenceType } from '../common/types';

export class ManualPositionStep extends SpindlePositionStep {
  constructor(wizard: Wizard, priorStep: WizardStep | null = null) {
    const referenceType = wizard.state.referenceType;
    let title = "Position Spindle";
    let instructions = "Position the tool where you want to set the Z reference.";
    
    switch (referenceType) {
      case ZAxisReferenceType.BED:
        title = "Position Spindle Over Machine Bed";
        instructions = "Position the tool over the machine bed where you want to set the Z reference. Use the jog controls or drag the spindle in the 3D view to move to the desired location.";
        break;
      case ZAxisReferenceType.SPOILBOARD:
        title = "Position Spindle Over Spoilboard";
        instructions = "Position the tool over the spoilboard where you want to set the Z reference. Use the jog controls or drag the spindle in the 3D view to move to the desired location.";
        break;
      case ZAxisReferenceType.MATERIAL:
        title = "Position Spindle Over Material";
        instructions = "Position the tool over the material surface where you want to set the Z reference. Use the jog controls or drag the spindle in the 3D view to move to the desired location on the material.";
        break;
    }

    super(wizard, priorStep, {
      nextStepFactory: () => {
        // Import here to avoid circular dependency
        const { JogControlsStep } = require('./JogControlsStep');
        return new JogControlsStep(wizard, this);
      },
      title,
      instructions
    });
  }
}
