import { Speed as SpeedIcon } from '@mui/icons-material';
import { Typography } from '@mui/material';
import React from 'react';
import { Machine } from '../../../../machine/Machine';
import { DataUtilities } from '../../../../utils/storage/DataUtilities';
import { FlowStep } from "../../../FlowStep";
import { FlowStepData } from "../../../FlowStepData";

export class GetSpindleSpeedStep extends FlowStep {
    readonly __type = 'GetSpindleSpeedStep';
    readonly category = ['Machine', 'Spindle'];
    readonly name = 'Get Spindle Speed';
    readonly description = 'Gets the current spindle speed';
    
    // Icon is created dynamically, not stored
    get icon(): React.ReactNode {
        return React.createElement(SpeedIcon, { sx: { color: 'info.main' } });
    }
    static readonly SUCCESS_PATH = 'success';
    async execute(data: FlowStepData, prototypeRun: boolean): Promise<string | null> {
        if (prototypeRun) {
            return GetSpindleSpeedStep.SUCCESS_PATH;
        }

        try {
            const speed = await Machine.getInstance().spindle.GetSpindleSpeed();
            data.setVariable('spindleSpeed', speed);
            return GetSpindleSpeedStep.SUCCESS_PATH;
        } catch (error) {
            console.error('GetSpindleSpeed failed:', error);
            // Still return success with fallback value - the step completed its attempt
            data.setVariable('spindleSpeed', 0);
            return GetSpindleSpeedStep.SUCCESS_PATH;
        }
    }

    results(): string[] {
        return [GetSpindleSpeedStep.SUCCESS_PATH];
    }

    renderResultsUI(data: FlowStepData, result: string): React.ReactNode {
        const speed = data.getVariable('spindleSpeed');
        return (
            <Typography variant="caption">
                Get spindle speed: {result}
                {speed !== undefined && ` (${speed} RPM)`}
            </Typography>
        );
    }

    public toJSON(): any {
        const data = DataUtilities.getStorageData(this, ['icon']) as any;
        data.__type = this.__type;
        return data;
    }

    public fromJSON(data: any): void {
        DataUtilities.loadStorageData(this, data);
    }
}






