import { UserMessageQueue } from '../data/UserMessageQueue';
import { ICNCSpindle } from '../machine/ICNCSpindle';

export class SimulatorCNCSpindle implements ICNCSpindle {
  private spindleRunning: boolean = false;
  private spindleSpeedFactor: number = 0;
  private currentSpeed: number = 0;

  async WarmUpSpindle(): Promise<void> {
    UserMessageQueue.Instance.addMessage('✓ Spindle warm-up started');
    await new Promise(resolve => setTimeout(resolve, 2000));
    UserMessageQueue.Instance.addMessage('✓ Spindle warm-up complete');
  }

  async GetSpindleSpeed(): Promise<number> {
    return this.currentSpeed;
  }

  async SetSpindleSpeed(speed: number): Promise<void> {
    this.currentSpeed = speed;
    UserMessageQueue.Instance.addMessage(`✓ Set spindle speed to ${speed} RPM`);
  }

  async AdjustSpindleSpeed(factor: number): Promise<void> {
    this.spindleSpeedFactor = factor;
    UserMessageQueue.Instance.addMessage(`✓ Adjusted spindle speed by ${factor}%`);
  }

  async GetCurrentSpindleSpeedFactor(): Promise<number> {
    return this.spindleSpeedFactor;
  }

  async ResetSpindleSpeedFactor(): Promise<void> {
    this.spindleSpeedFactor = 0;
    UserMessageQueue.Instance.addMessage(`✓ Reset spindle speed factor`);
  }

  async StartSpindle(speed?: number): Promise<void> {
    this.spindleRunning = true;
    if (speed !== undefined) {
      this.currentSpeed = speed;
      UserMessageQueue.Instance.addMessage(`✓ Started spindle at ${speed} RPM`);
    } else {
      UserMessageQueue.Instance.addMessage(`✓ Started spindle at ${this.currentSpeed || 'default'} RPM`);
    }
  }

  async StopSpindle(): Promise<void> {
    this.spindleRunning = false;
    UserMessageQueue.Instance.addMessage('✓ Stopped spindle');
  }

  async IsSpindleRunning(): Promise<boolean> {
    return this.spindleRunning;
  }
}
