import { Box, LinearProgress, Switch, Typography } from '@mui/material';
import { ConfigurationData } from '../../data/ConfigurationData';
import { ConfigurationState } from '../../data/ConfigurationState';
import { ObserveMultiProperties } from '../../utils/statemanager/ObserveMultiProperties';

interface SafeModeControlProps {
    variant?: 'compact' | 'full'; // compact for Home view, full for ControlPanel
}

export function SafeModeControl({ variant = 'full' }: SafeModeControlProps) {
    const configState = ConfigurationState.Instance;
    const configData = ConfigurationData.Instance;

    // Format time for display
    const formatTime = (ms: number) => {
        const seconds = Math.ceil(ms / 1000);
        const mins = Math.floor(seconds / 60);
        const secs = seconds % 60;
        return mins > 0 ? `${mins}:${secs.toString().padStart(2, '0')}` : `${secs}s`;
    };

    // Format timeout setting for display
    const formatTimeoutSetting = (ms: number) => {
        const seconds = ms / 1000;
        const mins = Math.floor(seconds / 60);
        const remainingSecs = seconds % 60;
        if (mins > 0) {
            return remainingSecs > 0 ? `${mins}m ${remainingSecs}s` : `${mins}m`;
        }
        return `${seconds}s`;
    };

    return (
        <ObserveMultiProperties
            key="safe-mode-control"
            listenTo={[
                { object: configState, properties: ['delayOff', 'collisionOff', 'softLimitsOff', 'safeModeRemainingTime'] }
            ]}
            control={() => {
                const isAnyModeOff = configState.isSafeModeActive;
                const remainingTime = configState.safeModeRemainingTime;
                const totalTime = configData.safeModeTimeout;

                // Calculate progress for progress bar (0-100)
                const progress = isAnyModeOff ? ((totalTime - remainingTime) / totalTime) * 100 : 0;

                return (
                    <Box
                        sx={{
                            mb: 2,
                            mt: 2,
                            p: 2,
                            border: isAnyModeOff ? 3 : 1,
                            borderColor: isAnyModeOff ? 'warning.main' : 'divider',
                            borderRadius: 1,
                            position: 'relative'
                        }}
                    >
                        {/* Label on border */}
                        <Typography
                            variant="body2"
                            sx={{
                                position: 'absolute',
                                top: -8,
                                left: 8,
                                backgroundColor: 'background.paper',
                                px: 0.5,
                                color: isAnyModeOff ? 'warning.main' : 'text.secondary',
                                fontSize: '0.75rem',
                                fontWeight: isAnyModeOff ? 'bold' : 'normal'
                            }}
                        >
                            Safe Mode {isAnyModeOff ? '(DISABLED)' : ''}
                        </Typography>

                        {/* Safety toggles in one line */}
                        <Box sx={{ display: 'flex', flexDirection: 'row', gap: 2, justifyContent: 'space-between', mb: isAnyModeOff ? 2 : 0 }}>
                            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                                <Typography
                                    variant="body2"
                                    sx={{ color: configState.delayOff ? 'warning.main' : 'text.primary' }}
                                >
                                    Delays
                                </Typography>
                                <Switch
                                    checked={!configState.delayOff}
                                    onChange={(e) => (configState.delayOff = !e.target.checked)}
                                    size="small"
                                    color={configState.delayOff ? 'warning' : 'success'}
                                    sx={{
                                        '& .MuiSwitch-track': {
                                            backgroundColor: configState.delayOff ? configData.warningColor : undefined,
                                            opacity: configState.delayOff ? 0.8 : undefined
                                        },
                                        '& .MuiSwitch-thumb': {
                                            color: configState.delayOff ? '#fff' : undefined
                                        }
                                    }}
                                />
                            </Box>

                            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                                <Typography
                                    variant="body2"
                                    sx={{ color: configState.collisionOff ? 'warning.main' : 'text.primary' }}
                                >
                                    Collisions
                                </Typography>
                                <Switch
                                    checked={!configState.collisionOff}
                                    onChange={(e) => (configState.collisionOff = !e.target.checked)}
                                    size="small"
                                    color={configState.collisionOff ? 'warning' : 'success'}
                                    sx={{
                                        '& .MuiSwitch-track': {
                                            backgroundColor: configState.collisionOff ? configData.warningColor : undefined,
                                            opacity: configState.collisionOff ? 0.8 : undefined
                                        },
                                        '& .MuiSwitch-thumb': {
                                            color: configState.collisionOff ? '#fff' : undefined
                                        }
                                    }}
                                />
                            </Box>

                            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                                <Typography
                                    variant="body2"
                                    sx={{ color: configState.softLimitsOff ? 'warning.main' : 'text.primary' }}
                                >
                                    Soft Limits
                                </Typography>
                                <Switch
                                    checked={!configState.softLimitsOff}
                                    onChange={(e) => (configState.softLimitsOff = !e.target.checked)}
                                    size="small"
                                    color={configState.softLimitsOff ? 'warning' : 'success'}
                                    sx={{
                                        '& .MuiSwitch-track': {
                                            backgroundColor: configState.softLimitsOff ? configData.warningColor : undefined,
                                            opacity: configState.softLimitsOff ? 0.8 : undefined
                                        },
                                        '& .MuiSwitch-thumb': {
                                            color: configState.softLimitsOff ? '#fff' : undefined
                                        }
                                    }}
                                />
                            </Box>
                        </Box>

                        {/* Countdown timer and progress bar */}
                        {isAnyModeOff && (
                            <Box>
                                <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 0.5 }}>
                                    <Typography variant="caption" sx={{ color: 'warning.main', fontWeight: 'bold' }}>
                                        Auto-reset in: {formatTime(remainingTime)}
                                    </Typography>
                                    <Typography variant="caption" sx={{ color: 'text.secondary' }}>
                                        Timeout: {formatTimeoutSetting(totalTime)}
                                    </Typography>
                                </Box>
                                <LinearProgress
                                    variant="determinate"
                                    value={progress}
                                    sx={{
                                        height: 6,
                                        borderRadius: 3,
                                        backgroundColor: 'rgba(255, 152, 0, 0.15)',
                                        '& .MuiLinearProgress-bar': {
                                            backgroundColor: 'warning.main',
                                            borderRadius: 3
                                        }
                                    }}
                                />
                            </Box>
                        )}
                    </Box>
                );
            }}
        />
    );
}
