import { UserMessageQueue } from '../data/UserMessageQueue';
import { ICNCProgram } from '../machine/ICNCProgram';
import { RunGCodeResponse } from '../machine/Machine';

export class SimulatorCNCProgram implements ICNCProgram {
  private currentGCode: string[] = [];
  private currentLineNumber: number = 0;

  async Stop(): Promise<void> {
    UserMessageQueue.Instance.addMessage('✓ Program stopped');
  }

  async Resume(): Promise<void> {
    UserMessageQueue.Instance.addMessage('✓ Program resumed');
  }

  async ResumeAt(lineNumber: number): Promise<void> {
    this.currentLineNumber = lineNumber;
    UserMessageQueue.Instance.addMessage(`✓ Program resumed at line ${lineNumber}`);
  }

  async GetCurrentGCode(): Promise<string[]> {
    return this.currentGCode;
  }

  async GetCurrentLineNumber(): Promise<number> {
    return this.currentLineNumber;
  }

  async RunGCode(gcode: string[], startImmediately: boolean = true, gcodeParameterString?: string): Promise<void> {
    // Load the G-code
    this.currentGCode = gcode;
    this.currentLineNumber = 0;

    const paramInfo = gcodeParameterString ? ` with parameters: ${gcodeParameterString}` : '';

    if (startImmediately) {
      UserMessageQueue.Instance.addMessage(`✓ Loaded and running G-code with ${gcode.length} lines${paramInfo}`);

      // Simulate program execution
      for (let i = 0; i < this.currentGCode.length; i++) {
        this.currentLineNumber = i + 1;
        await new Promise(resolve => setTimeout(resolve, 100));
      }
      UserMessageQueue.Instance.addMessage('✓ G-code program completed');
    } else {
      UserMessageQueue.Instance.addMessage(`✓ Loaded G-code with ${gcode.length} lines (not started)${paramInfo}`);
    }
  }

  async StartStepRun(gcode: string[], gcodeParameterString?: string): Promise<RunGCodeResponse> {
    // Load the G-code for step execution
    this.currentGCode = gcode;
    this.currentLineNumber = 0;

    const paramInfo = gcodeParameterString ? ` with parameters: ${gcodeParameterString}` : '';
    UserMessageQueue.Instance.addMessage(`✓ Step run mode enabled with ${gcode.length} lines${paramInfo}`);

    // Return a simulated response
    return {
      success: true,
      jobId: `sim-job-${Date.now()}`,
      message: `Step run started with ${gcode.length} lines${paramInfo}`,
      job: undefined,
      error: undefined
    };
  }

  async EndStepRun(): Promise<void> {
    UserMessageQueue.Instance.addMessage('✓ Step run mode disabled');
  }

  async StepRunNext(): Promise<void> {
    if (this.currentLineNumber < this.currentGCode.length) {
      this.currentLineNumber++;
      UserMessageQueue.Instance.addMessage(`✓ Executed step: ${this.currentGCode[this.currentLineNumber - 1]}`);
    } else {
      UserMessageQueue.Instance.addMessage('✓ Program completed');
    }
  }

  async RunFromCurrentStep(): Promise<void> {
    UserMessageQueue.Instance.addMessage(`✓ Running from line ${this.currentLineNumber}`);
    // Simulate running from current step
    for (let i = this.currentLineNumber; i < this.currentGCode.length; i++) {
      this.currentLineNumber = i + 1;
      await new Promise(resolve => setTimeout(resolve, 100));
    }
    UserMessageQueue.Instance.addMessage('✓ Program completed');
  }

  async RunGCodeCommand(gcode: string): Promise<void> {
    UserMessageQueue.Instance.addMessage(`✓ Executed G-code: ${gcode}`);
  }
}
