import {
  Add as AddIcon,
  Delete as DeleteIcon,
  Edit as EditIcon
} from '@mui/icons-material';
import {
  Box,
  Button,
  Chip,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  Divider,
  FormControl,
  FormControlLabel,
  Grid,
  IconButton,
  InputLabel,
  MenuItem,
  Paper,
  Select,
  Switch,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  TextField,
  Typography
} from '@mui/material';
import React, { useState } from 'react';
import { CutterType, Tool } from '../../../data/Common/Tool';
import { ToolLibrary } from '../../../data/Common/ToolLibrary';
import { ConfigurationData } from '../../../data/ConfigurationData';
import { UserMessageQueue } from '../../../data/UserMessageQueue';
import { ObserveState } from '../../../utils/statemanager/ObserveState';
import { NumberInput } from '../../Common/NumberInput';
import { OffsetEditor } from '../../Common/OffsetEditor';
import { ToolViewer } from '../../MachineViewer/ToolViewer';

interface ToolDialogProps {
  open: boolean;
  tool: Tool | null;
  library: ToolLibrary;
  onClose: () => void;
  onSave: (tool: Tool) => void;
}

const ToolDialog: React.FC<ToolDialogProps> = ({ open, tool, library, onClose, onSave }) => {
  const [formData, setFormData] = useState<Tool>(() => tool || new Tool());
  const [toolNumberError, setToolNumberError] = useState<string>('');
  const [cuttingLengthError, setCuttingLengthError] = useState<string>('');
  const [vBitAngleError, setVBitAngleError] = useState<string>('');

  // Validate tool number for duplicates
  const validateToolNumber = React.useCallback((toolNumber: number) => {
    if (toolNumber <= 0) {
      setToolNumberError('Tool number must be greater than 0');
      return;
    }

    const isDuplicate = library.tools.some((existingTool, index) => {
      // If we're editing a tool, exclude it from the duplicate check
      if (tool && library.tools[index] === tool) {
        return false;
      }
      return existingTool.toolNumber === toolNumber;
    });

    if (isDuplicate) {
      setToolNumberError(`Tool number ${toolNumber} already exists`);
    } else {
      setToolNumberError('');
    }
  }, [library.tools, tool]);

  // Validate cutting length
  const validateCuttingLength = React.useCallback((cuttingLength: number, lengthBelowHolder: number) => {
    // Compare absolute values since lengthBelowHolder is stored negative
    if (cuttingLength > Math.abs(lengthBelowHolder)) {
      setCuttingLengthError('Cutting length must be <= length below holder');
    } else {
      setCuttingLengthError('');
    }
  }, []);

  // Validate V-bit angle
  const validateVBitAngle = React.useCallback((angle: number) => {
    if (angle <= 0 || angle >= 180) {
      setVBitAngleError('V-bit angle must be between 0° and 180°');
    } else {
      setVBitAngleError('');
    }
  }, []);

  React.useEffect(() => {
    setFormData(tool || new Tool());
    // Clear any existing errors when switching tools
    setToolNumberError('');
    setCuttingLengthError('');
    setVBitAngleError('');
    // Validate the initial tool if we have a tool
    if (tool) {
      validateToolNumber(tool.toolNumber);
    }
  }, [tool, validateToolNumber]);

  // Auto-update tool name when properties change (only if custom names are disabled)
  React.useEffect(() => {
    if (!formData.allowCustomName && formData.cuttingDiameter > 0) {
      const autoName = formData.getAutoGeneratedName();
      if (formData.toolName !== autoName) {
        setFormData(prevTool => {
          const newTool = new Tool();
          Object.assign(newTool, prevTool);
          newTool.toolName = autoName;
          return newTool;
        });
      }
    }
  }, [formData]);

  // Helper function to update Tool properties while maintaining the class instance
  const updateFormData = (updates: Partial<any>) => {
    const newTool = new Tool();
    // Copy all properties from current formData
    Object.assign(newTool, formData);

    // Special handling for shank width changes
    if ('shankWidth' in updates) {
      const oldShankWidth = formData.shankWidth;
      const newShankWidth = updates.shankWidth;

      // If cutting diameter was same as old shank or smaller than new shank, update it
      if (formData.cuttingDiameter === oldShankWidth || formData.cuttingDiameter < newShankWidth) {
        newTool.cuttingDiameter = newShankWidth;
      }
    }

    // Apply updates
    Object.assign(newTool, updates);
    setFormData(newTool);

    // Validate based on what was updated
    if ('toolNumber' in updates) {
      validateToolNumber(updates.toolNumber);
    }
    if ('cuttingLength' in updates || 'lengthBelowHolder' in updates) {
      const cuttingLength = 'cuttingLength' in updates ? updates.cuttingLength : newTool.cuttingLength;
      const lengthBelowHolder = 'lengthBelowHolder' in updates ? updates.lengthBelowHolder : newTool.lengthBelowHolder;
      validateCuttingLength(cuttingLength, lengthBelowHolder);
    }
    if ('vCuttingEdgeAngle' in updates) {
      validateVBitAngle(updates.vCuttingEdgeAngle);
    }
  };

  const handleSave = () => {
    // Final validation before save
    validateToolNumber(formData.toolNumber);
    validateCuttingLength(formData.cuttingLength, formData.lengthBelowHolder);
    if (formData.cutterType === CutterType.VBit) {
      validateVBitAngle(formData.vCuttingEdgeAngle);
    }

    if (toolNumberError || cuttingLengthError || vBitAngleError) {
      return; // Don't save if there are errors
    }

    onSave(formData);
    onClose();
  };

  const handleMeasureTool = () => {
    // Placeholder for tool measurement wizard
    // TODO: Implement actual tool measurement wizard
    UserMessageQueue.Instance.addMessage('Tool measurement wizard will be implemented - placeholder step: Measuring tool...');
  };

  return (
    <Dialog open={open} onClose={onClose} maxWidth="lg" fullWidth>
      <DialogTitle>{tool ? 'Edit Tool' : 'Add New Tool'}</DialogTitle>
      <DialogContent>
        <Grid container spacing={3} sx={{ mt: 1, minHeight: '500px' }}>
          {/* Left side - Form */}
          <Grid item xs={12} md={7}>
            <Grid container spacing={2}>
              {/* Row 1 - Tool Name with edit/generate link */}
              <Grid item xs={12}>
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                  <TextField
                    fullWidth
                    label="Tool Name"
                    value={formData.allowCustomName ? formData.toolName : formData.getAutoGeneratedName()}
                    onChange={(e) => updateFormData({ toolName: e.target.value })}
                    InputProps={{
                      readOnly: !formData.allowCustomName || formData.systemLocked,
                    }}
                    disabled={formData.systemLocked}
                  />
                  <Button
                    variant="text"
                    size="small"
                    onClick={() => updateFormData({ allowCustomName: !formData.allowCustomName })}
                    disabled={formData.systemLocked}
                    sx={{ minWidth: 'auto', whiteSpace: 'nowrap' }}
                  >
                    {formData.allowCustomName ? 'Generate' : 'Edit'}
                  </Button>
                </Box>
              </Grid>

              {/* Row 2 - Tool Number and Cutter Type */}
              <Grid item xs={12} md={6}>
                <NumberInput
                  fullWidth
                  label="Tool Number"
                  value={formData.toolNumber}
                  onChange={(value) => updateFormData({ toolNumber: value })}
                  allowFractions={false}
                  precision={0}
                  error={!!toolNumberError}
                  helperText={toolNumberError}
                  disabled={formData.systemLocked}
                />
              </Grid>

              <Grid item xs={12} md={6}>
                <FormControl fullWidth disabled={formData.systemLocked}>
                  <InputLabel>Cutter Type</InputLabel>
                  <Select
                    value={formData.cutterType}
                    onChange={(e) => updateFormData({ cutterType: e.target.value as CutterType })}
                  >
                    <MenuItem value={CutterType.FlatEndMill}>Flat End Mill</MenuItem>
                    <MenuItem value={CutterType.BallEndMill}>Ball End Mill</MenuItem>
                    <MenuItem value={CutterType.VBit}>V-Bit</MenuItem>
                  </Select>
                </FormControl>
              </Grid>

              {/* Divider line */}
              <Grid item xs={12}>
                <Divider />
              </Grid>

              {/* Row 3 - Shank Width and Length Below Tool Holder */}
              <Grid item xs={12} md={6}>
                <NumberInput
                  fullWidth
                  label="Shank Width"
                  value={formData.shankWidth}
                  onChange={(value) => updateFormData({ shankWidth: value })}
                  precision={3}
                  disabled={formData.systemLocked}
                />
              </Grid>

              <Grid item xs={12} md={6}>
                <NumberInput
                  fullWidth
                  label="Length Below Tool Holder"
                  value={Math.abs(formData.lengthBelowHolder)}
                  onChange={(value) => updateFormData({ lengthBelowHolder: -Math.abs(value) })}
                  precision={3}
                  disabled={formData.systemLocked}
                />
              </Grid>

              {/* Row 4 - Different layouts based on cutter type */}
              {/* For Flat End Mill, Ball End Mill, Surfacing */}
              {(formData.cutterType === CutterType.FlatEndMill ||
                formData.cutterType === CutterType.BallEndMill ||
                formData.cutterType === CutterType.Surfacing) && (
                  <>
                    <Grid item xs={12} md={6}>
                      <NumberInput
                        fullWidth
                        label="Cutter Diameter"
                        value={formData.cuttingDiameter}
                        onChange={(value) => updateFormData({ cuttingDiameter: value })}
                        precision={3}
                        disabled={formData.systemLocked}
                      />
                    </Grid>

                    <Grid item xs={12} md={6}>
                      <NumberInput
                        fullWidth
                        label="Cutter Length"
                        value={formData.cuttingLength}
                        onChange={(value) => updateFormData({ cuttingLength: value })}
                        precision={3}
                        error={!!cuttingLengthError}
                        helperText={cuttingLengthError}
                        disabled={formData.systemLocked}
                      />
                    </Grid>
                  </>
                )}

              {/* For V-Bit */}
              {formData.cutterType === CutterType.VBit && (
                <>
                  <Grid item xs={12} md={6}>
                    <NumberInput
                      fullWidth
                      label="Cutter Diameter"
                      value={formData.cuttingDiameter}
                      onChange={(value) => updateFormData({ cuttingDiameter: value })}
                      precision={3}
                      disabled={formData.systemLocked}
                    />
                  </Grid>

                  <Grid item xs={12} md={6}>
                    <NumberInput
                      fullWidth
                      label="V-Bit Angle"
                      value={formData.vCuttingEdgeAngle}
                      onChange={(value) => updateFormData({ vCuttingEdgeAngle: value })}
                      precision={1}
                      error={!!vBitAngleError}
                      helperText={vBitAngleError}
                      disabled={formData.systemLocked}
                    />
                  </Grid>
                </>
              )}

              {/* System Locked - conditional display based on system configuration mode */}
              <Grid item xs={12}>
                <ObserveState
                  listenTo={ConfigurationData.Instance}
                  properties={['systemConfigurationUnlocked']}
                  control={() => {
                    const config = ConfigurationData.Instance;

                    // If system is unlocked, show toggle for system locked
                    if (config.systemConfigurationUnlocked) {
                      return (
                        <FormControlLabel
                          control={
                            <Switch
                              checked={formData.systemLocked}
                              onChange={(e) => updateFormData({ systemLocked: e.target.checked })}
                            />
                          }
                          label="System Locked"
                        />
                      );
                    }

                    // If system is locked and tool is locked, show chip indicator
                    if (formData.systemLocked) {
                      return (
                        <Chip
                          label="System Locked"
                          color="primary"
                          variant="outlined"
                          size="small"
                        />
                      );
                    }

                    // If system is locked but tool is not locked, show nothing
                    return null;
                  }}
                />
              </Grid>

              {/* Measured Length and Tool Measurement section */}
              <Grid item xs={12}>
                <Typography variant="subtitle2" gutterBottom>Tool Measurement</Typography>
              </Grid>

              <Grid item xs={12} md={6}>
                <NumberInput
                  fullWidth
                  label="Measured Length"
                  value={Math.abs(formData.measuredLength || 0)}
                  onChange={(value) => updateFormData({ measuredLength: -Math.abs(value) })}
                  precision={3}
                  disabled={true}
                />
              </Grid>

              <Grid item xs={12} md={6}>
                <Box sx={{ display: 'flex', alignItems: 'center', height: '100%' }}>
                  <Button
                    variant="contained"
                    color="primary"
                    onClick={handleMeasureTool}
                    disabled={formData.systemLocked}
                    fullWidth
                    sx={{ height: '56px' }} // Match the height of the input field
                  >
                    Measure Tool
                  </Button>
                </Box>
              </Grid>

              {/* Tool Offsets section */}
              <Grid item xs={12}>
                <Typography variant="subtitle2" gutterBottom>Tool Offsets</Typography>
              </Grid>

              <Grid item xs={12}>
                <OffsetEditor
                  offset={formData.toolOffset}
                  onOffsetChange={(newOffset) => {
                    formData.toolOffset.setValues(newOffset.x, newOffset.y, newOffset.z);
                    updateFormData({});
                  }}
                  disabled={formData.systemLocked}
                  xLabel="X Offset"
                  yLabel="Y Offset"
                  zLabel="Z Offset"
                />
              </Grid>
            </Grid>
          </Grid>

          {/* Right side - 3D Preview */}
          <Grid item xs={12} md={5}>
            <Box sx={{
              height: '100%',
              minHeight: '400px',
              border: 1,
              borderColor: 'divider',
              borderRadius: 1,
              p: 2
            }}>
              <Typography variant="h6" gutterBottom>
                Tool Preview
              </Typography>
              {/* Show preview only if tool has valid dimensions */}
              {Math.abs(formData.lengthBelowHolder) > 0 &&
                ((formData.cutterType === CutterType.VBit && formData.cuttingDiameter > 0) ||
                  (formData.cutterType !== CutterType.VBit && formData.cuttingLength > 0)) &&
                formData.cuttingDiameter > 0 ? (
                <ToolViewer
                  tool={formData}
                  width="100%"
                  height="350px"
                  showGrid={true}
                  enableControls={true}
                />
              ) : (
                <Box sx={{
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  height: '350px',
                  backgroundColor: 'grey.100',
                  borderRadius: 1
                }}>
                  <Typography variant="body2" color="text.secondary">
                    Enter tool dimensions to see preview
                  </Typography>
                </Box>
              )}
            </Box>
          </Grid>
        </Grid>
      </DialogContent>
      <DialogActions>
        <Button onClick={onClose}>Cancel</Button>
        <Button
          onClick={handleSave}
          variant="contained"
          disabled={formData.systemLocked || !!toolNumberError}
        >
          Save
        </Button>
      </DialogActions>
    </Dialog>
  );
};

export const ToolLibraryTab: React.FC = () => {
  const [library] = useState(() => ToolLibrary.Instance);
  const [dialogOpen, setDialogOpen] = useState(false);
  const [editingTool, setEditingTool] = useState<Tool | null>(null);

  const handleAddTool = () => {
    setEditingTool(null);
    setDialogOpen(true);
  };

  const handleEditTool = (tool: Tool) => {
    if (tool.systemLocked) return; // Prevent editing system locked tools
    setEditingTool(tool);
    setDialogOpen(true);
  };

  const handleDeleteTool = (tool: Tool) => {
    if (tool.systemLocked) return; // Prevent deleting system locked tools
    const index = library.tools.indexOf(tool);
    if (index > -1) {
      library.tools.splice(index, 1);
    }
  };

  const handleSaveTool = (tool: Tool) => {
    // Check for duplicate tool numbers
    const isDuplicate = library.tools.some((existingTool, index) => {
      // If we're editing a tool, exclude it from the duplicate check
      if (editingTool && library.tools[index] === editingTool) {
        return false;
      }
      return existingTool.toolNumber === tool.toolNumber;
    });

    if (isDuplicate) {
      UserMessageQueue.Instance.addMessage(`❌ Tool number ${tool.toolNumber} already exists in the library. Please choose a different tool number.`);
      return;
    }

    if (editingTool) {
      // Update existing tool
      const index = library.tools.indexOf(editingTool);
      if (index > -1) {
        library.tools[index] = tool;
        UserMessageQueue.Instance.addMessage(`✓ Tool ${tool.toolNumber} updated successfully`);
      }
    } else {
      // Add new tool
      library.tools.push(tool);
      UserMessageQueue.Instance.addMessage(`✓ Tool ${tool.toolNumber} added successfully`);
    }
  };

  return (
    <ObserveState
      listenTo={library}
      control={() => (
        <Box sx={{ p: 3 }}>
          <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 3 }}>
            <Typography variant="h6">Tool Library</Typography>
            <Button
              variant="contained"
              startIcon={<AddIcon />}
              onClick={handleAddTool}
            >
              Add Tool
            </Button>
          </Box>

          <TableContainer component={Paper}>
            <Table>
              <TableHead>
                <TableRow>
                  <TableCell>Tool #</TableCell>
                  <TableCell>Name</TableCell>
                  <TableCell>Type</TableCell>
                  <TableCell>Diameter</TableCell>
                  <TableCell>Length</TableCell>
                  <TableCell>Status</TableCell>
                  <TableCell align="right">Actions</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {library.tools
                  .sort((a, b) => a.toolNumber - b.toolNumber) // Sort by tool number
                  .map((tool, index) => (
                    <TableRow key={index}>
                      <TableCell>{tool.toolNumber}</TableCell>
                      <TableCell>{tool.displayName}</TableCell>
                      <TableCell>
                        <Chip
                          label={tool.cutterType}
                          size="small"
                          color={tool.cutterType === CutterType.FlatEndMill ? 'primary' :
                            tool.cutterType === CutterType.BallEndMill ? 'success' : 'warning'}
                        />
                      </TableCell>
                      <TableCell>{tool.cuttingDiameter}</TableCell>
                      <TableCell>{Math.abs(tool.lengthBelowHolder)}</TableCell>
                      <TableCell>
                        <Box sx={{ display: 'flex', gap: 0.5 }}>
                          {tool.toolMeasured && (
                            <Chip label="Measured" size="small" color="success" />
                          )}
                          {tool.toolMeasuredThisSession && (
                            <Chip label="This Session" size="small" color="info" />
                          )}
                          {tool.systemLocked && (
                            <Chip label="System Locked" size="small" color="default" />
                          )}
                        </Box>
                      </TableCell>
                      <TableCell align="right">
                        <IconButton
                          size="small"
                          onClick={() => handleEditTool(tool)}
                          color="primary"
                          title={tool.systemLocked ? "View tool (read-only)" : "Edit Tool"}
                        >
                          <EditIcon />
                        </IconButton>
                        <IconButton
                          size="small"
                          onClick={() => handleDeleteTool(tool)}
                          color="error"
                          disabled={tool.systemLocked}
                          title={tool.systemLocked ? "Cannot delete system locked tool" : "Delete Tool"}
                        >
                          <DeleteIcon />
                        </IconButton>
                      </TableCell>
                    </TableRow>
                  ))}
                {library.tools.length === 0 && (
                  <TableRow>
                    <TableCell colSpan={8} align="center" sx={{ py: 4, color: 'text.secondary' }}>
                      No tools found. Click "Add Tool" to create your first tool.
                    </TableCell>
                  </TableRow>
                )}
              </TableBody>
            </Table>
          </TableContainer>

          <ToolDialog
            open={dialogOpen}
            tool={editingTool}
            library={library}
            onClose={() => setDialogOpen(false)}
            onSave={handleSaveTool}
          />
        </Box>
      )}
    />
  );
};
