import { PlayArrow as PlayIcon } from '@mui/icons-material';
import { Box, TextField, Typography } from '@mui/material';
import React from 'react';
import { Machine } from '../../../../machine/Machine';
import { LogCategory, Logger } from '../../../../utils/Logger';
import { DataUtilities } from '../../../../utils/storage/DataUtilities';
import { FlowStep } from "../../../FlowStep";
import { FlowStepData } from "../../../FlowStepData";

export class ResumeAtStep extends FlowStep {
    readonly __type = 'ResumeAtStep';
    readonly category = ['Machine', 'Program'];
    readonly name = 'Resume At Line';
    readonly description = 'Resumes program execution at specific line';
    
    // Icon is created dynamically, not stored
    get icon(): React.ReactNode {
        return React.createElement(PlayIcon, { sx: { color: 'success.main' } });
    }

    public lineNumber: number = 1;

    static readonly DONE_PATH = 'done';

    async execute(data: FlowStepData, prototypeRun: boolean): Promise<string | null> {
        if (prototypeRun) {
            //Logger.Instance.log(LogCategory.System, `Prototype: Resume at line ${this.lineNumber}`);
            return ResumeAtStep.DONE_PATH;
        }

        try {
            await Machine.getInstance().program.ResumeAt(this.lineNumber);
            //Logger.Instance.log(LogCategory.System, `Resumed at line ${this.lineNumber}`);
            return ResumeAtStep.DONE_PATH;
        } catch (error) {
            Logger.Instance.logError(LogCategory.System, 'Resume at line failed:', error);
            return ResumeAtStep.DONE_PATH; // Still done, just with error logged
        }
    }

    results(): string[] {
        return [ResumeAtStep.DONE_PATH];
    }

    renderResultsUI(data: FlowStepData, result: string): React.ReactNode {
        return (
            <Typography variant="caption">
                Resume at line {this.lineNumber}: {result}
            </Typography>
        );
    }

    renderEditUI(props: { onClose: () => void }): React.ReactNode {
        const EditUI = () => {
            const [lineNumber, setLineNumber] = React.useState(this.lineNumber);

            // Update the instance when the local state changes
            React.useEffect(() => {
                this.lineNumber = lineNumber;
            }, [lineNumber]);

            return (
                <Box sx={{ p: 2, minWidth: 300 }}>
                    <TextField
                        label="Line Number"
                        type="number"
                        value={lineNumber}
                        onChange={(e) => setLineNumber(parseInt(e.target.value) || 1)}
                        fullWidth
                        margin="normal"
                        inputProps={{ min: 1 }}
                    />
                </Box>
            );
        };

        return <EditUI />;
    }

    public toJSON(): any {
        const data = DataUtilities.getStorageData(this, ['icon']) as any;
        data.__type = this.__type;
        return data;
    }

    public fromJSON(data: any): void {
        DataUtilities.loadStorageData(this, data);
    }
}





