import { Input as InputIcon } from '@mui/icons-material';
import { Typography } from '@mui/material';
import React from 'react';
import { Machine } from '../../../../machine/Machine';
import { LogCategory, Logger } from '../../../../utils/Logger';
import { DataUtilities } from '../../../../utils/storage/DataUtilities';
import { FlowStep } from "../../../FlowStep";
import { FlowStepData } from "../../../FlowStepData";

export class GetCurrentInputsStep extends FlowStep {
    readonly __type = 'GetCurrentInputsStep';
    readonly category = ['Machine', 'IO'];
    readonly name = 'Get Current Inputs';
    readonly description = 'Reads all current input states';
    
    // Icon is created dynamically, not stored
    get icon(): React.ReactNode {
        return React.createElement(InputIcon, { sx: { color: 'primary.main' } });
    }
    static readonly SUCCESS_PATH = 'success';
    async execute(data: FlowStepData, prototypeRun: boolean): Promise<string | null> {
        if (prototypeRun) {
            //Logger.Instance.log(LogCategory.System, 'Prototype: Get current inputs');
            data.setVariable('currentInputs', { 1: true, 2: false, 3: true });
            return GetCurrentInputsStep.SUCCESS_PATH;
        }

        try {
            const inputs = await Machine.getInstance().io.GetCurrentInputs();
            data.setVariable('currentInputs', inputs);
            //Logger.Instance.log(LogCategory.System, `Retrieved ${Object.keys(inputs).length} input states`);
            return GetCurrentInputsStep.SUCCESS_PATH;
        } catch (error) {
            Logger.Instance.logError(LogCategory.System, 'Get current inputs failed:', error);
            // Still return success with fallback value - the step completed its attempt
            data.setVariable('currentInputs', {});
            return GetCurrentInputsStep.SUCCESS_PATH;
        }
    }

    results(): string[] {
        return [GetCurrentInputsStep.SUCCESS_PATH];
    }

    renderResultsUI(data: FlowStepData, result: string): React.ReactNode {
        const inputs = data.getVariable('currentInputs') as Record<number, boolean> || {};
        const inputCount = Object.keys(inputs).length;
        return (
            <Typography variant="caption">
                Get inputs ({inputCount} channels): {result}
            </Typography>
        );
    }

    renderEditUI(props: { onClose: () => void }): React.ReactNode {
        return null; // No parameters, no edit UI needed
    }

    public toJSON(): any {
        const data = DataUtilities.getStorageData(this, ['icon']) as any;
        data.__type = this.__type;
        return data;
    }

    public fromJSON(data: any): void {
        DataUtilities.loadStorageData(this, data);
    }
}






