import type { InputWithState } from '../IOStateData';
import { DefaultInputs } from './DefaultInputs';
import { MachineInput } from './MachineInput';

/**
 * Static factory for machine input definitions
 * These are the base configurations - actual numbers and states come from API
 */
export class InputDefinitions {
    /**
     * Get all static input definitions
     * Centroid name is the key - our custom names and text can be customized
     */
    public static getDefinitions(): MachineInput[] {
        return [
            // Safety inputs
            new MachineInput('EStopOk', 'E-Stop', 'E-Stop Normal', 'E-Stop Pressed'),

            // Machine position sensors
            new MachineInput('FirstAxisHomeLimitOk', 'X Home', 'At Home Position', 'Not at Home'),
            new MachineInput('SecondAxisHomeLimitOk', 'Y1 Home', 'At Home Position', 'Not at Home'),
            new MachineInput('ThirdAxisHomeLimitOk', 'Z Home', 'At Home Position', 'Not at Home'),

            // Probing inputs
            new MachineInput('ProbeInput', 'Probe', 'Probe Contact', 'Probe Open'),
            new MachineInput('FixedTouchpadInput', 'Fixed Touchpad', 'Touch Detected', 'No Touch'),
            new MachineInput('MovableTouchpadInput', 'Movable Touchpad', 'Touch Detected', 'No Touch'),

            // Custom machine inputs (no centroid mapping - user-defined)
            new MachineInput('CustomInput1', 'Clamp Closed', 'Clamp Closed', 'Clamp Open'),
            new MachineInput('CustomInput2', 'Tool Present', 'Tool Present', 'No Tool'),
            new MachineInput('CustomInput3', 'Clamp Open', 'Clamp Open', 'Clamp Closed'),
            new MachineInput('CustomInput4', 'Pull Stud Button', 'Button Pressed', 'Button Released'),
            new MachineInput('CustomInput5', 'Pressure Detection', 'Pressure OK', 'Low Pressure'),
            new MachineInput('CustomInput6', 'Brush Upper Limit', 'At Upper Limit', 'Below Limit'),
            new MachineInput('CustomInput7', 'Touch Pad', 'Touch Detected', 'No Touch'),
            new MachineInput('CustomInput8', 'Y2 Home', 'At Home Position', 'Not at Home'),
            new MachineInput('CustomInput9', 'Chiller Alarm', 'Chiller OK', 'Chiller Alarm'),
            new MachineInput('CustomInput10', 'Motor 0 Alarm', 'Motor OK', 'Motor Alarm'),
            new MachineInput('CustomInput11', 'Motor 1 Alarm', 'Motor OK', 'Motor Alarm'),
            new MachineInput('CustomInput12', 'Motor 2 Alarm', 'Motor OK', 'Motor Alarm'),
            new MachineInput('CustomInput13', 'Motor 3 Alarm', 'Motor OK', 'Motor Alarm'),
            new MachineInput('CustomInput14', 'Spindle Alarm', 'Spindle OK', 'Spindle Alarm'),
        ];
    }

    /**
     * Get input definition by centroid name
     */
    public static getByCentroidName(centroidName: string): MachineInput | undefined {
        return this.getDefinitions().find(input => input.centroidName === centroidName);
    }

    /**
     * Combine API input definitions with our static metadata
     * @param apiDefinitions Input definitions from API (name + number)
     * @returns Combined definitions with metadata
     */
    public static combineWithMetadata(apiMappings: Array<{ number: number; centroidName?: string }>): Array<{ number: number; centroidName: string; name: string; activeText: string; inactiveText: string }> {
        const staticDefs = this.getDefinitions();

        return apiMappings.map(apiMapping => {
            // Find matching static definition by centroid name
            const staticDef = staticDefs.find(sd => sd.centroidName === apiMapping.centroidName);

            if (staticDef) {
                // Use static definition's metadata
                return {
                    number: apiMapping.number,
                    centroidName: apiMapping.centroidName || '',
                    name: staticDef.name,
                    activeText: staticDef.activeText,
                    inactiveText: staticDef.inactiveText
                };
            } else {
                // No matching metadata - use centroid name and default text
                return {
                    number: apiMapping.number,
                    centroidName: apiMapping.centroidName || '',
                    name: apiMapping.centroidName || `Input ${apiMapping.number}`,
                    activeText: 'Active',
                    inactiveText: 'Inactive'
                };
            }
        });
    }

    /**
     * Create full input state by combining all static definitions, API mappings (used list), and current state
     * @param apiMappings Input mappings from API (used list - what's actually configured)
     * @param currentStates Current state of inputs (number -> active/inactive)
     * @returns Full input definitions with state
     */
    public static createFullState(
        apiMappings: Array<{ number: number; centroidName?: string }>,
        currentStates: Record<number, boolean>
    ): InputWithState[] {
        const allDefaultInputs = DefaultInputs.getDefaults(); // Full list of all defined functions
        const result: InputWithState[] = [];

        // Process all default definitions (full list)
        allDefaultInputs.forEach(defaultInput => {
            // Find corresponding API mapping (from used list)
            const apiMapping = apiMappings.find(api => api.centroidName === defaultInput.centroidName);

            if (apiMapping) {
                // This input is both defined and used - combine API number with default metadata
                const { InputWithState } = require('../IOStateData');
                const input = new InputWithState();
                input.number = apiMapping.number;
                input.centroidName = defaultInput.centroidName;
                input.name = defaultInput.name;
                input.activeText = defaultInput.activeText;
                input.inactiveText = defaultInput.inactiveText;
                input.isActive = currentStates[apiMapping.number] ?? false;
                result.push(input);
            }
            // Skip inputs that don't have API mappings (no longer add them with number = 0)
        });        // Add any API mappings that don't have default definitions (unknown inputs from used list)
        apiMappings.forEach(apiMapping => {
            const hasDefaultDef = allDefaultInputs.some(defaultInput => defaultInput.centroidName === apiMapping.centroidName);
            if (!hasDefaultDef) {
                const { InputWithState } = require('../IOStateData');
                const input = new InputWithState();
                input.number = apiMapping.number;
                input.centroidName = apiMapping.centroidName || '';
                input.name = apiMapping.centroidName || `Input ${apiMapping.number}`;
                input.activeText = 'Active';
                input.inactiveText = 'Inactive';
                input.isActive = currentStates[apiMapping.number] ?? false;
                result.push(input);
            }
        });

        // Filter out inputs with number = 0 (unmapped/unused inputs)
        return result;
    }
}
