/**
 * Machine Input definition
 * Static configuration for inputs - actual number and state come from API/SignalR
 */
export class MachineInput {
  public readonly centroidName: string;
  public name: string;
  public activeText: string;
  public inactiveText: string;

  constructor(
    centroidName: string,
    name: string = '',
    activeText: string = 'Active',
    inactiveText: string = 'Inactive'
  ) {
    this.centroidName = centroidName;
    this.name = name;
    this.activeText = activeText;
    this.inactiveText = inactiveText;
  }

  /**
   * Create a copy of this input definition
   */
  public clone(): MachineInput {
    return new MachineInput(
      this.centroidName,
      this.name,
      this.activeText,
      this.inactiveText
    );
  }
}