import { IStorable } from '../../common/IStorable';
import { StateManager } from '../../utils/statemanager/StateManager';
import { DataUtilities } from '../../utils/storage/DataUtilities';
import { CNCOffset } from '../CNCOffset';
import { ConfigurationState } from '../ConfigurationState';

/**
 * Cutter type enum
 * Direct conversion from C# CutterType enum
 */
export enum CutterType {
  FlatEndMill = 'FlatEndMill',
  BallEndMill = 'BallEndMill',
  VBit = 'VBit',
  Surfacing = 'Surfacing',
  Manual = 'Manual'

}

/**
 * Tool/Bit definition
 * Direct conversion from C# Bit class
 */
export class Tool implements IStorable {
  private _toolNumber: number;
  private _toolName: string;
  private _shankWidth: number;
  private _lengthBelowHolder: number;
  private _cuttingLength: number;
  private _cuttingDiameter: number;
  private _vCuttingEdgeAngle: number;
  private _cutterType: CutterType;
  private _toolOffset: CNCOffset;
  private _toolMeasured: boolean;
  private _measuredLength: number;
  private _systemLocked: boolean = false; // Indicates if this tool is locked by the system
  private _allowCustomName: boolean = false; // Whether user can set custom tool name


  constructor() {
    this._toolNumber = 0;
    this._toolName = '';
    this._shankWidth = 0;
    this._lengthBelowHolder = 0;
    this._cuttingLength = 0;
    this._cuttingDiameter = 0;
    this._vCuttingEdgeAngle = 0;
    this._cutterType = CutterType.FlatEndMill;
    this._toolOffset = new CNCOffset(0, 0, 0);
    this._toolMeasured = false;
    this._measuredLength = 0;
    this._systemLocked = false; // Default to not locked
    this._allowCustomName = false; // Default to auto-generated names
  }

  // Getter and setter methods with StateManager property change notifications

  public get toolNumber(): number {
    return this._toolNumber;
  }

  public set toolNumber(value: number) {
    this._toolNumber = value;
    StateManager.propertyChanged(this, 'toolNumber');
  }

  public get toolName(): string {
    return this._toolName;
  }

  public set toolName(value: string) {
    this._toolName = value;
    StateManager.propertyChanged(this, 'toolName');
  }

  public get shankWidth(): number {
    return this._shankWidth;
  }

  public set shankWidth(value: number) {
    this._shankWidth = value;
    StateManager.propertyChanged(this, 'shankWidth');
  }

  public get lengthBelowHolder(): number {
    return this._lengthBelowHolder;
  }

  public set lengthBelowHolder(value: number) {
    this._lengthBelowHolder = value;
    StateManager.propertyChanged(this, 'lengthBelowHolder');
  }

  public get cuttingLength(): number {
    return this._cuttingLength;
  }

  public set cuttingLength(value: number) {
    this._cuttingLength = value;
    StateManager.propertyChanged(this, 'cuttingLength');
  }

  public get cuttingDiameter(): number {
    return this._cuttingDiameter;
  }

  public set cuttingDiameter(value: number) {
    this._cuttingDiameter = value;
    StateManager.propertyChanged(this, 'cuttingDiameter');
  }

  public get vCuttingEdgeAngle(): number {
    return this._vCuttingEdgeAngle;
  }

  public set vCuttingEdgeAngle(value: number) {
    this._vCuttingEdgeAngle = value;
    StateManager.propertyChanged(this, 'vCuttingEdgeAngle');
  }

  public get cutterType(): CutterType {
    return this._cutterType;
  }

  public set cutterType(value: CutterType) {
    this._cutterType = value;
    StateManager.propertyChanged(this, 'cutterType');
  }

  public get toolOffset(): CNCOffset {
    return this._toolOffset;
  }

  public get toolOffsetX(): number {
    return this._toolOffset.x;
  }

  public set toolOffsetX(value: number) {
    this._toolOffset.x = value;
    StateManager.propertyChanged(this, 'toolOffsetX');
  }

  public get toolOffsetY(): number {
    return this._toolOffset.y;
  }

  public set toolOffsetY(value: number) {
    this._toolOffset.y = value;
    StateManager.propertyChanged(this, 'toolOffsetY');
  }

  public get toolOffsetZ(): number {
    return this._toolOffset.z;
  }

  public set toolOffsetZ(value: number) {
    this._toolOffset.z = value;
    StateManager.propertyChanged(this, 'toolOffsetZ');
  }

  public get toolMeasured(): boolean {
    return this._toolMeasured;
  }

  public set toolMeasured(value: boolean) {
    this._toolMeasured = value;
    StateManager.propertyChanged(this, 'toolMeasured');
  }

  public get measuredLength(): number {
    return this._measuredLength;
  }

  public set measuredLength(value: number) {
    this._measuredLength = value;
    StateManager.propertyChanged(this, 'measuredLength');
  }

  public get systemLocked(): boolean {
    return this._systemLocked;
  }

  public set systemLocked(value: boolean) {
    this._systemLocked = value;
    StateManager.propertyChanged(this, 'systemLocked');
  }

  public get allowCustomName(): boolean {
    return this._allowCustomName;
  }

  public set allowCustomName(value: boolean) {
    this._allowCustomName = value;
    StateManager.propertyChanged(this, 'allowCustomName');

    // If switching to auto-generated names, update the name
    if (!value) {
      this.toolName = this.getAutoGeneratedName();
    }
  }

  /**
   * Get the effective cutting length for this tool
   * For ball end mills, returns cutting length + radius (cylindrical portion + hemisphere)
   * For v-bit tools, returns diameter/2 (auto-calculated)
   * For flat end mills, returns the specified cutting length
   */
  public get effectiveCuttingLength(): number {
    if (this._cutterType === CutterType.BallEndMill) {
      return this._cuttingLength + (this._cuttingDiameter / 2);
    }
    if (this._cutterType === CutterType.VBit) {
      return this._cuttingDiameter / 2;
    }
    return this._cuttingLength;
  }

  /**
   * Generate auto-calculated tool name based on type and dimensions
   */
  public getAutoGeneratedName(): string {
    const diameter = this._cuttingDiameter.toFixed(3).replace(/\.?0+$/, '');
    const lengthStr = Math.abs(this._lengthBelowHolder).toFixed(3).replace(/\.?0+$/, '');

    switch (this._cutterType) {
      case CutterType.VBit:
        const angle = this._vCuttingEdgeAngle.toFixed(0);
        return `${diameter}" ${this._cutterType} ${angle}° - ${lengthStr}"`;
      case CutterType.BallEndMill:
      case CutterType.FlatEndMill:
      case CutterType.Surfacing:
      default:
        return `${diameter}" ${this._cutterType} - ${lengthStr}"`;
    }
  }

  /**
   * Get the display name for this tool
   * Returns auto-generated name if allowCustomName is false, otherwise returns the custom name
   */
  public get displayName(): string {
    if (this._allowCustomName) {
      return this._toolName;
    }
    return this.getAutoGeneratedName();
  }

  /**
   * Check if this tool was measured this session by looking in ConfigurationState
   */
  public get toolMeasuredThisSession(): boolean {
    return ConfigurationState.Instance.isToolMeasured(this._toolNumber);
  }

  /**
   * Set tool as measured this session by adding to ConfigurationState
   */
  public set toolMeasuredThisSession(value: boolean) {
    if (value) {
      ConfigurationState.Instance.addMeasuredTool(this._toolNumber);
    } else {
      ConfigurationState.Instance.removeMeasuredTool(this._toolNumber);
    }
  }

  /**
   * Serialize to JSON using generic DataUtilities approach
   */
  public toJSON(): any {
    const baseData = DataUtilities.getStorageData(this, ['_toolOffset']);
    return {
      ...baseData,
      _toolOffset: this._toolOffset.toJSON()
    };
  }

  /**
   * Load from JSON using generic DataUtilities approach
   */
  public fromJSON(data: any): void {
    if (!data) return;

    // Load CNCOffset first
    if (data._toolOffset) {
      this._toolOffset.fromJSON(data._toolOffset);
    }

    // Load remaining properties (excluding _toolOffset)
    DataUtilities.loadStorageData(this, data, ['_toolOffset']);
  }
}
